import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_settings } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_settings";

/**
 * Test creation of a discussion board setting with an invalid scope_type.
 *
 * This test ensures that the discussionboard_settings creation API properly validates the allowed values for `scope_type`. Attempting to provide a scope_type value that is not supported should result in a client validation error (HTTP 400), confirming schema and type enforcement at the API boundary.
 *
 * Steps:
 * 1. Prepare valid values for all required fields, except deliberately set an invalid (nonsensical) string for scope_type.
 * 2. Call the `discussionboard.settings.create` endpoint with this payload.
 * 3. Assert that the API responds with an error (i.e., the request does not succeed and returns a validation failure, not success).
 * 4. Optionally, check with a valid scope_type that creation would succeed for control.
 */
export async function test_api_discussionboard_settings_test_create_setting_invalid_scope_type(connection: api.IConnection) {
  // 1. Try to create a setting with an unsupported scope_type
  const invalidPayload: Idiscussionboard_settings.ICreate = {
    scope_type: "not_a_valid_scope_type", // This should not be accepted by schema (if enforced by API)
    key: "test_key",
    value: "test_value",
    description: "Testing invalid scope_type behavior in settings API",
    // scope_id is optional and left undefined/null
  };

  await TestValidator.error("invalid scope_type should trigger validation error")(() =>
    api.functional.discussionboard.settings.create(connection, { body: invalidPayload })
  );
}

