    api.functional.discussionboard.channels.erase(connection, {
      id: "12345",
    }),
  );

  // Step 3: Try to delete using an empty string
  await TestValidator.error("invalid id format: empty string")(() =>
    api.functional.discussionboard.channels.erase(connection, {
      id: "",
    }),
  );
