import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Validate successful update of a board category by its UUID.
 *
 * This test ensures that updating an existing board category's mutable fields (name, code, description, or position) via PUT succeeds and returns the updated record. We first create a unique category to work with (to enforce uniqueness constraints for name and code), then issue an update that modifies one or more mutable properties with new unique values. After the update, we assert that the updated properties reflect the new values, that unchanged properties remain unmodified, and that unique constraints on name and code are respected.
 *
 * Steps:
 * 1. Create a new board category with unique values for name and code.
 * 2. Update the existing category (by id) with new unique values for name/code/description/position using PUT.
 * 3. Validate success response and confirm that updated fields changed as expected, while others remain intact.
 * 4. Optionally, attempt a unique constraint violation update (e.g., duplicate name/code) and confirm error (scenario does not require this but suggested for further coverage).
 */
export async function test_api_discussionboard_test_update_board_category_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a unique board category
  const originalCreate = {
    name: `cat-${RandomGenerator.alphaNumeric(8)}`,
    code: `code-${RandomGenerator.alphaNumeric(6)}`,
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionboardBoardCategory.ICreate;

  const created = await api.functional.discussionboard.boardCategories.create(connection, { body: originalCreate });
  typia.assert(created);

  // 2. Prepare new unique values for update
  const updateData = {
    name: `cat-${RandomGenerator.alphaNumeric(8)}`,
    code: `code-${RandomGenerator.alphaNumeric(6)}`,
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
  } satisfies IDiscussionboardBoardCategory.IUpdate;

  // 3. Issue the PUT request to update the category
  const updated = await api.functional.discussionboard.boardCategories.update(connection, {
    id: created.id,
    body: updateData,
  });
  typia.assert(updated);

  // 4. Validate the updated fields are as expected
  TestValidator.equals("updated name")(updated.name)(updateData.name);
  TestValidator.equals("updated code")(updated.code)(updateData.code);
  TestValidator.equals("updated description")(updated.description)(updateData.description);
  TestValidator.equals("updated position")(updated.position)(updateData.position);

  // 5. Validate the unmodified fields remain intact (created_at and id)
  TestValidator.equals("id unchanged")(updated.id)(created.id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(created.created_at);
}

