/**
 * Test unique constraint enforcement when updating notification template code.
 *
 * This test verifies that the system enforces global uniqueness of the `code` field on notification templates, both during creation and update. The process is:
 *
 * 1. Create a notification template with a unique code (code1)
 * 2. Create another notification template with a different unique code (code2)
 * 3. Attempt to update the second template's code to match code1, causing a unique violation
 * 4. Assert that the update operation fails and throws an error (ideally a HttpError with status code 409 or similar)
 *
 * This ensures that the API does not allow duplicate template codes via update, preserving the code uniqueness invariant required for downstream notification logic.
 */
export async function test_api_discussionboard_notificationTemplates_test_update_notification_template_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Create first notification template (code1)
  const code1 = `test_template_${RandomGenerator.alphaNumeric(8)}`;
  const template1 = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    {
      body: {
        code: code1,
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.paragraph()(1),
        subject: RandomGenerator.paragraph()(1),
        body: RandomGenerator.paragraph()(3),
        is_active: true,
      } satisfies IDiscussionboardNotificationTemplate.ICreate,
    },
  );
  typia.assert(template1);
  TestValidator.equals("created template1 code matches")(template1.code)(code1);

  // 2. Create second template with another code (code2)
  const code2 = `test_template_${RandomGenerator.alphaNumeric(8)}`;
  TestValidator.notEquals("template codes must differ")(code1)(code2);
  const template2 = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    {
      body: {
        code: code2,
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.paragraph()(1),
        subject: RandomGenerator.paragraph()(1),
        body: RandomGenerator.paragraph()(3),
        is_active: true,
      } satisfies IDiscussionboardNotificationTemplate.ICreate,
    },
  );
  typia.assert(template2);
  TestValidator.equals("created template2 code matches")(template2.code)(code2);

  // 3. Try to update template2's code to `code1` and expect error
  await TestValidator.error("should reject duplicate code update")(async () => {
    await api.functional.discussionboard.notificationTemplates.update(
      connection,
      {
        id: template2.id,
        body: {
          code: code1,
        } satisfies IDiscussionboardNotificationTemplate.IUpdate,
      },
    );
  });
}

