import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Validate that updating a section's code to duplicate another section's code within the same channel results in a unique constraint error.
 *
 * This test verifies that the API enforces uniqueness of section 'code' values within a channel. It ensures that attempting to update a section's code to match another section's code under the same parent channel is properly rejected.
 *
 * Steps:
 * 1. Create a discussion board channel (parent grouping for sections)
 * 2. Create two sections (A and B) under this channel, each with unique codes
 * 3. Attempt to update section B's code to be the same as section A's code
 * 4. Confirm that the API responds with an error indicating violation of the unique constraint
 */
export async function test_api_discussionboard_test_update_section_with_duplicate_code_returns_error(
  connection: api.IConnection,
) {
  // 1. Create parent channel for sections
  const channel = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.paragraph()(3),
      description: RandomGenerator.paragraph()(2),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel);

  // 2. Create two sections under this channel with different codes
  const sectionA = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(2),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    } satisfies IDiscussionboardSection.ICreate,
  });
  typia.assert(sectionA);
  const sectionB = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(2),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    } satisfies IDiscussionboardSection.ICreate,
  });
  typia.assert(sectionB);

  // 3. Attempt to update section B to have the same code as section A
  await TestValidator.error("update should fail due to duplicate code")(
    async () => {
      await api.functional.discussionboard.sections.update(connection, {
        id: sectionB.id,
        body: {
          code: sectionA.code,
        } satisfies IDiscussionboardSection.IUpdate,
      });
    },
  );
}

