import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotificationTemplate";
import type { IBoolResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoolResult";

/**
 * Test double deletion of a notification template in the discussion board system.
 *
 * This scenario validates correct handling of repeated DELETE operations on the same resource. It ensures:
 *  - Idempotency of the DELETE endpoint: double-deletion does not cause data corruption or crash
 *  - Proper error feedback: on the second deletion attempt, the API should indicate the template no longer exists
 *
 * Test workflow:
 * 1. Create a notification template via POST /discussionboard/notificationTemplates
 * 2. Delete the created template using DELETE /discussionboard/notificationTemplates/{id}
 * 3. Attempt to delete the same template again (should fail with a biz error and/or success=false in response)
 * 4. Validate the first deletion succeeded (success=true), second deletion gives appropriate error (success=false or error thrown)
 *
 * Business Value:
 *  - Validates idempotency and standards compliance for destructive ops
 *  - Ensures users can safely re-submit delete requests without ambiguity
 */
export async function test_api_discussionboard_test_delete_notification_template_twice(
  connection: api.IConnection,
) {
  // 1. Create a notification template
  const created = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(10),
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.paragraph()(1),
        subject: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()()(),
        is_active: true,
      } satisfies IDiscussionboardNotificationTemplate.ICreate,
    },
  );
  typia.assert(created);

  // 2. Delete the created template
  const firstDeletion = await api.functional.discussionboard.notificationTemplates.erase(
    connection,
    { id: created.id },
  );
  typia.assert(firstDeletion);
  TestValidator.equals("First deletion should succeed")(firstDeletion.success)(true);

  // 3. Try deleting again (double-delete)
  await TestValidator.error("Second deletion should fail")(
    async () => {
      await api.functional.discussionboard.notificationTemplates.erase(
        connection,
        { id: created.id },
      );
    },
  );
}

