import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate that the discussion board post creation endpoint rejects requests missing required fields.
 *
 * Business context:
 * Creating a post on the discussion board requires all mandatory fields as per the database schema. Omitting any required field (such as discussionboard_thread_id, discussionboard_member_id, title, body, discussionboard_board_id, is_deleted, created_at, or updated_at) should trigger a validation error from the API.
 *
 * Workflow:
 * 1. Attempt to create a post with each required field missing (one at a time). For each such request, expect the API to throw an error (validation failure).
 * 2. Additionally, validate that trying to submit completely invalid data (such as empty strings for required strings, or invalid data formats – e.g., non-UUIDs for UUID fields) triggers errors as well.
 * 3. For each invalid case, check that the API responds with an error (do not validate error code/message, only that an error was thrown and post was not created).
 */
export async function test_api_discussionboard_test_create_post_missing_required_fields(
  connection: api.IConnection,
) {
  // Test cases of missing required fields, one at a time.
  const validPost: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Valid Title",
    body: "Valid Body Content",
    is_deleted: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  // Utility to deep clone an object
  const clone = <T>(obj: T): T => JSON.parse(JSON.stringify(obj));

  // List all required fields
  const requiredFields = [
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "discussionboard_board_id",
    "title",
    "body",
    "is_deleted",
    "created_at",
    "updated_at",
  ];

  // Omit each required field one at a time and verify error
  for (const field of requiredFields) {
    const invalidPost = clone(validPost);
    delete invalidPost[field as keyof typeof invalidPost];
    await TestValidator.error(
      `creation fails with missing field ${field}`,
    )(async () => {
      // @ts-expect-error intentionally omitting required field for negative test
      await api.functional.discussionboard.posts.create(connection, {
        body: invalidPost,
      });
    });
  }

  // Test empty string for required string fields
  const stringFields = [
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "discussionboard_board_id",
    "title",
    "body",
    "created_at",
    "updated_at",
  ];
  for (const field of stringFields) {
    const invalidPost = clone(validPost);
    // @ts-expect-error intentionally writing empty string for invalid test
    invalidPost[field as keyof typeof invalidPost] = "";
    await TestValidator.error(
      `creation fails with empty string for field ${field}`,
