 * This test covers the complete flow for creating a warning (moderation escalation record) and then retrieving it by its unique id, ensuring business logic and schema compliance.
 *
 * Steps:
 * 1. Create (issue) a warning to a member using the warnings.create API – this yields a real warning id.
 * 2. Retrieve the warning by id using warnings.at.
 * 3. Compare all fields of the returned record to the created warning, ensuring accuracy on id, warned_member_id, acting_moderator_id, report_id, reason, and warned_at per schema rules.
 * 4. Validate output type/schema for both create and getById operations.
 * 5. (Negative test omitted – only valid ID scenario covered per instructions).
 */
export async function test_api_discussionboard_test_get_warning_with_valid_id(connection: api.IConnection) {
  // Step 1: Issue a warning (moderation record) to get a valid warning id
  const createInput: IDiscussionboardWarning.ICreate = {
    warned_member_id: typia.random<string & tags.Format<"uuid">>(),
    acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
