  TestValidator.equals("report_id matches")(fetchedWarning.report_id)(createdWarning.report_id);
  TestValidator.equals("reason matches")(fetchedWarning.reason)(createdWarning.reason);
  TestValidator.equals("warned_at matches")(fetchedWarning.warned_at)(createdWarning.warned_at);
}

