import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMemberPreference";

/**
 * E2E test: Update notification/preferences with an invalid or unauthorized ID.
 *
 * This test verifies that the API securely handles attempts to update discussion board member notification/preferences using an ID that does not exist or does not belong to the authenticated user. It ensures that:
 *   - The user is registered and authenticated before attempting to update preferences.
 *   - An update request with an invalid (random) UUID is rejected gracefully with an error.
 *   - The error does not leak sensitive information or implementation details.
 *
 * Steps:
 * 1. Register a new discussion board member (authentication context).
 * 2. Attempt to update preferences using a random UUID (not owned/not existing).
 * 3. Assert that an error occurred and no sensitive information has leaked.
 */
export async function test_api_my_test_update_notification_preferences_with_invalid_id(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(15),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Attempt to update preferences with an invalid/inaccessible id
  await TestValidator.error("should reject invalid id update")(() =>
    api.functional.my.discussionboard.member.preferences.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // Not the user's real preference record
      body: {
        receive_email_notifications: false,
        dark_mode_enabled: true,
      } satisfies IDiscussionboardMemberPreference.IUpdate,
    })
  );
}

