import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Validate successful retrieval of a discussion board category by UUID.
 *
 * This test ensures that when a valid (recently created) board category ID is provided to the GET endpoint, the API returns the complete category record.
 * The flow confirms that all key schema fields are present, that values reflect what was provided at creation (except for system-assigned ones), and that system-managed fields like created_at are handled and returned appropriately.
 *
 * Steps:
 * 1. Create a new board category via POST /discussionboard/boardCategories, storing the returned object.
 * 2. Fetch the newly created board category using its id via GET /discussionboard/boardCategories/{id}.
 * 3. Validate the GET response:
 *   - All main schema fields are present (id, name, code, description, position, created_at).
 *   - Properties name/code/description/position match the POST request data.
 *   - id is a UUID and matches the created record.
 *   - created_at is a valid date-time string.
 */
export async function test_api_discussionboard_test_get_board_category_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new board category
  const input: IDiscussionboardBoardCategory.ICreate = {
    name: RandomGenerator.paragraph()(1),
    code: RandomGenerator.alphaNumeric(8).toLowerCase(),
    description: RandomGenerator.content()()(),
    position: typia.random<number & tags.Type<"int32">>(),
  };
  const created = await api.functional.discussionboard.boardCategories.create(connection, { body: input });
  typia.assert(created);

  // 2. Fetch the newly created board category by its id
  const fetched = await api.functional.discussionboard.boardCategories.at(connection, { id: created.id });
  typia.assert(fetched);

  // 3. Validate schema fields and value correctness
  // id matches
  TestValidator.equals("id matches")(fetched.id)(created.id);
  // name matches
  TestValidator.equals("name matches")(fetched.name)(input.name);
  // code matches
  TestValidator.equals("code matches")(fetched.code)(input.code);
  // description matches (nullable OK)
  TestValidator.equals("description matches")(fetched.description ?? null)(input.description ?? null);
  // position matches
  TestValidator.equals("position matches")(fetched.position)(input.position);
  // created_at exists and is date-time
  TestValidator.predicate("created_at is date-time")(
    typeof fetched.created_at === "string" && !isNaN(Date.parse(fetched.created_at)),
  );
}

