import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Test that creating a board with a duplicate code results in a unique constraint error.
 *
 * This test verifies that the system prevents creation of multiple boards with the same unique code, as required by business rules and schema constraints. It checks the enforcement of the unique constraint on the board code field, ensuring data integrity at the API and database level.
 *
 * Steps:
 * 1. Create a board category (required for board creation)
 * 2. Create a section (required for board creation)
 * 3. Create a first board with a specific unique code
 * 4. Attempt to create a second board (different name) with the same code in the same category/section
 * 5. Expect and confirm a unique constraint error is thrown for the duplicate code scenario
 */
export async function test_api_discussionboard_boards_test_create_board_with_duplicate_code(connection: api.IConnection) {
  // 1. Create a board category
  const category = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphabets(6),
      description: RandomGenerator.paragraph()(),
      position: typia.random<number & tags.Type<"int32">>(),
    } satisfies IDiscussionboardBoardCategory.ICreate,
  });
  typia.assert(category);

  // 2. Create a section (requires a channel id)
  const section = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.alphabets(15),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    } satisfies IDiscussionboardSection.ICreate,
  });
  typia.assert(section);

  // 3. Create first board with a given code
  const boardCode = RandomGenerator.alphabets(10);
  const firstBoard = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: category.id,
      discussionboard_section_id: section.id,
      name: RandomGenerator.alphabets(12),
      code: boardCode,
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(firstBoard);

  // 4. Attempt to create a second board with same code (should fail)
  await TestValidator.error("Duplicate board code should raise unique constraint error")(
    async () => {
      await api.functional.discussionboard.boards.create(connection, {
        body: {
          discussionboard_board_category_id: category.id,
          discussionboard_section_id: section.id,
          name: RandomGenerator.alphabets(12), // different name
          code: boardCode, // same code
          description: RandomGenerator.paragraph()(),
          is_active: true,
          is_visible: true,
        } satisfies Idiscussionboard_boards.ICreate,
      });
    },
  );
}

