/**
 * Test retrieval of a notification log by its existing id.
 *
 * This test ensures that when a notification log record exists, it can be retrieved exactly by its id.
 * It validates that all properties in the response exist and are correct according to the schema, and that no extra fields are returned.
 *
 * Step-by-step process:
 * 1. Create a new notification log via the create endpoint, capturing the returned id.
 * 2. Retrieve the same notification log by id using the getById endpoint.
 * 3. Assert that all fields (id, target_id, type, title, body, delivered, created_at, delivered_at, description) in the response match the schema and expectation.
 * 4. Assert that no extra properties not defined in the schema are included in the response.
 */
export async function test_api_discussionboard_notifications_test_retrieve_notification_by_existing_id(
  connection: api.IConnection,
) {
  // 1. Create a new notification log
  const created = await api.functional.discussionboard.notifications.create(connection, {
    body: {
      target_id: typia.random<string & tags.Format<"uuid">>(),
      type: "user_mention",
      title: "Test Title",
      body: "Test body content.",
      delivered: false,
    },
  });
  typia.assert(created);

  // 2. Retrieve the notification log by id
  const retrieved = await api.functional.discussionboard.notifications.at(connection, {
    id: created.id,
  });
  typia.assert(retrieved);

  // 3. Check that all response fields exist and match the schema
  TestValidator.equals("id matches")(retrieved.id)(created.id);
  TestValidator.equals("target_id matches")(retrieved.target_id)(created.target_id);
  TestValidator.equals("type matches")(retrieved.type)(created.type);
  TestValidator.equals("title matches")(retrieved.title)(created.title);
  TestValidator.equals("body matches")(retrieved.body)(created.body);
  TestValidator.equals("delivered matches")(retrieved.delivered)(created.delivered);
  // created_at and delivered_at are system fields; just ensure type
  TestValidator.predicate("created_at is string")(typeof retrieved.created_at === "string");
  if (retrieved.delivered_at !== undefined && retrieved.delivered_at !== null)
    TestValidator.predicate("delivered_at is string")(typeof retrieved.delivered_at === "string");
  TestValidator.predicate("description is string")(typeof retrieved.description === "string");

  // 4. Ensure no extra fields
  const expectedKeys = [
    "id", "target_id", "type", "title", "body", "delivered", "created_at", "delivered_at", "description"
  ];
  TestValidator.equals("No extra properties")(
    Object.keys(retrieved).sort().join(",")
  )(
    expectedKeys.sort().join(",")
  );
}

