import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { ISuccessResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuccessResponse";

/**
 * Validate the soft deletion functionality for discussion board threads.
 *
 * This test covers the entire lifecycle of soft-deleting a thread and
 * ensures that core business and access expectations are maintained:
 *
 * 1. Create a thread for deletion testing.
 * 2. Soft delete the thread using its ID—verify operation succeeds
 *    and that `deleted_at` is no longer null.
 * 3. Attempt to repeatedly delete the same thread—validate that
 *    repeated deletions are idempotent and that a suitable message or
 *    response is returned (e.g., still success, no change, or a business logic alert).
 * 4. Attempt to retrieve or update the soft-deleted thread. Confirm
 *    these operations are denied (e.g. not found, forbidden, or null response).
 *
 * Assumptions:
 * - Only the provided APIs are tested: create (POST) and erase (DELETE).
 * - Since no "get by id" or "update" APIs are provided, only deletion success and
deleted_at (in returned record) can be checked here.
 * - This test is thus limited to creation and soft deletion, with as much logical
 *   verification as possible from available SDK functions and types.
 */
export async function test_api_discussionboard_threads_test_soft_delete_thread_and_access_after_deletion(
  connection: api.IConnection,
) {
  // 1. Create a new thread for the test
  const createInput: IDiscussionboardThreads.ICreate = {
    board_id: typia.random<string & tags.Format<"uuid">>(),
    author_member_id: typia.random<string & tags.Format<"uuid">>(),
    title: `Test thread for soft delete - ${RandomGenerator.alphabets(8)}`,
    body: RandomGenerator.paragraph()(),
  };
  const created: IDiscussionboardThreads = await api.functional.discussionboard.threads.create(
    connection, { body: createInput },
  );
  typia.assert(created);
  TestValidator.equals("Thread not deleted at creation")(created.deleted_at)(null);

  // 2. Soft delete the created thread
  const delResult1 = await api.functional.discussionboard.threads.erase(
    connection, { id: created.id },
  );
  typia.assert(delResult1);
  TestValidator.equals("Soft delete success")(delResult1.success)(true);

  // 3. Repeatedly soft delete the same thread—should be idempotent
  const delResult2 = await api.functional.discussionboard.threads.erase(
    connection, { id: created.id },
  );
  typia.assert(delResult2);
  TestValidator.equals("Soft delete success (idempotent)")(delResult2.success)(true);

  // 4. There are no SDK functions for reading or updating threads by id, so
  // skip those steps. If such APIs existed, here we would attempt to retrieve or
  // update and expect denial/null/forbidden results.
}

