import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostSnapshot";

/**
 * Validate hard deletion of a post snapshot by an administrator.
 *
 * This test ensures that a post snapshot can be permanently deleted by an authorized administrator, with immediate removal and no possibility of soft restoration, in accordance with the schema that lacks soft-delete support. As part of the process:
 *   1. Create a post as the source for snapshotting.
 *   2. Create a post snapshot associated with the post.
 *   3. Delete the snapshot by ID using the admin-only endpoint.
 *   4. Attempt to delete the same snapshot again and verify that it results in a not found (404) error.
 *   5. (If snapshot retrieval endpoint existed, we would verify it cannot be found; since none is listed, we focus on delete behavior only.)
 *   6. Confirm all operations are compliance with role-based and audit restrictions, assuming the test context is running as admin.
 */
export async function test_api_discussionboard_test_delete_post_snapshot_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create a discussion board post
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    } satisfies IDiscussionboardPost.ICreate
  });
  typia.assert(post);

  // Step 2: Create a post snapshot to be deleted
  const snapshot: IPostSnapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: post.discussionboard_member_id,
      title: post.title,
      body: post.body,
      taken_at: new Date().toISOString()
    } satisfies IPostSnapshot.ICreate
  });
  typia.assert(snapshot);

  // Step 3: Delete the post snapshot (admin privilege)
  await api.functional.discussionboard.postSnapshots.erase(connection, { id: snapshot.id });

  // Step 4: Attempt to delete the same snapshot again should result in a 404 error
  await TestValidator.error("Deleting an already-deleted post snapshot results in not found error")(
    async () => {
      await api.functional.discussionboard.postSnapshots.erase(connection, { id: snapshot.id });
    }
  );
}

