import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_data_erasure_requests } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_data_erasure_requests";

/**
 * 검증: 회원이 최초 데이터 삭제 요청을 성공적으로 생성하는지 테스트합니다.
 *
 * 시나리오: 회원이(이전에 삭제 요청 이력이 없음) 필수 정보만을 넣어 dataErasureRequests 엔드포인트로 요청을 보냅니다.
 * 시스템은 새 요청을 status = 'pending'(혹은 논리상 동등 기본값)으로 저장하며, 요청 시각(requested_at) 기록이 남아야 합니다.
 * 응답은 저장된 erasure request 전체 레코드를 반환하며, 이 레코드는 요청 회원의 id, status, 요청 시점 등을 갖추고 있어야 합니다.
 * (해당 단계에서는 admin/moderator 개입이 필요 없습니다.)
 *
 * 테스트 절차:
 * 1. 신규 회원을 등록한다.
 * 2. 회원 id 등 필수정보로 data erasure request를 생성한다.
 * 3. 응답으로 반환된 erasure request가 DB에 올바로 저장되었는지,
