 *      - 'reviewed_at' < 'completed_at' (timestamps)
 *      - admin_remark is present and correct
 *      - All other fields remain correct (no unwanted changes)
 */
export async function test_api_discussionboard_dataErasureRequests_test_update_data_erasure_request_status_to_approved_with_admin_remark(
  connection: api.IConnection,
) {
  // 1. Create member
  const memberData: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberData,
  });
  typia.assert(member);

  // 2. Create pending data erasure request
  const erasureRequestData: Idiscussionboard_data_erasure_requests.ICreate = {
    discussionboard_member_id: member.id,
    status: "pending",
    requested_at: new Date().toISOString(),
    admin_remark: null,
  };
  const erasure = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: erasureRequestData,
  });
  typia.assert(erasure);

  // 3. Prepare admin update: approve with timestamps and remark
  const reviewedAt = new Date().toISOString();
  const completedAt = new Date(Date.parse(reviewedAt) + 1000 * 60).toISOString(); // +1min
  const adminRemark = "Approved for compliance, user identity confirmed.";

  const updateData: Idiscussionboard_data_erasure_requests.IUpdate = {
    status: "approved",
    reviewed_at: reviewedAt,
    completed_at: completedAt,
    admin_remark: adminRemark,
  };

  const updated = await api.functional.discussionboard.dataErasureRequests.update(
    connection,
    {
      id: erasure.id,
      body: updateData,
    }
  );
  typia.assert(updated);

  // 4. Validate result
