  TestValidator.predicate("reviewed_at set correctly")(
    !!updated.reviewed_at && !!updated.completed_at && updated.reviewed_at < updated.completed_at
  );
  TestValidator.equals("requested_at unchanged")(updated.requested_at)(erasure.requested_at);
}

