 * 4. Create a snapshot of the comment, using its current content, post id, member id, comment id, and setting a version (e.g., 2) and snapshot timestamp.
 * 5. Validate that the snapshot response correctly reflects the versioned comment state at snapshot time, with all fields matching those of the updated comment and snapshot params.
 */
export async function test_api_discussionboard_test_create_comment_snapshot_on_edit(connection: api.IConnection) {
