 * 4. All schema rules and required fields are respected. Response should reflect updated fields.
 */
export async function test_api_discussionboard_channels_test_update_channel_success_with_valid_data(connection: api.IConnection) {
  // 1. Create the initial channel (dependency for test subject ID; must use realistic values)
  const originalInput: IDiscussionboardChannel.ICreate = {
    code: `code_${RandomGenerator.alphaNumeric(8)}`,
    name: `Channel ${RandomGenerator.alphaNumeric(4)}`,
