  const updatePayload: IDiscussionboardChannel.IUpdate = {
    name: `${created.name} - Updated`, // update the name
    description: "Updated description for the channel.", // update description
    // Optionally, change position/active if needed
    position: created.position + 1,
    active: false
  };

  const updated: IDiscussionboardChannel = await api.functional.discussionboard.channels.update(connection, {
    id: created.id,
