/**
 * Verify correct role-based filtering of members in the discussion board.
 *
 * This test ensures that searching for members by a specific role returns only those members,
 * and that no others are included in the result. It covers the following flow:
 *
 * 1. Create multiple members, each with a unique username and email, and a mix of all valid roles ("member", "moderator", "admin").
 * 2. Select one of the roles as the filtering target (e.g., "moderator").
 * 3. Use the members.index (PATCH /discussionboard/members) endpoint to search with a filter for the selected role only.
 * 4. Assert that all returned members have the expected role
 * 5. Assert that no members with other roles appear in the result
 * 6. Assert that the returned list is not empty (at least the created users with that role exist in results)
 * 7. Assert that all users of the filtered role that were created are present
 *
 * Error/edge conditions implicitly covered:
 * - The members with other roles are not accidentally included
 * - Filtering by each role works independently (though this test covers one role for brevity)
 */
export async function test_api_discussionboard_test_search_members_with_role_filter(
  connection: api.IConnection,
) {
  // 1. Create members with all 3 roles
  const roles: ("member" | "moderator" | "admin")[] = ["member", "moderator", "admin"];
  const createdMembers: IDiscussionboardMember[] = [];
  for (const role of roles) {
    // For each role, create 2 members to ensure more than 1 result per role
    for (let i = 0; i < 2; ++i) {
      const username = RandomGenerator.alphaNumeric(8) + `_${role}_${i}`;
      const email = `${username}@example.com`;
      const member = await api.functional.discussionboard.members.create(connection, {
        body: {
          username,
          email: email as string & tags.Format<"email">,
          hashed_password: RandomGenerator.alphaNumeric(16),
          role,
          is_active: true,
        } satisfies IDiscussionboardMember.ICreate,
      });
      typia.assert(member);
      createdMembers.push(member);
    }
  }

  // 2. Pick one role to filter on (e.g., "moderator")
  const targetRole: "member" | "moderator" | "admin" = "moderator";
  const membersWithTargetRole = createdMembers.filter((m) => m.role === targetRole);

  // 3. Search for members having only that role
  const searchResult = await api.functional.discussionboard.members.index(connection, {
    body: {
      role: targetRole,
      pagination: {
        page: 1,
        limit: 100,
      },
    } satisfies IDiscussionboardMember.IRequest,
  });
  typia.assert(searchResult);

  // 4. Assert that all returned members have the requested role
  for (const member of searchResult.data) {
    TestValidator.equals("returned role matches filter")(member.role)(targetRole);
  }
  // 5. Assert that members with non-matching roles are not present
  for (const member of searchResult.data) {
    TestValidator.predicate(`member is not another role`)(member.role === targetRole);
  }
  // 6. The result set includes at least all created members with this role
  for (const created of membersWithTargetRole) {
    TestValidator.predicate("created member present in search result")(
      searchResult.data.some((found) => found.id === created.id),
    );
  }
}

