import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReport";

/**
 * Validate update operations for discussion board post reports, as performed by a moderator with different valid and invalid data scenarios.
 *
 * Business context: Moderators need to update certain fields of post reports for accuracy, audit corrections, or resolving disputes. Only editable schema-defined fields should be accepted; attempts to update forbidden fields or use invalid inputs must be properly rejected by the backend.
 *
 * Test Steps:
 * 1. Create a post to serve as the target for moderation reports.
 * 2. Create a post report record attached to that post.
 * 3. Attempt to update the report's editable fields (report_type_id, description) with new values. Check that changes persist in the updated report object.
 * 4. Try to update with forbidden fields (simulate by passing extra fields in the update body that don't exist in the schema - should be ignored or trigger errors by type system, so this step is skipped at code level if not technically possible).
 * 5. Try to update with empty body, and with partial update (only description).
 * 6. Try to update a report with a non-existent id and confirm error.
 * 7. Try to update with an empty description (should succeed since nullable/optional).
 */
export async function test_api_discussionboard_test_update_post_report_fields_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a post
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. Create a post report attached to the post
  const originalReport: IPostReport = await api.functional.discussionboard.postReports.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
      report_type_id: typia.random<string & tags.Format<"uuid">>(),
      description: RandomGenerator.paragraph()(1),
      created_at: new Date().toISOString(),
    } satisfies IPostReport.ICreate,
  });
  typia.assert(originalReport);

  // 3. Update editable fields (report_type_id, description) with new values
  const newReportTypeId = typia.random<string & tags.Format<"uuid">>();
  const newDescription = RandomGenerator.paragraph()(1);
  const updatedReport: IPostReport = await api.functional.discussionboard.postReports.update(connection, {
    id: originalReport.id,
    body: {
      report_type_id: newReportTypeId,
      description: newDescription,
    } satisfies IPostReport.IUpdate,
  });
  typia.assert(updatedReport);
  TestValidator.equals("report_type_id updated")(updatedReport.report_type_id)(newReportTypeId);
  TestValidator.equals("description updated")(updatedReport.description)(newDescription);

  // 4. Try to update with forbidden fields: SKIPPED (not implementable by type system)
  // (Only schema-defined fields can be set according to types; violating this would cause TS error.)

  // 5. Try update with empty body (should not make any changes, but at least test the behavior)
  const emptyUpdate = await api.functional.discussionboard.postReports.update(connection, {
    id: originalReport.id,
    body: {},
  });
  typia.assert(emptyUpdate);
  // If the API returns the unmodified report, the values should remain as previously updated
  TestValidator.equals("no changes after empty update")(emptyUpdate.report_type_id)(newReportTypeId);
  TestValidator.equals("no changes after empty update")(emptyUpdate.description)(newDescription);

  // 5b. Try update with partial body (only description)
  const partialDescription = RandomGenerator.paragraph()(1);
  const partialUpdate = await api.functional.discussionboard.postReports.update(connection, {
    id: originalReport.id,
    body: {
      description: partialDescription
    },
  });
  typia.assert(partialUpdate);
  TestValidator.equals("partial update description")(partialUpdate.description)(partialDescription);

  // 6. Try to update a report with non-existent id (should error)
  await TestValidator.error("update with non-existent id")(() =>
    api.functional.discussionboard.postReports.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        report_type_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 7. Try to update with empty description (should accept null or empty)
  const updatedWithEmptyDesc = await api.functional.discussionboard.postReports.update(connection, {
    id: originalReport.id,
    body: { description: "" },
  });
  typia.assert(updatedWithEmptyDesc);
  TestValidator.equals("empty description allowed")(updatedWithEmptyDesc.description)("");
}

