  TestValidator.equals("admin2.assigned_by_admin_id")(admin2.assigned_by_admin_id)(member2.id);
  TestValidator.equals("admin2.revoked_at")(admin2.revoked_at)(null);

  // Now, assign member1 as admin, with member2 as assigner
  const admin1_input = {
    member_id: member1.id,
    assigned_by_admin_id: admin2.id, // Use the created admin id
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies IDiscussionboardAdmin.ICreate;
