    await api.functional.discussionboard.admins.create(connection, { body: bad_admin_input });
  });

  // 4b. Omit required fields (missing member_id)
  const incomplete_admin_input = {
    // member_id missing
    assigned_by_admin_id: admin2.id,
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } as any; // purposely invalid to simulate missing required field
  TestValidator.error("missing required member_id fails")(async () => {
