import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * Test revoking a moderator assignment by id by setting revoked_at.
 *
 * This test covers the following steps:
 * 1. Create both a regular member and an admin member.
 * 2. Assign the moderator role to the member using the admin's id.
 * 3. Revoke the moderator assignment using the provided delete endpoint, ensuring revoked_at is set.
 * 4. Assert that the returned assignment's revoked_at is now non-null and the state is as expected.
 * 5. Attempt to revoke the same assignment again, testing idempotency (should return the same, already revoked state, not error).
 * 6. Attempt to revoke a non-existent moderator assignment (should return error).
 * 7. Ensure that the related member profile (moderated member) is not directly affected by this operation beyond the assignment status.
 * 8. (If possible with API and DTO) Attempt revocation as a non-admin and ensure error is thrown.
 */
export async function test_api_discussionboard_test_soft_revoke_moderator_assignment_and_error_cases(connection: api.IConnection) {
  // 1. Create admin and member accounts
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "admin",
    is_active: true,
  };
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: adminInput,
  });
  typia.assert(admin);

  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Assign moderator role
  const assignedAt = new Date().toISOString();
  const modAssignInput: IDiscussionboardModerator.ICreate = {
    member_id: member.id,
    assigned_by_admin_id: admin.id,
    assigned_at: assignedAt,
    expires_at: null,
    revoked_at: null,
  };
  const moderator = await api.functional.discussionboard.moderators.create(connection, {
    body: modAssignInput,
  });
  typia.assert(moderator);

  // 3. Revoke moderator assignment
  const revoked = await api.functional.discussionboard.moderators.erase(connection, { id: moderator.id });
  typia.assert(revoked);

  // 4. Confirm revoked_at is set (non-null, date increases, not affected fields)
  TestValidator.predicate("revoked_at was set and is a date")(!!revoked.revoked_at && typeof revoked.revoked_at === "string");
  TestValidator.equals("moderator assignment remains for historical reference")(revoked.member_id)(member.id);
  TestValidator.equals("mod assignment admin remains reference")(revoked.assigned_by_admin_id)(admin.id);
  TestValidator.equals("mod assignment assigned_at unchanged")(revoked.assigned_at)(assignedAt);

  // 5. Double-revoke (idempotency)
  const revokedAgain = await api.functional.discussionboard.moderators.erase(connection, { id: moderator.id });
  typia.assert(revokedAgain);
  TestValidator.equals("revoked moderator idempotent")(revokedAgain.revoked_at)(revoked.revoked_at);

  // 6. Revoke non-existent moderator (expect error)
  await TestValidator.error("non-existent mod assignment id fails")(() =>
    api.functional.discussionboard.moderators.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 7. Verify the member is not modified
  const loadedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: member.username + "_readcheck",
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(loadedMember);
  TestValidator.equals("related member not altered by moderator revoke")(member.is_active)(true);
