  TestValidator.equals("code matches")(fetched.code)(prefInput.code);
  TestValidator.equals("email_enabled matches")(fetched.email_enabled)(prefInput.email_enabled);
  TestValidator.equals("inapp_enabled matches")(fetched.inapp_enabled)(prefInput.inapp_enabled);
