/**
 * Validates that creating a duplicate post report (same post, same member, same report type) is rejected.
 *
 * Business context:
 * It must not be possible for the same member to file the same report type against the same post more than once. This check is crucial for preventing spam or abuse of reporting functionality. The test ensures enforcement of the uniqueness constraint on post reports (per [post, reporter, type] tuple).
 *
 * Step-by-step process:
 * 1. Create a discussion board member for use as the reporting account.
 * 2. Create a discussion board post to serve as the report target (with required linked thread and board, all set as new UUIDs).
 * 3. Create a report type record (using valid enum/code, active=true).
 * 4. Create the first post report for the member, post, and report type—should succeed.
 * 5. Attempt to create a duplicate post report (same member, post, and type)—should fail with an error (due to unique constraint).
 * 6. Confirm the first report was created successfully, and the duplicate is rejected (runtime error is thrown).
 */
export async function test_api_discussionboard_test_create_post_report_with_duplicate_returns_error(
  connection: api.IConnection,
) {
  // 1. Create member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create post (with thread_id and board_id as required UUIDs)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: threadId,
    discussionboard_member_id: member.id,
    discussionboard_board_id: boardId,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_deleted: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Create (active) report type
  const reportTypeInput: IDiscussionboardReportType.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    display_name: RandomGenerator.paragraph()(),
    description: RandomGenerator.paragraph()(),
    active: true,
    created_at: new Date().toISOString(),
  };
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, { body: reportTypeInput });
  typia.assert(reportType);

  // 4. Create a report (should succeed)
  const now = new Date().toISOString();
  const postReportInput: IPostReport.ICreate = {
    discussionboard_post_id: post.id,
    reporter_member_id: member.id,
    report_type_id: reportType.id,
    description: RandomGenerator.paragraph()(),
    created_at: now,
  };
  const report = await api.functional.discussionboard.postReports.create(connection, { body: postReportInput });
  typia.assert(report);

  // 5. Attempt to create a duplicate report (should fail with error)
  await TestValidator.error("duplicate post report must be rejected")(
    async () => {
      await api.functional.discussionboard.postReports.create(connection, { body: postReportInput });
    },
  );
}

