 * - Accepting unintended fields poses a risk of incorrect data persistence or silent API changes.
 *
 * Step-by-step process:
 * 1. Register a new member (dependency setup).
 * 2. Create a notification template for reference (dependency setup).
 * 3. Register a valid notification preference for the member and template (dependency setup).
 * 4. Attempt to update the notification preference, sending a request body which is correct except for an additional property (e.g., "unexpected_field": "foo").
 * 5. Assert that the API call fails with a schema validation error; the server must not accept or ignore non-schema fields.
 * 6. Optionally, re-read the notification preference to ensure that no changes were applied to its official schema fields (proving the update was entirely rejected if possible).
 */
export async function test_api_discussionboard_notificationPreferences_test_update_notification_preference_with_invalid_schema_field(
  connection: api.IConnection,
) {
  // 1. Register a member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a notification template
  const template = await api.functional.discussionboard.notificationTemplates.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(10),
      name: RandomGenerator.paragraph()(2),
      subject: RandomGenerator.paragraph()(1),
      body: RandomGenerator.alphabets(100),
      is_active: true,
      // description is optional
    },
  });
  typia.assert(template);

  // 3. Register a valid notification preference for the member/template
  const pref = await api.functional.discussionboard.notificationPreferences.create(connection, {
    body: {
      discussionboard_member_id: member.id,
      code: template.code,
      email_enabled: true,
      inapp_enabled: false,
      browser_enabled: true,
    },
  });
  typia.assert(pref);

  // 4. Attempt update with an additional invalid property
  const invalidUpdate = {
    discussionboard_member_id: member.id,
    code: template.code,
    email_enabled: false,
    inapp_enabled: true,
    browser_enabled: false,
    created_at: pref.created_at,
    updated_at: new Date().toISOString(),
    unexpected_field: "SHOULD_FAIL", // <-- non-schema extra field
  };

  // 5. Assert that the API rejects the call because of invalid schema
  await TestValidator.error("Should fail when extra property is present")(() =>
    api.functional.discussionboard.notificationPreferences.update(connection, {
      id: pref.id,
      body: invalidUpdate as any,
    }),
  );
