 *
 * Steps:
 * 1. Create an initial discussion board post by member A (the owner/editor).
 * 2. Have member A create a post snapshot for the post (so editor_member_id = member A's id).
 * 3. Log in as a different member (member B) who is neither the original editor nor an admin.
 * 4. Attempt to update the snapshot with member B's credentials.
 * 5. Expect an authorization error (forbidden/not allowed) and verify that the snapshot is not changed.
 */
export async function test_api_discussionboard_test_update_post_snapshot_unauthorized_user(connection: api.IConnection) {
  // 1. Create a post as member A
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
