import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostSnapshot";

/**
 * Validate that a non-editor, non-admin user cannot update a post snapshot (authorization enforcement).
 *
 * This test ensures that only the original editor of a post snapshot or a system admin has the privilege to update a post snapshot. Any other user attempting to update should receive an authorization error and see no changes performed in the database.
 *
 * Steps:
 * 1. Create an initial discussion board post by member A (the owner/editor).
 * 2. Have member A create a post snapshot for the post (so editor_member_id = member A's id).
 * 3. Log in as a different member (member B) who is neither the original editor nor an admin.
 * 4. Attempt to update the snapshot with member B's credentials.
 * 5. Expect an authorization error (forbidden/not allowed) and verify that the snapshot is not changed.
 *
 * (Note: Since no explicit user authentication/role switching API is present in provided SDK, the test simulates switching by using different member IDs. If a read-back API for post snapshots existed, it would be used to verify the snapshot was not mutated, but such verification is not possible here.)
 */
export async function test_api_discussionboard_test_update_post_snapshot_unauthorized_user(connection: api.IConnection) {
  // 1. Create a post as member A
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberAId,
      discussionboard_board_id: boardId,
      title: "Member A's post",
      body: "Original content.",
      is_deleted: false,
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(post);

  // 2. Create a post snapshot as member A
  const takenAt = new Date().toISOString() as string & tags.Format<"date-time">;
  const snapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: memberAId,
      title: post.title,
      body: post.body,
      taken_at: takenAt,
    },
  });
  typia.assert(snapshot);

  // 3. Emulate login as member B (no real auth, just switch ID)
  const memberBId = typia.random<string & tags.Format<"uuid">>();

  // 4. Attempt to update the snapshot as member B and expect authorization error
  await TestValidator.error("Non-editor/non-admin cannot update post snapshot")(
    async () => {
      await api.functional.discussionboard.postSnapshots.update(connection, {
        id: snapshot.id,
        body: {
          title: "Unauthorized update attempt",
          body: "This should not succeed.",
          taken_at: takenAt,
          editor_member_id: memberBId,
        },
      });
    },
  );
  // (If a snapshot GET API were available, we would fetch and check for unchanged content.)
}

