import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Test unique constraint enforcement when updating board categories.
 *
 * This test verifies that the discussion board category update endpoint denies
 * attempts to set the name or code to duplicate values that already exist for
 * another category. This ensures business rules are enforced to prevent
 * duplicate categories, which is critical for navigation, admin config, and routing.
 *
 * Steps:
 * 1. Create the first board category with unique name and code
 * 2. Create a second board category with different (also unique) name and code
 * 3. Attempt to update the second category's name to match the first's name (should fail)
 * 4. Attempt to update the second category's code to match the first's code (should fail)
 * 5. (Extra edge case) Attempt to update the second category's name AND code at once to match the first's (should fail)
 *
 * For each failed update, assert that a unique constraint violation error is thrown.
 */
export async function test_api_discussionboard_test_update_board_category_with_duplicate_name_or_code(
  connection: api.IConnection,
) {
  // 1. Create the first board category with unique name and code
  const first: IDiscussionboardBoardCategory =
    await api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        name: RandomGenerator.alphaNumeric(12),
        code: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
        position: typia.random<number & tags.Type<"int32">>(),
      } satisfies IDiscussionboardBoardCategory.ICreate,
    });
  typia.assert(first);

  // 2. Create a second board category with a different unique name and code
  const second: IDiscussionboardBoardCategory =
    await api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        name: RandomGenerator.alphaNumeric(12),
        code: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
        position: typia.random<number & tags.Type<"int32">>(),
      } satisfies IDiscussionboardBoardCategory.ICreate,
    });
  typia.assert(second);

  // 3. Attempt to update the second category's name to the first's name (should fail)
  await TestValidator.error("duplicate category name should fail")(
    async () => {
      await api.functional.discussionboard.boardCategories.update(connection, {
        id: second.id,
        body: {
          name: first.name,
        } satisfies IDiscussionboardBoardCategory.IUpdate,
      });
    },
  );

  // 4. Attempt to update the second category's code to the first's code (should fail)
  await TestValidator.error("duplicate category code should fail")(
    async () => {
      await api.functional.discussionboard.boardCategories.update(connection, {
        id: second.id,
        body: {
          code: first.code,
        } satisfies IDiscussionboardBoardCategory.IUpdate,
      });
    },
  );

  // 5. Attempt to update BOTH name and code to match the first (should fail)
  await TestValidator.error("duplicate category name and code should fail")(
    async () => {
      await api.functional.discussionboard.boardCategories.update(connection, {
        id: second.id,
        body: {
          name: first.name,
          code: first.code,
        } satisfies IDiscussionboardBoardCategory.IUpdate,
      });
    },
  );
}

