 *
 * Steps:
 * 1. Create a discussion board post (dependency for reporting)
 * 2. Create a post report targeting the created post
 * 3. Retrieve the post report by its ID and verify all fields match
 * 4. Attempt to retrieve a report with a random UUID (should return null)
 */
export async function test_api_discussionboard_test_retrieve_existing_and_nonexistent_post_report_by_id(
  connection: api.IConnection,
) {
  // 1. Create a discussion board post
  const postBody: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_deleted: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const createdPost = await api.functional.discussionboard.posts.create(connection, { body: postBody });
  typia.assert(createdPost);

  // 2. Create a post report referencing the above post
  const reportBody: IPostReport.ICreate = {
    discussionboard_post_id: createdPost.id,
    reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
    report_type_id: typia.random<string & tags.Format<"uuid">>(),
    description: RandomGenerator.paragraph()(),
    created_at: new Date().toISOString(),
  };
  const createdReport = await api.functional.discussionboard.postReports.create(connection, { body: reportBody });
  typia.assert(createdReport);

  // 3. Retrieve the created post report by its id
  const fetchedReport = await api.functional.discussionboard.postReports.at(connection, { id: createdReport.id });
  typia.assert(fetchedReport);

  // Assert all major fields match what was returned at creation
  TestValidator.equals("post report: id")(fetchedReport.id)(createdReport.id);
  TestValidator.equals("post report: post id")(fetchedReport.discussionboard_post_id)(createdReport.discussionboard_post_id);
  TestValidator.equals("post report: reporter")(fetchedReport.reporter_member_id)(createdReport.reporter_member_id);
  TestValidator.equals("post report: report type")(fetchedReport.report_type_id)(createdReport.report_type_id);
  TestValidator.equals("post report: description")(fetchedReport.description)(createdReport.description);
  TestValidator.equals("post report: created_at")(fetchedReport.created_at)(createdReport.created_at);

  // 4. Attempt to fetch a non-existent post report by random id; expect null
  const randomId = typia.random<string & tags.Format<"uuid">>();
  const notFoundReport = await api.functional.discussionboard.postReports.at(connection, { id: randomId });
  TestValidator.equals("fetching unknown post report yields null")(notFoundReport)(null);
}

