import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Validate updating of moderation report type fields and related error conditions.
 *
 * 1. Create two report types (A and B) with different codes and display_names.
 * 2. Update type A: change its code, display_name, description, and active flag.
 *    - Verify each changed field persists.
 * 3. Attempt to update type A's code to duplicate type B's code.
 *    - Confirm uniqueness violation error.
 * 4. Attempt invalid updates:
 *    - Add a non-existent property in the body.
 *    - Use an invalid id (non-existent UUID) for the update.
 *    - Set code/display_name to empty string or forbidden value (edge case for business validation).
 * 5. Test toggling of active flag (true→false→true), verifying persistence after each.
 */
export async function test_api_discussionboard_test_update_report_type_fields_and_uniqueness_rule(
  connection: api.IConnection,
) {
  // 1. Create two report types (A & B)
  const now = new Date();
  const typeA = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: `testcodeA_${RandomGenerator.alphaNumeric(6)}`,
      display_name: `신고유형A_${RandomGenerator.alphabets(5)}`,
      description: "테스트A: 최초 생성된 유형입니다.",
      active: true,
      created_at: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(typeA);
  const typeB = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: `testcodeB_${RandomGenerator.alphaNumeric(6)}`,
      display_name: `신고유형B_${RandomGenerator.alphabets(6)}`,
      description: "테스트B: 비교용 유형입니다.",
      active: false,
      created_at: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(typeB);

  // 2. Update typeA fields
  const updateInput = {
    code: `${typeA.code}_updated`,
    display_name: `${typeA.display_name}_수정`,
    description: "(수정됨) 신고 유형 설명 신규변경!",
    active: false,
  } satisfies IDiscussionboardReportType.IUpdate;
  const updated = await api.functional.discussionboard.reportTypes.update(connection, {
    id: typeA.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("updated code")(updated.code)(updateInput.code);
  TestValidator.equals("updated display_name")(updated.display_name)(updateInput.display_name);
  TestValidator.equals("updated description")(updated.description)(updateInput.description);
  TestValidator.equals("updated active")(updated.active)(updateInput.active);

  // 3. Uniqueness violation: set typeA's code to typeB's (should fail)
  await TestValidator.error("Duplicate code must fail")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typeA.id,
      body: { code: typeB.code },
    })
  );

  // 4.1 Invalid: non-existent property in update body (TS error: skip runtime)
  // 4.2 Invalid id (non-existent UUID)
  await TestValidator.error("Non-existent id should fail")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { code: "shouldnotmatter" } satisfies IDiscussionboardReportType.IUpdate,
    })
  );
  // 4.3 Invalid update: code or display_name is empty string
  await TestValidator.error("Empty code should fail")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typeA.id,
      body: { code: "" },
    })
  );
  await TestValidator.error("Empty display_name should fail")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typeA.id,
      body: { display_name: "" },
    })
  );

  // 5. Toggle 'active' on and off and verify
  const resDeactivated = await api.functional.discussionboard.reportTypes.update(connection, {
    id: typeA.id,
    body: { active: false },
  });
  typia.assert(resDeactivated);
  TestValidator.equals("active should be deactivated")(resDeactivated.active)(false);
  const resActivated = await api.functional.discussionboard.reportTypes.update(connection, {
    id: typeA.id,
    body: { active: true },
  });
  typia.assert(resActivated);
  TestValidator.equals("active should be re-activated")(resActivated.active)(true);
}

