import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Validate updating of moderation report type fields and related error conditions.
 *
 * Business purpose:
 *   - Allows admins to modify the code, display_name, description, and active state of moderation report type records.
 *   - Ensures data integrity via code uniqueness, correct field validation, and proper persistence.
 *   - Confirms that only schema-permitted fields can be modified, improper mutations are prevented, and error states are surfaced per API contract.
 *
 * Test Scenario:
 * 1. Create two report types with different unique codes/display_names.
 * 2. Update type A's fields (code, display_name, description, active), verify all changes persisted.
 * 3. Attempt to update type A's code to match type B's code (should fail due to uniqueness constraint).
 * 4. Attempt invalid updates:
 *    - Use non-existent (random) id (should fail)
 *    - Use empty string for code or display_name (should fail)
 * 5. Toggle type A's active flag (deactivate/activate), verify state after each update.
 */
export async function test_api_discussionboard_test_update_report_type_fields_and_uniqueness_rule(
  connection: api.IConnection,
) {
  // 1. Create two report types A and B
  const now = new Date();
  const typeA = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: `testcodeA_${RandomGenerator.alphaNumeric(7)}`,
      display_name: `신고유형A_${RandomGenerator.alphabets(5)}`,
      description: "테스트 생성 A",
      active: true,
      created_at: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(typeA);
  const typeB = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: `testcodeB_${RandomGenerator.alphaNumeric(7)}`,
      display_name: `신고유형B_${RandomGenerator.alphabets(6)}`,
      description: "테스트 생성 B",
      active: false,
      created_at: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(typeB);

  // 2. Update type A's fields, check persist
  const updateInput: IDiscussionboardReportType.IUpdate = {
    code: `${typeA.code}_fix`,
    display_name: `${typeA.display_name} (수정됨)`,
    description: "관리자에 의해 설명이 수정됨.",
    active: false,
  };
  const updated = await api.functional.discussionboard.reportTypes.update(connection, {
    id: typeA.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("updated code")(updated.code)(updateInput.code);
  TestValidator.equals("updated display_name")(updated.display_name)(updateInput.display_name);
  TestValidator.equals("updated description")(updated.description)(updateInput.description);
  TestValidator.equals("updated active")(updated.active)(updateInput.active);

  // 3. Code uniqueness error: change typeA code to typeB code
  await TestValidator.error("duplicate code error")(() =>
    api.functional.discussionboard.reportTypes.update(connection, {
      id: typeA.id,
      body: { code: typeB.code } satisfies IDiscussionboardReportType.IUpdate,
    })
