  const updateInput = {
    key: config1.key + "_updated",
    value: "200",
    description: "Changed max posts to 200."
  } satisfies IDiscussionboardConfiguration.IUpdate;
  const updatedConfig = await api.functional.discussionboard.configurations.update(connection, {
    id: config1.id,
