        id: typia.random<string & tags.Format<"uuid">>(),
        body: { key: "ghost_key", value: "ghost_value" },
      });
    }
  );

  // 5. Try to update using a field not in schema (should trigger schema validation error, but this is not implementable via TypeScript - skip per guideline)
}

