/**
 * Test searching and paginating the list of moderation report types using various filter combinations.
 *
 * Steps:
 * 1. Create multiple distinct report types with different code, display_name, description, active status, and created_at values.
 * 2. Request the /discussionboard/reportTypes list endpoint using:
 *    a. Filters for specific status (active/inactive)
 *    b. Creation date range (created_at)
 *    c. Partial and full matches on code or display_name
 *    d. Pagination: limit and page params
 * 3. Validate API returns only report types matching each filter condition.
 * 4. Test edge cases:
 *    - Query that matches no records (should return empty list)
 *    - Query that matches only one record
 *    - Query just enough to fill a page (and check pagination info)
 * 5. Try using invalid filter parameter types and ensure API returns error (not ignoring or returning all records).
 */
export async function test_api_discussionboard_test_list_report_types_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create sample report types with diverse values
  const sampleTypes = [
    {
      code: 'spam',
      display_name: 'Spam',
      description: 'Unwanted advertisement',
      active: true,
      created_at: new Date('2024-07-01T10:00:00Z').toISOString(),
    },
    {
      code: 'abuse',
      display_name: 'Abuse',
      description: 'Offensive language',
      active: true,
      created_at: new Date('2024-04-01T12:00:00Z').toISOString(),
    },
    {
      code: 'test-old',
      display_name: 'Old Report',
      description: 'Report created far in the past',
      active: false,
      created_at: new Date('2022-01-01T00:00:00Z').toISOString(),
    },
    {
      code: 'inactive-type',
      display_name: 'Inactive',
      description: 'Inactive type',
      active: false,
      created_at: new Date('2024-07-01T08:00:00Z').toISOString(),
    },
    {
      code: 'duplicate',
      display_name: 'Duplicate',
      description: 'Repeated report',
      active: true,
      created_at: new Date('2024-07-01T07:00:00Z').toISOString(),
    },
  ];

  const createdTypes = [];
  for (const t of sampleTypes) {
    const created = await api.functional.discussionboard.reportTypes.create(connection, { body: t });
    typia.assert(created);
    createdTypes.push(created);
  }

  // 2a. Filter for active report types
  let result = await api.functional.discussionboard.reportTypes.index(connection, { body: { active: true } });
  typia.assert(result);
  TestValidator.predicate('Only active types')(result.data.every(r => r.active));

  // 2b. Filter for inactive report types
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { active: false } });
  typia.assert(result);
  TestValidator.predicate('Only inactive types')(result.data.every(r => !r.active));

  // 2c. Filter by partial code
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { code: 'sp' } });
  typia.assert(result);
  TestValidator.predicate('Partial code match valid')(result.data.every(r => r.code.includes('sp')));

  // 2d. Filter by display_name
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { display_name: 'Inactive' } });
  typia.assert(result);
  TestValidator.predicate('Display name match')(result.data.every(r => r.display_name.includes('Inactive')));

  // 2e. Filter by creation date
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { created_at: '2024-07-01T10:00:00Z' } });
  typia.assert(result);
  TestValidator.predicate('Created date match')(result.data.every(r => r.created_at === '2024-07-01T10:00:00Z'));

  // 3. Edge case: query matches nothing
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { code: 'nonexistent' } });
  typia.assert(result);
  TestValidator.equals('Empty result')(result.data.length)(0);

  // 3b. Edge case: query matches one record
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { code: 'duplicate' } });
  typia.assert(result);
  TestValidator.equals('Single hit')(result.data.length)(1);
  TestValidator.equals('Code check')(result.data[0].code)('duplicate');

  // 3c. Edge case: full-page result (simulate limit)
  result = await api.functional.discussionboard.reportTypes.index(connection, { body: { active: true } });
  typia.assert(result);
  // Assume all created actives fit a page. If not, additional pagination tests can be added here.

  // 4. Invalid filter parameter, should throw error
  await TestValidator.error('Invalid param type should cause error')(async () => {
    // @ts-expect-error - purposely wrong type for active
    await api.functional.discussionboard.reportTypes.index(connection, { body: { active: 'wrong' } });
  });
}

