import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * 테스트할 내용: 동일한 채널 내에서 이미 사용 중인 코드(code) 또는 이름(name)으로 섹션을 생성하려고 시도하는 경우, 고유성 제약 조건 위반으로 에러가 반환되는지 검증합니다.
 *
 * 비즈니스 목적: 게시판 섹션의 코드/이름 고유성 보장은 데이터 무결성과 내비게이션/링킹 신뢰성을 확보하기 위한 필수 요구 조건입니다. 중복 코드나 이름으로 인한 데이터 오류 및 예기치 않은 UI/라우팅 문제를 미연에 방지합니다.
 *
 * 단계별 검증 시나리오:
 * 1. 고유한 코드/이름으로 부모 채널을 생성합니다.
 * 2. 해당 채널 아래에, 특정 코드 및 이름을 가진 최초 섹션을 생성합니다.
 * 3. 동일 채널 내부에서 다음 3가지 케이스로 섹션 생성 시도를 합니다.
 *    a) 코드만 중복, 이름은 다른 경우 → 실패(에러 반환)
 *    b) 이름만 중복, 코드는 다른 경우 → 실패(에러 반환)
 *    c) 코드와 이름 모두 중복인 경우   → 실패(에러 반환)
 *
 * 각 시도에서 API가 고유성 제약조건 위반으로 반드시 에러를 반환해야 합니다.
 */
export async function test_api_discussionboard_test_create_section_with_duplicate_code_or_name_returns_error(
  connection: api.IConnection,
) {
  // 1. 고유한 랜덤 코드/이름으로 부모 채널 생성
  const channelCreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  } satisfies IDiscussionboardChannel.ICreate;
  const channel = await api.functional.discussionboard.channels.create(connection, { body: channelCreate });
  typia.assert(channel);

  // 2. 첫 번째 섹션 생성 (특정 코드, 이름 지정)
  const sectionCode = RandomGenerator.alphaNumeric(7);
  const sectionName = RandomGenerator.paragraph()(2);
  const sectionCreate: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    code: sectionCode,
    name: sectionName,
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  };
  const section = await api.functional.discussionboard.sections.create(connection, { body: sectionCreate });
  typia.assert(section);

  // 3a. 코드 중복(이름은 다름) 시도 → 실패해야 함
  const dupCodeSection: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    code: sectionCode, // 중복 코드
    name: RandomGenerator.paragraph()(2), // 다른 이름
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  };
  await TestValidator.error("동일 채널 내 코드 중복 생성 시 에러")(async () => {
    await api.functional.discussionboard.sections.create(connection, { body: dupCodeSection });
  });

  // 3b. 이름 중복(코드는 다름) 시도 → 실패해야 함
  const dupNameSection: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(8), // 다른 코드
    name: sectionName, // 중복 이름
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  };
  await TestValidator.error("동일 채널 내 이름 중복 생성 시 에러")(async () => {
    await api.functional.discussionboard.sections.create(connection, { body: dupNameSection });
  });

  // 3c. 코드, 이름 모두 중복 시도 → 실패해야 함
  const dupBothSection: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    code: sectionCode,
    name: sectionName,
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  };
  await TestValidator.error("동일 채널 내 코드/이름 모두 중복 시 에러")(async () => {
    await api.functional.discussionboard.sections.create(connection, { body: dupBothSection });
  });
}

