import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMember";

/**
 * 회원 가입 일자(created_at) 기준 범위 필터가 정상적으로 동작하는지 검증합니다.
 *
 * - 명확한 시각 차를 두고 2명 이상의 회원을 등록한다(테스트의 재현성을 위해, 가입 시각이 컨트롤될 수 있도록 사전 시차 적용)
 * - 각 가입 시각을 기준으로 created_at_from/created_at_to 필터 파라미터 값 범위를 생성한다
 * - 각 범위 조합별로 검색 시 포함/제외가 정확히 일치하는지 검증한다
 * - pagination (page/limit) 옵션 조합도 함께 검증한다
 * - 검색 결과로 반환된 data 배열의 모든 객체의 created_at값이 쿼리 범위와 일치함을 체크한다
 * - page/limit 조정에 따른 반환 데이터 truncation도 확인한다
 */
export async function test_api_discussionboard_test_search_members_by_date_range(connection: api.IConnection) {
  // 1. 서로 다른 가입 시각으로 회원 2명 이상 생성
  // -- 첫번째 회원 생성
  const timeA = new Date(Date.now() - 60 * 1000).toISOString(); // 1분 전
  const userA = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true
    }
  });
  typia.assert(userA);

  // -- 두번째 회원 생성 (현재 시각)
  const timeB = new Date().toISOString();
  const userB = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true
    }
  });
  typia.assert(userB);

  // 2. created_at_from~to 쿼리 - 1분 전부터 지금까지: 둘 다 포함되어야 함
  const resultsAll = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: timeA,
      created_at_to: timeB
    }
  });
  typia.assert(resultsAll);
  // 2-1. 두 회원 모두 포함 확인
  TestValidator.predicate("두 회원 모두 포함됨")(
    resultsAll.data.some(r=>r.id===userA.id) && resultsAll.data.some(r=>r.id===userB.id)
  );
  // 2-2. 결과의 각 레코드 created_at이 범위 내인지 확인
  for (const member of resultsAll.data) {
    TestValidator.predicate("created_at 범위 검증")(
      member.created_at >= timeA && member.created_at <= timeB
    );
  }

  // 3. from~to == timeA ~ timeA (userA만 포함)
  const resultsA = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: timeA,
      created_at_to: timeA
    }
  });
  typia.assert(resultsA);
  TestValidator.predicate("userA만 포함")(
    resultsA.data.length===1 && resultsA.data[0].id===userA.id
  );

  // 4. from~to == timeB ~ timeB (userB만 포함)
  const resultsB = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: timeB,
      created_at_to: timeB
    }
  });
  typia.assert(resultsB);
  TestValidator.predicate("userB만 포함")(
    resultsB.data.length===1 && resultsB.data[0].id===userB.id
  );

  // 5. pagination 검증: page=1, limit=1로 전체 검색 - 1건만 반환
  const resultsPaged = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: timeA,
      created_at_to: timeB,
      pagination: { page: 1, limit: 1 }
    }
  });
  typia.assert(resultsPaged);
  TestValidator.equals("1건 반환됨")(resultsPaged.data.length)(1);
  TestValidator.equals("pagination.limit 일치")(resultsPaged.pagination.limit)(1);
}

