import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostSnapshot";

/**
 * 테스트 목적: 포스트 스냅샷의 유효한 데이터로 업데이트 기능의 정상 동작과 감사를 위한 변경 내용 반영을 확인합니다.
 * 
 * 비즈니스 컨텍스트:
 * - discussionboard_post_snapshots 엔터티는 게시글의 과거 내용을 보관하는 버전 레코드입니다. 일반적 사용자는 새로운 스냅샷 기록만 생성하며, 업데이트는 주로 관리자 또는 원 편집자에 의해 잘못된 감사 내용 정정, 관리목적, 오류수정 시에만 허용됩니다.
 * - 업데이트에서는 title, body, taken_at, editor_member_id만 수정할 수 있으며, id 및 post 연관 등 기타 필드는 불변입니다.
 *
 * [시나리오 절차]
 * 1. 포스트를 먼저 생성(disucssionboard/posts)
 * 2. 방금 만든 포스트의 id로 최초 스냅샷 생성(discussionboard/postSnapshots)
 * 3. put 연산으로 title, body, taken_at 값들을 변경하여 해당 스냅샷을 업데이트
 * 4. 반환 결과에 대해 title, body, taken_at이 실제로 변경되었는지, discussionboard_post_id와 id(스냅샷의 PK)는 변하지 않았는지 검증
 * 5. 불변 필드(예: discussionboard_post_id, id 등)이 변경되지 않는 정책 준수 확인
 * 6. (필요 시) editor_member_id 필드를 null, uuid 등 다양한 값으로 시도해 정상 동작 확인
 */
export async function test_api_discussionboard_test_update_post_snapshot_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 포스트를 생성
  const postCreate: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Initial Post Title",
      body: "Initial post body content.",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }
  });
  typia.assert(postCreate);
  // 2. 스냅샷 생성 (원본 state 보존용)
  const snapshotCreate: IPostSnapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: postCreate.id,
      editor_member_id: postCreate.discussionboard_member_id,
      title: postCreate.title,
      body: postCreate.body,
      taken_at: new Date().toISOString(),
    },
  });
  typia.assert(snapshotCreate);
  // 3. 스냅샷 업데이트, title/body/taken_at/option(editor_member_id) 변경
  const updateInput: IPostSnapshot.IUpdate = {
