  connection: api.IConnection,
) {
  // 1. Create a member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a post (requires membership, thread, and board context)
  // We'll fabricate thread_id and board_id as random UUIDs for test isolation
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(10),
    body: RandomGenerator.content()(2)(),
    is_deleted: false,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Create a comment on the post as this member
  const commentInput: IComment.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    body: RandomGenerator.content()(1)(),
  };
  const comment = await api.functional.discussionboard.comments.create(connection, { body: commentInput });
  typia.assert(comment);

  // 4. Member votes on the comment
  const voteInput: IDiscussionboardCommentVote.ICreate = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: member.id,
    vote_type: "up",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const vote = await api.functional.discussionboard.commentVotes.create(connection, { body: voteInput });
  typia.assert(vote);

  // 5. Attempt to submit a duplicate vote by same member on same comment
  await TestValidator.error("expect unique constraint violation on duplicate vote")(async () => {
    await api.functional.discussionboard.commentVotes.create(connection, { body: voteInput });
  });
}

