import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IPageIDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for hard-deleting a discussion board configuration by id and verifying runtime effects.
 *
 * This test validates the followings:
 * 1. A configuration can be created via POST /discussionboard/configurations.
 * 2. It can be hard-deleted by calling DELETE /discussionboard/configurations/{id}.
 * 3. After deletion, it no longer appears in filtering/listing (PATCH /discussionboard/configurations).
 * 4. Deleting again yields a 404 error for already-deleted or non-existent ids.
 * 5. Deletion returns no body and has correct status code (204 on success).
 * 6. Deleting with invalid or malformed UUID rejects as error.
 */
export async function test_api_discussionboard_configurations_test_delete_configuration_by_id_and_handle_missing_records(connection: api.IConnection) {
  // 1. Create a new configuration
  const configKey = `autotest_key_${RandomGenerator.alphaNumeric(8)}`;
  const createBody: IDiscussionboardConfiguration.ICreate = {
    key: configKey,
    value: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
  };
  const created = await api.functional.discussionboard.configurations.create(connection, { body: createBody });
  typia.assert(created);

  // 2. Delete the newly created configuration
  const deletion = await api.functional.discussionboard.configurations.erase(connection, { id: created.id });

  // 3. Confirm the deletion returns no body (void) and is successful (204)
  TestValidator.equals("erase returns void")(deletion)(undefined);

  // 4. List configurations and confirm deleted id is absent
  const list = await api.functional.discussionboard.configurations.index(connection, {
    body: { key: configKey },
  });
  typia.assert(list);
  const listed = list.data.find((conf) => conf.id === created.id);
  TestValidator.equals("deleted config is absent in list")(listed)(undefined);

  // 5. Try to delete again (should yield 404 error)
  await TestValidator.error("repeat deletion returns 404 error")(async () => {
    await api.functional.discussionboard.configurations.erase(connection, { id: created.id });
  });

  // 6. Try to delete with malformed/invalid UUID
  await TestValidator.error("malformed UUID returns error")(async () => {
    await api.functional.discussionboard.configurations.erase(connection, { id: "invalid-uuid" as any });
  });
}

