 *
 * 업무 맥락과 필요성:
 * 게시판에 신규 모더레이터를 지정하면, 해당 모더레이터(moderator)와 게시판(board)이 정확하게 매핑되어 저장되어야 하며,
 * 중복 할당(동일 모더레이터-게시판 페어의 2회 이상 등록)이 불가능해야 함을 보장해야 합니다.
 *
 * 진행 순서 및 세부 검증:
 * 1. (사전) 게시판 카테고리와 섹션 UUID 의미 있는 값 준비(또는 랜덤 생성)
 * 2. (어드민 역할) 게시판 생성
 * 3. (어드민 역할) 모더레이터 유저(회원) 생성 및 등록
 * 4. (어드민 역할) 모더레이터 할당(POST /discussionboard/boardModerators)
 * 5. 응답 데이터의 board/mdoerator/is_primary/joined_at 필드가 실제 입력값과 일치하는지 검증
 * 6. (에러 케이스) 동일 모더레이터/게시판 쌍으로 중복 할당 시도 시 Unique 제약 위반 에러 발생 검증
 */
export async function test_api_discussionboard_test_assign_moderator_to_board_success(connection: api.IConnection) {
  // 1. 게시판 카테고리 및 섹션 UUID 준비(랜덤)
  const boardCategoryId = typia.random<string & tags.Format<'uuid'>>();
  const sectionId = typia.random<string & tags.Format<'uuid'>>();

  // 2. 게시판 생성
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: boardCategoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.name(),
      code: RandomGenerator.alphaNumeric(8),
      is_active: true,
      is_visible: true,
      // description은 optional이므로 생략
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(board);

  // 3. 모더레이터(회원) 생성 및 등록
  const memberId = typia.random<string & tags.Format<'uuid'>>();
  const adminId = typia.random<string & tags.Format<'uuid'>>();
  const assignedAt = new Date().toISOString();
  const moderator = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: memberId,
      assigned_by_admin_id: adminId,
      assigned_at: assignedAt,
      // expires_at/revoked_at은 null로 설정
      expires_at: null,
      revoked_at: null,
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(moderator);

  // 4. 게시판-모더레이터 할당(본 테스트의 핵심)
  const joinedAt = new Date().toISOString();
  const isPrimary = true;
