  TestValidator.equals('moderator id')(assignment.discussionboard_moderator_id)(moderator.id);
  TestValidator.equals('is primary')(assignment.is_primary)(isPrimary);
  TestValidator.equals('joined at')(assignment.joined_at)(joinedAt);

  // 6. (에러 시나리오) 동일 모더레이터-게시판 중복 배정 시도: Unique 제약 실패
  await TestValidator.error('중복 할당 unique 제약')(async () => {
    await api.functional.discussionboard.boardModerators.create(connection, {
      body: {
        discussionboard_board_id: board.id,
        discussionboard_moderator_id: moderator.id,
        is_primary: false,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionboardBoardModerator.ICreate,
    });
  });
}

