 *
 * This test verifies that a regular member (non-moderator) is forbidden from updating a thread tag assignment.
 *
 * Test workflow:
 * 1. Create a non-moderator (role: member).
 * 2. Create a board required for thread creation (randomized IDs for category and section foreign keys).
 * 3. Create a thread belonging to the above member and board.
 * 4. Assign a tag to the thread as the member (create thread tag assignment).
 * 5. As the member, attempt to update the thread tag assignment, expecting an authorization error as only moderators can perform updates.
 *
 * Validates that the system blocks unauthorized users (non-moderators) from updating thread tag records.
 */
export async function test_api_discussionboard_test_update_thread_tag_assignment_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register a non-moderator member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a board
  const boardInput: Idiscussionboard_boards.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.paragraph()(1),
    code: RandomGenerator.alphabets(6),
    description: RandomGenerator.paragraph()(1),
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a thread for the member in the board
  const threadInput: IDiscussionboardThreads.ICreate = {
    board_id: board.id,
    author_member_id: member.id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.paragraph()(2),
  };
  const thread = await api.functional.discussionboard.threads.create(connection, { body: threadInput });
  typia.assert(thread);

  // 4. Assign a tag as the member
  const tagInput: IDiscussionboardThreadTag.ICreate = {
    thread_id: thread.id,
    assigned_at: new Date().toISOString(),
    removed_at: null,
  };
  const threadTag = await api.functional.discussionboard.threadTags.create(connection, { body: tagInput });
  typia.assert(threadTag);

  // 5. Attempt to update the tag assignment (should fail for member role)
  await TestValidator.error("non-moderator update forbidden")(async () => {
    await api.functional.discussionboard.threadTags.update(connection, {
      id: threadTag.id,
      body: {
        assigned_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreadTag.IUpdate,
    });
  });
}

