import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * Test creating a system notification log with valid and invalid input fields.
 *
 * This test covers the creation of notification log entries in the discussion board module, including positive and negative cases for request structure validation, format enforcement, and error responses. It ensures that:
 *   - A valid notification entry can be created with all required and optional fields (including both individualized and system-wide scenarios via target_id).
 *   - Missing required fields, extraneous fields, and invalid formats are rejected as per schema validation rules.
 *   - Any referenced foreign key/id is checked against the backend, and errors (such as for non-existent targets) are handled properly.
 *   - System-managed fields are auto-populated and returned as per contract.
 *
 * Steps:
 * 1. Create a notification with all correct fields (valid UUID for target_id, or null for broadcast).
 *    - Validate that response includes id, created_at, delivered_at, and data matches input.
 * 2. Create a notification omitting optional fields (body and target_id), verify default/nullable handling.
 * 3. Attempt to create notifications with each of:
 *    - Omitted required fields (type, title, delivered)
 *    - Malformed UUID for target_id
 *    - Extra non-schema fields
 *    - Invalid (nonexistent) UUID in target_id (simulate foreign-key violation)
 *    and check for error responses.
 */
export async function test_api_discussionboard_test_create_notification_with_valid_and_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create notification with all correct fields (valid UUID for target_id)
  const fullInput: IDiscussionboardNotification.ICreate = {
    target_id: typia.random<string & tags.Format<"uuid">>(),
    type: "system_announcement",
    title: "System maintenance scheduled",
    body: "The discussion board will be offline for scheduled maintenance tonight.",
    delivered: true,
  };
  const created = await api.functional.discussionboard.notifications.create(connection, { body: fullInput });
  typia.assert(created);
  // System-managed fields
  TestValidator.predicate("id is uuid")(
    typeof created.id === "string" && created.id.length > 0,
  );
  TestValidator.equals("type")(created.type)(fullInput.type);
  TestValidator.equals("title")(created.title)(fullInput.title);
  TestValidator.equals("body")(created.body)(fullInput.body);
  TestValidator.equals("delivered")(created.delivered)(fullInput.delivered);
  if (fullInput.target_id !== undefined) {
    TestValidator.equals("target_id")(created.target_id)(fullInput.target_id);
  }
  TestValidator.predicate("created_at is ISO date")(
    typeof created.created_at === "string" && !isNaN(Date.parse(created.created_at)),
  );
  // delivered_at is nullable, but if delivered flag is true, expect non-null
  if (created.delivered)
    TestValidator.predicate("delivered_at present if delivered")(
      typeof created.delivered_at === "string" && created.delivered_at.length > 0,
    );

  // 2. Create notification omitting optional fields (target_id and body)
  const minimalInput: IDiscussionboardNotification.ICreate = {
    type: "user_mention",
    title: "You were mentioned in a thread",
    delivered: false,
  };
  const createdMinimal = await api.functional.discussionboard.notifications.create(connection, { body: minimalInput });
  typia.assert(createdMinimal);
  TestValidator.equals("type")(createdMinimal.type)(minimalInput.type);
  TestValidator.equals("title")(createdMinimal.title)(minimalInput.title);
  TestValidator.equals("delivered")(createdMinimal.delivered)(minimalInput.delivered);
  TestValidator.equals("target_id")(createdMinimal.target_id)(undefined);
  TestValidator.equals("body")(createdMinimal.body)(undefined);
  // delivered_at may be null/undefined since delivered is false
  if (!createdMinimal.delivered)
    TestValidator.equals("delivered_at")(createdMinimal.delivered_at)(null);

  // 3.a. Attempt create with missing required fields (should error)
  await TestValidator.error("missing required fields")(
    async () => {
      // @ts-expect-error on purpose: missing type/title/delivered
      await api.functional.discussionboard.notifications.create(connection, {
        body: { },
      } as any);
    },
  );

  // 3.b. Attempt create with malformed uuid for target_id
  await TestValidator.error("malformed target_id uuid")(
    async () => {
      const badUuidInput: IDiscussionboardNotification.ICreate = {
        target_id: "not-a-uuid" as any,
        type: "user_mention",
        title: "Title",
        delivered: false,
      };
      await api.functional.discussionboard.notifications.create(connection, { body: badUuidInput });
    },
  );

  // 3.c. Attempt create with extra, non-schema field
  await TestValidator.error("extra field is not accepted")(
    async () => {
      // @ts-expect-error on purpose: extra 'foo' field
      await api.functional.discussionboard.notifications.create(connection, {
        body: {
          type: "system_announcement",
          title: "Test",
          delivered: true,
          foo: "bar",
        },
      } as any);
    },
  );

  // 3.d. Attempt create with invalid (nonexistent) target_id UUID (simulating foreign-key check)
  await TestValidator.error("invalid target_id foreign key")(
    async () => {
      const unreachableUuidInput: IDiscussionboardNotification.ICreate = {
        target_id: "00000000-0000-0000-0000-000000000001" as any,
        type: "user_mention",
        title: "Nonexistent target test",
        delivered: true,
      };
      await api.functional.discussionboard.notifications.create(connection, { body: unreachableUuidInput });
    },
  );
}

