      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create moderator
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "moderator",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(moderator);

  // 3. Issue initial ban
  const ban = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: member.id,
      acting_moderator_id: moderator.id,
      report_id: null,
