/**
 * Test the creation of a new system configuration for the discussion board application.
 *
 * This test verifies that submitting a valid IDiscussionboardConfiguration.ICreate object
 * properly creates a configuration entry and returns the expected system-managed fields.
 *
 * Business rules:
 * - The configuration key must be unique per system schema.
 * - Value and description are optional but tested with normal non-null values.
 * - No additional (non-schema) fields should be accepted or returned.
 *
 * Test Steps:
 * 1. Generate a new, unique configuration key (ensure very low likelihood of collision).
 * 2. Call the create API with a valid IDiscussionboardConfiguration.ICreate input including key, value, and description.
 * 3. Verify the returned configuration object includes:
 *     - Auto-assigned 'id' in string UUID format.
 *     - The key, value, and description as submitted.
 *     - System-managed 'created_at' and 'updated_at' as date-time strings.
 * 4. Assert that only schema-defined fields are present in the response (no extraneous properties).
 *
 * This test does not cover duplicate key conflicts or schema violation errors—only the 'happy path' (successful creation with valid input).
 */
export async function test_api_discussionboard_test_create_new_configuration_with_valid_input(
  connection: api.IConnection,
) {
  // 1. Generate a unique configuration key
  const uniqueKey = `test_config_key_${Date.now()}_${Math.floor(Math.random() * 1e6)}`;
  const value = "100";
  const description = "Maximum number of posts a user can create per hour for testing.";

  // 2. Call the API to create the configuration
  const created = await api.functional.discussionboard.configurations.create(
    connection,
    {
      body: {
        key: uniqueKey,
        value,
        description,
      } satisfies IDiscussionboardConfiguration.ICreate,
    },
  );
  typia.assert(created);

  // 3. Verify all expected fields
  TestValidator.predicate("id is uuid")(
    typeof created.id === "string" && /^[0-9a-fA-F-]{36}$/.test(created.id),
  );
  TestValidator.equals("key matches")(created.key)(uniqueKey);
  TestValidator.equals("value matches")(created.value)(value);
  TestValidator.equals("description matches")(created.description)(description);
  TestValidator.predicate("created_at is date-time")(
    typeof created.created_at === "string" && !isNaN(Date.parse(created.created_at)),
  );
  TestValidator.predicate("updated_at is date-time")(
    typeof created.updated_at === "string" && !isNaN(Date.parse(created.updated_at)),
  );

  // 4. Assert that no extra fields are present (only schema-defined fields)
  const allowedFields = [
    "id",
    "key",
    "value",
    "description",
    "created_at",
    "updated_at",
  ];
  for (const prop of Object.keys(created)) {
    TestValidator.predicate(`no extra field: ${prop}`)(allowedFields.includes(prop));
  }
}

