import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";
import type { IPageIDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching comment reports with multiple valid filters and pagination.
 *
 * This test validates that the comment reports index/search endpoint properly supports all the main filtering axes (comment id, reporter member id, report type, created_at date range, and reason substring/full text) and returns paginated results with correct structure. Scenarios include both precise equality filters and substring text matches for the reason field.
 *
 * Steps:
 * 1. Create multiple comments to be reported
 * 2. Create several comment reports with diverse: comment, report type, reporting member, reason string, and created_at timestamps
 * 3. For each main filter, issue a search and validate the response:
 *    - Filter by comment id
 *    - Filter by reporting member id
 *    - Filter by report type id
 *    - Filter by created_at range
 *    - Filter by reason substring and full text
 * 4. For every query, assert that returned results match the filter and pagination metadata is coherent
 */
export async function test_api_discussionboard_test_search_comment_reports_with_valid_filters(
  connection: api.IConnection,
) {
  // ------ SETUP: Create data cohort ------

  // Generate two base members and basic post IDs for comments
  const memberA = typia.random<string & tags.Format<"uuid">>();
  const memberB = typia.random<string & tags.Format<"uuid">>();
  const postA = typia.random<string & tags.Format<"uuid">>();
  const postB = typia.random<string & tags.Format<"uuid">>();

  // Create two comments (to be reported)
  const comment1 = await api.functional.discussionboard.comments.create(
    connection, {
      body: {
        discussionboard_post_id: postA,
        discussionboard_member_id: memberA,
        body: "This is the first comment.",
      } satisfies IComment.ICreate
    }
  );
  typia.assert(comment1);

  const comment2 = await api.functional.discussionboard.comments.create(
    connection, {
      body: {
        discussionboard_post_id: postB,
        discussionboard_member_id: memberB,
        body: "This is the second comment.",
      } satisfies IComment.ICreate
    }
  );
  typia.assert(comment2);

  // Set two report types (UUIDs only, since the structure is opaque here)
  const reportTypeA = typia.random<string & tags.Format<"uuid">>();
  const reportTypeB = typia.random<string & tags.Format<"uuid">>();

  // Mark reference timestamps for created_at searching
  const now = new Date();
  const t0 = new Date(now.getTime() - 1000 * 60 * 60); // 1hr ago
  const t1 = new Date(now.getTime() - 1000 * 30);      // 30 sec ago
  const t2 = new Date(now.getTime());                  // now

  // Create a variety of reports
  const report1 = await api.functional.discussionboard.commentReports.create(
    connection, {
      body: {
        discussionboard_comment_id: comment1.id,
        discussionboard_member_id: memberA,
        discussionboard_report_type_id: reportTypeA,
        reason: "Offensive language (uniquePhraseA)",
        created_at: t0.toISOString(),
      } satisfies IDiscussionboardCommentReport.ICreate,
    }
  );
  typia.assert(report1);

  const report2 = await api.functional.discussionboard.commentReports.create(
    connection, {
      body: {
        discussionboard_comment_id: comment1.id,
        discussionboard_member_id: memberB,
        discussionboard_report_type_id: reportTypeB,
        reason: "Spam content (uniquePhraseB)",
        created_at: t1.toISOString(),
      } satisfies IDiscussionboardCommentReport.ICreate,
    }
  );
  typia.assert(report2);

  const report3 = await api.functional.discussionboard.commentReports.create(
    connection, {
      body: {
        discussionboard_comment_id: comment2.id,
        discussionboard_member_id: memberB,
        discussionboard_report_type_id: reportTypeA,
        reason: "Harassment report (uniquePhraseC)",
        created_at: t2.toISOString(),
      } satisfies IDiscussionboardCommentReport.ICreate,
    }
  );
  typia.assert(report3);

  // Additional: Create more reports if needed for pagination checks
  const extraReports = await ArrayUtil.asyncRepeat(5)(async (i) => {
    return await api.functional.discussionboard.commentReports.create(
      connection,
      {
        body: {
          discussionboard_comment_id: RandomGenerator.pick([
            comment1.id,
            comment2.id,
          ]),
          discussionboard_member_id: RandomGenerator.pick([
            memberA,
            memberB,
          ]),
          discussionboard_report_type_id: RandomGenerator.pick([
            reportTypeA,
            reportTypeB,
          ]),
          reason:
            i % 2 === 0
              ? `Contains link (paginationCheckPhrase${i})`
              : `Unrelated reason (paginationCheckUnique${i})`,
          created_at: new Date(
            now.getTime() - 1000 * 60 * (i + 2)
          ).toISOString(),
        } satisfies IDiscussionboardCommentReport.ICreate,
      }
    );
  });
  for (const x of extraReports) typia.assert(x);

  // ------- FILTER TESTS -------

  // a) By specific comment id
  {
    const out = await api.functional.discussionboard.commentReports.index(
      connection,
      {
        body: {
          discussionboard_comment_id: comment1.id,
        } satisfies IDiscussionboardCommentReport.IRequest,
      }
    );
    typia.assert(out);
    for (const r of out.data) {
      TestValidator.equals("filter by comment id")(r.discussionboard_comment_id)(comment1.id);
    }
    TestValidator.predicate("pagination - at least one exists")(out.data.length >= 1);
  }

  // b) By reporter member id
  {
    const out = await api.functional.discussionboard.commentReports.index(
      connection,
      {
        body: {
          discussionboard_member_id: memberB,
        } satisfies IDiscussionboardCommentReport.IRequest,
      }
    );
    typia.assert(out);
    for (const r of out.data) {
      TestValidator.equals("filter by member")(r.discussionboard_member_id)(memberB);
    }
  }

  // c) By report type
  {
    const out = await api.functional.discussionboard.commentReports.index(
      connection,
      {
        body: {
          discussionboard_report_type_id: reportTypeA,
        } satisfies IDiscussionboardCommentReport.IRequest,
      }
    );
    typia.assert(out);
    for (const r of out.data) {
      TestValidator.equals("report type matches")(r.discussionboard_report_type_id)(reportTypeA);
    }
  }

  // d) Date range search
  {
    const out = await api.functional.discussionboard.commentReports.index(
      connection,
      {
        body: {
          created_at_from: t0.toISOString(),
          created_at_to: t2.toISOString(),
        } satisfies IDiscussionboardCommentReport.IRequest,
      }
    );
    typia.assert(out);
    for (const r of out.data) {
      TestValidator.predicate("created_at in range")(
        r.created_at >= t0.toISOString() && r.created_at <= t2.toISOString()
      );
    }
  }

  // e) Reason substring search (partial)
  {
    const out = await api.functional.discussionboard.commentReports.index(
      connection,
      {
        body: {
          reason: "uniquePhraseA",
        } satisfies IDiscussionboardCommentReport.IRequest,
      }
    );
    typia.assert(out);
    for (const r of out.data) {
      TestValidator.predicate("reason includes substring")(
        r.reason.includes("uniquePhraseA")
      );
    }
  }

  // f) Reason exact search (full text)
  {
    const exactReason = "Spam content (uniquePhraseB)";
    const out = await api.functional.discussionboard.commentReports.index(
      connection,
      {
        body: {
          reason: exactReason,
        } satisfies IDiscussionboardCommentReport.IRequest,
      }
    );
    typia.assert(out);
    for (const r of out.data) {
      TestValidator.equals("reason exact matches")(r.reason)(exactReason);
    }
  }

  // g) Pagination checks (limit and total count coherence)
  {
    const out = await api.functional.discussionboard.commentReports.index(
      connection,
      {
        body: {},
      }
    );
    typia.assert(out);
    TestValidator.predicate("pagination fields shape")(
      typeof out.pagination?.current === "number" &&
      typeof out.pagination?.limit === "number" &&
      typeof out.pagination?.records === "number" &&
      typeof out.pagination?.pages === "number"
    );
    TestValidator.equals("pagination record sum")(
      out.pagination.records
    )(out.data.length);
  }
}

