import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";
import type { IDiscussionboardThreadSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshot";

/**
 * E2E test: Update a thread snapshot with valid and invalid data
 * 
 * This test verifies the update operation for discussionboard thread snapshots, validating both valid and error flows.
 * 
 * Steps:
 * 1. Create a member (prerequisite - author/actor)
 * 2. Create a board (prerequisite)
 * 3. Create a thread (prerequisite)
 * 4. Create a snapshot (prerequisite)
 * 5. Update the snapshot with all updatable fields (body/reason) — checks successful update
 * 6. Update the snapshot, changing only one allowed field (e.g., reason), and ensure only that field is changed
 * 7. Attempt to update with required fields missing or types invalid to confirm validation errors
 *
 * Validation: On every creation and update, assert type compliance. Compare updated result with the sent body for matching values. On error, ensure an error is thrown by the validation system (TestValidator.error).
 */
export async function test_api_discussionboard_test_update_thread_snapshot_with_valid_fields(connection: api.IConnection) {
  // 1. Create a member for author/actor
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(2),
      code: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. Create a thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(3),
    },
  });
  typia.assert(thread);

  // 4. Create a snapshot
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: member.id,
      title: thread.title,
      body: thread.body,
      reason: "Initial snapshot",
    },
  });
  typia.assert(snapshot);

  // 5. Update the snapshot, changing both body and reason
  const updateBody = { body: RandomGenerator.content()()(), reason: "Updated for test" } satisfies IDiscussionboardThreadSnapshot.IUpdate;
  const updated = await api.functional.discussionboard.threadSnapshots.update(connection, {
    id: snapshot.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("snapshot id not changed")(updated.id)(snapshot.id);
  TestValidator.equals("body updated")(updated.body)(updateBody.body);
  TestValidator.equals("reason updated")(updated.reason)(updateBody.reason);

  // 6. Update again, change only reason, keep body null
  const updateReason = { reason: "Moderator note: further edit", body: null } satisfies IDiscussionboardThreadSnapshot.IUpdate;
  const updated2 = await api.functional.discussionboard.threadSnapshots.update(connection, {
    id: snapshot.id,
    body: updateReason,
  });
  typia.assert(updated2);
  TestValidator.equals("snapshot id unchanged")(updated2.id)(snapshot.id);
  TestValidator.equals("reason correctly changed")(updated2.reason)(updateReason.reason);
  TestValidator.equals("body correctly null")(updated2.body)(null);

  // 7. Attempt update with no valid updatable fields (body and reason both omitted)
  TestValidator.error("should fail on missing updatable fields")(() =>
    api.functional.discussionboard.threadSnapshots.update(connection, { id: snapshot.id, body: {} as any })
  );
}

