import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostVote";
import type { IPageIPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test for retrieving post votes with valid filters and pagination.
 *
 * This test ensures that post votes can be searched and paginated based on filter criteria:
 * - discussionboard_post_id
 * - discussionboard_member_id
 * - vote_type
 *
 * Steps:
 * 1. Create several members
 * 2. Create several posts
 * 3. Each member votes (upvote/downvote/neutral) on different posts
 * 4. For various combinations of (post, member, vote_type), search post votes
 * 5. Verify returned post votes match expected records
 * 6. Test pagination by limiting and offsetting results
 */
export async function test_api_discussionboard_test_list_post_votes_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create members
  const members = await Promise.all(ArrayUtil.repeat(3)(async () => {
    const member = await api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphabets(16),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    });
    typia.assert(member);
    return member;
  }));

  // 2. Create posts
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const posts = await Promise.all(ArrayUtil.repeat(2)(async (_, i) => {
    const post = await api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: thread_id,
        discussionboard_member_id: members[i % members.length].id,
        discussionboard_board_id: board_id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_deleted: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardPost.ICreate,
    });
    typia.assert(post);
    return post;
  }));

  // 3. Each member votes on each post, with varying vote_type values
  const vote_types: (-1 | 0 | 1)[] = [1, -1, 0];
  const voteRecords: IPostVote[] = [];
  for (let mi = 0; mi < members.length; ++mi) {
    for (let pi = 0; pi < posts.length; ++pi) {
      const vote = await api.functional.discussionboard.postVotes.create(connection, {
        body: {
          discussionboard_post_id: posts[pi].id,
          discussionboard_member_id: members[mi].id,
          vote_type: vote_types[(mi + pi) % vote_types.length],
          created_at: new Date(Date.now() + mi * 1000 + pi * 500).toISOString(),
        } satisfies IPostVote.ICreate,
      });
      typia.assert(vote);
      voteRecords.push(vote);
    }
  }

  // 4. Test queries: by post id, by member id, by vote_type, and pagination
  // (a) Filter by post id
  for (const post of posts) {
    const expectedVotes = voteRecords.filter(v => v.discussionboard_post_id === post.id);
    const output = await api.functional.discussionboard.postVotes.index(connection, {
      body: { discussionboard_post_id: post.id },
    });
    typia.assert(output);
    // All returned votes are for the given post
    TestValidator.equals("matching votes for post")(output.data.length)(expectedVotes.length);
    for (const vote of output.data) {
      TestValidator.equals("vote post matches")(vote.discussionboard_post_id)(post.id);
    }
  }

  // (b) Filter by member id
  for (const member of members) {
    const expectedVotes = voteRecords.filter(v => v.discussionboard_member_id === member.id);
    const output = await api.functional.discussionboard.postVotes.index(connection, {
      body: { discussionboard_member_id: member.id },
    });
    typia.assert(output);
    TestValidator.equals("matching votes for member")(output.data.length)(expectedVotes.length);
    for (const vote of output.data) {
      TestValidator.equals("vote member matches")(vote.discussionboard_member_id)(member.id);
    }
  }

  // (c) Filter by vote_type
  for (const vt of vote_types) {
    const expectedVotes = voteRecords.filter(v => v.vote_type === vt);
    const output = await api.functional.discussionboard.postVotes.index(connection, {
      body: { vote_type: vt },
    });
    typia.assert(output);
    TestValidator.equals("matching votes for vote_type")(output.data.length)(expectedVotes.length);
    for (const vote of output.data) {
      TestValidator.equals("vote_type matches")(vote.vote_type)(vt);
    }
  }

  // (d) Combined filter: post id + member id + vote_type
  for (const vote of voteRecords) {
    const output = await api.functional.discussionboard.postVotes.index(connection, {
      body: {
        discussionboard_post_id: vote.discussionboard_post_id,
        discussionboard_member_id: vote.discussionboard_member_id,
        vote_type: vote.vote_type,
      },
    });
    typia.assert(output);
    expect(output.data.length).toBeGreaterThanOrEqual(1);
    for (const v of output.data) {
      TestValidator.equals("vote composite matches")(v.discussionboard_post_id)(vote.discussionboard_post_id);
      TestValidator.equals("vote composite matches")(v.discussionboard_member_id)(vote.discussionboard_member_id);
      TestValidator.equals("vote composite matches")(v.vote_type)(vote.vote_type);
    }
  }

  // (e) Pagination: limit and offset simulation
  const allVotes = await api.functional.discussionboard.postVotes.index(connection, { body: {} });
  typia.assert(allVotes);
  const pageLimit = 2;
  if (allVotes.data.length > pageLimit) {
    const paged = {
      ...allVotes,
      data: allVotes.data.slice(0, pageLimit),
      pagination: {
        ...allVotes.pagination,
        limit: pageLimit,
        current: 1,
        pages: Math.ceil(allVotes.data.length / pageLimit),
      },
    };
    TestValidator.equals("page size == limit")(paged.data.length)(pageLimit);
  }
}

