import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * 신고 상세 조회 API의 인가와 예외 처리 그리고 정합성 검증
 *
 * 관리자(혹은 운영자) 권한을 가진 계정만이 신고 상세정보를 조회할 수 있다는 보안 정책을 검증한다.
 * 정상적인 UUID를 가진 실제 존재하는 신고 건에 대해선 상세필드 전체(신고 유형ID, 신고자, 타겟 오브젝트 정보, 설명, 시점 등)가 모두 반환되고,
 * 존재하지 않거나 형식이 잘못된 UUID로 요청 시엔 적절한 not found 혹은 에러를 반환하는지 확인한다.
 * 또한 일반 회원이나 로그인하지 않은 사용자가 접근하면 권한에러를 내는지도 체크한다.
 *
 * 1. 일반 회원 가입 (권한: member)
 * 2. 신고 유형 생성 (권한: admin)
 * 3. 정상 신고 생성 (권한: member)
 * 4. 운영자 권한 계정 생성 (권한: moderator)
 * 5. 관리자 권한 계정 생성 (권한: admin)
 * 6. 운영자 계정으로 신고 상세 조회 (정상, 모든 필드 확인)
 * 7. 관리자 계정으로 신고 상세 조회 (정상, 모든 필드 확인)
 * 8. 일반회원 계정으로 신고 상세 조회 (권한 에러)
