import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Test that attempting to update immutable fields (`id` and `created_at`) in a comment report is rejected.
 *
 * This test creates a comment and a comment report as dependencies. It then attempts to update the comment report using the update endpoint, but with an invalid request: it tries to include immutable fields `id` or `created_at` in the update payload (which the schema does NOT allow via the IDiscussionboardCommentReport.IUpdate type).
 *
 * The expectation is that the API schema will reject this operation (even before reaching any backend logic), and the E2E test should validate that a runtime error is thrown and no changes are accepted if the payload is not schema-compliant.
 *
 * Because TypeScript/typia prevents impossible type combinations at compile time, only runtime property-injection attempts using standard techniques can be tested, but not compile-time invalid assignments. Therefore, this test attempts to inject forbidden fields via plain object extension and ensures that such malformed requests are rejected by the API (or by typia/assert at e2e runtime).
 *
 * Steps:
 * 1. Create a comment for testing (dependency)
 * 2. Create a comment report for the comment (dependency)
 * 3. Attempt to update the comment report, forcibly injecting 'id' and 'created_at' in the payload object
 * 4. Confirm an error is thrown by the API or schema validator, with no successful update
 */
export async function test_api_discussionboard_test_update_comment_report_with_immutable_field(
  connection: api.IConnection,
) {
  // 1. Prepare: create a comment for reporting
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      body: "Test content for immutable update validation",
    },
  });
  typia.assert(comment);

  // 2. Prepare: create a comment report referencing the comment
  const report = await api.functional.discussionboard.commentReports.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Initial report reason",
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(report);

  // 3. Attempt to update immutable fields (simulate user hacking the payload)
  const invalidPayload = {
    discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Forged update reason attempting to change system fields",
    id: typia.random<string & tags.Format<"uuid">>(), // forbidden
    created_at: new Date().toISOString(), // forbidden
  } as any; // Used only to bypass TypeScript enforcement for test purposes

  await TestValidator.error("forbidden fields in update should fail")(async () => {
    await api.functional.discussionboard.commentReports.update(connection, {
      id: report.id,
      body: invalidPayload, // forced error
    });
  });

  // 4. Confirm normal valid update works
  const validPayload = {
    discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Permitted update reason.",
  } satisfies IDiscussionboardCommentReport.IUpdate;

  const updated = await api.functional.discussionboard.commentReports.update(connection, {
    id: report.id,
    body: validPayload,
  });
  typia.assert(updated);
  TestValidator.equals("updated reason")(updated.reason)(validPayload.reason);
}

