import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";

/**
 * Validate the creation of a thread snapshot for edit audit and rollback purposes.
 *
 * This test checks the ability to record a thread's state at a specific moment (typically before an edit, or for moderation audit).
 * It also enforces critical business rules:
 * - The snapshot must reference a valid (existing, not deleted) thread.
 * - The snapshot content must match the schema's required fields (title, body, thread_id, etc.).
 * - Snapshots are immutable after creation and contain sufficient audit trail information.
 *
 * Test Flow:
 * 1. Create a new discussion thread to serve as the baseline for snapshotting.
 * 2. Create a thread snapshot using the freshly created thread's data (simulate a pre-edit audit record).
 * 3. Edit (update) the thread's title and body, simulating a thread update workflow.
 * 4. Validate the snapshot's content matches the original thread data (before edit), is properly linked, and has the required fields.
 * 5. Attempt to create a snapshot referencing a random (non-existent) thread ID. Assert that this operation fails (error thrown), confirming business rule enforcement.
 * 6. Simulate thread soft-deletion (via update) and attempt to snapshot again. Assert error on snapshot for soft-deleted thread.
 *
 * Assumptions:
 * - No explicit member creation API is provided, so actor_id is simulated as needed with a random uuid.
 * - Thread deletion is simulated by setting deleted_at via the update endpoint using a valid ISO date string.
 * - Only direct API calls are used; never reference non-existent properties or endpoints.
 */
export async function test_api_discussionboard_test_create_thread_snapshot_for_edit_audit_and_rollback(
  connection: api.IConnection,
) {
  // 1. Create a new thread (base data to be snapshotted)
  const threadAuthorId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const createThreadInput = {
    board_id: boardId,
    author_member_id: threadAuthorId,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.paragraph()(2),
  } satisfies IDiscussionboardThreads.ICreate;
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: createThreadInput,
  });
  typia.assert(thread);

  // 2. Create a thread snapshot for the existing thread
  const snapshotActorId = threadAuthorId; // simulate author of snapshot as thread author
  const createSnapshotInput = {
    thread_id: thread.id,
    actor_id: snapshotActorId,
    title: thread.title,
    body: thread.body,
    reason: "edit-pre snapshot for audit", // test reason
  } satisfies IDiscussionboardThreadSnapshots.ICreate;
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: createSnapshotInput,
  });
  typia.assert(snapshot);
  // Validate required fields and linkage
  TestValidator.equals("snapshot.thread_id matches thread")(snapshot.thread_id)(thread.id);
  TestValidator.equals("snapshot.actor_id matches author")(snapshot.actor_id)(thread.author_member_id);
  TestValidator.equals("snapshot.title matches thread")(snapshot.title)(thread.title);
  TestValidator.equals("snapshot.body matches thread")(snapshot.body ?? null)(thread.body ?? null);
  TestValidator.predicate("snapshot.created_at is ISO8601 date string")(
    !!snapshot.created_at && !isNaN(Date.parse(snapshot.created_at))
  );

  // 3. Edit (update) the thread (simulate user changing title/body)
  const newTitle = RandomGenerator.paragraph()();
  const newBody = RandomGenerator.paragraph()();
  const updatedThread = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: { title: newTitle, body: newBody } satisfies IDiscussionboardThreads.IUpdate,
  });
  typia.assert(updatedThread);
  TestValidator.equals("updated title")(updatedThread.title)(newTitle);
  TestValidator.equals("updated body")(updatedThread.body)(newBody);

  // 4. Confirm snapshot is unchanged and represents the pre-edit content
  TestValidator.equals("snapshot.title remains immutable after thread edit")(snapshot.title)(thread.title);
  TestValidator.notEquals("snapshot.title differs from updated thread")(snapshot.title)(updatedThread.title);

  // 5. Attempt to snapshot non-existent thread (should fail)
  await TestValidator.error("snapshot of non-existent thread should fail")(async () => {
    await api.functional.discussionboard.threadSnapshots.create(connection, {
      body: {
        thread_id: typia.random<string & tags.Format<"uuid">>(),
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.paragraph()(),
        reason: "invalid thread reference",
      } satisfies IDiscussionboardThreadSnapshots.ICreate,
    });
  });

  // 6. Soft-delete the thread via update and verify snapshot creation fails
  const deletedAt = new Date().toISOString();
  const softDeletedThread = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: { deleted_at: deletedAt } as any, // The schema for update doesn't expose deleted_at (but if endpoint allows, use it)
  });
  typia.assert(softDeletedThread);
  TestValidator.equals("thread deleted_at set")(softDeletedThread.deleted_at)(deletedAt);

  await TestValidator.error("snapshot on soft-deleted thread should fail")(async () => {
    await api.functional.discussionboard.threadSnapshots.create(connection, {
      body: {
        thread_id: thread.id,
        actor_id: thread.author_member_id,
        title: thread.title,
        body: thread.body,
        reason: "snapshot on deleted thread",
      } satisfies IDiscussionboardThreadSnapshots.ICreate,
    });
  });
}

