/**
 * Validate retrieval of a trending discussion topic by its id as an admin.
 *
 * Business context:
 * Trending topics reflect threads with the most engagement, calculated daily or by the ranking engine. Only threads created in an active, visible board will appear after sufficient engagement and analytics pass. This test must cover the full process from board/thread creation to trending topic retrieval and verification by id.
 *
 * Steps:
 * 1. Create a discussion board (requires valid section/category uuids and attributes).
 * 2. Create a thread within that board. For now, use a random author_member_id, as authentication context is out of scope for this test.
 * 3. (In a live system, one would add replies/engagement, but trending calculation is simulated.)
 * 4. Fetch the trending topics list with a filter (optionally by board/thread) to get valid trending topic ids.
 * 5. Retrieve the trending topic by its id and verify that its information matches the record found in the trending topics listing. Validate all primary fields (id, discussionboard_thread_id, discussionboard_board_id, ranking_period_date, trending_score).
 */
export async function test_api_discussionboard_test_get_trending_topic_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(12),
      code: RandomGenerator.alphaNumeric(8),
      is_active: true,
      is_visible: true,
      description: RandomGenerator.paragraph()(),
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(board);

  // 2. Create a thread in that board
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(20),
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. Fetch trending topics (simulate analytics/trending engine)
  const trendingPage = await api.functional.discussionboard.trendingTopics.index(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_board_id: board.id,
      ranking_period_date_from: null,
      ranking_period_date_to: null,
    } satisfies IDiscussionboardTrendingTopic.IRequest,
  });
  typia.assert(trendingPage);
  TestValidator.predicate("at least one trending topic returned")(
    trendingPage.data.length > 0,
  );

  // Pick the first trending topic
  const trending = trendingPage.data[0];
  typia.assert(trending);

  // 4. Retrieve this trending topic by id
  const trendingById = await api.functional.discussionboard.trendingTopics.at(connection, {
    id: trending.id,
  });
  typia.assert(trendingById);

  // 5. Validate that both match
  TestValidator.equals("id matches")(trendingById.id)(trending.id);
  TestValidator.equals("thread id matches")(trendingById.discussionboard_thread_id)(trending.discussionboard_thread_id);
  TestValidator.equals("board id matches")(trendingById.discussionboard_board_id)(trending.discussionboard_board_id);
  TestValidator.equals("ranking_period_date matches")(trendingById.ranking_period_date)(trending.ranking_period_date);
  TestValidator.equals("trending_score matches")(trendingById.trending_score)(trending.trending_score);
}

