import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * End-to-end test for updating administrator assignments (discussionboard_admins.update).
 *
 * Validates behavior for updating an admin assignment by id. This includes:
 *
 * 1. Normal update of the permitted field (revoked_at)
 * 2. Revocation (setting revoked_at from null to now)
 * 3. Attempting to update with forbidden fields (should be rejected)
 * 4. Attempting update on non-existent admin assignment id (should error)
 * 5. Attempting to update an already-revoked assignment (should either not change or error appropriately)
 *
 * The workflow covers:
 *  - Creating an ordinary member (target)
 *  - Creating an initial admin (to be assigner)
 *  - Assigning admin rights to the target member with initial assignment
 *  - Updating the assignment record
 *  - Negative cases for invalid/immutable/forbidden updates and nonexistent record
 */
export async function test_api_discussionboard_test_update_admin_assignment_fields_and_handle_revocation(
  connection: api.IConnection,
) {
  // 1. Create admin who will assign another admin
  const adminCreator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "admin",
      is_active: true,
    },
  });
  typia.assert(adminCreator);

  // 2. Create a member to be promoted to admin
  const targetMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(targetMember);

  // 3. Assign admin rights to the target member
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: targetMember.id,
      assigned_by_admin_id: adminCreator.id, // self-assignment OK for initial bootstrapping
      assigned_at: new Date().toISOString(),
      revoked_at: null,
    },
  });
  typia.assert(adminAssignment);
  TestValidator.equals("admin assignment active")(adminAssignment.revoked_at)(null);

  // 4. Update (revoke) admin assignment -- main happy-path update
  const revocationTime = new Date().toISOString();
  const revoked = await api.functional.discussionboard.admins.update(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: revocationTime,
    },
  });
  typia.assert(revoked);
  TestValidator.equals("assignment revoked")(revoked.revoked_at)(revocationTime);

  // 5. Try updating forbidden/immutable field (should be ignored or error): only revoked_at is allowed
  await TestValidator.error("forbidden update fields")(async () => {
    await api.functional.discussionboard.admins.update(connection, {
      id: adminAssignment.id,
      body: {
        revoked_at: null,
        non_existent_field: "not allowed", // Should error or ignore (invalid keys)
      } as any, // For illustration: real code won't use extra fields
    });
  });

  // 6. Try to update a non-existent admin assignment (should error)
  await TestValidator.error("update nonexistent admin assignment")(async () => {
    await api.functional.discussionboard.admins.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        revoked_at: new Date().toISOString(),
      },
    });
  });

  // 7. Try to update an already-revoked assignment (revoked_at set); update revoked_at again (should not re-activate/should not error fatally)
  const reUpdate = await api.functional.discussionboard.admins.update(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: revoked.revoked_at,
    },
  });
  typia.assert(reUpdate);
  TestValidator.equals("revoked remains")(reUpdate.revoked_at)(revocationTime);
}

