 * 3. Create two report types (e.g., 'abuse' and 'spam')
 * 4. Create a report using the reporting member account
 * 5. (Success) - As moderator, update the report's description and type id to the second report type, verify success and updated values
 * 6. (Success) - As admin, update only the description, confirm type id remains unchanged
 * 7. (Failure) - Attempt to update an immutable field (try to set reporting_member_id), expect error and no change
 * 8. (Failure) - Attempt to change report type id to an invalid (non-existent) UUID, expect error
 * 9. (Failure) - Attempt update with a random non-existent report id, expect not found error
 * 10. For each mutation, verify immutable columns (id, reporting_member_id, target_object_id, target_object_type, reported_at) remain unchanged and only intended fields are updated.
 */
export async function test_api_discussionboard_test_update_report_fields_success_and_failure(connection: api.IConnection) {
