 * 이 테스트는 다음 절차를 완수함으로써 태그 할당 엔드포인트의 기본적인 동작을 검증합니다.
 *
 * 1. 회원(member) 생성 (태그 할당 작업을 위한 주체)
 * 2. 게시판(board) 생성 (쓰레드 등록을 위한 공간 마련)
 * 3. 쓰레드(thread) 생성 (태그 할당 대상)
 * 4. 쓰레드 태그 할당 생성 (ID 획득 및 이후 업데이트를 위함)
 * 5. 태그 할당의 assigned_at 값을 현재값과 다르게 변경해서 업데이트 실행
 * 6. 응답이 업데이트된 필드를 반영했는지 확인
 * 7. removed_at 값을 설정(=태그 해제 처리)하여 업데이트 실행
 * 8. 응답이 removed_at 값 변경을 반영했는지 확인
 */
export async function test_api_discussionboard_test_update_thread_tag_assignment_success(
  connection: api.IConnection,
) {
  // 1. 멤버(회원) 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 게시판 생성 (가짜 카테고리 및 섹션 값)
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. 쓰레드 생성
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(thread);

  // 4. 쓰레드 태그 할당 생성
  const threadTag = await api.functional.discussionboard.threadTags.create(connection, {
