      assigned_at: newAssignedAt,
      removed_at: null,
    },
  });
  typia.assert(updatedTag);
  TestValidator.equals("assigned_at 변경 반영됨")(updatedTag.assigned_at)(newAssignedAt);

  // 7. removed_at 값을 설정 (=태그 해제 처리)
  const removedAt = new Date(Date.now() + 1000 * 60 * 120).toISOString();
  const updatedTag2 = await api.functional.discussionboard.threadTags.update(connection, {
    id: threadTag.id,
    body: {
      removed_at: removedAt,
    },
  });
  typia.assert(updatedTag2);
  TestValidator.equals("removed_at 변경 반영됨")(updatedTag2.removed_at)(removedAt);
}

