      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. 쓰레드 생성
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(thread);

  // 4. 쓰레드 태그 할당 생성
  const threadTag = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: new Date().toISOString(),
      removed_at: null,
    },
  });
  typia.assert(threadTag);

  // 5. assigned_at 값을 변경해서 업데이트 실행
  const newAssignedAt = new Date(Date.now() + 1000 * 60 * 60).toISOString();
  const updatedTag = await api.functional.discussionboard.threadTags.update(connection, {
    id: threadTag.id,
    body: {
      assigned_at: newAssignedAt,
      removed_at: null,
    },
  });
  typia.assert(updatedTag);
  TestValidator.equals("assigned_at 변경 반영됨")(updatedTag.assigned_at)(newAssignedAt);

  // 7. removed_at 값을 설정 (=태그 해제 처리)
  const removedAt = new Date(Date.now() + 1000 * 60 * 120).toISOString();
  const updatedTag2 = await api.functional.discussionboard.threadTags.update(connection, {
    id: threadTag.id,
    body: {
      removed_at: removedAt,
    },
  });
  typia.assert(updatedTag2);
  TestValidator.equals("removed_at 변경 반영됨")(updatedTag2.removed_at)(removedAt);
}

