/**
 * Validate rejection of post report submissions with invalid or missing fields.
 *
 * This test ensures the API does not accept creation of post report objects when required fields are missing or reference non-existent entities. It covers cases such as:
 *   - Supplying an invalid/nonexistent post ID
 *   - Supplying an invalid/nonexistent reporter member ID
 *   - Supplying an invalid/nonexistent report type ID
 *   - Omitting required fields (e.g., missing reporter, report type, or post ID)
 *   - Omitting the description (should be allowed if it is optional)
 *   - Omitting the created_at timestamp (should cause error)
 *
 * Steps:
 * 1. Set up a valid member, post, and report type for baseline (all with real IDs).
 * 2. Attempt to create reports with various invalid or incomplete payloads, including:
 *    - Fake/nonexistent UUID for post, member, or report type
 *    - Omitting each required property one at a time
 * 3. For each attempt, assert that the API throws a validation or integrity error (TestValidator.error) and no report is created as a result.
 * 4. Confirm success for valid payload (sanity check, not required in this negative test, but ensures baseline works).
 */
export async function test_api_discussionboard_test_create_post_report_with_invalid_fields_fails(
  connection: api.IConnection,
) {
  // 1. Create valid member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
