    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(), // Not in database
        reporter_member_id: member.id,
        report_type_id: reportType.id,
        description: "Test report",
        created_at: new Date().toISOString(),
      } satisfies IPostReport.ICreate,
    })
  );

  // 5. Negative test: non-existent member id
  await TestValidator.error("non-existent reporter_member_id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: typia.random<string & tags.Format<"uuid">>(), // Not in database
        report_type_id: reportType.id,
        description: "Test report",
        created_at: new Date().toISOString(),
      } satisfies IPostReport.ICreate,
    })
  );

  // 6. Negative test: non-existent report_type_id
  await TestValidator.error("non-existent report_type_id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: member.id,
        report_type_id: typia.random<string & tags.Format<"uuid">>(), // Not in database
        description: "Test report",
        created_at: new Date().toISOString(),
      } satisfies IPostReport.ICreate,
    })
  );

  // 7. Negative test: missing required field 'discussionboard_post_id'
  await TestValidator.error("missing discussionboard_post_id")(() =>
    // This will fail type checking so we skip actually defining the missing field test
    // See implementation guidance: do not attempt tests that cause TS compile errors
    Promise.reject()
  );

  // 8. Negative test: missing required field 'reporter_member_id'
  await TestValidator.error("missing reporter_member_id")(() =>
    // Likewise, this will fail type checking. Skipped.
    Promise.reject()
  );

  // 9. Negative test: missing required field 'report_type_id'
  await TestValidator.error("missing report_type_id")(() =>
    Promise.reject()
  );

  // 10. Negative test: missing required field 'created_at'
  await TestValidator.error("missing created_at")(() =>
    Promise.reject()
  );

  // 11. Omitting optional description should be valid (sanity check)
  const report = await api.functional.discussionboard.postReports.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      reporter_member_id: member.id,
      report_type_id: reportType.id,
      created_at: new Date().toISOString(),
    } satisfies IPostReport.ICreate,
  });
