import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotificationTemplate";
import type { IPageDiscussionboardNotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotificationTemplate";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and filtering for notification templates using valid criteria (code, name, is_active, created_at/updated_at ranges).
 *
 * 1. Create several notification templates with different code, name, is_active, date ranges, and subject values.
 * 2. Use the API to search/filter templates using a variety of valid criteria:
 *    - By code (exact match)
 *    - By name (exact match)
 *    - By is_active (true/false)
 *    - By created_at range
 *    - By updated_at range
 *    - By a combination of the above with pagination (page, limit)
 * 3. Each time, assert that only templates matching the filter are returned and that response pagination is correct.
 * 4. Attempt to search using unsupported/filter fields (schema-undefined) — skip this as only schema-defined fields can be used (per API contract).
 * 5. Check that no extraneous fields are returned in the response.
 */
export async function test_api_discussionboard_notificationTemplates_test_search_notification_templates_with_valid_criteria(
  connection: api.IConnection,
) {
  // 1. Create several notification templates
  const timeStart = new Date(Date.now() - 10 * 60 * 1000).toISOString(); // 10 minutes ago
  const templates: IDiscussionboardNotificationTemplate[] = [];
  for (let i = 0; i < 4; ++i) {
    const template = await api.functional.discussionboard.notificationTemplates.create(connection, {
      body: {
        code: `code_filter_test_${i}`,
        name: `Filter Test Name ${i}`,
        description: `Test template for filtering (${i})`,
        subject: `Filter Test Subject ${i}`,
        body: `Body Filter Test ${i}`,
        is_active: i % 2 === 0,
      } satisfies IDiscussionboardNotificationTemplate.ICreate,
    });
    typia.assert(template);
    templates.push(template);
  }

  const timeEnd = new Date(Date.now() + 10 * 60 * 1000).toISOString(); // 10 minutes after

  // 2a. Filter by code
  for (const template of templates) {
    const res = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { code: template.code },
    });
    typia.assert(res);
    TestValidator.predicate(`filter by code finds correct template`)(
      res.data.some((t) => t.code === template.code)
    );
  }

  // 2b. Filter by name
  for (const template of templates) {
    const res = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { name: template.name },
    });
    typia.assert(res);
    TestValidator.predicate(`filter by name finds correct template`)(
      res.data.some((t) => t.name === template.name)
    );
  }

  // 2c. Filter by is_active = true
  let res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { is_active: true },
  });
  typia.assert(res);
  TestValidator.predicate("all returned active templates are is_active = true")(
    res.data.every((t) => t.is_active)
  );
  TestValidator.predicate("pagination fields present")(res.pagination.current >= 1 && res.pagination.limit >= 1);

  // 2d. Filter by is_active = false
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { is_active: false },
  });
  typia.assert(res);
  TestValidator.predicate("all returned inactive templates are is_active = false")(
    res.data.every((t) => t.is_active === false)
  );
  TestValidator.predicate("pagination fields present")(res.pagination.current >= 1 && res.pagination.limit >= 1);

  // 2e. Filter by created_at range
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { created_at_from: timeStart, created_at_to: timeEnd },
  });
  typia.assert(res);
  TestValidator.predicate("all returned templates created within range")(
    res.data.every((t) => t.created_at >= timeStart && t.created_at <= timeEnd)
  );

  // 2f. Filter by updated_at range (should match recent templates)
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { updated_at_from: timeStart, updated_at_to: timeEnd },
  });
  typia.assert(res);
  TestValidator.predicate("all returned templates updated within range")(
    res.data.every((t) => t.updated_at >= timeStart && t.updated_at <= timeEnd)
  );

  // 2g. Pagination (page/limit)
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(res);
  TestValidator.equals("limit honored")(res.data.length)(2);
  TestValidator.equals("current page is 1")(res.pagination.current)(1);
  TestValidator.equals("per page equals limit")(res.pagination.limit)(2);

  // 3. No schema-undefined fields are accepted (cannot test invalid fields, as type safety prevents)
  // 4. All response objects must only have schema-defined fields (verified by typia assertions)
}

