import type { IPageIDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing (searching) of activity logs with a variety of filters and pagination options as an admin.
 *
 * This test ensures:
 * 1. Activity logs exist by triggering relevant actions (member creation, board creation, post creation, comment creation).
 * 2. You can successfully list activity logs filtered by:
 *    - member id
 *    - board id
 *    - post id
 *    - comment id
 *    - event type
 * 3. Pagination metadata is correct and matches expected result counts.
 * 4. Only schema-defined fields are present in the response.
 *
 * Steps:
 * 1. Create an admin member to serve as the actor for log-generating actions.
 * 2. Create a board to allow actions in its context.
 * 3. Create a post in the board (requiring thread id, use board id as pseudo-thread id if needed for test).
 * 4. Create a comment under the post with the admin member as the author.
 * 5. For each entity (member, board, post, comment), query the activity log endpoint using the relevant filter.
 * 6. Query by known event types that must exist due to the actions completed above (e.g. member_create, board_create, post_create, comment_create).
 * 7. Test pagination by limiting to 1 and checking returned record count and pagination metadata.
 * 8. Verify all records in responses only contain schema fields (no unexpected fields present).
 */
export async function test_api_discussionboard_test_list_activity_logs_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create an admin member
  const admin: IDiscussionboardMember = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: "admin",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    },
  );
  typia.assert(admin);

  // 2. Create a board
  const board: Idiscussionboard_boards = await api.functional.discussionboard.boards.create(
    connection,
    {
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
        name: RandomGenerator.alphabets(8),
        code: RandomGenerator.alphaNumeric(6),
        description: RandomGenerator.paragraph()(),
        is_active: true,
        is_visible: true,
      } satisfies Idiscussionboard_boards.ICreate,
    },
  );
  typia.assert(board);

  // 3. Create a post by the admin member in the board (using random thread id)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        discussionboard_member_id: admin.id,
        discussionboard_board_id: board.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_deleted: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Create a comment under the post by the admin
  const comment: IComment = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: admin.id,
        body: RandomGenerator.content()()(),
      } satisfies IComment.ICreate,
    },
  );
  typia.assert(comment);

  // 5. Query activity logs by member id
  const logsByMember = await api.functional.discussionboard.activityLogs.index(
    connection,
    {
      body: {
        discussionboard_member_id: admin.id,
      },
    },
  );
  typia.assert(logsByMember);
  TestValidator.predicate("activity logs by member exist")(logsByMember.data.length > 0);
  logsByMember.data.forEach((log) => {
    TestValidator.equals("member ID matches")(log.discussionboard_member_id)(admin.id);
  });

  // 6. Query activity logs by board id
  const logsByBoard = await api.functional.discussionboard.activityLogs.index(
    connection,
    {
      body: {
        discussionboard_board_id: board.id,
      },
    },
  );
  typia.assert(logsByBoard);
  TestValidator.predicate("activity logs by board exist")(logsByBoard.data.length > 0);
  logsByBoard.data.forEach((log) => {
    TestValidator.equals("board ID matches")(log.discussionboard_board_id)(board.id);
  });

  // 7. Query activity logs by post id
  const logsByPost = await api.functional.discussionboard.activityLogs.index(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
      },
    },
  );
  typia.assert(logsByPost);
  TestValidator.predicate("activity logs by post exist")(logsByPost.data.length > 0);
  logsByPost.data.forEach((log) => {
    TestValidator.equals("post ID matches")(log.discussionboard_post_id)(post.id);
  });

  // 8. Query activity logs by comment id
  const logsByComment = await api.functional.discussionboard.activityLogs.index(
    connection,
    {
      body: {
        discussionboard_comment_id: comment.id,
      },
    },
  );
  typia.assert(logsByComment);
  TestValidator.predicate("activity logs by comment exist")(logsByComment.data.length > 0);
  logsByComment.data.forEach((log) => {
    TestValidator.equals("comment ID matches")(log.discussionboard_comment_id)(comment.id);
  });

  // 9. Query by (likely) event types
  const eventTypes = [
    logsByMember.data[0]?.event_type,
    logsByBoard.data[0]?.event_type,
    logsByPost.data[0]?.event_type,
    logsByComment.data[0]?.event_type,
  ].filter((evt) => typeof evt === "string");
  for (const event_type of eventTypes) {
    const logsByEventType = await api.functional.discussionboard.activityLogs.index(
      connection,
      {
        body: {
          event_type,
        },
      },
    );
    typia.assert(logsByEventType);
    TestValidator.predicate("activity logs by event type exist")(logsByEventType.data.length > 0);
    logsByEventType.data.forEach((log) => {
      TestValidator.equals("event_type matches")(log.event_type)(event_type);
    });
  }

  // 10. Test pagination (limit to 1 result per page if filter returns results)
  const logsPage = await api.functional.discussionboard.activityLogs.index(
    connection,
    {
      body: {
        discussionboard_member_id: admin.id,
        // Since pagination fields are not directly in IRequest, test limiting by slicing in further assertions
      },
    },
  );
  typia.assert(logsPage);
  if (logsPage.data.length > 0) {
    TestValidator.predicate("Pagination metadata valid")(
      typeof logsPage.pagination === "object" &&
        typeof logsPage.pagination.current === "number" &&
        typeof logsPage.pagination.records === "number"
    );
    // Simulate page with single result for direct check
    if (logsPage.data.length > 1) {
      const firstLogId = logsPage.data[0].id;
      const oneLog = await api.functional.discussionboard.activityLogs.index(
        connection,
        {
          body: {
            discussionboard_member_id: admin.id,
            // Actual backend implementation should have a limit/offset in body, but if not, simply check .data[0]
          },
        },
      );
      typia.assert(oneLog);
      TestValidator.equals("first log same as oneLog[0]")(oneLog.data[0].id)(firstLogId);
    }
  }

  // 11. Check returned fields are only those defined in schema
  const allowedFields = [
    "id",
    "discussionboard_member_id",
    "discussionboard_board_id",
    "discussionboard_thread_id",
    "discussionboard_post_id",
    "discussionboard_comment_id",
    "event_timestamp",
    "event_type",
    "event_metadata",
  ];
