      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Cast upvote (vote_type=1)
  const vote1 = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
