import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPrivacyPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPrivacyPolicy";
import type { IPageDiscussionboardPrivacyPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardPrivacyPolicy";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 다양한 필터(제목, 버전, 시행일 등)를 적용하여 개인정보처리방침(PP) 페이지네이션/검색 API를 검증합니다.
 *
 * 시나리오 배경:
 * - 개인정보처리방침(PP)은 효력발생일, 버전, 제목, 본문, 생성/수정일 등 schema 기반 필드만 필터로 지원하며, field 외 검색/정렬/삭제 기능은 허용되지 않습니다.
 * - 이 테스트는 감사·버전 이력 관리 및 준법감시 목적 하에, 올바른 필터링/검색/페이지네이션 결과와 관련 메타데이터가 응답되는지 검증합니다.
 *
 * 테스트 프로세스:
 * 1. 관리자 회원을 등록합니다(정상 인가 및 인증용).
 * 2. 여러 건의 개인정보처리방침을 서로 다른 version, effective_date로 등록합니다(데이터 세팅).
 * 3. 다음 필터별로 검색을 시도하고 결과 검증:
 *    - version(정확일치): 특정 버전값으로 필터하여 해당 version의 정책이 단건/0건만 반환되는지, 없는 값은 결과 없음(confirm).
 *    - title(일부/부분검색): title 일부를 포함하는 키워드로 검색하여 해당 되는 정책만 반환되는지.
 *    - effective_date(날짜 범위): 효력 발생일이 특정 범위 이상/이하/일치하는 데이터만 반환되는지.
 * 4. 응답 데이터의 pagination 메타데이터(현재 페이지, 페이지별 개수, 전체 개수 등)와 반환 privacy policy 필드 구조 일치 및 type 검증.
 *
 * 유의사항:
 * - schema에 없는 필드로 검색할 경우, API가 허용하지 않아야 하며 반려되어야 합니다(여기선 schema 필드로만 테스트).
 * - 각 단계별 응답 및 조회된 개인정보처리방침 데이터와 설정 값이 일치하는지 확인합니다.
 */
export async function test_api_discussionboard_test_search_privacy_policies_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. 관리자 회원 등록
  const admin: IDiscussionboardMember =
    await api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(20),
        role: "admin",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    });
  typia.assert(admin);

  // 2. 테스트용 서로 다른 개인정보처리방침 데이터 여러 건 등록
  const policies: IDiscussionboardPrivacyPolicy[] = await ArrayUtil.asyncRepeat(3)(async (idx) => {
    const item = await api.functional.discussionboard.privacyPolicies.create(connection, {
      body: {
        version: `v2024.0${idx+1}`,
        effective_date: new Date(2024, 6, 1 + idx).toISOString(),
        title: `정책 타이틀 ${idx+1}`,
        content: `정책 본문 텍스트 ${idx+1}`,
      } satisfies IDiscussionboardPrivacyPolicy.ICreate,
    });
    typia.assert(item);
    return item;
  });

  // 3. 버전(version) 필터 테스트: 정책 별로 정확히 조회
  for (const policy of policies) {
    const result = await api.functional.discussionboard.privacyPolicies.index(connection, {
      body: { version: policy.version } satisfies IDiscussionboardPrivacyPolicy.IRequest,
    });
    typia.assert(result);
    TestValidator.predicate(`버전별 단건 조회/확인`)(
      result.data.length === 1 && result.data[0].version === policy.version
    );
  }
  // 없는 버전 문자열로 0건 필터
  const noneResult = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { version: "v9999.99" } satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(noneResult);
  TestValidator.equals("없는버전 0건")(noneResult.data.length)(0);

  // 4. title 부분검색(정책 타이틀 일부 키워드 포함 필터)
  for (const searchWord of ["정책", "타이틀", "1"]) {
    const result = await api.functional.discussionboard.privacyPolicies.index(connection, {
      body: { title: searchWord } satisfies IDiscussionboardPrivacyPolicy.IRequest,
    });
    typia.assert(result);
    TestValidator.predicate("title 서브스트링 매칭 확인")(
      result.data.every((row) => row.title.includes(searchWord))
    );
  }

  // 5. effective_date 범위(이상/이하/정확일치) 필터
  // 이상 (after-or-equal)
  const afterDate = policies[1].effective_date;
  const afterResult = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { effective_date: afterDate } satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(afterResult);
  TestValidator.predicate("이후 effective_date만 조회")(
    afterResult.data.every((row) => row.effective_date >= afterDate)
  );

  // 이하 테스트(earlier or equal) - created_at도 응용할 수 있으나 여기선 effective_date 집중

  // 정확히 특정 날짜만 필터
  const exactDate = policies[0].effective_date;
  const exactResult = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { effective_date: exactDate } satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(exactResult);
  TestValidator.predicate("정확히 해당 effective_date만 조회")(
    exactResult.data.every((row) => row.effective_date === exactDate)
  );

  // 6. 페이지네이션 및 응답 구조/타입 검증
  const pagedResult = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: {} satisfies IDiscussionboardPrivacyPolicy.IRequest,
  });
  typia.assert(pagedResult);
  TestValidator.predicate("pagination 메타데이터 존재")(
    typeof pagedResult.pagination.current === "number" &&
    typeof pagedResult.pagination.limit === "number" &&
    typeof pagedResult.pagination.records === "number" &&
    typeof pagedResult.pagination.pages === "number"
  );
  TestValidator.predicate("응답데이터 타입 검증[PrivacyPolicy]")(
    pagedResult.data.every((item) =>
      typeof item.id === "string" && typeof item.version === "string" && typeof item.title === "string"
    )
  );
}

