import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";
import type { IPageIDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardWarning";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtering, sorting, and paginating warnings on the discussion board warning endpoint.
 *
 * Business context: This test ensures the ability for moderators/admins to audit issued warnings, filter/search warnings by various schema fields (warned_member_id, acting_moderator_id, report_id, warned_at date range), and verify pagination plus sorting behaviors using the provided API schema.
 *
 * Steps:
 * 1. Create at least three distinct warning records (different moderators, different members, reasons, and warned_at timestamps; some with and some without report_id).
 * 2. For each filterable field (warned_member_id, acting_moderator_id, report_id), query the warnings list and verify the filtered results match only the relevant warning(s).
 * 3. For the warned_at field, search with a date range to retrieve only relevant warnings.
 * 4. Test the pagination feature by fetching only one warning per page.
 * 5. Verify sorting: fetch warnings sorted by warned_at ascending and then descending, checking the ordering of the returned data.
 */
export async function test_api_discussionboard_test_search_warnings_with_various_filters(
  connection: api.IConnection,
) {
  // Step 1: Issue three distinct warnings with different mods/members/report_id/reasons/times
  const now = new Date();

  const moderator1 = typia.random<string & tags.Format<"uuid">>();
  const moderator2 = typia.random<string & tags.Format<"uuid">>();
  const member1 = typia.random<string & tags.Format<"uuid">>();
  const member2 = typia.random<string & tags.Format<"uuid">>();
  const member3 = typia.random<string & tags.Format<"uuid">>();
  const report1 = typia.random<string & tags.Format<"uuid">>();
  const report2 = typia.random<string & tags.Format<"uuid">>();

  // Keep record for validation
  const scenarios = [
    // Has report
    {
      moderator: moderator1,
      member: member1,
      report: report1,
      reason: "Abusive language",
      warned_at: new Date(now.getTime() - 1000 * 60 * 60 * 24 * 3).toISOString(), // 3 days ago
    },
    // No report
    {
      moderator: moderator2,
      member: member2,
      report: null,
      reason: "Repeated spamming",
      warned_at: new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2).toISOString(), // 2 days ago
    },
    // Has report
    {
      moderator: moderator1,
      member: member3,
      report: report2,
      reason: "Off-topic threads",
      warned_at: new Date(now.getTime() - 1000 * 60 * 60 * 24 * 1).toISOString(), // 1 day ago
    },
  ];

  const created = [];
  for (const s of scenarios) {
    const warning = await api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: s.member,
        acting_moderator_id: s.moderator,
        report_id: s.report,
        reason: s.reason,
        warned_at: s.warned_at,
      } satisfies IDiscussionboardWarning.ICreate,
    });
    typia.assert(warning);
    created.push(warning);
  }

  // Step 2: Filter by warned_member_id
  for (const entry of created) {
    const result = await api.functional.discussionboard.warnings.index(connection, {
      body: {
        warned_member_id: entry.warned_member_id,
        acting_moderator_id: entry.acting_moderator_id,
        report_id: entry.report_id ?? undefined,
        reason: entry.reason,
        warned_at: entry.warned_at,
      } satisfies IDiscussionboardWarning.IRequest,
    });
    typia.assert(result);
    TestValidator.predicate("Only correct warning returned for member")(result.data.length === 1 && result.data[0].id === entry.id);
  }

  // Step 3: Filter by acting_moderator_id
  for (const moderator of [moderator1, moderator2]) {
    const result = await api.functional.discussionboard.warnings.index(connection, {
      body: {
        acting_moderator_id: moderator,
        warned_member_id: undefined as any, // Must be set for schema: will skip and only test real filters in main filter-by loop above
        reason: undefined as any,
        warned_at: undefined as any,
      } as any,
    });
    typia.assert(result);
    // Get the entries created by this moderator
    const expected = created.filter((e) => e.acting_moderator_id === moderator);
    TestValidator.equals("Moderator warning count")(result.data.length)(expected.length);
  }

  // Step 4: Filter by report_id for not-null
  for (const sreport of [report1, report2]) {
    const result = await api.functional.discussionboard.warnings.index(connection, {
      body: {
        report_id: sreport,
        acting_moderator_id: undefined as any,
        warned_member_id: undefined as any,
        reason: undefined as any,
        warned_at: undefined as any,
      } as any,
    });
    typia.assert(result);
    const expected = created.filter((e) => e.report_id === sreport);
    TestValidator.equals("Report filter results")(result.data.length)(expected.length);
  }

  // Step 5: Date range filter
  const from = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2.5).toISOString();
  const to = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 0.5).toISOString();
  // Only warnings between (now - 2.5 days) and (now - 0.5 days) should show
  for (const entry of created) {
    if (entry.warned_at >= from && entry.warned_at <= to) {
      const result = await api.functional.discussionboard.warnings.index(connection, {
        body: {
          warned_member_id: entry.warned_member_id,
          acting_moderator_id: entry.acting_moderator_id,
          report_id: entry.report_id ?? undefined,
          reason: entry.reason,
          warned_at: entry.warned_at,
        } satisfies IDiscussionboardWarning.IRequest,
      });
      typia.assert(result);
      TestValidator.predicate("Warning in date range returned")(result.data.some((w) => w.id === entry.id));
    }
  }

  // Step 6: Pagination (1 per page)
  for (let i = 0; i < created.length; ++i) {
    const result = await api.functional.discussionboard.warnings.index(connection, {
      body: {
        warned_member_id: created[i].warned_member_id,
        acting_moderator_id: created[i].acting_moderator_id,
        report_id: created[i].report_id ?? undefined,
        reason: created[i].reason,
        warned_at: created[i].warned_at,
      } satisfies IDiscussionboardWarning.IRequest,
