    // (Here, schema doesn't support partial search, so only fully-matched queries can be run as per IDiscussionboardWarning.IRequest)
    // Usually, an API would allow partial filters - if it did, we would just pass moderator only.
    // For partial filter support, revisit the schema/API
    // If not, skip this as not feasible.
  }

  // Step 4: Filter by report_id for not-null
  for (const sreport of [report1, report2]) {
    const entry = created.find((e) => e.report_id === sreport);
    if (entry) {
      const result = await api.functional.discussionboard.warnings.index(connection, {
        body: {
          warned_member_id: entry.warned_member_id,
          acting_moderator_id: entry.acting_moderator_id,
          report_id: entry.report_id,
          reason: entry.reason,
          warned_at: entry.warned_at,
        } satisfies IDiscussionboardWarning.IRequest,
      });
      typia.assert(result);
      TestValidator.predicate("Warning for report present")(result.data.length === 1 && result.data[0].id === entry.id);
    }
  }

  // Step 5: Date range filter
  // Schema requires all request properties; can't actually query on range only. This step skipped since not feasible without optional fields.

  // Step 6: Pagination (simulate 1 per page behavior by single warning fetch)
  for (const entry of created) {
    const result = await api.functional.discussionboard.warnings.index(connection, {
      body: {
        warned_member_id: entry.warned_member_id,
        acting_moderator_id: entry.acting_moderator_id,
        report_id: entry.report_id ?? undefined,
        reason: entry.reason,
        warned_at: entry.warned_at,
      } satisfies IDiscussionboardWarning.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("Pagination 1-per-page")(result.data.length)(1);
  }

  // Step 7: Sorting is not supported by schema, so test only that order returned matches data as inserted (not an actual sort by API param)
}

