 * 5. List board settings filtered by allow_anonymous_viewing=false and verify all returned settings have allow_anonymous_viewing=false.
 * 6. List board settings with pagination parameters (limit=2, page=1/2) and verify pagination correctness and paging behavior.
 *
 * Each step asserts that filtering and pagination behave as expected. All API responses are type-checked with typia.assert, and business logic is verified with TestValidator.
 */
export async function test_api_discussionboard_test_list_board_settings_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create several boards
  const categoryIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const sectionIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const boards = await Promise.all(categoryIds.map((category, idx) =>
    api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: category,
        discussionboard_section_id: sectionIds[idx],
        name: `Board ${idx+1} - ${RandomGenerator.name()}`,
        code: `code_${RandomGenerator.alphaNumeric(6)}_${idx}`,
        description: RandomGenerator.paragraph()(),
        is_active: true,
        is_visible: true
      } satisfies Idiscussionboard_boards.ICreate
    })
  ));
  boards.forEach((board, idx) => {
    typia.assert(board);
    TestValidator.equals(`board id nonempty`)(typeof board.id === "string" && !!board.id)(true);
    TestValidator.equals(`board category matches`)(board.discussionboard_board_category_id)(categoryIds[idx]);
    TestValidator.equals(`board section matches`)(board.discussionboard_section_id)(sectionIds[idx]);
  });

  // 2. Create unique board settings for each board
  const settingsVariants = [
    { is_locked: false, require_approval_for_posting: false, allow_anonymous_viewing: true, allow_file_uploads: true, max_posts_per_hour: 10 },
    { is_locked: true, require_approval_for_posting: true, allow_anonymous_viewing: false, allow_file_uploads: false, max_posts_per_hour: 5 },
    { is_locked: false, require_approval_for_posting: true, allow_anonymous_viewing: false, allow_file_uploads: true, max_posts_per_hour: 3 }
  ];
  const settings = await Promise.all(boards.map((board, idx) =>
    api.functional.discussionboard.boardSettings.create(connection, {
      body: {
        discussionboard_board_id: board.id,
        ...settingsVariants[idx]
      } satisfies IDiscussionboardBoardSetting.ICreate
    })
  ));
  settings.forEach((setting, idx) => {
    typia.assert(setting);
    TestValidator.equals(`settings id nonempty`)(typeof setting.id === "string" && !!setting.id)(true);
    TestValidator.equals(`settings board id matches`)(setting.discussionboard_board_id)(boards[idx].id);
    TestValidator.equals(`is_locked matches`)(setting.is_locked)(settingsVariants[idx].is_locked);
    TestValidator.equals(`require_approval_for_posting matches`)(setting.require_approval_for_posting)(settingsVariants[idx].require_approval_for_posting);
    TestValidator.equals(`allow_anonymous_viewing matches`)(setting.allow_anonymous_viewing)(settingsVariants[idx].allow_anonymous_viewing);
    TestValidator.equals(`allow_file_uploads matches`)(setting.allow_file_uploads)(settingsVariants[idx].allow_file_uploads);
    TestValidator.equals(`max_posts_per_hour matches`)(setting.max_posts_per_hour)(settingsVariants[idx].max_posts_per_hour);
  });

  // 3. Filter: by specific board
  const targetIdx = 1;
  const filterByBoard = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { discussionboard_board_id: boards[targetIdx].id } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(filterByBoard);
  TestValidator.equals("single board setting returned")(filterByBoard.data.length)(1);
  TestValidator.equals("correct setting board id")(filterByBoard.data[0].discussionboard_board_id)(boards[targetIdx].id);

  // 4. Filter: is_locked = true
  const lockedRes = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { is_locked: true } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(lockedRes);
  TestValidator.predicate("all is_locked true")(
    lockedRes.data.length > 0 && lockedRes.data.every(s => s.is_locked === true)
  );

  // 5. Filter: allow_anonymous_viewing = false
  const anonRes = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { allow_anonymous_viewing: false } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(anonRes);
  TestValidator.predicate("none allow anonymous viewing")(
    anonRes.data.every(s => s.allow_anonymous_viewing === false)
  );

  // 6a. Pagination: limit=2, page=1
  const page1 = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { page: 1, limit: 2 } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(page1);
  TestValidator.equals("pagination page one")(page1.pagination.current)(1);
  TestValidator.equals("pagination limit two")(page1.pagination.limit)(2);
  TestValidator.predicate("max 2 records for page 1")(page1.data.length <= 2);

  // 6b. Pagination: limit=2, page=2
  const page2 = await api.functional.discussionboard.boardSettings.index(connection, {
    body: { page: 2, limit: 2 } satisfies IDiscussionboardBoardSetting.IRequest
  });
  typia.assert(page2);
  TestValidator.equals("pagination page two")(page2.pagination.current)(2);
  TestValidator.equals("pagination limit two")(page2.pagination.limit)(2);
  // Ensure no overlap in ids between page 1 and page 2
  const page1Ids = page1.data.map(d => d.id);
  const page2Ids = page2.data.map(d => d.id);
  TestValidator.predicate("no overlap between page 1 and page 2")(
    page1Ids.every(id => !page2Ids.includes(id))
  );
}

