import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReport";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBan";

/**
 * Tests searching and retrieving bans in the discussion board with various filtering criteria and pagination.
 *
 * This test covers the following business and technical requirements:
 * - Bans can be filtered by banned member, acting moderator, report association (report_id), ban_type (temporary/permanent), date ranges (banned_at/expires_at), and combinations thereof.
 * - Proper pagination is enforced and result data matches the filtering envelope.
 * - Only schema-defined/filterable fields are used in search envelope and validated.
 *
 * Test workflow:
 * 1. Create a normal member (to be used as a banned user)
 * 2. Create a moderator member (to act as the banning moderator)
 * 3. Create a report made by the banned user (so it can be associated with a ban)
 * 4. Create several bans with different field values so all major filter scenarios are covered (banned by report, temporary/permanent ban_type, different time periods)
 * 5. Search bans:
 *    - By banned_member_id
 *    - By acting_moderator_id
 *    - By report_id
 *    - By ban_type
 *    - By date range (banned_at_from/banned_at_to, expires_at_from/expires_at_to)
 *    - By pagination (limits, offsets)
 *    - For a combination guaranteeing zero results
 *    - For a combination guaranteeing one or multiple results
 * 6. Validate: results only include bans matching filters, paginated listing is consistent with data, bans not matching are excluded.
 *
 * Edge cases:
 * - Attempt to search with filter values that do not match any bans (expect empty results).
 * - Use pagination to request data beyond available pages (expect empty data).
 */
export async function test_api_discussionboard_test_search_bans_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create a normal member (banned user)
  const bannedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(bannedMember);

  // Step 2: Create a moderator member
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(moderator);

  // Step 3: Create a post report by bannedMember
  const report = await api.functional.discussionboard.postReports.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      reporter_member_id: bannedMember.id,
      report_type_id: typia.random<string & tags.Format<"uuid">>(),
      description: "Test violation",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(report);

  // Step 4: Create bans with varied fields
  const now = new Date();
  const bans = [
    // Permanent ban, linked to the above report
    await api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderator.id,
        report_id: report.id,
        reason: "Abuse report ban",
        ban_type: "permanent",
        banned_at: now.toISOString(),
        expires_at: null,
      },
    }),
    // Temporary ban, not linked to a report
    await api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderator.id,
        reason: "Temp ban test",
        ban_type: "temporary",
        banned_at: new Date(now.getTime() + 1000 * 60 * 60 * 24).toISOString(),
        expires_at: new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7).toISOString(),
        report_id: null,
      },
    }),
  ];
  bans.forEach(ban => typia.assert(ban));

  // Step 5: Filtering & Paging - Single field: banned_member_id
  const byBannedMember = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_member_id: bannedMember.id,
    },
  });
  typia.assert(byBannedMember);
  TestValidator.predicate("all bans match bannedMember")(
    byBannedMember.data.every(ban => ban.banned_member_id === bannedMember.id),
  );

  // Filtering: acting_moderator_id
  const byModerator = await api.functional.discussionboard.bans.index(connection, {
    body: {
      acting_moderator_id: moderator.id,
    },
  });
  typia.assert(byModerator);
  TestValidator.predicate("all bans match moderator")(
    byModerator.data.every(ban => ban.acting_moderator_id === moderator.id),
  );

  // Filtering: report_id (should find only the permanent ban)
  const byReport = await api.functional.discussionboard.bans.index(connection, {
    body: {
      report_id: report.id,
    },
  });
  typia.assert(byReport);
  TestValidator.predicate("bans by report_id have correct report_id")(
    byReport.data.every(ban => ban.report_id === report.id),
  );
  TestValidator.equals("report_id ban count")(byReport.data.length)(1);

  // Filtering: ban_type (temporary)
  const byTemporaryType = await api.functional.discussionboard.bans.index(connection, {
    body: {
      ban_type: "temporary",
    },
  });
  typia.assert(byTemporaryType);
  TestValidator.predicate("bans of type temporary")(
    byTemporaryType.data.every(ban => ban.ban_type === "temporary"),
  );

  // Filtering: ban_type (permanent)
  const byPermanentType = await api.functional.discussionboard.bans.index(connection, {
    body: {
      ban_type: "permanent",
    },
  });
  typia.assert(byPermanentType);
  TestValidator.predicate("bans of type permanent")(
    byPermanentType.data.every(ban => ban.ban_type === "permanent"),
  );

  // Filtering: banned_at date range
  const start = now.toISOString();
  const end = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 2).toISOString();
  const byBannedAtRange = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_at_from: start,
      banned_at_to: end,
    },
  });
  typia.assert(byBannedAtRange);
  TestValidator.predicate("bans within banned_at range")(
    byBannedAtRange.data.every(ban => ban.banned_at >= start && ban.banned_at <= end),
  );

  // Filtering: expires_at_from and expires_at_to (should match only the temporary ban)
  const tempBan = bans.find(ban => ban.ban_type === "temporary")!;
  const byExpiresAtRange = await api.functional.discussionboard.bans.index(connection, {
    body: {
      expires_at_from: tempBan.expires_at!,
      expires_at_to: tempBan.expires_at!,
    },
  });
  typia.assert(byExpiresAtRange);
  TestValidator.predicate("bans within expires_at range")(
    byExpiresAtRange.data.every(ban => ban.expires_at === tempBan.expires_at),
  );

  // Filtering: pagination, limit to 1 per page to test paging mechanics
  const paged = await api.functional.discussionboard.bans.index(connection, {
    body: {
      pagination: { current: 1, limit: 1, records: 0, pages: 0 },
    },
  });
  typia.assert(paged);
  TestValidator.equals("paged result size")(paged.data.length)(1);

  // Filtering: combinations that should return no results (e.g., fake member id)
  const empty = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(empty);
  TestValidator.equals("empty query returns empty data")(empty.data.length)(0);

  // Filtering: combination that should return one result (temp ban with banned_member_id and ban_type=temporary)
  const oneResult = await api.functional.discussionboard.bans.index(connection, {
    body: {
      banned_member_id: bannedMember.id,
      ban_type: "temporary",
    },
  });
  typia.assert(oneResult);
  TestValidator.equals("temp ban unique result")(oneResult.data.length)(1);
  TestValidator.equals("temp ban's id matches")(oneResult.data[0].id)(tempBan.id);
}

