  const requiredFields = [
    "discussionboard_comment_id",
    "discussionboard_member_id",
    "discussionboard_report_type_id",
    "reason",
    "created_at"
  ] as const;

  for (const field of requiredFields) {
    const partialInput = { ...validInput };
    delete partialInput[field];
    TestValidator.error(`${field} 누락 시 validation 에러 발생해야 함`)(async () => {
      // @ts-expect-error: intentionally omit required
      await api.functional.discussionboard.commentReports.create(connection, {
        body: partialInput,
      });
    });
  }
}

