import type { IPageIDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트: 댓글 스냅샷의 페이지네이션(페이징) 검색 동작 검증
 *
 * 이 테스트는 /discussionboard/commentSnapshots API에 대해 실제 댓글이 여럿 버전으로
 * 스냅샷이 쌓인 상황에서 페이징 검색 시 메타데이터(pagination)와 데이터 슬라이스가
 * 정확하게 동작하는지 검증합니다.
 *
 * 단계:
 * 1. 댓글 작성자를 위한 멤버 생성
 * 2. 댓글이 달릴 게시글 생성 (post, thread/board UUID 필요)
 * 3. 해당 게시글에 댓글 생성
 * 4. 댓글에 대해 여러 번(버전) 스냅샷 생성 (댓글의 수정 이력 시뮬레이트)
 * 5. PATCH /discussionboard/commentSnapshots를 통해 페이징 기반으로 검색
 * 6. 페이징 메타데이터(전체 개수/limit 등)와 데이터 결과가 기대와 일치하는지 검증
 *
 * 중점 검증 사항:
 * - 특정 댓글에 대한 스냅샷들이 올바르게 리스트업됨
 * - 페이지네이션 메타(pagination)에 전체 개수, limit 등이 정확히 표시됨
 * - 요청 limit에 맞춘 데이터 slice(슬라이스) 정합성
 * - 각 요소가 올바른 comment id/버전/시각 정보 보유
 */
export async function test_api_discussionboard_test_search_comment_snapshots_with_pagination(
  connection: api.IConnection,
) {
  // 1. 댓글 작성자 멤버 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 게시글 생성 (스레드/보드 UUID 임의 생성)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();

  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_board_id: boardId,
      discussionboard_member_id: member.id,
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()(30)(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. 게시글에 댓글 작성
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.content()(15)(),
      // parent_id 없음 (최상위 덧글)
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. 댓글에 대한 여러 스냅샷(수정이력) 생성
  const SNAPSHOT_COUNT = 7;
  const snapshots: IDiscussionboardCommentSnapshot[] = [];
  let baseTime = Date.now();
  for (let i = 1; i <= SNAPSHOT_COUNT; ++i) {
    // 1회 수정마다 1분씩 증가 (시계열 순서 보장)
    const createdAt = new Date(baseTime + i * 60000).toISOString();
    const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
      body: {
        discussionboard_comment_id: comment.id,
        discussionboard_member_id: member.id,
        discussionboard_post_id: post.id,
        body: `Edit body ${i}`,
        version: i,
        snapshot_created_at: createdAt,
      } satisfies IDiscussionboardCommentSnapshot.ICreate,
    });
    typia.assert(snapshot);
    snapshots.push(snapshot);
  }

  // 5. 페이징 검색: limit=3 기준으로 한번 요청
  const PAGE_LIMIT = 3;
  // 첫 페이지(초기 limit 내 데이터)
  const firstPage = await api.functional.discussionboard.commentSnapshots.index(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      // limit/offset 파라미터는 search DTO에 없지만, 통상 결과는 limit=100(default) 기준으로 슬라이스됨
    } satisfies IDiscussionboardCommentSnapshot.IRequest,
  });
  typia.assert(firstPage);

  // 6. 페이지네이션/데이터 결과 검증
  TestValidator.equals("pagination: total count")(firstPage.pagination.records)(SNAPSHOT_COUNT);
  // limit=100(default)임을 전제로, 결과 slicing은 직접 체크
  TestValidator.equals("snapshots: count on first page")(firstPage.data.length)(Math.min(100, SNAPSHOT_COUNT));

  // 각 결과가 올바른 comment id인지, 버전 증가 순서 여부(버전 필드가 1~7 순인지) 검증
  let version = 1;
  for (const snapshot of firstPage.data) {
    TestValidator.equals("snapshot: comment id 매칭")(snapshot.discussionboard_comment_id)(comment.id);
    TestValidator.equals("snapshot: version 번호")(snapshot.version)(version++);
  }
}

