import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IPageIdiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_boards";
