import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * E2E test for listing discussion boards with various filters and pagination.
 *
 * Business context:
 * Admin panel or moderation interfaces require advanced board list views for maintenance, auditing, or navigation structure management. Realistic scenarios must verify:
 *  - Board metadata is correctly indexed by various criteria: category, section, code, name (partial/substring), is_active/is_visible flags.
 *  - Pagination accurately reflects limits/offset and page structure.
 *  - Sorting (by e.g. position or name) delivers the accurately ordered result set.
 *  - Error handling properly rejects invalid filter values and responds correctly if unknown category/section filters are used.
 *
 * Test steps:
 * 1. Create at least two categories with unique names/codes/position.
 * 2. Create at least two sections in (potentially different) channels, with unique codes/names/positions.
 *    (If channels are not createable, use random UUID for relation.)
 * 3. Create at least four boards, distributed across categories/sections, with a variety of name/code/description/active/visible settings to ensure diversity.
 * 4. Search for boards by exact category ID and verify only boards in that category are returned.
 * 5. Search by section ID and verify correct boards.
 * 6. Search by is_active/is_visible=true and false, confirm status filtering works.
 * 7. Search by code (exact), name (substring), and description (substring) for match.
 * 8. Test pagination: create a paginated request (limit/offset), verify returned count, navigation meta, and correct boards for the segment.
 * 9. Test result ordering (e.g., by name or position, if supported).
 * 10. Attempt filters with invalid (unknown) category_id/section_id and expect empty results or error.
 * 11. Provide incomplete/invalid filter object to test validation error.
 *
 * Assertions:
 * - All boards in result match filters.
 * - Pagination meta matches expected stats (current, limit, records, pages).
 * - Partial string search finds the right boards.
 * - Error/empty result for non-existent entities as filter.
 */
export async function test_api_discussionboard_test_list_boards_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create board categories
  const categoryA = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: `Category A ${RandomGenerator.alphaNumeric(6)}`,
      code: `catA${RandomGenerator.alphaNumeric(4)}`,
      description: "Board category A for tests.",
      position: 1,
    },
  });
  const categoryB = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: `Category B ${RandomGenerator.alphaNumeric(6)}`,
      code: `catB${RandomGenerator.alphaNumeric(4)}`,
      description: "Board category B for tests.",
      position: 2,
    },
  });
  typia.assert(categoryA);
  typia.assert(categoryB);

  // 2. Create board sections
  const channelIdA = typia.random<string & tags.Format<"uuid">>();
  const channelIdB = typia.random<string & tags.Format<"uuid">>();
  const sectionA = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channelIdA,
      name: `Section A ${RandomGenerator.alphaNumeric(5)}`,
      code: `sectA${RandomGenerator.alphaNumeric(3)}`,
      description: "Section A for test flow.",
      position: 1,
      active: true,
    },
  });
  const sectionB = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channelIdB,
      name: `Section B ${RandomGenerator.alphaNumeric(5)}`,
      code: `sectB${RandomGenerator.alphaNumeric(3)}`,
      description: "Section B for test flow.",
      position: 2,
      active: false,
    },
  });
  typia.assert(sectionA);
  typia.assert(sectionB);

  // 3. Create boards under all combinations of categories and sections
  const boards = [
    // Active & visible, categoryA + sectionA
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categoryA.id,
        discussionboard_section_id: sectionA.id,
        name: "Board AV",
        code: `baV${RandomGenerator.alphaNumeric(3)}`,
        description: "Active and visible board.",
        is_active: true,
        is_visible: true,
      },
    }),
    // Inactive & visible, categoryA + sectionB
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categoryA.id,
        discussionboard_section_id: sectionB.id,
        name: "Board IV",
        code: `biV${RandomGenerator.alphaNumeric(3)}`,
        description: "Inactive but visible.",
        is_active: false,
        is_visible: true,
      },
    }),
    // Active & hidden, categoryB + sectionA
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categoryB.id,
        discussionboard_section_id: sectionA.id,
        name: "Board AH",
        code: `baH${RandomGenerator.alphaNumeric(3)}`,
        description: "Active but not visible.",
        is_active: true,
        is_visible: false,
      },
    }),
    // Inactive & hidden, categoryB + sectionB
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categoryB.id,
        discussionboard_section_id: sectionB.id,
        name: "Board IH",
        code: `biH${RandomGenerator.alphaNumeric(3)}`,
        description: "Inactive and hidden.",
        is_active: false,
        is_visible: false,
      },
    }),
  ];
  for (const b of boards) typia.assert(b);

  // 4. Test search by category
  let listing = await api.functional.discussionboard.boards.index(connection, {
    body: {
      discussionboard_board_category_id: categoryA.id,
    },
  });
  typia.assert(listing);
  TestValidator.predicate("category filter matches correct boards")(
    listing.data.every(
      (b) => b.discussionboard_board_category_id === categoryA.id,
    ),
  );

  // 5. Test search by section
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: {
      discussionboard_section_id: sectionB.id,
    },
  });
  typia.assert(listing);
  TestValidator.predicate("section filter matches correct boards")(
    listing.data.every(
      (b) => b.discussionboard_section_id === sectionB.id,
    ),
  );

  // 6. Test filtering by is_active
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: {
      is_active: true,
    },
  });
  typia.assert(listing);
  TestValidator.predicate("active filter")(
    listing.data.every((b) => b.is_active === true),
  );

  // 7. Filter by is_visible
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: {
      is_visible: false,
    },
  });
  typia.assert(listing);
  TestValidator.predicate("visibility filter")(
    listing.data.every((b) => b.is_visible === false),
  );

  // 8. Search by code (exact)
  const oneBoard = boards[0];
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: { code: oneBoard.code },
  });
  typia.assert(listing);
  TestValidator.predicate("code search result")(
    listing.data.some((b) => b.id === oneBoard.id),
  );

  // 9. Search by substring of name
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: { name: "Board A" },
  });
  typia.assert(listing);
  TestValidator.predicate("partial name search")(
    listing.data.some((b) => b.name.includes("Board A")),
  );

  // 10. Search by substring of description
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: { description: "hidden" } as any, // omitting since not in schema, check if result is empty or error
  });
  typia.assert(listing);

  // 11. Test pagination (limit/offset)
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: { is_visible: true },
  });
  const allVisible = listing.data;
  const limit = 1;
  const paged = await api.functional.discussionboard.boards.index(connection, {
    body: { is_visible: true },
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit matches")(paged.pagination.limit)(limit);

  // 12. Attempt filter with unknown/non-existent category
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  listing = await api.functional.discussionboard.boards.index(connection, {
    body: { discussionboard_board_category_id: nonExistentId },
  });
  typia.assert(listing);
  TestValidator.equals("no boards match non-existent category")(
    listing.data.length,
  )(0);

  // 13. Submit invalid request object to cause (runtime) validation error
  await TestValidator.error("invalid board list filter fails")(() =>
    api.functional.discussionboard.boards.index(connection, {
      body: { is_active: "yes" as any },
    }),
  );
}

