  const threadD = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board2.id,
      author_member_id: member1.id,
      title: "ShouldBeExcluded",
      body: "This is a deleted thread.",
    },
  });
  typia.assert(threadD);

  // Soft-delete threadD via direct patch (simulate soft delete by setting deleted_at)
  // Simulate by altering the threadD object, as no delete API provided: "soft delete" for test only
  threadD.deleted_at = new Date().toISOString();

  // 4. Search with different filter/pagination scenarios
  // a) By board_id only (board1)
  const resultBoard = await api.functional.discussionboard.threads.index(connection, {
    body: { board_id: board1.id, page: 1, limit: 10, deleted: false },
