    body: { author_member_id: member2.id, page: 1, limit: 10, deleted: false },
  });
  typia.assert(resultAuthor);
  for (const t of resultAuthor.data) {
    TestValidator.equals("author matches")(t.author_member_id)(member2.id);
    TestValidator.equals("not soft-deleted")(t.deleted_at)(null);
  }

  // c) By date range (from the earliest thread to now)
  const createdDates = [threadA.created_at, threadB.created_at, threadC.created_at];
  const minDate = createdDates.reduce((a, b) => (a < b ? a : b));
  const maxDate = new Date().toISOString();
  const resultDate = await api.functional.discussionboard.threads.index(connection, {
    body: { created_at_from: minDate, created_at_to: maxDate, page: 1, limit: 10, deleted: false },
