    TestValidator.predicate("created_at upper bound")(t.created_at <= maxDate);
    TestValidator.equals("not soft-deleted")(t.deleted_at)(null);
  }

  // d) By partial keyword in title
  const resultTitle = await api.functional.discussionboard.threads.index(connection, {
    body: { title: "FindMe", page: 1, limit: 10, deleted: false },
  });
  typia.assert(resultTitle);
