  // f) Pagination check (limit: 1)
  const resultPage = await api.functional.discussionboard.threads.index(connection, {
    body: { page: 1, limit: 1, deleted: false },
  });
  typia.assert(resultPage);
  TestValidator.equals("1 record page")(resultPage.data.length)(1);
  TestValidator.equals("pagination.page")(resultPage.pagination.current)(1);
  TestValidator.equals("pagination.limit")(resultPage.pagination.limit)(1);
