    TestValidator.equals("not soft-deleted")(t.deleted_at)(null);
  }

  // c) Filter: date range
  const createdDates = [threadA.created_at, threadB.created_at, threadC.created_at];
  const minDate = createdDates.reduce((a, b) => (a < b ? a : b));
  const maxDate = new Date().toISOString();
  const resultDate = await api.functional.discussionboard.threads.index(connection, {
    body: { created_at_from: minDate, created_at_to: maxDate, page: 1, limit: 10, deleted: false },
  });
  typia.assert(resultDate);
  for (const t of resultDate.data) {
    TestValidator.predicate("created_at lower bound")(t.created_at >= minDate);
    TestValidator.predicate("created_at upper bound")(t.created_at <= maxDate);
    TestValidator.equals("not soft-deleted")(t.deleted_at)(null);
  }

  // d) Filter: partial match in title
  const resultTitle = await api.functional.discussionboard.threads.index(connection, {
    body: { title: "FindMe", page: 1, limit: 10, deleted: false },
  });
  typia.assert(resultTitle);
  for (const t of resultTitle.data) {
    TestValidator.predicate("title contains FindMe")(t.title.includes("FindMe"));
    TestValidator.equals("not soft-deleted")(t.deleted_at)(null);
  }

  // e) Combined: board_id + author_member_id
  const resultCombo = await api.functional.discussionboard.threads.index(connection, {
    body: { board_id: board1.id, author_member_id: member2.id, page: 1, limit: 10, deleted: false },
  });
  typia.assert(resultCombo);
  for (const t of resultCombo.data) {
    TestValidator.equals("combo board_id")(t.board_id)(board1.id);
    TestValidator.equals("combo author")(t.author_member_id)(member2.id);
    TestValidator.equals("not soft-deleted")(t.deleted_at)(null);
  }

  // f) Pagination: page 1, limit 1
  const resultPage = await api.functional.discussionboard.threads.index(connection, {
    body: { page: 1, limit: 1, deleted: false },
  });
  typia.assert(resultPage);
  TestValidator.equals("1 record page")(resultPage.data.length)(1);
  TestValidator.equals("pagination.page")(resultPage.pagination.current)(1);
  TestValidator.equals("pagination.limit")(resultPage.pagination.limit)(1);
  TestValidator.equals("not soft-deleted")(resultPage.data[0].deleted_at)(null);
}

