import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentVote";
import type { IPageIDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates listing and searching of comment votes with diverse filtering and pagination options.
 *
 * Business context: Vote search is used for moderation, analytics, and user histories; must support querying by member, comment, vote direction, date ranges, and pagination, and only return/request schema fields.
 *
 * Steps:
 * 1. Create several discussion board members.
 * 2. Create multiple posts (on potentially different boards/threads) as comment/vote targets.
 * 3. Each member authors comments on posts.
 * 4. Multiple members cast upvotes and downvotes (and update at least one vote) on comments.
 * 5. List votes using various filters (member, comment, vote_type, date range, pagination) and validate results/pagination and schema compliance.
 * 6. Test edge cases (nonexistent entity filters, empty date range, pagination correctness).
 */
export async function test_api_discussionboard_test_list_comment_votes_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // --- Step 1: Create 3 members ---
  const members = await Promise.all(
    ArrayUtil.repeat(3)(async () => {
      const username = RandomGenerator.alphaNumeric(8);
      const member = await api.functional.discussionboard.members.create(
        connection,
        {
          body: {
            username,
            email: `${username}@test.com` as string & tags.Format<"email">,
            hashed_password: RandomGenerator.alphaNumeric(12),
            role: "member",
            is_active: true,
          } satisfies IDiscussionboardMember.ICreate,
        },
      );
      typia.assert(member);
      return member;
    }),
  );

  // --- Step 2: Create 2 posts for voting ---
  // For required fields: need thread_id/board_id/member_id for each
  const threadIdA = typia.random<string & tags.Format<"uuid">>();
  const threadIdB = typia.random<string & tags.Format<"uuid">>();
  const boardIdA = typia.random<string & tags.Format<"uuid">>();
  const boardIdB = typia.random<string & tags.Format<"uuid">>();
  const posts = await Promise.all([
    api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: threadIdA,
        discussionboard_member_id: members[0].id,
        discussionboard_board_id: boardIdA,
        title: RandomGenerator.paragraph()(2),
        body: RandomGenerator.content()(1)(),
        is_deleted: false,
        created_at: new Date().toISOString() as string & tags.Format<"date-time">,
        updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardPost.ICreate,
    }),
    api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: threadIdB,
        discussionboard_member_id: members[1].id,
        discussionboard_board_id: boardIdB,
        title: RandomGenerator.paragraph()(2),
        body: RandomGenerator.content()(1)(),
        is_deleted: false,
        created_at: new Date().toISOString() as string & tags.Format<"date-time">,
        updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardPost.ICreate,
    }),
  ]);
  posts.forEach(typia.assert);

  // --- Step 3: Create 4 comments (2 per post, varying author) ---
  const comments = [
    // Post 0, member 1
    await api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: posts[0].id,
        discussionboard_member_id: members[1].id,
        body: RandomGenerator.content()(1)(),
      } satisfies IComment.ICreate,
    }),
    // Post 0, member 2
    await api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: posts[0].id,
        discussionboard_member_id: members[2].id,
        body: RandomGenerator.content()(1)(),
      } satisfies IComment.ICreate,
    }),
    // Post 1, member 0
    await api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: posts[1].id,
        discussionboard_member_id: members[0].id,
        body: RandomGenerator.content()(1)(),
      } satisfies IComment.ICreate,
    }),
    // Post 1, member 2
    await api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: posts[1].id,
        discussionboard_member_id: members[2].id,
        body: RandomGenerator.content()(1)(),
      } satisfies IComment.ICreate,
    }),
  ];
  comments.forEach(typia.assert);

  // --- Step 4: Members vote on comments ---
  // Vote map: Key is (member, comment). Use 6 votes, with one duplicate vote to test update.
  //                       v[0]        v[1]        v[2]        v[3]        v[4]        v[5]
  // member:              0           1           2           0           1           2
  // comment:          0           1          2           2           3           0
  // vote_type:        up          down        up          down        up          up
  // one updated: member 0 on comment 0: up->down
  const now = new Date();
  const votes = [
    // v0
    await api.functional.discussionboard.commentVotes.create(connection, {
      body: {
        discussionboard_comment_id: comments[0].id,
        discussionboard_member_id: members[0].id,
        vote_type: "up",
        created_at: now.toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardCommentVote.ICreate,
    }),
    // v1
    await api.functional.discussionboard.commentVotes.create(connection, {
      body: {
        discussionboard_comment_id: comments[1].id,
        discussionboard_member_id: members[1].id,
        vote_type: "down",
        created_at: now.toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardCommentVote.ICreate,
    }),
    // v2
    await api.functional.discussionboard.commentVotes.create(connection, {
      body: {
        discussionboard_comment_id: comments[2].id,
        discussionboard_member_id: members[2].id,
        vote_type: "up",
        created_at: now.toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardCommentVote.ICreate,
    }),
    // v3
    await api.functional.discussionboard.commentVotes.create(connection, {
      body: {
        discussionboard_comment_id: comments[2].id,
        discussionboard_member_id: members[0].id,
        vote_type: "down",
        created_at: now.toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardCommentVote.ICreate,
    }),
    // v4
    await api.functional.discussionboard.commentVotes.create(connection, {
      body: {
        discussionboard_comment_id: comments[3].id,
        discussionboard_member_id: members[1].id,
        vote_type: "up",
        created_at: now.toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardCommentVote.ICreate,
    }),
    // v5
    await api.functional.discussionboard.commentVotes.create(connection, {
      body: {
        discussionboard_comment_id: comments[0].id,
        discussionboard_member_id: members[2].id,
        vote_type: "up",
        created_at: now.toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardCommentVote.ICreate,
    }),
  ];
  votes.forEach(typia.assert);

  // Update v0 (member 0, comment 0) to 'down' + new created_at (simulate vote update)
  const updatedAt = new Date(now.getTime() + 1000);
  const updatedVote = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: comments[0].id,
      discussionboard_member_id: members[0].id,
      vote_type: "down",
      created_at: updatedAt.toISOString() as string & tags.Format<"date-time">,
    } satisfies IDiscussionboardCommentVote.ICreate,
  });
  typia.assert(updatedVote);

  // --- Step 5: Listing/search tests ---
  // 5.1 Filter by member (should only fetch votes cast by a member)
  const byMember = await api.functional.discussionboard.commentVotes.index(connection, {
    body: {
      discussionboard_member_id: members[0].id,
    } satisfies IDiscussionboardCommentVote.IRequest,
  });
  typia.assert(byMember);
  TestValidator.predicate("only member 0's votes")(
    byMember.data.every(v => v.discussionboard_member_id === members[0].id),
  );

  // 5.2 Filter by comment (should only fetch votes for a given comment)
  const byComment = await api.functional.discussionboard.commentVotes.index(connection, {
    body: {
      discussionboard_comment_id: comments[0].id,
    } satisfies IDiscussionboardCommentVote.IRequest,
  });
  typia.assert(byComment);
  TestValidator.predicate("all for comment 0")(
    byComment.data.every(v => v.discussionboard_comment_id === comments[0].id),
  );

  // 5.3 Filter by vote_type
  const byVoteType = await api.functional.discussionboard.commentVotes.index(connection, {
    body: {
      vote_type: "down",
    } satisfies IDiscussionboardCommentVote.IRequest,
  });
  typia.assert(byVoteType);
  TestValidator.predicate("all are down votes")(
    byVoteType.data.every(v => v.vote_type === "down"),
  );

  // 5.4 Filter by created_at_from/created_at_to (simulate range outside actual votes)
  const future = new Date(now.getTime() + 10 * 24 * 60 * 60 * 1000); // 10 days later
  const byFutureRange = await api.functional.discussionboard.commentVotes.index(connection, {
    body: {
      created_at_from: future.toISOString() as string & tags.Format<"date-time">,
      created_at_to: future.toISOString() as string & tags.Format<"date-time">,
    } satisfies IDiscussionboardCommentVote.IRequest,
  });
  typia.assert(byFutureRange);
  TestValidator.equals("future yields 0 results")(byFutureRange.data.length)(0);

