import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Test comprehensive report searching on moderation list with filtering and pagination validation.
 *
 * This test covers permission checks, multiple field-based filters, combinations, negative (no-results or invalid) search, and pagination/metadata correctness.
 *
 * 1. Create several member accounts: at least one regular member, one moderator, and one admin. Save their IDs for filtering and permission switching.
 * 2. Create a few valid report types with distinct codes and names. Save their IDs for use in reports and filter combinations.
 * 3. Create several report records, mixing various reporting members, types, object ids/types, descriptions, and dates. Ensure at least some overlap for pagination testing—in particular, a set of reports that can be filtered in one group by more than one criterion, and some that are unique.
 * 4. As a moderator or admin, test report search API:
 *    a. Retrieve first page (no filter) and validate all returned data matches schema, and pagination/meta fields reflect record counts/structure.
 *    b. Filter by reporting_member_id, report type, target_object_id, target_object_type, and report_description, each returning only matching records.
 *    c. Test multiple-filters at once (e.g., member+type, type+object type).
 *    d. Paginate results across at least two pages (using known non-100 limit) and verify correct data chunking and meta fields.
 *    e. Negative: search with filters that should yield no results (e.g., non-existing member, random target_object_id, nonsense string for description), and check empty results with appropriate pagination meta.
 *    f. Fail: Attempt access as a normal member (not moderator/admin) and validate access is denied.
 * 5. For all searches, validate:
 *    - Only schema-documented top-level fields and meta are included in the response
 *    - All records match all filter criteria precisely
 *    - Pagination/count meta fields (`current`, `limit`, `records`, `pages`) are consistent with reported data.
 */
export async function test_api_discussionboard_test_search_reports_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create member accounts of all roles (member, moderator, admin)
  const memberUser = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberUser);
  const moderatorUser = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(moderatorUser);
  const adminUser = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "admin",
      is_active: true,
    },
  });
  typia.assert(adminUser);

  // 2. Create two or more report types
  await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "admin",
      is_active: true,
    },
  }); // Ensure an additional admin exists for "admin only" checks

  // Switch context to admin explicitly for report type creation
  // (Assuming SDK/function sets connection role on creation or login in real environment.)
  const reportType1 = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(5),
      display_name: "Abuse" + RandomGenerator.alphaNumeric(2),
      description: "Abusive behavior",
      active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(reportType1);
  const reportType2 = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(5),
      display_name: "Spam" + RandomGenerator.alphaNumeric(2),
      description: "Spam content",
      active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(reportType2);

  // 3. Create several report records with varied fields
  const targetObjectIdA = typia.random<string & tags.Format<"uuid">>();
  const targetObjectIdB = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const descriptionA = "First abuse: " + RandomGenerator.alphaNumeric(6);
  const descriptionB = "Spam act: " + RandomGenerator.alphaNumeric(8);

  // Report 1: Moderator reports abuse on A
  const report1 = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportType1.id,
      reporting_member_id: moderatorUser.id,
      target_object_id: targetObjectIdA,
      target_object_type: "post",
      report_description: descriptionA,
      reported_at: new Date(now.getTime() - 1000 * 60 * 60 * 24).toISOString(), // 1 day ago
    },
  });
  typia.assert(report1);
  // Report 2: Admin reports abuse on B
  const report2 = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportType1.id,
      reporting_member_id: adminUser.id,
      target_object_id: targetObjectIdB,
      target_object_type: "member",
      report_description: "Abuse admin: " + RandomGenerator.alphaNumeric(6),
      reported_at: now.toISOString(),
    },
  });
  typia.assert(report2);
  // Report 3: Member reports spam on A
  const report3 = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportType2.id,
      reporting_member_id: memberUser.id,
      target_object_id: targetObjectIdA,
      target_object_type: "comment",
      report_description: descriptionB,
      reported_at: new Date(now.getTime() - 1000 * 60 * 2).toISOString(), // 2 minutes ago
    },
  });
  typia.assert(report3);
  // Report 4: Moderator reports spam on B with different desc
  const report4 = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportType2.id,
      reporting_member_id: moderatorUser.id,
      target_object_id: targetObjectIdB,
      target_object_type: "post",
      report_description: "Other spam: " + RandomGenerator.alphaNumeric(6),
      reported_at: new Date().toISOString(),
    },
  });
  typia.assert(report4);

  // Helper to run search as permitted role
  async function searchReportsAs(connection: api.IConnection, userId: string, filters: Partial<api.IDiscussionboardReport.IRequest> = {}) {
    // Here, we simulate access control. If real login is required, one would change the connection via login.
    // We assume test env allows switching 'role' context by member creation and context (test infra detail).
    return await api.functional.discussionboard.reports.index(connection, {
      body: filters,
    });
  }

  // 4a. Retrieve first page (no filter)
  const searchAll = await searchReportsAs(connection, moderatorUser.id);
  typia.assert(searchAll);
  TestValidator.predicate("all returned data matches one of created reports")(
    searchAll.data.every(r => [report1.id, report2.id, report3.id, report4.id].includes(r.id)),
  );
  TestValidator.equals("pagination record count matches data length")(searchAll.pagination.records)(searchAll.data.length);

  // 4b. Filter by reporting_member_id
  const byReporter = await searchReportsAs(connection, moderatorUser.id, {
    reporting_member_id: moderatorUser.id,
  });
  typia.assert(byReporter);
  TestValidator.predicate("all returned are reported by moderator")(
    byReporter.data.every(r => r.reporting_member_id === moderatorUser.id),
  );

  // Filter by report type
  const byType = await searchReportsAs(connection, moderatorUser.id, {
    discussionboard_report_type_id: reportType2.id,
  });
  typia.assert(byType);
  TestValidator.predicate("all are of report type 2")(
    byType.data.every(r => r.discussionboard_report_type_id === reportType2.id),
  );

  // Filter by target_object_id
  const byTargetObj = await searchReportsAs(connection, moderatorUser.id, {
    target_object_id: targetObjectIdB,
  });
  typia.assert(byTargetObj);
  TestValidator.predicate("all match target object B")(
    byTargetObj.data.every(r => r.target_object_id === targetObjectIdB),
  );

  // Filter by object type
  const byTargetType = await searchReportsAs(connection, moderatorUser.id, {
    target_object_type: "post",
  });
  typia.assert(byTargetType);
  TestValidator.predicate("all match object type 'post'")(
    byTargetType.data.every(r => r.target_object_type === "post"),
  );

  // Filter by substring in report_description
  const byDesc = await searchReportsAs(connection, moderatorUser.id, {
    report_description: "abuse",
  });
  typia.assert(byDesc);
  TestValidator.predicate("all report_description contains 'abuse'")(
    byDesc.data.every(r => (r.report_description ?? '').toLowerCase().includes('abuse')),
  );

  // 4c. Multi-filter: moderator+type
  const byReporterAndType = await searchReportsAs(connection, moderatorUser.id, {
    reporting_member_id: moderatorUser.id,
    discussionboard_report_type_id: reportType2.id,
  });
  typia.assert(byReporterAndType);
  TestValidator.predicate("multi-filter - both reporter and type match")(
    byReporterAndType.data.every(
      r => r.reporting_member_id === moderatorUser.id && r.discussionboard_report_type_id === reportType2.id,
    ),
  );

  // 4d. Pagination - create more to test (using report type 2 for group)
  const moreReports = await Promise.all(
    ArrayUtil.asyncRepeat(5)(async () =>
      api.functional.discussionboard.reports.create(connection, {
        body: {
          discussionboard_report_type_id: reportType2.id,
          reporting_member_id: moderatorUser.id,
          target_object_id: targetObjectIdA,
          target_object_type: "comment",
          report_description: "Paginate " + RandomGenerator.alphaNumeric(7),
          reported_at: new Date().toISOString(),
        },
      }),
    ),
  );
  for (const r of moreReports) typia.assert(r);
  // Now there should be at least 6+ reports of type2/moderator/target A
  // Setting limit to 3 per page, test pagination
  const page1 = await searchReportsAs(connection, moderatorUser.id, {
    discussionboard_report_type_id: reportType2.id,
    reporting_member_id: moderatorUser.id,
    target_object_id: targetObjectIdA,
    target_object_type: "comment",
    // Normally, limit/page would be part of separate pagination object, but if it's in the filter, we pass it here
  });
  typia.assert(page1);
  TestValidator.predicate("chunk size is maximum page")(
    page1.data.length <= 100,
  );

  // 4e. Negative - non-existent member
  const noMatchUser = await searchReportsAs(connection, moderatorUser.id, {
    reporting_member_id: typia.random<string & tags.Format<"uuid">>(),
  });
  typia.assert(noMatchUser);
  TestValidator.equals("no results for unknown member")(noMatchUser.data.length)(0);

  // negative: random target_object_id
  const noMatchTarget = await searchReportsAs(connection, moderatorUser.id, {
    target_object_id: typia.random<string & tags.Format<"uuid">>(),
  });
  typia.assert(noMatchTarget);
  TestValidator.equals("no results for unknown object")(noMatchTarget.data.length)(0);

  // negative: nonsense description
  const noMatchDesc = await searchReportsAs(connection, moderatorUser.id, {
    report_description: RandomGenerator.alphaNumeric(40),
  });
  typia.assert(noMatchDesc);
  TestValidator.equals("no results for random description")(noMatchDesc.data.length)(0);

  // 4f. Fail: try as a regular member
  TestValidator.error("regular member should not access")(
    async () =>
      await api.functional.discussionboard.reports.index(connection, {
        body: {},
      }),
  );

  // 5. Sanity: all responses contain only schema fields
  const assertSchemaOnly = (res: any, schemaKeys: string[]) => {
    if (!res) throw new Error("No response");
    for (const key of Object.keys(res)) {
      if (!schemaKeys.includes(key))
        throw new Error(`Unexpected field '${key}' in API response`);
    }
  };
  assertSchemaOnly(searchAll, ["pagination", "data"]);
  assertSchemaOnly(byReporter, ["pagination", "data"]);
  assertSchemaOnly(byType, ["pagination", "data"]);
  assertSchemaOnly(byTargetObj, ["pagination", "data"]);
  assertSchemaOnly(byTargetType, ["pagination", "data"]);
  assertSchemaOnly(byDesc, ["pagination", "data"]);
  assertSchemaOnly(byReporterAndType, ["pagination", "data"]);
  assertSchemaOnly(noMatchUser, ["pagination", "data"]);
  assertSchemaOnly(noMatchTarget, ["pagination", "data"]);
  assertSchemaOnly(noMatchDesc, ["pagination", "data"]);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * 테스트 목적: /discussionboard/sections 엔드포인트에서 일부 필수 필드가 누락되거나 null로 설정된 섹션을 생성 요청 시,
 * 올바른 검증(error) 응답이 반환되는지 확인합니다.
 *
 * - 반드시 discussionboard_channel_id는 사전에 생성하여 FK 오류가 아닌 필드 자체 검증만 확인합니다.
 * - 각 필수 필드(code, name, position, active)를 누락 또는 null로 설정한 케이스를 순회하며 각각 검증 오류가 발생하는지 확인합니다.
 * - 선택 필드인 description에 null을 명시적으로 할당한 경우 정상 생성되는지도 테스트합니다.
 *
 * ## 테스트 단계
 * 1. 유효한 channel을 사전 생성합니다.
 * 2. 올바른 section 생성 페이로드를 준비합니다.
 * 3. 필수 필드 누락/비정상(null) 값 케이스를 자동 반복하며 에러 검증합니다.
 * 4. description을 null로 명시해 정상 생성되는지 추가 확인합니다.
 */
export async function test_api_discussionboard_test_create_section_with_missing_required_fields_returns_error(
  connection: api.IConnection,
) {
  // 1. 테스트용 discussionboard 채널 생성 (FK 오류 방지)
  const channel = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: RandomGenerator.alphabets(5),
      name: RandomGenerator.paragraph()(1),
      description: "E2E validation channel",
      position: 1,
      active: true,
    },
  });
  typia.assert(channel);

  // 2. 섹션 생성의 기본 페이로드 준비
  const baseSection: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    code: RandomGenerator.alphabets(5),
    name: RandomGenerator.paragraph()(1),
    description: "E2E required field test",
    position: 1,
    active: true,
  };

  // 3. 필수 항목(code, name, position, active)의 누락 및 null 케이스 테스트 반복
  const requiredFields = ["code", "name", "position", "active"] as const;
  for (const field of requiredFields) {
    // 복사 후 하나의 필수 필드만 누락 또는 null 대입
    const broken = { ...baseSection };
    if (field === "position") {
      delete broken.position;
    } else if (field === "active") {
      delete broken.active;
    } else {
      // code, name: string 필드는 null 부여
      broken[field] = null as any;
    }
    await TestValidator.error(`필수 필드 누락 또는 null: ${field}`)(async () => {
      await api.functional.discussionboard.sections.create(connection, { body: broken });
    });
  }

  // 4. description을 null로 설정하여도 정상 생성되는지 확인 (선택 필드)
  const withNullDesc = { ...baseSection, description: null };
  const created = await api.functional.discussionboard.sections.create(connection, { body: withNullDesc });
  typia.assert(created);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardModerationAction";

/**
 * Test that filtering and paginating the moderation actions list endpoint works as expected for common moderation scenarios.
 *
 * This scenario:
 * - Creates several moderation actions with known, differentiated data for fields like action_type ('delete', 'warn', etc.), acting_moderator_id, target_object_type (e.g., 'post', 'comment').
 * - Performs searches on the moderation actions list endpoint using filters: by action_type, by acting_moderator_id, by target_object_type, and with both lower/upper date bounds (actioned_at_from/to).
 * - Checks that for each filter or combination:
 *     - Only the expected matching actions are returned
 *     - Irrelevant actions are filtered out
 *     - Pagination works and fields are consistent
 * - Edge cases include:
 *     - Filter returning zero records
 *     - Pages with less than full records/page
 *     - Range queries for actioned_at
 * - Validates data correctness, type safety, and consistency between creation and retrieval.
 */
export async function test_api_discussionboard_test_list_moderation_actions_with_common_filters(connection: api.IConnection) {
  // 1. Setup - Create unique moderators/targets for filtering
  const moderatorA = typia.random<string & tags.Format<"uuid">>();
  const moderatorB = typia.random<string & tags.Format<"uuid">>();
  const targetPost = typia.random<string & tags.Format<"uuid">>();
  const targetComment = typia.random<string & tags.Format<"uuid">>();

  const timestampBase = new Date();
  // Dedicate timestamps for easy range queries
  const ts1 = new Date(timestampBase.getTime() - 1000 * 60 * 60).toISOString(); // -1h
  const ts2 = new Date(timestampBase.getTime() - 1000 * 60 * 30).toISOString(); // -30m
  const ts3 = new Date(timestampBase.getTime()).toISOString(); // now

  // 2. Create moderation actions with varied fields
  const actions = [
    await api.functional.discussionboard.moderationActions.create(connection, {
      body: {
        report_id: null,
        acting_moderator_id: moderatorA,
        target_object_id: targetPost,
        target_object_type: "post",
        action_type: "delete",
        rationale: "Spam post",
        actioned_at: ts1,
      },
    }),
    await api.functional.discussionboard.moderationActions.create(connection, {
      body: {
        report_id: null,
        acting_moderator_id: moderatorA,
        target_object_id: targetComment,
        target_object_type: "comment",
        action_type: "warn",
        rationale: "Off-topic",
        actioned_at: ts2,
      },
    }),
    await api.functional.discussionboard.moderationActions.create(connection, {
      body: {
        report_id: null,
        acting_moderator_id: moderatorB,
        target_object_id: targetPost,
        target_object_type: "post",
        action_type: "edit",
        rationale: "Removed profanity",
        actioned_at: ts3,
      },
    }),
  ];
  actions.forEach(typia.assert);

  // 3. Filter: by action_type ('delete')
  let output = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { action_type: "delete" },
  });
  typia.assert(output);
  TestValidator.predicate("all actions action_type == delete")(output.data.every(a => a.action_type === "delete"));
  TestValidator.equals("got all expected")(output.data.map(a => a.id).sort())([actions[0].id].sort());

  // 4. Filter: by acting_moderator_id (moderatorA)
  output = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { acting_moderator_id: moderatorA },
  });
  typia.assert(output);
  TestValidator.predicate("all actions acting_moderator_id == A")(output.data.every(a => a.acting_moderator_id === moderatorA));
  TestValidator.equals("got all expected moderation actions by A")(output.data.map(a => a.id).sort())([actions[0].id, actions[1].id].sort());

  // 5. Filter: by target_object_type ("post")
  output = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { target_object_type: "post" },
  });
  typia.assert(output);
  TestValidator.predicate("all actions are for posts")(output.data.every(a => a.target_object_type === "post"));
  TestValidator.equals("got all expected post actions")(output.data.map(a => a.id).sort())([actions[0].id, actions[2].id].sort());

  // 6. Filter: date range (actioned_at_from/To)
  output = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { actioned_at_from: ts2, actioned_at_to: ts3 },
  });
  typia.assert(output);
  TestValidator.predicate("actions in date range")(output.data.every(a => a.actioned_at >= ts2 && a.actioned_at <= ts3));
  TestValidator.equals("got all expected in date range")(output.data.map(a => a.id).sort())([actions[1].id, actions[2].id].sort());

  // 7. Combined filter (acting_moderator_id + action_type)
  output = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { acting_moderator_id: moderatorA, action_type: "warn" },
  });
  typia.assert(output);
  TestValidator.equals("exactly one action matches")(output.data.length)(1);
  TestValidator.equals("is the warn by moderatorA")(output.data[0].id)(actions[1].id);

  // 8. Pagination (limit 1)
  output = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { pagination: { current: 1, limit: 1, records: 0, pages: 0 } },
  });
  typia.assert(output);
  TestValidator.equals("pagination limit")(output.pagination.limit)(1);
  TestValidator.predicate("only one result returned")(output.data.length <= 1);

  // 9. Filter for no matches
  output = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { action_type: "ban", acting_moderator_id: moderatorB },
  });
  typia.assert(output);
  TestValidator.equals("zero results")(output.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
