      typeof paginated1.pagination.records === "number" &&
      typeof paginated1.pagination.pages === "number",
  );
  TestValidator.predicate("non-empty page")(
    paginated1.data.length > 0,
  );

  // --- Edge case: nonexistent entity filters ---
  const notfound = await api.functional.discussionboard.commentVotes.index(connection, {
    body: {
      discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IDiscussionboardCommentVote.IRequest,
  });
  typia.assert(notfound);
  TestValidator.equals("nonexistent comment yields 0")(notfound.data.length)(0);

  // --- All responses: Validate schema compliance (fields only schema-allowed) ---
  for (const pack of [byMember, byComment, byVoteType, paginated1]) {
    for (const v of pack.data) {
      typia.assert(v);
      // (no extra fields check: typia.assert will fail if extra fields exist)
    }
    typia.assert(pack.pagination);
  }
}

