 * 1. 투표를 위한 member 계정을 생성한다.
 * 2. 해당 멤버로 게시글을 1개 생성한다.
 * 3. 생성된 post에 멤버가 vote 기록을 1건 생성한다 (vote_type은 -1/0/1 랜덤)
 * 4. 생성된 vote의 id로 postVotes.at()을 호출하여 단건 조회
 * 5. 조회 결과와 생성 입력값이 완전히 일치하는지, 필드 값과 schema strictness까지 모두 검증
 */
export async function test_api_discussionboard_test_get_post_vote_by_valid_id_returns_vote(
  connection: api.IConnection,
) {
  // 1. 회원 계정 생성
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(8),
        email: memberEmail,
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: RandomGenerator.pick(["member", "moderator", "admin"]),
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }
  );
  typia.assert(member);

  // 2. 게시글 1건 생성
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(2)(),
        is_deleted: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardPost.ICreate,
    }
  );
  typia.assert(post);

  // 3. vote 생성
  const voteType = RandomGenerator.pick([-1, 0, 1]);
  const voteInput: IPostVote.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: voteType,
    created_at: new Date().toISOString(),
  };
  const vote: IPostVote = await api.functional.discussionboard.postVotes.create(
    connection,
    { body: voteInput }
  );
  typia.assert(vote);

  // 4. 생성된 vote id로 단건 조회
  const fetched: IPostVote = await api.functional.discussionboard.postVotes.at(
    connection,
    { id: vote.id }
  );
  typia.assert(fetched);

  // 5. 필드 값 정합성 및 스키마 strictness 검증
  TestValidator.equals("vote id")(fetched.id)(vote.id);
  TestValidator.equals("post id")(fetched.discussionboard_post_id)(post.id);
  TestValidator.equals("member id")(fetched.discussionboard_member_id)(member.id);
  TestValidator.equals("vote_type")(fetched.vote_type)(voteType);
  TestValidator.equals("created_at")(fetched.created_at)(vote.created_at);

  const keys = Object.keys(fetched).sort();
  const expectedKeys = [
    "id",
    "discussionboard_post_id",
    "discussionboard_member_id",
    "vote_type",
    "created_at"
  ].sort();
  TestValidator.equals("응답 스키마 strictness")(keys)(expectedKeys);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostSnapshot";

/**
 * 포스트 스냅샷(감사 레코드)의 title, body, taken_at 및 editor_member_id 값을 정상적으로 업데이트하고,
 * 불변 필드(스냅샷 id, 원본 post 연관 id)가 변하지 않음을 확인하는 E2E 테스트
 *
 * [비즈니스 목적 및 필요성]
 * - discussionboard_post_snapshots 엔터티는 게시물의 모든 편집/감사 히스토리를 저장합니다.
 * - 일반 사용자는 snapshot 생성만 가능하며, update는 오류 정정, 감사 기록 수동 수정 등 극히 예외적으로 권한 사용자에 한해 수행됩니다.
 * - 본 테스트는 정상 업데이트(편집 내용 적용), 불변 필드 보존, nullable editor_member_id 등 히스토리 관리 정책 준수 여부를 검증합니다.
 *
 * [테스트 절차]
 * 1. 게시글(post)을 생성
 * 2. 해당 post의 id로 최초 스냅샷(postSnapshot) 생성
 * 3. 스냅샷의 title/body/taken_at/editor_member_id 값을 변경하여 업데이트
 * 4. 반환 결과에서 변경 사항 반영 확인 (title, body, taken_at, editor_member_id)
 * 5. 불변 필드(스냅샷 PK, post 연관 id)가 변하지 않았는지 확인
 * 6. editor_member_id에 null 입력 시에도 업데이트 정상 반영되는지 검증
 */
export async function test_api_discussionboard_test_update_post_snapshot_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 게시글(post) 생성
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Original Discussion Title",
      body: "This is the original post body for audit.",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }
  });
  typia.assert(post);

  // 2. 생성한 post의 id로 포스트 스냅샷 생성
  const snapshot: IPostSnapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: post.discussionboard_member_id,
      title: post.title,
      body: post.body,
      taken_at: new Date().toISOString(),
    },
  });
  typia.assert(snapshot);

  // 3. 스냅샷 업데이트: title, body, taken_at 및 editor_member_id 값 변경
  const updateInput: IPostSnapshot.IUpdate = {
    title: "After Audit Correction Title",
    body: "Body content after audit correction update.",
    taken_at: new Date(Date.now() + 3600 * 1000).toISOString(), // 1시간 후로 변경
    editor_member_id: typia.random<string & tags.Format<"uuid">>(), // 새로운 편집자
  };
  const updated: IPostSnapshot = await api.functional.discussionboard.postSnapshots.update(connection, {
    id: snapshot.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. updated 필드가 실제로 반영됐는지, 불변 필드는 그대로인지 확인
  TestValidator.equals("title 변경 반영됨")(updated.title)(updateInput.title);
  TestValidator.equals("body 변경 반영됨")(updated.body)(updateInput.body);
  TestValidator.equals("taken_at 변경 반영됨")(updated.taken_at)(updateInput.taken_at);
  TestValidator.equals("변경 불가 - snapshot id")(updated.id)(snapshot.id);
  TestValidator.equals("변경 불가 - post 연관 id")(updated.discussionboard_post_id)(snapshot.discussionboard_post_id);
  // editor_member_id 지정 값 반영 검증
  TestValidator.equals("editor_member_id 변경 반영됨")(updated.editor_member_id)(updateInput.editor_member_id);

  // 5. editor_member_id: null로 업데이트 시 정상 동작 확인
  const updateNullEditor: IPostSnapshot.IUpdate = {
    title: "Null Editor Title",
    body: "Body with editor_member_id nulled.",
    taken_at: new Date(Date.now() + 7200 * 1000).toISOString(), // 2시간 후
    editor_member_id: null,
  };
  const updatedNullEditor: IPostSnapshot = await api.functional.discussionboard.postSnapshots.update(connection, {
    id: snapshot.id,
    body: updateNullEditor,
  });
  typia.assert(updatedNullEditor);
  TestValidator.equals("editor_member_id null 처리됨")(updatedNullEditor.editor_member_id)(null);
}

