import type { IPageDiscussionboardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated retrieval of notification preferences for a discussion board member.
 *
 * This test verifies that paginated notification preference browsing works, including:
 * - Creating sufficient notification templates and setting up preferences to span multiple pages
 * - Using specific paging parameters (page and limit)
 * - Asserting response metadata accurately reflects total records, limit, and pagination state
 * - Asserting that only preferences belonging to the test member are returned
 *
 * Workflow:
 * 1. Create a member to own notification preferences
 * 2. Create enough notification templates (>pageSize) to ensure results span multiple pages
 * 3. Create one notification preference (all enabled channel true except browser) per template for the test member
 * 4. Perform paginated retrieval (e.g., page=2, limit=5)
 * 5. Assert correct data count per page
 * 6. Assert pagination metadata is correct
 * 7. Assert preference owner correctness for each result
 */
export async function test_api_discussionboard_test_search_notification_preferences_with_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    }
  });
  typia.assert(member);

  // 2. Create notification templates (>pageSize) for diversity
  const pageSize = 5;
  const templateCount = pageSize * 2 + 3; // 13
  const templates = await ArrayUtil.asyncRepeat(templateCount)(async (_, i) => {
    const tpl = await api.functional.discussionboard.notificationTemplates.create(connection, {
      body: {
        code: `test_notif_${i}_${RandomGenerator.alphaNumeric(6)}`,
        name: `Template #${i}`,
        description: `Description ${i}`,
        subject: `Subject ${i}`,
        body: `Body text for ${i}`,
        is_active: true,
      }
    });
    typia.assert(tpl);
    return tpl;
  });

  // 3. Create notification preferences (one per template) for the member
  const preferences = await ArrayUtil.asyncMap(templates)(async tpl => {
    const pref = await api.functional.discussionboard.notificationPreferences.create(connection, {
      body: {
        discussionboard_member_id: member.id,
        code: tpl.code,
        email_enabled: true,
        inapp_enabled: true,
        browser_enabled: false,
      },
    });
    typia.assert(pref);
    return pref;
  });

  // 4. Retrieve page 2 of notification preferences for this member, page size 5
  const page = 2;
  const resp = await api.functional.discussionboard.notificationPreferences.index(connection, {
    body: {
      discussionboard_member_id: member.id,
      page,
      limit: pageSize,
    },
  });
  typia.assert(resp);

  // 5. Validate returned data length
  TestValidator.equals("page data count")(resp.data.length)(pageSize);

  // 6. Validate pagination metadata state
  TestValidator.equals("pagination.current")(resp.pagination.current)(page);
  TestValidator.equals("pagination.limit")(resp.pagination.limit)(pageSize);
  TestValidator.equals("pagination.records")(resp.pagination.records)(templateCount);
  TestValidator.equals("pagination.pages")(resp.pagination.pages)(Math.ceil(templateCount / pageSize));

  // 7. All preferences should belong to the created member
  for (const pref of resp.data) {
    TestValidator.equals("member id matches")(pref.discussionboard_member_id)(member.id);
  }
}

