import api from "@ORGANIZATION/PROJECT-api";
import type { IPostReference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReference";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * Validate deletion of a post reference by ID in the discussion board.
 *
 * This test verifies that a post reference can be created and then hard-deleted by its unique identifier. The process simulates an end-to-end workflow:
 *
 * 1. Create a post reference using POST /discussionboard/postReferences with valid UUID fields.
 * 2. Delete the post reference using DELETE /discussionboard/postReferences/{id}.
 * 3. Confirm the record is irrecoverably deleted by attempting to delete it again and expecting a not found or error response.
 *
 * Steps:
 * 1. Generate random valid source_post_id (uuid), target_post_id (uuid), and reference_type.
 * 2. Create a new post reference.
 * 3. Delete the post reference by its returned id.
 * 4. Attempt to delete the same id again and validate error is thrown since the record should not exist anymore.
 */
export async function test_api_discussionboard_test_delete_post_reference_by_id(
  connection: api.IConnection,
) {
  // 1. Generate valid IDs for source and target posts
  const source_post_id = typia.random<string & tags.Format<"uuid">>();
  const target_post_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a post reference record
  const created = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id,
      target_post_id,
      reference_type: "post",
    },
  });
  typia.assert(created);

  // 3. Delete the post reference by its ID
  const delResult = await api.functional.discussionboard.postReferences.erase(connection, { id: created.id });
  typia.assert(delResult);

  // 4. Attempt to delete again. Should throw (not found).
  await TestValidator.error("second erase should fail")(() =>
    api.functional.discussionboard.postReferences.erase(connection, { id: created.id })
  );
}

