/**
 * Ensure that filtering own member profiles with an invalid field results in a schema validation error.
 *
 * This test verifies robustness in the filtering endpoint of /my/discussionboard/member/profiles: if the client attempts to use a non-schema property (e.g., created_by or updated_by) in the search request, the API should respond with an error, rejecting the request.
 *
 * Steps:
 * 1. Register and authenticate a new member, ensuring access to /my/discussionboard/member/profiles.
 * 2. Attempt to filter using an extra property not in IDiscussionboardMemberProfile.IRequest (e.g., created_by).
 * 3. Assert that the API correctly rejects the request.
 */
export async function test_api_my_discussionboard_member_profiles_test_search_own_member_profiles_with_invalid_field(
  connection: api.IConnection,
) {
  // 1. Register a new member (simulate authentication context for /my/ endpoints)
  const email = typia.random<string & tags.Format<"email">>();
  const username = RandomGenerator.alphaNumeric(8);
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username,
      email,
      hashed_password: "validHashedPassword123!",
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Attempt to filter with an invalid field ("created_by") in the body
  //    - This is intentionally a schema violation to test error handling.
  await TestValidator.error("Filtering with invalid field should fail")(
    async () => {
      // This block intentionally uses a field outside IDiscussionboardMemberProfile.IRequest schema.
      // TypeScript will error here; such usage is only permitted inside this error assertion block for negative validation tests.
      await api.functional.my.discussionboard.member.profiles.index(connection, {
        body: { created_by: member.id },
      });
    },
  );
}

