/**
 * Validate permanent deletion of a board category by UUID.
 *
 * This test examines the proper handling of hard deletion for a board category entity:
 *
 * 1. Create a new category to obtain a valid UUID.
 * 2. Delete the created category using the erase API.
 * 3. Attempt to fetch the deleted category, expecting a 404 not found error.
 *
 * This ensures resources are not retrievable after deletion and the API responds correctly to attempts to access deleted records.
 */
export async function test_api_discussionboard_boardCategories_test_delete_board_category_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new board category
  const createInput: IDiscussionboardBoardCategory.ICreate = {
    name: RandomGenerator.paragraph()(3),
    code: `test_${RandomGenerator.alphaNumeric(8)}`,
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
  };
  const category = await api.functional.discussionboard.boardCategories.create(connection, {
    body: createInput,
  });
  typia.assert(category);

  // 2. Delete the category by its id
  await api.functional.discussionboard.boardCategories.erase(connection, {
    id: category.id,
  });

  // 3. Attempt to fetch the deleted category and verify that 404 error is thrown
  await TestValidator.error("deleted category should not be found")(() =>
    api.functional.discussionboard.boardCategories.at(connection, { id: category.id })
  );
}

