import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardActivityLog";
import type { IPageIDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that the activity logs endpoint properly rejects requests
 * containing invalid filter parameters (non-schema fields).
 *
 * This test ensures the endpoint enforces strict schema validation: only
 * fields defined in IDiscussionboardActivityLog.IRequest are permissible. Any
 * extra field in the filter object should trigger a validation error.
 *
 * Steps:
 * 1. Construct a valid IDiscussionboardActivityLog.IRequest object.
 * 2. Inject a non-existent property (e.g., "not_a_real_field").
 * 3. Attempt to list activity logs using the malformed filter object.
 * 4. Assert that a validation error occurs as expected.
 */
export async function test_api_discussionboard_test_list_activity_logs_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Construct a valid filter per schema
  const validFilter: IDiscussionboardActivityLog.IRequest = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "login",
  };

  // 2. Add a non-schema (invalid) filter property
  const invalidFilter = {
    ...validFilter,
    not_a_real_field: "unexpected param triggers validation error",
  };

  // 3 & 4. Expect the API to reject the request with a validation error
  await TestValidator.error("should reject invalid filter property")(
    async () => {
      // @ts-expect-error: Deliberately supplying invalid property for negative test
      await api.functional.discussionboard.activityLogs.index(connection, {
        body: invalidFilter,
      });
    },
  );
}

