import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * Test updating specified fields of an existing warning record.
 *
 * Business context:
 * Moderators and admins need to update warning records for audit or appeal corrections, but may only modify allowed fields. The system must enforce this, prohibiting any extra/non-schema properties.
 *
 * Steps:
 * 1. Issue a warning via POST /discussionboard/warnings.
 * 2. Update the warning via PUT /discussionboard/warnings/{id}, modifying the reason and warned_at fields.
 * 3. Validate that the update was successful, changes are reflected, and the fields not included are unchanged.
 * 4. Attempt to update with a non-schema property and verify the system rejects it (error should occur).
 * 5. (Edge) Attempt to set null values for nullable fields and verify system behavior.
 */
export async function test_api_discussionboard_test_update_warning_fields_successfully(
  connection: api.IConnection,
) {
  // 1. Issue a warning
  const createInput: IDiscussionboardWarning.ICreate = {
    warned_member_id: typia.random<string & tags.Format<"uuid">>(),
    acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    report_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Initial Reason: Offensive language in multiple threads.",
    warned_at: new Date().toISOString(),
  };
  const created = await api.functional.discussionboard.warnings.create(connection, { body: createInput });
  typia.assert(created);

  // 2. Update reason and warned_at
  const newReason = "Updated Reason: Evidence confirmed – pattern of abuse.";
  const newWarnedAt = new Date(Date.now() + 10000).toISOString();
  const updateInput: IDiscussionboardWarning.IUpdate = {
    reason: newReason,
    warned_at: newWarnedAt,
  };
  const updated = await api.functional.discussionboard.warnings.update(connection, { id: created.id, body: updateInput });
  typia.assert(updated);
  TestValidator.equals("Reason was updated")(updated.reason)(newReason);
  TestValidator.equals("Warned_at was updated")(updated.warned_at)(newWarnedAt);
  TestValidator.equals("warned_member_id unchanged")(updated.warned_member_id)(created.warned_member_id);
  TestValidator.equals("acting_moderator_id unchanged")(updated.acting_moderator_id)(created.acting_moderator_id);

  // 3. Attempt to update with a non-schema property (should fail)
  await TestValidator.error("Non-schema field is rejected")(() =>
    api.functional.discussionboard.warnings.update(connection, {
      id: created.id,
      // This property is intentionally invalid and should not exist in schema
      // TypeScript will not allow this unless forced; so this part is to show that runtime will fail
      // For e2e, this is demonstration; normally, TypeScript will prevent this usage
      // @ts-expect-error
      body: { extraField: "forbidden-value", reason: "Should not succeed" } as any,
    })
  );

  // 4. (Edge) Attempt to set some fields null where allowed (e.g., report_id)
  const nullUpdate: IDiscussionboardWarning.IUpdate = {
    report_id: null,
  };
  const edgeResult = await api.functional.discussionboard.warnings.update(connection, { id: created.id, body: nullUpdate });
  typia.assert(edgeResult);
  TestValidator.equals("report_id set to null")(edgeResult.report_id)(null);
}

