import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardSetting";

/**
 * Validate that updating a board settings record to use a discussionboard_board_id that is already used by another board settings record (violating the 1:1 unique constraint per board) results in an error.
 *
 * This test ensures the API enforces the uniqueness rule on board settings: each discussion board can have at most one settings record, and no two settings records can reference the same board.
 *
 * Steps:
 * 1. Create two discussion boards (boardA, boardB).
 * 2. Create distinct board settings for each board (settingsA for boardA, settingsB for boardB).
 * 3. Attempt to update settingsA, setting its discussionboard_board_id to the id of boardB (making both settings records reference the same board), which violates the unique constraint.
 * 4. Expect update to fail (conflict or error response indicating unique rule violation).
 */
export async function test_api_discussionboard_boardSettings_test_update_board_settings_violate_unique_constraint(
  connection: api.IConnection,
) {
  // 1. Create two discussion boards (boardA, boardB)
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const sectionId: string = typia.random<string & tags.Format<"uuid">>();
  const boardA = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: categoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(12),
      description: null,
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(boardA);

  const boardB = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: categoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(12),
      description: null,
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(boardB);

  // 2. Create board settings for boardA and boardB
  const settingsA = await api.functional.discussionboard.boardSettings.create(connection, {
    body: {
      discussionboard_board_id: boardA.id,
      is_locked: false,
      require_approval_for_posting: false,
      max_posts_per_hour: 10,
      allow_anonymous_viewing: true,
      allow_file_uploads: true,
    } satisfies IDiscussionboardBoardSetting.ICreate,
  });
  typia.assert(settingsA);

  const settingsB = await api.functional.discussionboard.boardSettings.create(connection, {
    body: {
      discussionboard_board_id: boardB.id,
      is_locked: false,
      require_approval_for_posting: true,
      max_posts_per_hour: 10,
      allow_anonymous_viewing: true,
      allow_file_uploads: true,
    } satisfies IDiscussionboardBoardSetting.ICreate,
  });
  typia.assert(settingsB);

  // 3. Attempt to update settingsA to reference boardB (should violate unique constraint)
  await TestValidator.error("should fail to update board settings with duplicate board id")(
    async () => {
      await api.functional.discussionboard.boardSettings.update(connection, {
        id: settingsA.id,
        body: { discussionboard_board_id: boardB.id },
      });
    },
  );
}

