import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate that the discussion board post creation endpoint rejects requests missing or malformatted required fields.
 *
 * Business context:
 * Creating a post on the discussion board requires all mandatory fields, including valid UUIDs/timestamps for IDs and dates, and non-empty content for text fields. If any required property is omitted or fails its basic validation, the API must reject the request.
 *
 * Process:
 * 1. Attempt to create a post with each required field missing (one at a time); each must throw an error (validation failure).
 * 2. For each required string field, try submitting an empty string (should fail).
 * 3. For UUID fields, try invalid UUID value (should fail).
 * 4. All such requests must result in an error—no post should be created for invalid/missing data.
 */
export async function test_api_discussionboard_test_create_post_missing_required_fields(
  connection: api.IConnection,
) {
  // A valid post object for baseline modifications
  const validPost: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Valid Title",
    body: "Valid Body Content",
    is_deleted: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  // Helper to deep-clone
  const clone = <T>(obj: T): T => JSON.parse(JSON.stringify(obj));

  // All required fields
  const requiredFields = [
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "discussionboard_board_id",
    "title",
    "body",
    "is_deleted",
    "created_at",
    "updated_at",
  ];

  // (1) Test omission of each required field
  for (const field of requiredFields) {
    const invalidPost = clone(validPost);
    delete invalidPost[field as keyof typeof invalidPost];
    await TestValidator.error(`missing required field: ${field}`)(async () => {
      // @ts-expect-error negative test for missing property
      await api.functional.discussionboard.posts.create(connection, {
        body: invalidPost,
      });
    });
  }

  // (2) Test empty string for required string/timestamp fields
  const stringFields = [
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "discussionboard_board_id",
    "title",
    "body",
    "created_at",
    "updated_at",
  ];
  for (const field of stringFields) {
    const invalidPostEmpty = clone(validPost);
    // @ts-expect-error negative test for invalid value
    invalidPostEmpty[field as keyof typeof invalidPostEmpty] = "";
    await TestValidator.error(`empty string for field: ${field}`)(async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: invalidPostEmpty,
      });
    });
  }

  // (3) Invalid UUID for uuid fields
  const uuidFields = [
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "discussionboard_board_id",
  ];
  for (const field of uuidFields) {
    const invalidPostUuid = clone(validPost);
    // @ts-expect-error negative test for invalid value
    invalidPostUuid[field as keyof typeof invalidPostUuid] = "invalid-uuid";
    await TestValidator.error(`invalid uuid for field: ${field}`)(async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: invalidPostUuid,
      });
    });
  }
}

