import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * Validate error handling when deleting a post reference with an invalid ID.
 *
 * This test simulates an attempt to hard-delete a post reference using a UUID that does not correspond to any existing record.
 * The endpoint implements hard-deletion logic and does not support soft deletes or undeletion. If the resource does not exist,
 * the system should respond with an appropriate "not found" error and existing records must remain unaffected.
 *
 * Steps:
 * 1. Generate a random UUID not associated with any post reference.
 * 2. Attempt to delete the post reference using the invalid ID via DELETE /discussionboard/postReferences/{id}.
 * 3. Verify that a suitable not found or error response is returned (i.e., error is thrown by the API SDK).
 * 4. Confirm that no other resources are affected by this deletion attempt.
 */
export async function test_api_discussionboard_postReferences_eraseById_test_delete_post_reference_with_invalid_id(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for a non-existent post reference
  const invalidId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt deletion and expect an error
  await TestValidator.error("deleting non-existent post reference should error")(
    async () => {
      await api.functional.discussionboard.postReferences.erase(connection, {
        id: invalidId,
      });
    },
  );
}

