import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Validate input validation for the comment creation API when required fields are missing.
 *
 * This test verifies that the system properly rejects comment creation attempts where one or more required fields
 * are missing from the payload. It checks API-side validation by sending invalid requests missing each of the
 * required fields of IComment.ICreate (discussionboard_post_id, discussionboard_member_id, body) both individually
 * and in combination, ensuring the API throws an error for each.
 *
 * Steps:
 * 1. Attempt to create a comment with missing post id
 * 2. Attempt to create a comment with missing member id
 * 3. Attempt to create a comment with missing body text
 * 4. Attempt to create a comment missing both post id and member id
 * 5. Attempt to create a completely empty comment object (all required fields missing)
 * For each case, TestValidator.error ensures an error is thrown, confirming server-side required-field enforcement.
 */
export async function test_api_discussionboard_test_create_comment_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Missing discussionboard_post_id
  await TestValidator.error("missing post id")(() =>
    api.functional.discussionboard.comments.create(connection, {
      body: {
