import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * 검증: 댓글 신고 생성 API의 필수 필드 누락 에러
 *
 * 본 테스트는 discussionboard_commentReports의 생성(POST /discussionboard/commentReports) API에서
 * required 필드를 하나씩 누락할 때 서버가 ValidationError (schema validation or HTTP 400/422)로 적절히 reject
 * 하는지를 검증한다.
 *
 * 과정은 다음과 같다:
 * 1. 신고할 멤버 계정 생성
 * 2. 신고 대상 포스트 작성
 * 3. 해당 포스트에 댓글 작성
 * 4. 정상적인 필드로 댓글 신고 생성 → 성공 케이스(준비용 및 생성/참조 체크)
 * 5. 댓글 신고 스키마의 각 필수 필드를 하나씩 누락시켜 API를 호출, 그때마다 error를 제대로 반환하는지 확인
 *    - discussionboard_comment_id 누락
 *    - discussionboard_member_id 누락
 *    - discussionboard_report_type_id 누락
 *    - reason 누락
 *    - created_at 누락
 * 6. 각 누락 케이스마다 TestValidator.error로 실패를 검증하여, 필드 수준 스키마 검증이 robust한지 평가.
 */
export async function test_api_discussionboard_commentReports_test_create_comment_report_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. 신고할 회원 계정 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 신고 대상 포스트 생성
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      title: RandomGenerator.paragraph()(3),
      body: RandomGenerator.paragraph()(5),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. 댓글 생성
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. 정상 신고 생성 - 준비 확인 및 생성/참조 체크
  const validInput: IDiscussionboardCommentReport.ICreate = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: member.id,
    discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
    reason: RandomGenerator.paragraph()(),
    created_at: new Date().toISOString(),
  };

  const report = await api.functional.discussionboard.commentReports.create(connection, {
    body: validInput,
  });
  typia.assert(report);

  // 5. 각 필수 필드 누락 - 반복적으로 각 필드를 누락하여 검증
  const requiredFields = [
    "discussionboard_comment_id",
    "discussionboard_member_id",
    "discussionboard_report_type_id",
    "reason",
    "created_at"
  ] as const;

  for (const field of requiredFields) {
    const partialInput = { ...validInput };
