import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardModerator";
import type { IDiscussionboardBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardModerators";

/**
 * Test updating an existing board-moderator assignment's fields (is_primary and joined_at).
 *
 * This scenario verifies that only administrators can update a board-moderator assignment's modifiable fields, that updated values persist, and that schema/uniqueness/integrity are preserved.
 *
 * Steps:
 * 1. Create a new board with valid category and section references.
 * 2. Create a new moderator (assigned by admin).
 * 3. Assign the moderator to the board (create assignment link).
 * 4. Update the assignment (toggle is_primary, set a new joined_at timestamp).
 * 5. Validate that only the updated fields change, references/IDs are unchanged.
 * 6. Negative: Attempt update as unauthorized user should error (simulated as much as permitted).
 * 7. Negative: Attempt update with a field not in the schema should trigger validation error.
 */
export async function test_api_discussionboard_test_update_board_moderator_assignment_fields(
  connection: api.IConnection,
) {
  // Step 1: Create a new board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // Step 2: Create a new moderator
  const moderator = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      assigned_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
      assigned_at: new Date().toISOString(),
      expires_at: null,
      revoked_at: null,
    },
  });
  typia.assert(moderator);

  // Step 3: Assign moderator to board
  const assignment = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: board.id,
      discussionboard_moderator_id: moderator.id,
      is_primary: false,
      joined_at: new Date().toISOString(),
    },
  });
  typia.assert(assignment);

  // Step 4: Update assignment fields
  const newIsPrimary = !assignment.is_primary;
  const newJoinedAt = new Date(Date.now() + 5 * 60 * 1000).toISOString();
  const updated = await api.functional.discussionboard.boardModerators.update(connection, {
    id: assignment.id,
    body: {
      is_primary: newIsPrimary,
      joined_at: newJoinedAt,
    },
  });
  typia.assert(updated);

  // Step 5: Validate update
  TestValidator.equals("updated is_primary")(updated.is_primary)(newIsPrimary);
  TestValidator.equals("updated joined_at")(updated.joined_at)(newJoinedAt);
  TestValidator.equals("assignment id unchanged")(updated.id)(assignment.id);
  TestValidator.equals("board id unchanged")(updated.discussionboard_board_id)(assignment.discussionboard_board_id);
  TestValidator.equals("moderator id unchanged")(updated.discussionboard_moderator_id)(assignment.discussionboard_moderator_id);

  // Step 6: Negative test – attempt unauthorized update (simulated, expects error if backend enforces auth)
  TestValidator.error("unauthorized update should fail")(async () => {
    // In actual E2E, simulate with unprivileged connection/context if supported; here, attempt with same connection
    await api.functional.discussionboard.boardModerators.update(connection, {
      id: assignment.id,
      body: { is_primary: false },
    });
  });

  // Step 7: Negative test – attempt invalid schema field (should trigger validation or type error)
  TestValidator.error("invalid fields should fail")(async () => {
    // @ts-expect-error: Intentionally invalid property for schema violation
    await api.functional.discussionboard.boardModerators.update(connection, {
      id: assignment.id,
      body: {
        is_primary: true,
        bogus_field: "not allowed",
      },
    });
  });
}

