import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentVote";

/**
 * 댓글 투표(vote_type) 변경 및 권한 검증 E2E 테스트.
 *
 * 본 테스트는 실제로 투표의 소유자만 투표 타입을 변경할 수 있고,
 * 변경 시 updated_at이 갱신됨을 보장하며, 비소유자 및 비회원 접근 시
 * 권한 오류가 발생하는지, 존재하지 않는 투표에 대한 update 시도시 에러 응답이 있는지 검증합니다.
 *
 * 테스트 단계:
 * 1. 회원A(소유자) 생성 및 로그인 연결 유지
 * 2. 게시글/댓글 작성 (회원A 소유)
 * 3. 회원A가 해당 댓글에 투표(vote_type: "up") 생성
 * 4. 회원A로 해당 투표 vote_type을 "down" 등으로 변경, updated_at 갱신
 * 5. 실제 객체에서 vote_type 및 updated_at 값이 반영됐는지 검증
 * 6. 별도 회원B로 동일 투표 업데이트 시도 -> 권한 에러 발생 확인
 * 7. 비로그인 상태(Authorization 헤더 없는 연결)에서 업데이트 시도 -> 접근 차단/에러 검증
 * 8. 마지막으로, 존재하지 않는 id로 업데이트 시도시 오류 발생 확인
 */
export async function test_api_discussionboard_commentVotes_test_update_comment_vote_type_and_check_permissions(
  connection: api.IConnection,
) {
  // 1. 회원A(소유자) 생성
  const memberA = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberA);

  // 2. 게시글/댓글 작성 (회원A 소유)
  const threadId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const boardId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberA.id,
      discussionboard_board_id: boardId,
      title: RandomGenerator.paragraph(1)(),
      body: RandomGenerator.paragraph(2)(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(post);

  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberA.id,
      body: RandomGenerator.paragraph(1)(),
    },
  });
  typia.assert(comment);

  // 3. 투표 최초 생성 (회원A, vote_type: "up")
  const voteCreated = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: memberA.id,
      vote_type: "up",
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(voteCreated);

  // 4. 회원A로 vote_type을 "down"으로 변경, updated_at 갱신
  const updated_at_new = new Date(new Date().getTime() + 1000).toISOString();
  const voteUpdated = await api.functional.discussionboard.commentVotes.update(connection, {
    id: voteCreated.id,
    body: {
      vote_type: "down",
      updated_at: updated_at_new,
    },
  });
  typia.assert(voteUpdated);
  TestValidator.equals("vote_type update")(voteUpdated.vote_type)("down");
  // updated_at 실제 반영 여부
  TestValidator.equals("updated_at changed")(voteUpdated.updated_at)(updated_at_new);

  // 5. 회원B(비소유자) 생성 및 해당 투표 접근 시도(업데이트)
  const memberB = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberB);

  // 회원B

