import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IPageIDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and searching of configuration records with various filters and pagination for the discussion board system configurations.
 *
 * This test covers:
 *
 * 1. Creating several configuration records using POST /discussionboard/configurations, with unique key/value/description.
 * 2. Listing records with no filters (should return all paged records).
 * 3. Filtering by key (exact match; result set contains only the config with that key).
 * 4. Filtering by description (exact match).
 * 5. Filtering by value (exact match).
 * 6. Paginating results—verifying that pagination metadata (current, limit, records, pages) matches expectations, and data slices are as expected.
 * 7. Sending invalid filter structure and confirming 400 error is returned.
 * 8. Sending impossible/out-of-range pagination (negative page/limit, zero limit) and confirming 400 error.
 * 9. Verifying only schema fields appear in actual response objects and not extra properties.
 */
export async function test_api_discussionboard_test_list_configurations_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create several configuration records with unique keys and descriptions
  const configs = await ArrayUtil.asyncRepeat(5)(async (idx) => {
    const key = `test_key_${idx}_${typia.random<string>().slice(0, 5)}`;
    const value = `${1000 + idx}`;
    const description = `Desc ${idx} - filterable ${RandomGenerator.alphabets(3)}`;
    const config = await api.functional.discussionboard.configurations.create(connection, {
      body: { key, value, description } satisfies IDiscussionboardConfiguration.ICreate,
    });
    typia.assert(config);
    return config;
  });

  // 2. List all records with no filter—should include all just-created
  const allPage = await api.functional.discussionboard.configurations.index(connection, {
    body: {} satisfies IDiscussionboardConfiguration.IRequest,
  });
  typia.assert(allPage);
  TestValidator.predicate("all configs present")(
    configs.every(seed => allPage.data.some(got => got.id === seed.id && got.key === seed.key)),
  );

  // 3. Filter by key (exact)
  const keyPick = configs[1];
  const byKey = await api.functional.discussionboard.configurations.index(connection, {
    body: { key: keyPick.key } satisfies IDiscussionboardConfiguration.IRequest,
  });
  typia.assert(byKey);
  TestValidator.equals("by key single record")(byKey.data.length)(1);
  TestValidator.equals("by key match")(byKey.data[0].key)(keyPick.key);

  // 4. Filter by description (exact)
  const descPick = configs[3];
  const byDesc = await api.functional.discussionboard.configurations.index(connection, {
    body: { description: descPick.description } satisfies IDiscussionboardConfiguration.IRequest,
  });
  typia.assert(byDesc);
  TestValidator.equals("by desc single record")(byDesc.data.length)(1);
  TestValidator.equals("desc matches")(byDesc.data[0].description)(descPick.description);

  // 5. Filter by value (exact)
  const valuePick = configs[2];
  const byValue = await api.functional.discussionboard.configurations.index(connection, {
    body: { value: valuePick.value } satisfies IDiscussionboardConfiguration.IRequest,
  });
  typia.assert(byValue);
  TestValidator.equals("by value single record")(byValue.data.length)(1);
  TestValidator.equals("value matches")(byValue.data[0].value)(valuePick.value);

  // 6. Paginate: No filter, but implies only a slice per page if API supports pagination
  //    Here we test only page 1, limit 2 (if API supports those fields)
  //    Some APIs do not, so the block is surrounded with best effort — skip if unsupported
  const testLimit = 2;
  try {
    const page1 = await api.functional.discussionboard.configurations.index(connection, {
      body: { current: 1, limit: testLimit } as any,
    });
    typia.assert(page1);
    TestValidator.equals("current page")(page1.pagination.current)(1);
    TestValidator.equals("limit")(page1.pagination.limit)(testLimit);
    TestValidator.predicate("data length ≤ limit")(page1.data.length <= testLimit);
  } catch {
    // API might not accept explicit pagination fields
  }

  // 7. Error: filter contains extra field (should 400)
  await TestValidator.error("unsupported filter field")(() =>
    api.functional.discussionboard.configurations.index(connection, {
      body: { bogus: "xx" } as any,
    }),
  );

  // 8. Error: pagination invalid (page/limit negative/zero)
  await TestValidator.error("negative page")(() =>
    api.functional.discussionboard.configurations.index(connection, {
      body: { current: -1 } as any,
    }),
  );
  await TestValidator.error("negative limit")(() =>
    api.functional.discussionboard.configurations.index(connection, {
      body: { limit: 0 } as any,
    }),
  );

  // 9. Schema: No extra fields in config record responses
  allPage.data.forEach(record => {
    const keys = Object.keys(record);
    TestValidator.equals("record schema keys")(keys.sort())(["id", "key", "value", "description", "created_at", "updated_at"].sort());
  });
}

