  const found = list.data.find((conf) => conf.id === created.id);
  TestValidator.equals("deleted config should not be listed")(found)(undefined);

  // 4. Attempt to delete again; expect a 404 error
  await TestValidator.error("repeat deletion returns 404 error")(async () => {
    await api.functional.discussionboard.configurations.erase(connection, { id: created.id });
  });

