import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostReference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReference";
import type { IPageIPostReference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostReference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtering/search for post references with valid filter criteria.
 *
 * This test verifies that the post reference search endpoint (PATCH /discussionboard/postReferences)
 * properly filters and paginates results based on the allowed filter schema fields:
 *  - source_post_id
 *  - reference_type
 *  - target_post_id
 *  - target_thread_id
 *
 * Steps:
 * 1. Create posts to serve as source, target posts, and as thread targets.
 * 2. Create post references with different types:
 *    - Post-to-post reference
 *    - Post-to-thread reference
 *    - Reference with both post/thread targets
 * 3. Perform search (index) with each individual filter, and with multiple filters.
 * 4. Validate that response data and pagination returns only records matching the search criteria.
 */
export async function test_api_discussionboard_test_search_post_references_with_valid_filters(
  connection: api.IConnection,
) {
  // Step 1: Create posts for combinations of source/target/thread targets
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId  = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();

  // Create 2 posts in the same thread for post-to-post reference
  const postA = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: "Source Post",
      body: "Body of the source post.",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(postA);

  const postB = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: "Target Post",
      body: "Body of the target post.",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(postB);

  // Create a post for a different thread for post-to-thread reference
  const otherThreadId = typia.random<string & tags.Format<"uuid">>();
  const threadTargetPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: otherThreadId,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: "Thread Target Post",
      body: "A post representing another thread.",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(threadTargetPost);

  const referenceTypePost = "post";
  const referenceTypeThread = "thread";
  const referenceTypeComment = "comment";

  // Step 2: Create various post references
  // Post-to-post
  const postToPost = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: postA.id,
      target_post_id: postB.id,
      target_thread_id: null,
      reference_type: referenceTypePost,
    },
  });
  typia.assert(postToPost);

  // Post-to-thread reference
  const postToThread = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: postA.id,
      target_post_id: null,
      target_thread_id: otherThreadId,
      reference_type: referenceTypeThread,
    },
  });
  typia.assert(postToThread);

  // Reference with both post and thread target and a different type
  const specialReference = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: postB.id,
      target_post_id: threadTargetPost.id,
      target_thread_id: threadTargetPost.discussionboard_thread_id,
      reference_type: referenceTypeComment,
    },
  });
  typia.assert(specialReference);

  // Step 3: Filter/search by each core field, plus a compound filter

  // (a) source_post_id
  const filteredBySource = await api.functional.discussionboard.postReferences.index(connection, {
    body: {
      source_post_id: postA.id,
    },
  });
  typia.assert(filteredBySource);
  TestValidator.predicate("All results: source_post_id matches filter")(filteredBySource.data.every(ref => ref.source_post_id === postA.id));

  // (b) target_post_id
  const filteredByTargetPost = await api.functional.discussionboard.postReferences.index(connection, {
    body: {
      target_post_id: postB.id,
    },
  });
  typia.assert(filteredByTargetPost);
  TestValidator.predicate("All results: target_post_id matches filter")(filteredByTargetPost.data.every(ref => ref.target_post_id === postB.id));

  // (c) reference_type ("thread")
  const filteredByTypeThread = await api.functional.discussionboard.postReferences.index(connection, {
    body: {
      reference_type: referenceTypeThread,
    },
  });
  typia.assert(filteredByTypeThread);
  TestValidator.predicate("All results: reference_type matches filter")(
    filteredByTypeThread.data.every(ref => ref.reference_type === referenceTypeThread),
  );

  // (d) target_thread_id
  const filteredByTargetThread = await api.functional.discussionboard.postReferences.index(connection, {
    body: {
      target_thread_id: otherThreadId,
    },
  });
