import type { IPageIDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching discussion board sections by partial (substring) name and ensure UI position sorting order.
 *
 * Business context:
 * Users (e.g., admins or moderators) frequently search for sections (second-level categories) using a partial match in the section name. These sections should be returned in UI order, i.e., sorted ascending by the 'position' property. This test ensures substring matching works correctly and ordering by 'position' is accurate.
 *
 * Workflow:
 * 1. Create one channel to serve as the parent for test sections.
 * 2. Under this channel, create at least three sections with distinct 'position' values and names sharing a common substring (e.g., 'Economics', 'Global Economics', 'Economics & Policy').
 * 3. Fetch the list of sections, filtering by a substring in their names.
 * 4. Assert that: (a) Each returned section includes the substring in its name, (b) sections are sorted by the 'position' property in ascending order, and (c) only the expected sections are returned.
 */
export async function test_api_discussionboard_test_list_sections_with_name_substring_search_and_sort_by_position(
  connection: api.IConnection,
) {
  // 1. Create a parent channel
  const channelCode = RandomGenerator.alphaNumeric(8);
  const channelName = "Economics Test Channel";
  const channel = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: channelCode,
      name: channelName,
      description: "Test channel for section search/sort scenario",
      position: 10,
      active: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel);

  // 2. Create three sections under this channel with a shared substring in the name
  const substring = "Eco";
  const sectionsInput = [
    { code: RandomGenerator.alphaNumeric(5), name: `${substring}nomics`, position: 2 },
    { code: RandomGenerator.alphaNumeric(5), name: `Global ${substring}nomics`, position: 1 },
    { code: RandomGenerator.alphaNumeric(5), name: `${substring}nomics & Policy`, position: 3 },
  ];
  const createdSections: IDiscussionboardSection[] = [];
  for (const sectionInput of sectionsInput) {
    const section = await api.functional.discussionboard.sections.create(connection, {
      body: {
        discussionboard_channel_id: channel.id,
        code: sectionInput.code,
        name: sectionInput.name,
        position: sectionInput.position,
        active: true,
      } satisfies IDiscussionboardSection.ICreate,
    });
    typia.assert(section);
    createdSections.push(section);
  }

  // 3. List sections by partial name and parent channel, sorted by position asc
  const page = await api.functional.discussionboard.sections.index(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      name: substring,
      limit: 10,
      page: 1,
    } satisfies IDiscussionboardSection.IRequest,
  });
  typia.assert(page);

  // 4. Assert substring match and order
  const returned = page.data;
  TestValidator.equals("section count")(returned.length)(3);
  for (const section of returned) {
    TestValidator.predicate(`Name includes substring ${substring}`)(section.name.includes(substring));
    TestValidator.equals("channel id matches")(section.discussionboard_channel_id)(channel.id);
  }
  // Ensure 'position' ascending order
  for (let i = 1; i < returned.length; ++i) {
    TestValidator.predicate("position asc order")(returned[i - 1].position <= returned[i].position);
  }
  // Optionally, assert that the codes match those inserted
  const expectedCodes = sectionsInput.map(s => s.code).sort();
  const returnedCodes = returned.map(s => s.code).sort();
  TestValidator.equals("codes match")(returnedCodes)(expectedCodes);
}

