  TestValidator.equals("section discussionboard_channel_id")(output.discussionboard_channel_id)(sectionInput.discussionboard_channel_id);
  TestValidator.equals("section code")(output.code)(sectionInput.code);
  TestValidator.equals("section name")(output.name)(sectionInput.name);
  TestValidator.equals("section description")(output.description)(sectionInput.description);
  TestValidator.equals("section position")(output.position)(sectionInput.position);
  TestValidator.equals("section active")(output.active)(sectionInput.active);
  // 6. Ensure created_at and updated_at are valid ISO date-time strings
  TestValidator.predicate("created_at is ISO date-time")(!!output.created_at && !isNaN(Date.parse(output.created_at)));
  TestValidator.predicate("updated_at is ISO date-time")(!!output.updated_at && !isNaN(Date.parse(output.updated_at)));
}

