import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * Test updating a moderator assignment record by ID.
 *
 * This test covers both valid update flows and expected failure/error scenarios:
 *
 * - Setup: Create admin and regular member accounts. Have admin assign moderator to a member.
 * - Success scenario: Admin updates moderator assignment -
 *   1. Extends expiry (`expires_at`) for a moderator assignment and checks updated value is reflected
 *   2. Revokes moderator assignment by setting `revoked_at` and checks updated state
 * - Error scenarios:
 *   3. Attempt to update with a non-existent assignment id (should error)
 *   4. Attempt with insufficient permissions (e.g. try as member, should error)
 *   5. Attempt to set invalid date (bad format) in update, should error
 *
 * Steps:
 * 1. Create admin and member users
 * 2. Create moderator assignment as admin
 * 3. Update assignment expires_at as admin (should succeed)
 * 4. Update assignment revoked_at as admin (should succeed)
 * 5. Attempt update with random invalid id (should fail)
 * 6. Attempt update as member (expect permission error)
 * 7. Attempt update with badly formatted date (expect error)
 */
export async function test_api_discussionboard_moderators_test_update_moderator_assignment_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Create admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(18),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(admin);

  // 2. Create regular member (to be assigned moderator)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(18),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 3. Assign member as moderator (as admin)
  const assignTime = new Date().toISOString();
  const moderatorAssignment: IDiscussionboardModerator = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: member.id,
      assigned_by_admin_id: admin.id,
      assigned_at: assignTime,
      expires_at: null,
      revoked_at: null,
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(moderatorAssignment);

  // 4. Update expires_at (extend)
  const extendedExpiry = new Date(Date.now() + 15 * 24 * 60 * 60 * 1000).toISOString();
  const updatedExpiry: IDiscussionboardModerator = await api.functional.discussionboard.moderators.update(connection, {
    id: moderatorAssignment.id,
    body: {
      expires_at: extendedExpiry,
    } satisfies IDiscussionboardModerator.IUpdate,
  });
  typia.assert(updatedExpiry);
  TestValidator.equals("expires extended")(updatedExpiry.expires_at)(extendedExpiry);

  // 5. Update revoked_at (revoke privileges)
  const revokeTime = new Date().toISOString();
  const updatedRevoked: IDiscussionboardModerator = await api.functional.discussionboard.moderators.update(connection, {
    id: moderatorAssignment.id,
    body: {
      revoked_at: revokeTime,
    } satisfies IDiscussionboardModerator.IUpdate,
  });
  typia.assert(updatedRevoked);
  TestValidator.equals("revoked_at set")(updatedRevoked.revoked_at)(revokeTime);

  // 6. Update with non-existent assignment ID (should error)
  await TestValidator.error("nonexistent id should error")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        expires_at: new Date(Date.now() + 10000).toISOString(),
      } satisfies IDiscussionboardModerator.IUpdate,
    });
  });

  // 7. Attempt update as member (not admin, insufficient permission)
  // Switch to member context
  // In absence of login, simulate as best possible
  // (If token/role context needed, this step may not be possible. If API keys override, skip)
  // Here we just call with a new member (simulate failure)
  const unauthorizedMemberEmail = typia.random<string & tags.Format<"email">>();
  const unauthorizedMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: unauthorizedMemberEmail,
      hashed_password: RandomGenerator.alphaNumeric(18),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(unauthorizedMember);
  // Try as this member (note: without authentication switching, just document intent)
  await TestValidator.error("insufficient permission")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: moderatorAssignment.id,
      body: {
        expires_at: new Date(Date.now() + 10000).toISOString(),
      } satisfies IDiscussionboardModerator.IUpdate,
    });
  });

  // 8. Attempt invalid date format
  await TestValidator.error("invalid date format")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: moderatorAssignment.id,
      body: {
        expires_at: "not-a-date",
      } satisfies IDiscussionboardModerator.IUpdate,
    });
  });
}

