import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * Test soft revocation of moderator assignment and error cases.
 *
 * This test verifies the revocation of a moderator role assignment via the erase endpoint. It covers proper setting of revoked_at, idempotency behavior, error handling for non-existent assignments, and ensures that related member accounts are unaffected.
 *
 * Steps:
 * 1. Create an admin member and a regular member.
 * 2. Assign the moderator role to the member as the admin.
 * 3. Revoke the moderator assignment (should set revoked_at and leave record for audit).
 * 4. Confirm revoked_at is set and assignment data is correct.
 * 5. Call revoke on same assignment again to test idempotency—should return same record and not error.
 * 6. Attempt to revoke a non-existent assignment—should throw error.
 * 7. Note: There is no direct API to read a member, so cannot further check member state beyond creation output. If/when member read/check endpoint exists, it should be validated that the member's profile (outside of role assignment) is unchanged by moderator revoke operation.
 */
export async function test_api_discussionboard_test_soft_revoke_moderator_assignment_and_error_cases(
  connection: api.IConnection,
) {
  // 1. Create admin and member accounts
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "admin",
    is_active: true,
  };
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: adminInput,
  });
  typia.assert(admin);

  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Assign moderator role
  const assignedAt = new Date().toISOString();
  const modAssignInput: IDiscussionboardModerator.ICreate = {
    member_id: member.id,
    assigned_by_admin_id: admin.id,
    assigned_at: assignedAt,
    expires_at: null,
    revoked_at: null,
  };
  const moderator = await api.functional.discussionboard.moderators.create(connection, {
    body: modAssignInput,
  });
  typia.assert(moderator);

  // 3. Revoke moderator assignment
  const revoked = await api.functional.discussionboard.moderators.erase(connection, { id: moderator.id });
  typia.assert(revoked);

  // 4. Validate that revoked_at is set (not null), data is correct, audit record remains
  TestValidator.predicate("revoked_at is set")(!!revoked.revoked_at && typeof revoked.revoked_at === "string");
  TestValidator.equals("member_id remains match")(revoked.member_id)(member.id);
  TestValidator.equals("assigned_by_admin_id remains match")(revoked.assigned_by_admin_id)(admin.id);
  TestValidator.equals("assigned_at remains match")(revoked.assigned_at)(assignedAt);

  // 5. Attempt to revoke again (idempotency: should not error, returns same revoked record)
  const revokedAgain = await api.functional.discussionboard.moderators.erase(connection, { id: moderator.id });
  typia.assert(revokedAgain);
  TestValidator.equals("revoked_at field stable")(revokedAgain.revoked_at)(revoked.revoked_at);

  // 6. Try to revoke non-existent moderator assignment (should error)
  await TestValidator.error("revoke non-existent assignment fails")(() =>
    api.functional.discussionboard.moderators.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 7. Member profile remains unaffected: No direct member read endpoint is available. If/when one exists, should verify member info unchanged except for mod assignments.
}

