import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Test admin assignment creation in the discussion board system, including success, unique constraint, and invalid data paths.
 *
 * This test covers:
 * 1. Register two valid members. One will be assigned admin privileges; the other acts as the assigning admin.
 * 2. Assign admin status to the target member, using the other admin's discussionboard_admins.id for `assigned_by_admin_id`. Verify all fields in the returned discussionboard_admin entity.
 * 3. Attempt to create a duplicate admin assignment for the same member and assert a unique constraint (1:1 mapping) error is thrown.
 * 4. Test edge cases: (a) try to assign admin for a non-existent member_id; (b) omit required fields (e.g., missing member_id), asserting validation/foreign key errors on all invalid requests.
 * 5. Validate that the member records themselves (role, is_active, etc.) remain unchanged by admin assignment—only the admin-assignment table is affected.
 */
export async function test_api_discussionboard_test_create_admin_assignment_with_unique_constraint_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register two valid members
  const member1_input = {
    username: RandomGenerator.alphabets(12),
    email: `${RandomGenerator.alphabets(8)}1@sample.com`,
    hashed_password: RandomGenerator.alphabets(24),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member2_input = {
    username: RandomGenerator.alphabets(12),
    email: `${RandomGenerator.alphabets(8)}2@sample.com`,
    hashed_password: RandomGenerator.alphabets(24),
    role: "admin",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;

  const member1 = await api.functional.discussionboard.members.create(connection, { body: member1_input });
  typia.assert(member1);
  TestValidator.equals("member1.username")(member1.username)(member1_input.username);
  TestValidator.equals("member1.email")(member1.email)(member1_input.email);

  const member2 = await api.functional.discussionboard.members.create(connection, { body: member2_input });
  typia.assert(member2);
  TestValidator.equals("member2.username")(member2.username)(member2_input.username);
  TestValidator.equals("member2.email")(member2.email)(member2_input.email);

  // 2. Assign admin status to member1, using member2 as the assigning admin
  // First, bootstrap: Allow self-appointment for member2's initial admin assignment
  const admin2_input = {
    member_id: member2.id,
    assigned_by_admin_id: member2.id, // Allow bootstrap: self-assignment
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies IDiscussionboardAdmin.ICreate;
  const admin2 = await api.functional.discussionboard.admins.create(connection, { body: admin2_input });
  typia.assert(admin2);
  TestValidator.equals("admin2.member_id")(admin2.member_id)(member2.id);
  TestValidator.equals("admin2.assigned_by_admin_id")(admin2.assigned_by_admin_id)(member2.id);
  TestValidator.equals("admin2.revoked_at")(admin2.revoked_at)(null);

  // Now, assign member1 as admin, with member2 as assigner
  const admin1_input = {
    member_id: member1.id,
    assigned_by_admin_id: admin2.id, // Use the created admin id
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies IDiscussionboardAdmin.ICreate;
  const admin1 = await api.functional.discussionboard.admins.create(connection, { body: admin1_input });
  typia.assert(admin1);
  TestValidator.equals("admin1.member_id")(admin1.member_id)(member1.id);
  TestValidator.equals("admin1.assigned_by_admin_id")(admin1.assigned_by_admin_id)(admin2.id);
  TestValidator.equals("admin1.revoked_at")(admin1.revoked_at)(null);

  // 3. Attempt to create a duplicate admin assignment for member1 (should fail unique constraint)
  TestValidator.error("duplicate admin assignment fails")(async () => {
    await api.functional.discussionboard.admins.create(connection, { body: admin1_input });
  });

  // 4a. Attempt to assign admin to a non-existent member
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  const bad_admin_input = {
    member_id: nonExistentId,
    assigned_by_admin_id: admin2.id,
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } satisfies IDiscussionboardAdmin.ICreate;
  TestValidator.error("assign admin to non-existent member fails")(async () => {
    await api.functional.discussionboard.admins.create(connection, { body: bad_admin_input });
  });

  // 4b. Omit required fields (missing member_id)
  const incomplete_admin_input = {
    // member_id missing
    assigned_by_admin_id: admin2.id,
    assigned_at: new Date().toISOString(),
    revoked_at: null,
  } as any; // purposely invalid to simulate missing required field
  TestValidator.error("missing required member_id fails")(async () => {
    await api.functional.discussionboard.admins.create(connection, { body: incomplete_admin_input });
  });

  // 5. Ensure member records are unchanged after admin assignment
  const member1_after = await api.functional.discussionboard.members.create(connection, { body: { ...member1_input, username: member1.username+"_new", email: `${RandomGenerator.alphabets(7)}_new@sample.com` } });
  typia.assert(member1_after);

  TestValidator.equals("original member role unchanged")(member1.role)(member1_input.role);
  TestValidator.equals("original member is_active unchanged")(member1.is_active)(member1_input.is_active);
}

