 *
 * - 목적: 게시판(board)에 신규 모더레이터(moderator)를 정상적으로 할당할 수 있고, 동일 게시판-모더레이터 조합에 중복 할당 시 Unique 제약이 위반됨을 보장
 *
 * 1. 게시판 생성(discussionboard_board_category_id/section_id 랜덤)
 * 2. 모더레이터(회원) 생성 후 등록
 * 3. boardModerators API로 모더레이터를 해당 게시판에 할당
 * 4. 응답값 필드 값(게시판/모더레이터/primary/joined_at)의 정확성 검증
 * 5. 동일 게시판-모더레이터 조합으로 중복 할당 시도 → Unique 제약 에러 정상 발생 확인
 */
export async function test_api_discussionboard_test_assign_moderator_to_board_success(
  connection: api.IConnection,
) {
  // 1. 게시판 생성 (카테고리, 섹션 UUID 랜덤)
  const boardCategoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: boardCategoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.name(),
      code: RandomGenerator.alphaNumeric(8),
      is_active: true,
      is_visible: true,
