      assigned_by_admin_id: adminId,
      assigned_at: assignedAt,
      expires_at: null,
      revoked_at: null,
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(moderator);

  // 3. 게시판-모더레이터 할당
  const joinedAt = new Date().toISOString();
  const isPrimary = true;
  const assignment = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: board.id,
      discussionboard_moderator_id: moderator.id,
      is_primary: isPrimary,
      joined_at: joinedAt,
    } satisfies IDiscussionboardBoardModerator.ICreate,
  });
