 * 동일한 moderator를 동일한 board에 두 번 할당할 때 고유성 제약 오류가 발생하는지 검증합니다.
 *
 * 비즈니스 시나리오:
 * 1. 테스트용 board(게시판)를 만듭니다.
 * 2. 테스트용 moderator(멤버)를 만듭니다.
 * 3. admin 권한으로 board에 moderator를 정상 할당합니다.
 * 4. 동일한 moderator를 동일 board에 두 번째로 또 할당시도 하여 실패(에러)를 검증합니다.
 *
 * 테스트 절차:
 * 1. board 선행 생성
 * 2. moderator 선행 생성
 * 3. 최초 board-moderator 정상 할당(post)
 * 4. 동일한 payload로 다시 post하여 unique 제약 오류(에러)를 검증
 */
export async function test_api_discussionboard_test_assign_duplicate_moderator_to_board_fails_unique_constraint(
  connection: api.IConnection,
) {
  // 1. 테스트용 board(게시판) 생성
  // board 생성에 필요한 필드(카테고리, 섹션 등)는 임의 UUID를 사용
  const boardCategoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const boardInput: Idiscussionboard_boards.ICreate = {
    discussionboard_board_category_id: boardCategoryId,
    discussionboard_section_id: sectionId,
    name: RandomGenerator.paragraph()(5),
    code: RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(2),
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 2. 테스트용 moderator(멤버) 생성
  // 임의 UUID 기반 member_id, admin_id와 현시각(assigned_at) 사용
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const moderatorInput: IDiscussionboardModerator.ICreate = {
    member_id: memberId,
    assigned_by_admin_id: adminId,
    assigned_at: now,
    expires_at: null,
    revoked_at: null,
  };
  const moderator = await api.functional.discussionboard.moderators.create(connection, {
    body: moderatorInput,
  });
  typia.assert(moderator);

  // 3. 최초 board-moderator 정상 할당
  const boardModeratorPayload: IDiscussionboardBoardModerator.ICreate = {
    discussionboard_board_id: board.id,
    discussionboard_moderator_id: moderator.id,
    is_primary: false,
    joined_at: now,
  };
  const boardModerator = await api.functional.discussionboard.boardModerators.create(
    connection,
    {
      body: boardModeratorPayload,
    },
  );
  typia.assert(boardModerator);

  // 4. 동일한 moderator를 동일 board에 다시 할당(중복) → unique 제약 오류 검증 (에러 발생 기대)
  await TestValidator.error("동일 moderator의 중복 board 할당 시 unique 제약 오류")(
    async () => {
      await api.functional.discussionboard.boardModerators.create(connection, {
        body: boardModeratorPayload,
      });
    },
  );
}

