  typia.assert(board);

  // 2. Create board settings referencing the board
  const settingsInput: IDiscussionboardBoardSetting.ICreate = {
    discussionboard_board_id: board.id,
    is_locked: false,
    require_approval_for_posting: true,
    max_posts_per_hour: 10,
    allow_anonymous_viewing: false,
    allow_file_uploads: true,
  };
  const settings = await api.functional.discussionboard.boardSettings.create(connection, { body: settingsInput });
