  TestValidator.equals("require_approval")(settings.require_approval_for_posting)(settingsInput.require_approval_for_posting);
  TestValidator.equals("max posts/hour")(settings.max_posts_per_hour)(settingsInput.max_posts_per_hour);
  TestValidator.equals("anon viewing")(settings.allow_anonymous_viewing)(settingsInput.allow_anonymous_viewing);
  TestValidator.equals("file uploads")(settings.allow_file_uploads)(settingsInput.allow_file_uploads);

  // 4. Attempt to create another board setting for the same board - should fail due to uniqueness
  await TestValidator.error("duplicate board settings should fail")(() =>
    api.functional.discussionboard.boardSettings.create(connection, { body: settingsInput })
