import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";

/**
 * Test retrieving a thread snapshot by its id (success, not found, malformed id).
 *
 * This test verifies the retrieval of a thread snapshot by id, tests both successful and error cases,
 * and confirms that only schema fields are present and correct. Business context: snapshot records are
 * versioned thread states for moderation/audit, so precise field integrity and error handling are critical.
 *
 * Steps:
 * 1. Create a discussion board member (as author and actor).
 * 2. Create a discussion board for the thread.
 * 3. Create a thread under this board by the member.
 * 4. Create a thread snapshot (with actor as the member).
 * 5. Retrieve the snapshot by valid id and check all schema fields match.
 * 6. Attempt retrieval with a random (non-existent) UUID; expect not found error.
 * 7. Attempt retrieval with a malformed/invalid UUID; expect validation error.
 * 8. Confirm only schema fields are in the response.
 */
export async function test_api_discussionboard_threadSnapshots_test_get_thread_snapshot_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a member for use as author and actor
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a board
  const boardInput: Idiscussionboard_boards.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphabets(8),
    code: RandomGenerator.alphaNumeric(8),
    description: "E2E thread snapshot board",
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a thread (by this member, on this board)
  const threadInput: IDiscussionboardThreads.ICreate = {
    board_id: board.id,
    author_member_id: member.id,
    title: "E2E thread title",
    body: "Main thread content",
  };
  const thread = await api.functional.discussionboard.threads.create(connection, { body: threadInput });
  typia.assert(thread);

  // 4. Create a thread snapshot
  const snapshotInput: IDiscussionboardThreadSnapshots.ICreate = {
    thread_id: thread.id,
    actor_id: member.id,
    title: "Snapshot 1",
    body: "Body v1",
    reason: "Initial post",
  };
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(connection, { body: snapshotInput });
  typia.assert(snapshot);

  // 5. Retrieve the thread snapshot by its id (success case)
  const fetched = await api.functional.discussionboard.threadSnapshots.at(connection, { id: snapshot.id });
  typia.assert(fetched);
  TestValidator.equals("Thread snapshot fetch matches created snapshot")(
    {
      id: fetched.id,
      thread_id: fetched.thread_id,
      actor_id: fetched.actor_id,
      title: fetched.title,
      body: fetched.body,
      reason: fetched.reason,
      created_at: fetched.created_at,
    },
  )({
    id: snapshot.id,
    thread_id: snapshot.thread_id,
    actor_id: snapshot.actor_id,
    title: snapshot.title,
    body: snapshot.body,
    reason: snapshot.reason,
    created_at: snapshot.created_at,
  });

  // 6. Try to retrieve with a random non-existent UUID (should 404)
  await TestValidator.error("Not found for nonexistent snapshot id")(() =>
    api.functional.discussionboard.threadSnapshots.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 7. Try to retrieve with a malformed UUID (should error)
  await TestValidator.error("Validation error for malformed uuid")(() =>
    api.functional.discussionboard.threadSnapshots.at(connection, {
      // Type is forcibly cast for this negative test only
      id: "invalid-uuid-string" as any,
    })
  );

  // 8. Schema field presence check (fetched object has only schema fields)
  const allowedKeys = [
    "id",
    "thread_id",
    "actor_id",
    "title",
    "body",
    "reason",
    "created_at",
  ];
  for (const key of Object.keys(fetched)) {
    if (!allowedKeys.includes(key))
      throw new Error(`Unexpected field '${key}' in thread snapshot fetch response.`);
  }
}

