import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";
import type { IDiscussionboardThreadSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshot";

/**
 * E2E test: Update a thread snapshot with valid and invalid data
 *
 * This test verifies the correctness of the thread snapshot update endpoint for the discussion board system.
 * It covers both successful update scenarios and negative (error) flows relating to allowed field constraints.
 *
 * Test scenario steps:
 * 1. Create a member (for acting as thread author and snapshot actor)
 * 2. Create a board (to hold the thread)
 * 3. Create a thread (to snapshot and edit)
 * 4. Create a snapshot (basis for update)
 * 5. Update the snapshot, modifying both allowed fields (body, reason), and confirm changes
 * 6. Update the snapshot with only one field changed (e.g., reason), and confirm the change without altering other fields
 * 7. Attempt to update with missing required update fields to confirm validation errors
 *
 * For every step, assert type correctness and business logic. For each update, check that only allowed fields are affected and other identifiers remain unchanged. In error tests, ensure server throws as expected for missing data.
 */
export async function test_api_discussionboard_test_update_thread_snapshot_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a member (author/actor)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: memberEmail,
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "member",
        is_active: true,
      },
    },
  );
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.create(
    connection,
    {
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
        name: RandomGenerator.paragraph()(2),
        code: RandomGenerator.alphaNumeric(12),
        description: RandomGenerator.paragraph()(),
        is_active: true,
        is_visible: true,
      },
    },
  );
  typia.assert(board);

  // 3. Create a thread
  const thread = await api.functional.discussionboard.threads.create(
    connection,
    {
      body: {
        board_id: board.id,
        author_member_id: member.id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.paragraph()(3),
      },
    },
  );
  typia.assert(thread);

  // 4. Create a snapshot
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(
    connection,
    {
      body: {
        thread_id: thread.id,
        actor_id: member.id,
        title: thread.title,
        body: thread.body,
        reason: "Initial snapshot",
      },
    },
  );
  typia.assert(snapshot);

  // 5. Update the snapshot, changing both body and reason
  const updateBody = {
    body: RandomGenerator.content()()(),
    reason: "Updated for test",
  } satisfies IDiscussionboardThreadSnapshot.IUpdate;
  const updated = await api.functional.discussionboard.threadSnapshots.update(
    connection,
    {
      id: snapshot.id,
      body: updateBody,
    },
  );
  typia.assert(updated);
  TestValidator.equals("snapshot id unchanged")(updated.id)(snapshot.id);
  TestValidator.equals("body updated")(updated.body)(updateBody.body);
  TestValidator.equals("reason updated")(updated.reason)(updateBody.reason);

  // 6. Update again, change only reason, set body null
  const updateReason = {
    reason: "Moderator note: further edit",
    body: null,
  } satisfies IDiscussionboardThreadSnapshot.IUpdate;
  const updated2 = await api.functional.discussionboard.threadSnapshots.update(
    connection,
    {
      id: snapshot.id,
      body: updateReason,
    },
  );
  typia.assert(updated2);
  TestValidator.equals("snapshot id unchanged")(updated2.id)(snapshot.id);
  TestValidator.equals("reason correctly changed")(updated2.reason)(updateReason.reason);
  TestValidator.equals("body correctly null")(updated2.body)(null);

  // 7. Attempt update with no updatable fields (body/reason missing)
  TestValidator.error("should fail on missing updatable fields")(() =>
    api.functional.discussionboard.threadSnapshots.update(connection, {
      id: snapshot.id,
      body: {} as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";
import type { IDiscussionboardThreadSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshot";

/**
 * E2E Test for error and validation handling on thread snapshot update
 *
 * This test validates two major business rules around thread snapshot modification:
 *   - Not found: When attempting to update a snapshot with an invalid/non-existent id, the API should return a not found error (404).
 *   - Validation & field restriction: When updating a valid snapshot, only permitted fields (body, reason) should be changeable. Attempts to update immutable/non-schema fields should be ignored or rejected, and a schema validation error must occur.
 *
 * The following steps are covered:
 * 1. Member is created for authorship context (precondition)
 * 2. Board is created to host thread (precondition)
 * 3. Thread is created (precondition)
 * 4. Valid thread snapshot is created (target for update)
 * 5. Attempt update with non-existent id → expect not found error
 * 6. Attempt valid update (body/reason fields) → expect success
 * 7. Attempt update with unknown/immutable fields (should not be possible in request schema, but API should ignore/reject extra fields)
 */
export async function test_api_discussionboard_test_update_thread_snapshot_with_invalid_id_or_immutable_fields(connection: api.IConnection) {
  // 1. Create member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create board (with random valid UUIDs for category/section)
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: "QnA",
      code: RandomGenerator.alphaNumeric(6),
      description: "Discussion board for tests",
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. Create thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: "Snapshot E2E Test Thread",
      body: "Baseline content for thread snapshot test",
    },
  });
  typia.assert(thread);

  // 4. Create valid snapshot
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: member.id,
      title: thread.title,
      body: thread.body,
      reason: "Initial creation",
    },
  });
  typia.assert(snapshot);

  // 5. Attempt update with non-existent id
  await TestValidator.error("updating non-existent snapshot id should fail")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.update(connection, {
        id: typia.random<string & tags.Format<"uuid">>(), // very likely to be unused id
        body: {
          body: "Should not update", // legal field
          reason: "Trying non-existent id",
        },
      });
    },
  );

  // 6. Attempt valid update (allowed fields: body, reason)
  const updated = await api.functional.discussionboard.threadSnapshots.update(connection, {
    id: snapshot.id,
    body: {
      body: "Edited body for E2E Test",
      reason: "Edit test update",
    },
  });
  typia.assert(updated);
  TestValidator.equals("updated body should match")(updated.body)("Edited body for E2E Test");
  TestValidator.equals("updated reason should match")(updated.reason)("Edit test update");

  // 7. Attempt update with forbidden fields (should fail TypeScript, so we cannot test this) - so we document this inability.
}

