 * Steps:
 *   1. Create an admin member (to ensure authorization for board/thread/snapshot deletes)
 *   2. Create a board (using valid sample category/section IDs)
 *   3. Create a thread in that board
 *   4. Create a thread snapshot for the thread
 *   5. Hard delete the snapshot by id (should 204)
 *   6. Try GET after delete (omitted; no endpoint provided)
 *   7. Try deleting a random uuid (should 404)
 *   8. Try deleting the same deleted id again (should 404)
 */
export async function test_api_discussionboard_test_hard_delete_thread_snapshot_by_valid_and_invalid_id(
