  // 5. Hard delete the thread snapshot by id
  await api.functional.discussionboard.threadSnapshots.erase(connection, {
    id: snapshot.id,
  });

  // 6. GET after delete by id (Omitted: no endpoint present)

  // 7. Attempt delete with a random UUID (should 404)
