import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";
import type { IPageIDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching for notification events by type and delivery status.
 *
 * This test creates a batch of notification records with diverse values for type and delivered status,
 * then executes filtered, paginated searches to validate the notification search API's correctness.
 *
 * Steps:
 * 1. Create multiple notification records with different types and both delivered: true/false flags.
 * 2. Pick a target type (e.g., 'system_alert') and delivered status, and count (in memory) the matching records.
 * 3. Search notifications via API filtered by the chosen type and delivered, and verify all response items have correct type and delivered flag.
 * 4. Test paginated response structure and correctness of pagination metadata (current, limit, total, pages).
 * 5. Edge case: Search using a type that does not exist in any record, assert response is an empty data array and pagination records count 0.
 */
export async function test_api_discussionboard_test_search_notifications_by_type_and_delivery_status(
  connection: api.IConnection,
) {
  // 1. Create notifications of diverse types and delivery statuses
  const types = ["system_alert", "user_mention", "admin_message"];
  const notifications: IDiscussionboardNotification[] = [];
  for (let i = 0; i < 9; ++i) {
    const type = types[i % types.length];
    const delivered = i % 2 === 0;
    const notif: IDiscussionboardNotification = await api.functional.discussionboard.notifications.create(connection, {
      body: {
        type,
        title: `Test Notification ${i} (${type})`,
        body: `Test body content ${i}`,
        delivered,
      } satisfies IDiscussionboardNotification.ICreate,
    });
    typia.assert(notif);
    notifications.push(notif);
  }

  // 2. Pick filter: type = 'system_alert', delivered = true
  const filterType = "system_alert";
  const filterDelivered = true;
  const expected = notifications.filter((n) => n.type === filterType && n.delivered === filterDelivered);

  // 3. Search with filters via API
  const page = await api.functional.discussionboard.notifications.index(connection, {
    body: { type: filterType, delivered: filterDelivered },
  });
  typia.assert(page);

  // Validate all returned records match the filters
  for (const notif of page.data) {
    TestValidator.equals("filtered by type")(notif.type)(filterType);
    TestValidator.equals("filtered by delivered")(notif.delivered)(filterDelivered);
  }
  TestValidator.equals("matching length")(page.data.length)(expected.length);

  // 4. Validate pagination metadata
  TestValidator.equals("pagination current")(page.pagination.current)(1); // page number starts at 1
  TestValidator.equals("pagination limit")(typeof page.pagination.limit)("number");
  TestValidator.predicate("pagination records >= data length")(page.pagination.records >= page.data.length);
  TestValidator.predicate("pagination pages >= 1")(page.pagination.pages >= 1);

  // 5. Edge: search for non-existent type
  const noneType = "nonexistent_type_xyz";
  const emptyPage = await api.functional.discussionboard.notifications.index(connection, {
    body: { type: noneType },
  });
  typia.assert(emptyPage);
  TestValidator.equals("edge case no results")(emptyPage.data.length)(0);
  TestValidator.equals("edge case records=0")(emptyPage.pagination.records)(0);
}

