/**
 * Test system validation for schema compliance on /discussionboard/notifications search endpoint.
 *
 * Business context: The API must strictly enforce that only schema-allowed fields are accepted for notification search filtering. Any attempt to provide unsupported filter fields, whether by accident or through malice, should result in a validation error and no processing of the request. This test ensures that arbitrary/extra filter fields are not tolerated by the endpoint.
 *
 * Process:
 * 1. Construct a valid discussionboard notification search request, then inject an unsupported filter field (e.g., "invalidField").
 * 2. Call PATCH /discussionboard/notifications with this augmented request payload.
 * 3. Assert that the API call fails (runtime validation error) and no data is returned.
 * 4. Confirm the API's schema enforcement protects against non-schema fields in search/filter requests.
 */
export async function test_api_discussionboard_test_search_notifications_invalid_filter_field(
  connection: api.IConnection,
) {
  // Step 1: Build a valid notification search filter
  const validRequest: IDiscussionboardNotification.IRequest = {
    type: "user_mention",
    delivered: true,
  };

  // Step 2: Inject an extra property not defined in the schema
  // This simulates a client attempting to use a non-existent filter.
  // TypeScript does not permit this structurally; use `as any` for negative E2E test only.
  const invalidRequest = {
    ...validRequest,
    invalidField: "arbitrary value",
  } as any;

  // Step 3: Call API and assert that the call fails due to schema validation
  await TestValidator.error(
    "should reject a filter request with a non-schema field (invalidField)",
  )(async () => {
    await api.functional.discussionboard.notifications.index(connection, {
      body: invalidRequest,
    });
  });
}

