 * 2. Call the API to create a new setting record.
 * 3. Assert the response type, verifying all schema fields are populated as expected.
 * 4. Attempt to create a second setting with the exact same {scope_type, key, scope_id} and expect an error (uniqueness constraint).
 * 5. Attempt another creation with different key but same scope_type to confirm successful creation when keys differ.
 */
export async function test_api_discussionboard_settings_test_create_setting_with_valid_fields(connection: api.IConnection) {
  // 1. Compose a valid settings creation payload (all required + optional fields)
  const payload: Idiscussionboard_settings.ICreate = {
    scope_type: "feature_flag", // normalized type per schema
    key: `max_upload_size_${RandomGenerator.alphaNumeric(5)}`,
    value: "50MB",
    description: "Sets the maximum upload size globally.",
    scope_id: null, // global setting
  };

  // 2. Create the setting
  const setting = await api.functional.discussionboard.settings.create(connection, {
    body: payload,
  });
  typia.assert(setting);
  // 3. Validate that response fields are correct and payload fields are present
  TestValidator.equals("scope_type matches")(setting.scope_type)(payload.scope_type);
  TestValidator.equals("key matches")(setting.key)(payload.key);
  TestValidator.equals("value matches")(setting.value)(payload.value);
  TestValidator.equals("description matches")(setting.description)(payload.description);
  TestValidator.equals("scope_id matches")(setting.scope_id)(payload.scope_id);
  TestValidator.predicate("id field is uuid")(typeof setting.id === "string" && setting.id.length > 0);
  TestValidator.predicate("created_at is ISO string")(!!Date.parse(setting.created_at));
  TestValidator.predicate("updated_at is ISO string")(!!Date.parse(setting.updated_at));

  // 4. Attempt to create duplicate (should fail)
  await TestValidator.error("duplicate key for same scope should be rejected")(
    async () => {
      await api.functional.discussionboard.settings.create(connection, {
        body: payload,
      });
    },
  );

  // 5. Create another setting with distinct key (should succeed)
  const nextSetting = await api.functional.discussionboard.settings.create(connection, {
    body: {
      ...payload,
      key: `${payload.key}_alt`, // ensure new key
    },
  });
  typia.assert(nextSetting);
  TestValidator.notEquals("should generate a distinct id")(nextSetting.id)(setting.id);
  TestValidator.equals("scope_type matches")(nextSetting.scope_type)(payload.scope_type);
  TestValidator.notEquals("key is different")(nextSetting.key)(payload.key);
}

