import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Test updating a discussion board with both valid and invalid data for schema and business logic.
 *
 * This test covers:
 * 1. Creating a category, section, and two boards (for uniqueness testing).
 * 2. Successful update: modifies name, code, description, category, section, is_active, is_visible fields.
 * 3. Uniqueness constraint violation: attempts to update with code or name that conflicts with the other board.
 * 4. FK constraint violation: updates with non-existent or invalid category/section ids.
 * 5. Invalid schema: sends extra non-schema fields in update (ignored by SDK, but can be checked by patching request object).
 * 6. Error handling for updates to non-existent id and to an invalid UUID format (expect error).
 *
 * Steps:
 * - Prep: Create required category and section.
 * - Create two boards (A and B). Board B will be used for uniqueness conflict.
 * - Step 1: Normal update on Board A with all updatable fields (positive case).
 * - Step 2: Attempt update on Board A with Board B's name/code (expect error).
 * - Step 3: Update on Board A with random UUIDs for FK fields (expect error).
 * - Step 4: Attempt update using a non-existent board id (expect not found).
 * - Step 5: Attempt update using an invalid UUID (expect error).
 */
export async function test_api_discussionboard_test_update_board_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // Step 1: Create a Board Category
  const category = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.alphabets(20),
      position: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(category);

  // Step 2: Create a Section (requires a channel id)
  const channelId = typia.random<string & tags.Format<"uuid">>();
  const section = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channelId,
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.alphabets(16),
      description: RandomGenerator.alphabets(20),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    },
  });
  typia.assert(section);

  // Step 3: Create two Boards (A, B)
  const boardA = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: category.id,
      discussionboard_section_id: section.id,
      name: RandomGenerator.alphabets(12),
      code: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.alphabets(22),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(boardA);

  const boardB = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: category.id,
      discussionboard_section_id: section.id,
      name: RandomGenerator.alphabets(13),
      code: RandomGenerator.alphaNumeric(14),
      description: RandomGenerator.alphabets(19),
      is_active: false,
      is_visible: false,
    },
  });
  typia.assert(boardB);

  // Step 4: Successful update - modify all updatable fields
  const newCategory = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(11),
      code: RandomGenerator.alphaNumeric(11),
      description: RandomGenerator.alphabets(21),
      position: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(newCategory);

  const newSection = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channelId,
      code: RandomGenerator.alphaNumeric(9),
      name: RandomGenerator.alphabets(17),
      description: RandomGenerator.alphabets(17),
      position: typia.random<number & tags.Type<"int32">>(),
      active: false,
    },
  });
  typia.assert(newSection);

  const updated = await api.functional.discussionboard.boards.update(connection, {
    id: boardA.id,
    body: {
      discussionboard_board_category_id: newCategory.id,
      discussionboard_section_id: newSection.id,
      name: RandomGenerator.alphabets(14),
      code: RandomGenerator.alphaNumeric(14),
      description: RandomGenerator.alphabets(18),
      is_active: false,
      is_visible: false,
    },
  });
  typia.assert(updated);
  TestValidator.equals("update board fields")(updated.discussionboard_board_category_id)(newCategory.id);
  TestValidator.equals("update board fields")(updated.discussionboard_section_id)(newSection.id);
  TestValidator.equals("update board fields")(updated.name)(updated.name);
  TestValidator.equals("update board fields")(updated.is_active)(false);
  TestValidator.equals("update board fields")(updated.is_visible)(false);

  // Step 5: Attempt update with duplicate name/code (from boardB)
  await TestValidator.error("duplicate name error")(() =>
    api.functional.discussionboard.boards.update(connection, {
      id: boardA.id,
      body: {
        name: boardB.name,
      },
    })
  );
  await TestValidator.error("duplicate code error")(() =>
    api.functional.discussionboard.boards.update(connection, {
      id: boardA.id,
      body: {
        code: boardB.code,
      },
    })
  );

  // Step 6: Attempt FK violation - invalid/non-existent category/section
  await TestValidator.error("invalid category id")(() =>
    api.functional.discussionboard.boards.update(connection, {
      id: boardA.id,
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );
  await TestValidator.error("invalid section id")(() =>
    api.functional.discussionboard.boards.update(connection, {
      id: boardA.id,
      body: {
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // Step 7: Attempt update with non-existent id
  await TestValidator.error("non-existent board id")(() =>
    api.functional.discussionboard.boards.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        name: RandomGenerator.alphaNumeric(10),
      },
    })
  );

  // Step 8: Attempt update with invalid UUID
  await TestValidator.error("invalid uuid format")(() =>
    api.functional.discussionboard.boards.update(connection, {
      id: "not-a-uuid" as string & tags.Format<"uuid">,
      body: {
        name: RandomGenerator.alphaNumeric(10),
      },
    })
  );
}

