import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Test creating a board category with valid, duplicate, and invalid data.
 *
 * This function tests the creation process of a board category entity via the /discussionboard/boardCategories endpoint.
 * The business and schema rules require board category name and code to be unique, and all required properties must be provided.
 * The function covers success with unique data, enforcement of unique constraints, validation for missing fields, and rejection of non-schema properties.
 *
 * 1. Create a category with unique name/code (should succeed and return all expected fields, with no extra properties in response).
 * 2. Attempt to create another category with the same name and/or code (should fail due to uniqueness constraint).
 * 3. Attempt to create with missing required fields (should fail validation).
 * 4. Attempt to create using unknown/non-schema properties (should fail validation and reject extra fields).
 */
export async function test_api_discussionboard_test_create_board_category_success_duplicate_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a category with unique name and code
  const createInput = {
    name: "Unique Category Name " + RandomGenerator.alphabets(6),
    code: "unique_code_" + RandomGenerator.alphaNumeric(5),
    position: typia.random<number & tags.Type<"int32">>(),
    description: RandomGenerator.paragraph()(),
  } satisfies IDiscussionboardBoardCategory.ICreate;
  const category = await api.functional.discussionboard.boardCategories.create(connection, {
    body: createInput,
  });
  typia.assert(category);
  TestValidator.predicate("Response has only expected properties")(
    Object.keys(category).sort().join(",") ===
      [
        "id",
        "name",
        "code",
        "description",
        "position",
        "created_at",
      ].sort().join(",")
  );

  // 2. Attempt to create with duplicate name
  await TestValidator.error("Duplicate name should fail")(() =>
    api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        ...createInput,
        code: createInput.code + "_other",
      },
    })
  );

  // 2b. Attempt to create with duplicate code
  await TestValidator.error("Duplicate code should fail")(() =>
    api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        ...createInput,
        name: createInput.name + "_other",
      },
    })
  );

  // 3. Attempt to create with missing required fields (name)
  await TestValidator.error("Missing 'name' should fail")(() =>
    api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        // name: intentionally missing
        code: "another_code_" + RandomGenerator.alphaNumeric(3),
        position: typia.random<number & tags.Type<"int32">>(),
        description: "desc",
      } as any,
    })
  );

  // 3b. Attempt to create with missing required fields (code)
  await TestValidator.error("Missing 'code' should fail")(() =>
    api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        name: "Missing code name",
        // code: missing
        position: typia.random<number & tags.Type<"int32">>(),
        description: "desc",
      } as any,
    })
  );

  // 3c. Attempt to create with missing required fields (position)
  await TestValidator.error("Missing 'position' should fail")(() =>
    api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        name: "Missing position name",
        code: "missing_position_code",
        // position: missing
        description: "desc",
      } as any,
    })
  );

  // 4. Attempt to create with unknown/non-schema fields
  await TestValidator.error("Unknown field should fail")(() =>
    api.functional.discussionboard.boardCategories.create(connection, {
      body: {
        name: "Extra Field Category",
        code: "extra_code",
        position: 1,
        description: "desc",
        extra_field: "should not be allowed",
      } as any,
    })
  );
}

