 * 2. Create a discussion board (category/section IDs are randomly generated)
 * 3. Create a thread authored by the member in the board
 * 4. Assign a tag to the thread at a known assignment time
 * 5. Fetch tag assignments using filters (thread_id, assigned_at range) and page/limit
 * 6. Assert the result includes our newly assigned tag
 * 7. Assert pagination metadata is present and valid
 */
export async function test_api_discussionboard_test_list_thread_tags_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a discussion board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(12),
      code: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(board);

  // 3. Create a thread in the board (by the member)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Assign a thread tag
  const assigned_at = new Date().toISOString();
  const tagAssignment = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at,
      removed_at: null,
    } satisfies IDiscussionboardThreadTag.ICreate,
  });
  typia.assert(tagAssignment);

  // 5. Query for tag assignments using thread_id and assigned_at range
  const tagPage = await api.functional.discussionboard.threadTags.index(connection, {
    body: {
      page: 1,
      limit: 10,
      thread_id: thread.id,
      assigned_at_from: assigned_at,
      assigned_at_to: assigned_at,
    } satisfies IPageIDiscussionboardThreadTag.IRequest,
  });
  typia.assert(tagPage);

  // 6. Assert at least 1 tag assignment is returned and matches the thread/tag
  TestValidator.predicate("should return at least one data")(
    Array.isArray(tagPage.data) && tagPage.data.length > 0,
  );
  const foundAssignment = tagPage.data.find(
    (t) => t.id === tagAssignment.id && t.thread_id === thread.id && t.assigned_at === assigned_at,
  );
  TestValidator.predicate("created assignment appears in paged results")(!!foundAssignment);

  // 7. Confirm pagination meta
  TestValidator.equals("current page is 1")(tagPage.pagination.current)(1);
  TestValidator.equals("limit is 10")(tagPage.pagination.limit)(10);
  TestValidator.predicate("records >= 1")(tagPage.pagination.records >= 1);
  TestValidator.predicate("pages >= 1")(tagPage.pagination.pages >= 1);
}

