import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadTag";

/**
 * Test successful hard deletion of a thread tag assignment by its ID in the discussion board system.
 *
 * Business Purpose:
 * Deleting a thread tag assignment should permanently remove the corresponding record from the system. The test covers the creation of all resource dependencies (member, board, thread assignment), performs the hard delete using the assignment ID, and verifies the record is no longer retrievable after deletion. This ensures the hard deletion contract is honored and confirms correct error handling when attempting to access deleted records.
 *
 * Workflow:
 * 1. Create a discussion board member (author for the thread).
 * 2. Create a discussion board.
 * 3. Create a thread in that board, authored by the member.
 * 4. Assign a tag to the thread (create a thread-tag assignment).
 * 5. Hard delete the thread tag assignment by its ID.
 * 6. Attempt to delete again; should yield an error, confirming record removal.
 */
export async function test_api_discussionboard_test_delete_thread_tag_assignment_success(
  connection: api.IConnection,
) {
  // 1. Create a member (for authoring a thread)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: 'member',
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_section_id: typia.random<string & tags.Format<'uuid'>>(),
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(12),
      description: null,
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. Create a thread in the board by the member
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.alphabets(8),
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(thread);

  // 4. Assign a tag to the thread
  const tagAssignment = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: new Date().toISOString(),
      removed_at: null,
    },
  });
  typia.assert(tagAssignment);

  // 5. Hard delete the thread tag assignment by its ID
  await api.functional.discussionboard.threadTags.erase(connection, { id: tagAssignment.id });

  // 6. Attempt to delete the same tag assignment again - should yield error, confirming deletion
  await TestValidator.error('Tag assignment should not be found after deletion')(async () => {
    await api.functional.discussionboard.threadTags.erase(connection, { id: tagAssignment.id });
  });
}

