/**
 * 게시판 스레드 태그 할당 삭제 권한 거부 테스트
 *
 * 일반 회원이(운영자도 아니고, 관리자도 아닌 권한) 자신이 할당한 태그를 삭제하려고 시도할 경우,
 * 권한 부족(Forbidden)으로 요청이 거부되는지 검증하는 테스트입니다.
 *
 * [테스트 시나리오]
 * 1. 일반 회원(권한: member) 계정을 생성한다.
 * 2. (운영자/관리자 필요 없이) 어떤 카테고리, 섹션 ID가 있다고 가정하고, 보드를 생성한다.
 * 3. 해당 회원으로 스레드를 생성한다.
 * 4. 생성한 스레드에 대해 태그 할당을 하나 추가한다.
 * 5. 생성된 threadTags.id를 해당 일반 회원 세션에서 삭제 시도한다.
 * 6. 삭제 요청 결과가 권한 부족(403 Forbidden) 등으로 거부되는지 검증한다.
 * [중요] 실제 삭제 API는 moderators/admin만 가능하도록 설계되었으므로, member가 직접 호출 시 실패해야 한다.
 */
export async function test_api_discussionboard_test_delete_thread_tag_assignment_permission_denied(connection: api.IConnection) {
  // 1. 일반 회원(권한: member) 계정 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 보드 생성 - 섹션/카테고리 UUID 랜덤값 사용
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(7),
      code: RandomGenerator.alphaNumeric(10),
      description: null,
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. 스레드 생성
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: null,
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. 태그 할당 생성
  const threadTag = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: new Date().toISOString(),
      removed_at: null,
    } satisfies IDiscussionboardThreadTag.ICreate,
  });
  typia.assert(threadTag);

  // 5. 일반 회원에서 태그 삭제 시도 (권한 부족 검증)
  await TestValidator.error("멤버는 스레드 태그 삭제 권한이 없어야 함.")(
    async () => {
      await api.functional.discussionboard.threadTags.erase(
        connection,
        { id: threadTag.id },
      );
    },
  );
}

