import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Test the creation of a discussion board post with all valid, complete data.
 *
 * This test ensures the end-to-end flow for a member posting to a thread within a board works as expected.
 * To satisfy all foreign key constraints, the test performs the following sequence:
 * 1. Create a new discussion board member (author).
 * 2. Create a new discussion board.
 * 3. Create a new thread authored by the member in the created board.
 * 4. Create a post in that thread using the member and board references, filling all required fields from IDiscussionboardPost.ICreate.
 * 5. Assert the response contains the expected post data and correct associations (thread, member, board). Validate type, value, and basic integrity constraints.
 */
export async function test_api_discussionboard_test_create_post_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create discussion board member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create discussion board (requires existing category/section UUIDs—use random for test)
  const boardInput: Idiscussionboard_boards.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphabets(10),
    code: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.paragraph()(),
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create thread in the board, authored by member
  const threadInput: IDiscussionboardThreads.ICreate = {
    board_id: board.id,
    author_member_id: member.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const thread = await api.functional.discussionboard.threads.create(connection, { body: threadInput });
  typia.assert(thread);

  // 4. Create post in the thread (all required fields)
  const now = new Date().toISOString();
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
    discussionboard_board_id: board.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_deleted: false,
    created_at: now,
    updated_at: now,
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);
  // 5. Assert post data matches input and foreign keys
  TestValidator.equals("post.thread_id matches")(post.discussionboard_thread_id)(thread.id);
  TestValidator.equals("post.member_id matches")(post.discussionboard_member_id)(member.id);
  TestValidator.equals("post.board_id matches")(post.discussionboard_board_id)(board.id);
  TestValidator.equals("title matches")(post.title)(postInput.title);
  TestValidator.equals("body matches")(post.body)(postInput.body);
  TestValidator.equals("is_deleted should be false")(post.is_deleted)(false);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate that the discussion board post creation endpoint rejects requests with invalid field values (e.g., empty/invalid uuid, empty title/body, invalid timestamps).
 *
 * Business context:
 * Creating a post on the discussion board requires all mandatory fields and valid UUID/timestamp/string formats. If any required property has an empty or improperly formatted value, the API must reject the request.
 *
 * Process:
 * 1. Build a valid baseline post creation payload.
 * 2. For each required uuid/timestamp/string field, try submitting an invalid value (empty string, invalid uuid, malformed date-time).
 * 3. Each invalid submission must raise a validation error (no post created).
 */
export async function test_api_discussionboard_test_create_post_missing_required_fields(
  connection: api.IConnection,
) {
  // Baseline valid post object
  const validPost: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Valid Title",
    body: "Valid Body Content",
    is_deleted: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  // Helper to deep-clone
  const clone = <T>(obj: T): T => JSON.parse(JSON.stringify(obj));

  // (1) Empty string for required uuid,string,date-time fields
  const stringFields = [
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "discussionboard_board_id",
    "title",
    "body",
    "created_at",
    "updated_at",
  ];
  for (const field of stringFields) {
    const invalidPost = clone(validPost);
    (invalidPost as any)[field] = "";
    await TestValidator.error(`empty string for field: ${field}`)(async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: invalidPost,
      });
    });
  }

  // (2) Invalid uuid string for uuid fields
  const uuidFields = [
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "discussionboard_board_id",
  ];
  for (const field of uuidFields) {
    const invalidPost = clone(validPost);
    (invalidPost as any)[field] = "not-a-uuid";
    await TestValidator.error(`invalid uuid for field: ${field}`)(async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: invalidPost,
      });
    });
  }

  // (3) Malformed date-time string for timestamp fields
  const dateTimeFields = ["created_at", "updated_at"];
  for (const field of dateTimeFields) {
    const invalidPost = clone(validPost);
    (invalidPost as any)[field] = "not-a-date";
    await TestValidator.error(`invalid date-time for field: ${field}`)(async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: invalidPost,
      });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Test that creating a discussion board post with invalid (non-existent or malformed) references for thread, member, or board IDs results in a validation or not found error.
 *
 * Business context:
 * This test ensures robust API handling of integrity constraints for foreign keys when creating discussion board posts. No valid resource should ever be created with references to non-existent threads, members, or boards. The system must return an appropriate error (HTTP 400/404 or equivalent business error) rather than allowing an incorrect relationship to be written.
 *
 * Test steps:
 * 1. Generate three different reference scenarios:
 *    a. All foreign keys are valid-format UUIDs but not corresponding to any existing thread/member/board records in the database (non-existent but valid shape).
 *    b. One or more foreign keys have completely malformed UUIDs (invalid shape).
 *    c. Mix valid-format and malformed values in a single request.
 * 2. For each scenario, attempt to create a discussion post via /discussionboard/posts using the API.
 * 3. Verify that each attempt results in an error from the backend (validation or not found error).
 * 4. Assert that no post object is returned and the response triggers an exception/error handling as expected.
 *
 * The test validates that the backend enforces referential integrity and UUID format for all related fields in discussionboard_posts creation.
 */
export async function test_api_discussionboard_test_create_post_with_invalid_references(
  connection: api.IConnection,
) {
  // 1. Scenario: All UUIDs are random (valid shape, non-existent in DB)
  await TestValidator.error("Post creation with non-existent FK UUIDs triggers not found error")(
    async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: {
          discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
          discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
          discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
          title: "Invalid references test - random valid UUIDs",
          body: "Body should not be created when FKs are non-existent.",
          is_deleted: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionboardPost.ICreate,
      });
    },
  );

  // 2. Scenario: One or more malformed (invalid format) UUIDs
  await TestValidator.error("Post creation with malformed UUIDs triggers validation error")(
    async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: {
          discussionboard_thread_id: "bad-uuid-format-1", // invalid
          discussionboard_member_id: "bad-uuid-format-2", // invalid
          discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(), // valid
          title: "Invalid references test - malformed UUIDs",
          body: "Body should not be created with malformed UUIDs.",
          is_deleted: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionboardPost.ICreate,
      });
    },
  );

  // 3. Scenario: Mix valid-format and malformed UUIDs
  await TestValidator.error("Post creation with mixed valid and invalid UUIDs triggers error")(
    async () => {
      await api.functional.discussionboard.posts.create(connection, {
        body: {
          discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(), // valid
          discussionboard_member_id: "not-a-uuid-value", // invalid
          discussionboard_board_id: "also-not-uuid", // invalid
          title: "Invalid references test - mixed values",
          body: "Should not create with mixed malformed and valid-format UUIDs.",
          is_deleted: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionboardPost.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * 유일성 제약(가령, 하나의 멤버가 동일 스레드/제목에 두 번 포스팅하지 못함 등)이 존재할 때, 게시판 글을 중복 데이터로 생성하려고 할 때 정상적으로 실패(에러)가 발생하는지 검증합니다.
 *
 * 이 테스트는 다음 절차로 진행됩니다:
 * 1. 테스트 멤버를 생성한다.
 * 2. 테스트 게시판을 생성한다.
 * 3. 테스트 스레드를 생성한다.
 * 4. (실패 재현을 위해) 첫 번째 게시글을 만든다.
 * 5. 똑같은 데이터로 두 번째 글 생성 시도를 하여 에러 발생을 검증한다.
 *
 * - 먼저 멤버, 게시판, 스레드 선행 생성(의존성 충족).
 * - 동일 thread, 동일 member, 동일 title, body 등으로 post 1, post 2 순차 생성.
 * - post 1은 성공해야 하고, post 2는 (유일성 제약 시) 에러 발생해야 함.
 * - (만약 DB에 유니크 제약 없음/중복허용이면, post 2도 성공이어야 함.)
 *
 * 구체적으로 어떤 컬럼의 복합 유일성 제약이 걸려있는지는 스키마 및 테이블 정책에 따라 다양한데,
 * 기본적으로 discussionboard_posts 테이블에 별도의 unique constraints 명시가 없으면 오직 논리적 중복(동일 thread+member+title+본문)만을 실질적으로 테스트할 수 있다.
 */
export async function test_api_discussionboard_test_create_post_with_duplicate_data(
  connection: api.IConnection,
) {
  // 1. 테스트 멤버 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 게시판 생성 (카테고리/섹션 id 임의 생성)
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(board);

  // 3. 스레드 생성 (board와 member 연결)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.alphaNumeric(16),
      body: RandomGenerator.paragraph()(2),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. 첫 번째 게시글 생성
  const now = new Date().toISOString();
  const postCreateBody: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
