 * This scenario validates that the preferences search/filter API only honors valid schema fields, returns paginated data, ignores (or rejects) non-schema fields, and processes filters as expected. We cover all valid fields (receive_email_notifications, receive_push_notifications, preferred_language, dark_mode_enabled) in various combinations, using different search parameters, and test pagination edge cases.
 *
 * 1. Register a new discussionboard member (and implicitly become authenticated)
 * 2. Use /my/discussionboard/member/preferences search API to fetch with each valid field (individually and in combination)
 * 3. Assert results only include schema fields, never extra fields
 * 4. Assert correct filtering and pagination works for the current user
 */
export async function test_api_my_discussionboard_member_preferences_test_search_own_notification_preferences_by_valid_fields(connection: api.IConnection) {
  // 1. Register a new discussionboard member (register and implicitly login)
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
