  let output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: {} });
  typia.assert(output);
  TestValidator.predicate("pagination meta present")(!!output.pagination);
  TestValidator.predicate("data array present")(Array.isArray(output.data));
  for (const pref of output.data)
    typia.assert(pref);

  // 3. Search with each valid field (confirmed do not error)
  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { receive_email_notifications: true } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { receive_push_notifications: false } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { preferred_language: "en" } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { dark_mode_enabled: true } });
  typia.assert(output);
