    typia.assert(pref);

  // 4. Combinatorial valid field search
  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { receive_email_notifications: false, preferred_language: "ko" } });
  typia.assert(output);
  for (const pref of output.data)
    typia.assert(pref);

  // 5. Pagination edge test: limit 1, page 1 (should return at most one record)
  output = await api.functional.my.discussionboard.member.preferences.index(connection, { body: { pagination: { page: 1, limit: 1 } } });
  typia.assert(output);
  TestValidator.predicate("at most one record on page 1")(output.data.length <= 1);

  // 6. Ensure no properties outside schema
  for (const pref of output.data) {
    const allowed = [
      "id",
      "member_id",
      "receive_email_notifications",
      "receive_push_notifications",
      "preferred_language",
      "dark_mode_enabled"
    ];
    for (const key of Object.keys(pref)) {
      TestValidator.predicate(`property ${key} allowed`)(allowed.includes(key));
    }
  }
}

