/**
 * 자신의 알림/환경설정 프리퍼런스에서 유효하지 않은(스키마 미정의) 필드로 검색 요청 시 validation 에러가 발생하는지 검증한다.
 *
 * - 허용되지 않은 필터(스키마 미정의 필드)로 검색 요청 시 API가 검증 오류를 반환해야 한다.
 * - 실제 회원 가입 및 인증 처리 선행 후 테스트 진행.
 *
 * 절차:
 * 1. 회원 등록 (필수)
 * 2. 정상 필터: 허용 필드(receive_email_notifications) 포함 검색 → 성공 검증
 * 3. 비정상 필터: 스키마에 없는 invalid_field 포함 → validation error 발생 확인
 */
export async function test_api_my_discussionboard_member_preferences_test_search_own_notification_preferences_with_invalid_field(
