import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * End-to-end test for updating administrator assignments (discussionboard_admins.update).
 *
 * Validates behavior for updating an admin assignment by id. This includes:
 *
 * 1. Normal update of the permitted field (revoked_at)
 * 2. Revocation (setting revoked_at from null to now)
 * 3. Attempting update on non-existent admin assignment id (should error)
 * 4. Attempting to update an already-revoked assignment (should remain revoked)
 *
 * The workflow covers:
 *  - Creating an ordinary member (target)
 *  - Creating an initial admin (to be assigner)
 *  - Assigning admin rights to the target member with initial assignment
 *  - Updating the assignment record
 *  - Negative cases for invalid/nonexistent records and re-update
 */
export async function test_api_discussionboard_test_update_admin_assignment_fields_and_handle_revocation(
  connection: api.IConnection,
) {
  // 1. Create admin who will assign another admin
  const adminCreator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(adminCreator);

  // 2. Create a member to be promoted to admin
  const targetMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(targetMember);

  // 3. Assign admin rights to the target member
  const assignmentTime = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: targetMember.id,
      assigned_by_admin_id: adminCreator.id,
      assigned_at: assignmentTime,
      revoked_at: null,
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("admin assignment active")(adminAssignment.revoked_at)(null);

  // 4. Update (revoke) admin assignment -- set revoked_at
  const revocationTime = new Date().toISOString();
  const revoked = await api.functional.discussionboard.admins.update(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: revocationTime,
    } satisfies IDiscussionboardAdmin.IUpdate,
  });
  typia.assert(revoked);
  TestValidator.equals("assignment revoked")(revoked.revoked_at)(revocationTime);

  // 5. Try to update a non-existent admin assignment (should error)
  await TestValidator.error("update nonexistent admin assignment")(async () => {
    await api.functional.discussionboard.admins.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        revoked_at: new Date().toISOString(),
      } satisfies IDiscussionboardAdmin.IUpdate,
    });
  });

  // 6. Try to update an already-revoked assignment (should remain revoked and not error fatally)
  const reUpdate = await api.functional.discussionboard.admins.update(connection, {
