import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Validate soft-revocation (idempotent) of discussionboard admin assignments by ID.
 *
 * This test covers both business and edge-case behavioral rules for the soft revocation (DELETE) of administrator assignments in the discussionboard_admins table. The focus is on proper status transitions, idempotency, and error response when non-existent IDs are used.
 *
 * Steps:
 * 1. Register a base member to serve as the admin assigner (bootstrapping, role: 'admin').
 * 2. Register a regular member who will become an admin (role: 'member').
 * 3. Assign admin privileges to the member—this returns an IDiscussionboardAdmin with a valid .id.
 * 4. Soft-revoke this admin assignment by calling erase with the assignment ID. Assert that: (a) revoked_at is set to a current timestamp, (b) the record is still structurally valid (not hard-deleted), and (c) the member's admin is no longer active.
 * 5. Call erase again for the same ID to confirm idempotency; the response should indicate revoked_at is still set and no error is thrown.
 * 6. Call erase for a random non-existent ID and assert that a not found error is thrown.
 */
export async function test_api_discussionboard_test_soft_revoke_admin_assignment_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Register bootstrapping "super-admin" member
  const adminMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. Register a target member
  const normalMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(normalMember);

  // 3. Assign admin privileges
  const now = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: normalMember.id,
      assigned_by_admin_id: adminMember.id, // bootstrapped admin
      assigned_at: now,
      revoked_at: null,
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("member is admin-assigned")(adminAssignment.revoked_at)(null);
  TestValidator.equals("correct member id")(adminAssignment.member_id)(normalMember.id);
  TestValidator.equals("correct assigned_by_admin_id")(adminAssignment.assigned_by_admin_id)(adminMember.id);

  // 4. Soft-revoke (delete) admin assignment
  const revoked = await api.functional.discussionboard.admins.erase(connection, {
    id: adminAssignment.id,
  });
  typia.assert(revoked);
  TestValidator.predicate("revoked_at is set")(!!revoked.revoked_at);
  TestValidator.equals("revoked id matches")(revoked.id)(adminAssignment.id);

  // 5. Idempotency: re-delete (erase) the already revoked assignment
  const revokedAgain = await api.functional.discussionboard.admins.erase(connection, {
    id: adminAssignment.id,
  });
  typia.assert(revokedAgain);
  TestValidator.equals("idempotency: revoked_at unchanged")(revokedAgain.revoked_at)(revoked.revoked_at);
  TestValidator.equals("idempotency: id matches")(revokedAgain.id)(revoked.id);

  // 6. Negative test: non-existent ID revocation
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found error on non-existent admin assignment id")(async () => {
    await api.functional.discussionboard.admins.erase(connection, { id: nonExistentId });
  });
}

