 *
 * Business context:
 * Moderation report types (e.g. 'spam', 'abuse') categorize user/content reports. Their deletion must be admin-restricted, respect referential integrity, and handle logic if types are in use.
 *
 * This E2E test ensures:
 * 1. A newly created report type can be deleted by id using the admin API, and is actually removed (repeat delete results in error).
 * 2. Deleting a random non-existent id gives a not found error.
 * 3. Attempting to delete a report type that is referenced by a report gives a FK constraint/cascading error as per DB policy.
 * 4. Only API-exposed admin context is used, as no user switching/auth APIs are provided.
 *
 * Steps:
 * 1. Create a report type for successful deletion scenario.
 * 2. Delete the report type; confirm it's deleted via repeated delete (get error).
 * 3. Try deleting a random UUID; expect not found error.
 * 4. Create another report type, create a report referencing it, then try to delete the in-use type; expect FK/cascading error.
 */
export async function test_api_discussionboard_test_delete_report_type_valid_not_found_and_foreign_key(
  connection: api.IConnection
) {
  // 1. Create a report type (for deletion)
  const reportTypeToRemove = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphabets(8),
      display_name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(),
      active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(reportTypeToRemove);

  // 2. Delete the report type (should succeed)
  await api.functional.discussionboard.reportTypes.erase(connection, { id: reportTypeToRemove.id });
  // Try deleting again: Should fail (not found)
  await TestValidator.error("Delete already deleted report type should fail")(() =>
    api.functional.discussionboard.reportTypes.erase(connection, { id: reportTypeToRemove.id }),
  );

  // 3. Attempt to delete a random/non-existent id (should fail)
  await TestValidator.error("Delete with non-existent UUID should fail")(() =>
    api.functional.discussionboard.reportTypes.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 4. Create a second report type (to be referenced)
  const reportTypeWithFK = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphabets(8),
      display_name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(),
      active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(reportTypeWithFK);

  // Create a report that references the created type
  const report = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportTypeWithFK.id,
      reporting_member_id: typia.random<string & tags.Format<"uuid">>(),
      target_object_id: typia.random<string & tags.Format<"uuid">>(),
      target_object_type: RandomGenerator.pick(["post", "comment", "member"]),
      report_description: RandomGenerator.paragraph()(1),
      reported_at: new Date().toISOString(),
    },
  });
  typia.assert(report);

  // 5. Attempt to delete referenced type (should fail by FK error/cascading rule)
  await TestValidator.error("FK-referenced report type delete should fail or error as per schema")(() =>
    api.functional.discussionboard.reportTypes.erase(connection, { id: reportTypeWithFK.id }),
  );
}

