import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";
import type { IDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationAction";

/**
 * moderation action 생성 API의 정상 동작 및 유효성 검증
 *
 * 관리자인 acting_moderator 회원, 일반 member, test post(타겟 오브젝트), reportType, 그리고 report 레코드를 모두 준비해 놓은 후 moderation action을 다양한 정상/오류 시나리오로 생성 시도함.
 *
 * 주요 절차:
 * 1. acting_moderator, member, post, reportType, report 등 선행 데이터 모두 생성
 * 2. 정상 - post를 'delete'하는 moderation action(report 연계)
 * 3. 정상 - member(target)에 'ban' moderation action(report 미연계)
 * 4. 정상 - member(target)에 'warn' moderation action(report_id=null)
 * 5. 존재하지 않는 acting_moderator_id, target_object_id, report_id 등으로 잘못 요청시 error 반환 검증
 * 6. 필수 필드 누락시 error 반환 검증
 *
 * business logic상 ban 또는 warn이 member에 올바르게 연결되는지 등도 직접 비교.
 */
export async function test_api_discussionboard_test_create_moderation_action_with_valid_and_invalid_reference_data(
  connection: api.IConnection,
) {
  // 1. acting moderator(관리자 또는 운영자) 생성
  const moderator = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(15),
        role: "admin",
        is_active: true,
      },
    },
  );
  typia.assert(moderator);

  // 2. 일반 멤버 및 테스트 post 생성
  const member = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(15),
        role: "member",
        is_active: true,
      },
    },
  );
  typia.assert(member);

  const post = await api.functional.discussionboard.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.content()(30)(),
        is_deleted: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(post);

  // 3. 신고 유형(reportType) 생성
  const reportType = await api.functional.discussionboard.reportTypes.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        display_name: RandomGenerator.paragraph()(5),
        description: RandomGenerator.paragraph()(10),
        active: true,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(reportType);

  // 4. 신고(report) 생성 (post 대상)
  const report = await api.functional.discussionboard.reports.create(
    connection,
    {
      body: {
        discussionboard_report_type_id: reportType.id,
        reporting_member_id: member.id,
        target_object_id: post.id,
        target_object_type: "post",
        report_description: RandomGenerator.paragraph()(8),
        reported_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(report);

  // 5. moderation action 정상: post 삭제 (report_id 연결)
  const action1 = await api.functional.discussionboard.moderationActions.create(
    connection,
    {
      body: {
        report_id: report.id,
        acting_moderator_id: moderator.id,
        target_object_id: post.id,
        target_object_type: "post",
        action_type: "delete",
        rationale: "불량 게시물 삭제",
        actioned_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(action1);
  TestValidator.equals("report_id")(action1.report_id)(report.id);
  TestValidator.equals("acting_moderator_id")(action1.acting_moderator_id)(moderator.id);
  TestValidator.equals("target_object_id")(action1.target_object_id)(post.id);
  TestValidator.equals("target_object_type")(action1.target_object_type)("post");

  // 6. moderation action 정상: member 대상 ban (report_id 생략)
  const action2 = await api.functional.discussionboard.moderationActions.create(
    connection,
    {
      body: {
        acting_moderator_id: moderator.id,
        target_object_id: member.id,
        target_object_type: "member",
        action_type: "ban",
        rationale: "부적절 행위로 인한 영구 정지",
        actioned_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(action2);
  TestValidator.equals("acting_moderator_id")(action2.acting_moderator_id)(moderator.id);
  TestValidator.equals("target_object_id")(action2.target_object_id)(member.id);
  TestValidator.equals("target_object_type")(action2.target_object_type)("member");

  // 7. moderation action 정상: member(target)에 warn (report_id=null)
  const action3 = await api.functional.discussionboard.moderationActions.create(
    connection,
    {
      body: {
        report_id: null,
        acting_moderator_id: moderator.id,
        target_object_id: member.id,
        target_object_type: "member",
        action_type: "warn",
        rationale: "경고 1회",
        actioned_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(action3);
  TestValidator.equals("report_id")(action3.report_id)(null);

  // 8. 오류: 존재하지 않는 acting_moderator_id 사용
  await TestValidator.error("invalid acting_moderator_id 에러")(() =>
    api.functional.discussionboard.moderationActions.create(connection, {
      body: {
        acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        target_object_id: post.id,
        target_object_type: "post",
        action_type: "delete",
        rationale: "존재하지 않는 acting_moderator_id",
        actioned_at: new Date().toISOString(),
      },
    }),
  );

  // 9. 오류: 존재하지 않는 target_object_id 사용
  await TestValidator.error("invalid target_object_id 에러")(() =>
    api.functional.discussionboard.moderationActions.create(connection, {
      body: {
        acting_moderator_id: moderator.id,
        target_object_id: typia.random<string & tags.Format<"uuid">>(),
        target_object_type: "post",
        action_type: "delete",
        rationale: "존재하지 않는 target_object_id",
        actioned_at: new Date().toISOString(),
      },
    }),
  );

  // 10. 오류: 존재하지 않는 report_id 사용
  await TestValidator.error("invalid report_id 에러")(() =>
    api.functional.discussionboard.moderationActions.create(connection, {
      body: {
        report_id: typia.random<string & tags.Format<"uuid">>(),
        acting_moderator_id: moderator.id,
        target_object_id: post.id,
        target_object_type: "post",
        action_type: "delete",
        rationale: "존재하지 않는 report_id",
        actioned_at: new Date().toISOString(),
      },
    }),
  );

  // 11. 오류: 필수 필드 누락 (acting_moderator_id 누락)
  await TestValidator.error("필수 필드 누락 - acting_moderator_id")(() =>
    api.functional.discussionboard.moderationActions.create(connection, {
      body: {
        target_object_id: post.id,
        target_object_type: "post",
        action_type: "delete",
        rationale: "acting_moderator_id 누락",
        actioned_at: new Date().toISOString(),
      } as any,
    }),
  );
}

