/**
 * Test rejection of duplicate setting key updates.
 *
 * This case ensures the system enforces unique constraints on settings keys:
 * 1. Create the first unique setting (A).
 * 2. Create the second unique setting (B) with a different key.
 * 3. Attempt to update A's key to B's value (duplicate) via update API.
 * 4. Confirm unique constraint violation is raised and update fails.
 *
 * This validates that the backend correctly rejects attempts to assign a key already present in another settings row.
 */
export async function test_api_discussionboard_settings_test_update_setting_key_to_duplicate_value(
  connection: api.IConnection,
) {
  // 1. Create the first unique setting (A)
  const keyA = `unique_key_${RandomGenerator.alphaNumeric(8)}`;
  const createAInput: Idiscussionboard_settings.ICreate = {
    scope_type: "feature_flag",
    key: keyA,
    value: RandomGenerator.alphaNumeric(10),
    description: "First unique setting for duplicate key rejection test.",
  };
  const settingA = await api.functional.discussionboard.settings.create(connection, { body: createAInput });
  typia.assert(settingA);

  // 2. Create the second unique setting (B) with a different key
  const keyB = `other_key_${RandomGenerator.alphaNumeric(8)}`;
  const createBInput: Idiscussionboard_settings.ICreate = {
    scope_type: "feature_flag",
    key: keyB,
    value: RandomGenerator.alphaNumeric(10),
    description: "Second unique setting for duplicate key rejection test.",
  };
  const settingB = await api.functional.discussionboard.settings.create(connection, { body: createBInput });
  typia.assert(settingB);

  // 3. Attempt to update A's key to B's key – should fail on unique constraint
  const updateToDuplicateKey: Idiscussionboard_settings.IUpdate = {
    scope_type: settingA.scope_type,
    key: settingB.key, // duplicate key intentionally
    value: settingA.value ?? null,
    description: settingA.description ?? null,
    scope_id: settingA.scope_id ?? null,
  };
  await TestValidator.error("Updating setting key to a duplicate must fail")(() =>
    api.functional.discussionboard.settings.update(connection, {
      id: settingA.id,
      body: updateToDuplicateKey,
    })
  );
}

