import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Permanently deletes a ban record by its unique identifier and verifies correct handling of both successful and failure scenarios.
 *
 * This test validates that:
 * - Deleting an existing ban by id works for moderator/admin users.
 * - Attempting to delete a non-existent or already deleted ban returns a not-found error.
 * - Only users with moderator/admin role can delete bans.
 * - Once deleted, the ban record cannot be retrieved (enforces irreversible deletion).
 *
 * Step-by-step process:
 * 1. Create a normal member (to later be banned).
 * 2. Create a moderator member (to authorize ban management).
 * 3. Moderator creates a permanent ban for the member.
 * 4. Moderator deletes the ban using its id.
 * 5. Attempt to delete the same ban again and expect not-found error.
 * 6. Attempt to delete a randomly generated, never-existing id and expect not-found error.
 * 7. (If retrieval endpoint is available:) Attempt to fetch the deleted ban should result in not-found error.
 * 8. (If domain supports permissions:) Test that normal members cannot delete bans (permission denied).
 */
export async function test_api_discussionboard_test_delete_ban_by_id_and_handle_not_found(
  connection: api.IConnection,
) {
  // Step 1: Create the normal member who will be banned
  const bannedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(bannedMember);

  // Step 2: Create the moderator
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(moderator);

  // Step 3: Moderator creates a permanent ban for the member
  const ban = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: bannedMember.id,
      acting_moderator_id: moderator.id,
      reason: "Test permanent ban deletion",
      ban_type: "permanent",
      banned_at: new Date().toISOString(),
      expires_at: null,
    },
  });
  typia.assert(ban);

  // Step 4: Moderator deletes the ban
  await api.functional.discussionboard.bans.erase(connection, { id: ban.id });

  // Step 5: Attempt to delete the same ban again - expect not-found error
  await TestValidator.error("Deleting already-deleted ban should return not found")(
    () => api.functional.discussionboard.bans.erase(connection, { id: ban.id })
  );

  // Step 6: Attempt to delete a never-existing ban id
  const nonExistingId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Deleting non-existent ban should return not found")(
    () => api.functional.discussionboard.bans.erase(connection, { id: nonExistingId })
  );

  // Step 7: [Not implemented - requires retrieval endpoint]

  // Step 8: [Not implemented - requires lower-privilege role session switch]
}

