import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReport";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * Test the creation of warning records (moderation warnings) for discussion board members,
 * including both valid and invalid scenarios and escalation constraints.
 *
 * Business Context:
 * Moderators or admins can issue warning records to members for policy violations, often referencing
 * a report (post report) as the cause. Schema and backend logic may enforce escalation for repeated
 * warnings (e.g., after three: ban/escalation logic). This test validates both the nominal flow and
 * various failure modes.
 *
 * Steps:
 * 1. Create a new regular member (to be warned).
 * 2. Create a new moderator member (who will issue the warning).
 * 3. Create a post report (some infraction to associate with the warning).
 * 4. Issue a warning with all required fields and a valid report_id (nominal case).
 * 5. Attempt to create a warning for a non-existent member (should fail/throw).
 * 6. Try to create a warning with an invalid report_id or missing required fields and check for validation errors.
 * 7. Issue multiple warnings to the same member (valid massive insertions), then confirm that if business logic
 *    enforces escalation on >=3 warnings, this rule is triggered or the insert is allowed.
 * 8. Attempt to create a duplicate/conflicting warning if backend checks for logical constraint duplicates; validate response.
 */
export async function test_api_discussionboard_test_create_warning_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create a member to be warned
  const warnedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(warnedMember);

  // 2. Create a moderator
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "moderator",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(moderator);

  // 3. Create a report (and an unrelated non-existent report_id)
  const report = await api.functional.discussionboard.postReports.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      reporter_member_id: moderator.id,
      report_type_id: typia.random<string & tags.Format<"uuid">>(),
      description: "Spam post detected",
      created_at: new Date().toISOString(),
    } satisfies IPostReport.ICreate,
  });
  typia.assert(report);

  // 4. Issue a valid warning
  const warning = await api.functional.discussionboard.warnings.create(connection, {
    body: {
      warned_member_id: warnedMember.id,
      acting_moderator_id: moderator.id,
      report_id: report.id,
      reason: "Violation of posting rules",
      warned_at: new Date().toISOString(),
    } satisfies IDiscussionboardWarning.ICreate,
  });
  typia.assert(warning);
  TestValidator.equals("warned member id matches")(warning.warned_member_id)(warnedMember.id);
  TestValidator.equals("acting moderator id matches")(warning.acting_moderator_id)(moderator.id);
  TestValidator.equals("reason matches")(warning.reason)("Violation of posting rules");

  // 5. Issue a warning with a non-existent member id (should fail)
  await TestValidator.error("warning creation fails for non-existent member")(() =>
    api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: typia.random<string & tags.Format<"uuid">>(), // assume non-existent
        acting_moderator_id: moderator.id,
        report_id: report.id,
        reason: "Non-existent warned member",
        warned_at: new Date().toISOString(),
      } satisfies IDiscussionboardWarning.ICreate,
    })
  );

  // 6. Invalid report_id (should fail) & missing required fields
  await TestValidator.error("warning creation fails for invalid report_id")(() =>
    api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: warnedMember.id,
        acting_moderator_id: moderator.id,
        report_id: typia.random<string & tags.Format<"uuid">>(), // assume invalid
        reason: "Invalid report",
        warned_at: new Date().toISOString(),
      } satisfies IDiscussionboardWarning.ICreate,
    })
  );

  await TestValidator.error("warning creation fails for missing required fields")(() =>
    api.functional.discussionboard.warnings.create(connection, {
      body: {
        // missing warned_member_id, acting_moderator_id, reason entirely
        report_id: report.id,
        warned_at: new Date().toISOString(),
      } as any, // deliberately incomplete, for error branch only
    })
  );

  // 7. Issue multiple warnings; if system enforces escalation/check for >3 warnings
  for (let i = 0; i < 3; ++i) {
    const extraWarning = await api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: warnedMember.id,
        acting_moderator_id: moderator.id,
        reason: `Repeated infraction #${i+1}`,
        warned_at: new Date(Date.now() + i * 60000).toISOString(),
      } satisfies IDiscussionboardWarning.ICreate,
    });
    typia.assert(extraWarning);
  }

  // Attempt a 4th warning to see if any escalation/ban logic applies (system-conditional)
  await TestValidator.error("warning business rule triggers on 4th warning or insert succeeds")(() =>
    api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: warnedMember.id,
        acting_moderator_id: moderator.id,
        reason: "Fourth warning/should escalate",
        warned_at: new Date(Date.now() + 4 * 60000).toISOString(),
      } satisfies IDiscussionboardWarning.ICreate,
    })
  );

  // 8. Attempt duplicate/conflicting warning (duplicate reason and warned_at)
  await TestValidator.error("duplicate/conflicting warning record creation should fail if uniqueness constraint exists")(() =>
    api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: warnedMember.id,
        acting_moderator_id: moderator.id,
        reason: "Violation of posting rules",
        warned_at: warning.warned_at,
      } satisfies IDiscussionboardWarning.ICreate,
    })
  );
}

