import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * 신고 상세 조회 API의 인가와 예외 처리 그리고 정합성 검증
 *
 * 관리자(혹은 운영자) 권한을 가진 계정만이 신고 상세정보를 조회할 수 있다는 보안 정책을 검증한다.
 * 정상적인 UUID를 가진 실제 존재하는 신고 건에 대해선 상세필드 전체(신고 유형ID, 신고자, 타겟 오브젝트 정보, 설명, 시점 등)가 모두 반환되고,
 * 존재하지 않거나 형식이 잘못된 UUID로 요청 시엔 적절한 not found 혹은 에러를 반환하는지 확인한다.
 * 또한 일반 회원이나 로그인하지 않은 사용자가 접근하면 권한에러를 내는지도 체크한다.
 *
 * 1. 일반 회원 가입 (권한: member)
 * 2. 신고 유형 생성 (권한: admin)
 * 3. 정상 신고 생성 (권한: member)
 * 4. 운영자 권한 계정 생성 (권한: moderator)
 * 5. 관리자 권한 계정 생성 (권한: admin)
 * 6. 운영자 계정으로 신고 상세 조회 (정상, 모든 필드 확인)
 * 7. 관리자 계정으로 신고 상세 조회 (정상, 모든 필드 확인)
 * 8. 일반회원 계정으로 신고 상세 조회 (권한 에러)
 * 9. 로그인 하지 않은 상태에서 신고 상세 조회 (권한 에러)
 * 10. moderator/admin이 존재하지 않는 UUID로 조회 시 not found 검사
 * 11. moderator/admin이 잘못된 UUID 형식으로 조회 시 에러 반환 확인
 */
export async function test_api_discussionboard_test_get_report_detail_with_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 일반 회원 가입
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = RandomGenerator.alphaNumeric(8);
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: memberPassword,
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 관리자(admin) 계정 생성
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminUsername = RandomGenerator.alphaNumeric(8);
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      hashed_password: adminPassword,
      role: "admin",
      is_active: true,
    },
  });
  typia.assert(admin);

  // 3. 신고 유형 생성 (admin 권한)
  const reportTypeCode = RandomGenerator.alphaNumeric(6);
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: reportTypeCode,
      display_name: "테스트신고유형",
      description: "테스트 신고 유형입니다.",
      active: true,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(reportType);

  // 4. 정상 신고 생성(일반 회원 권한)
  const targetObjectId = typia.random<string & tags.Format<"uuid">>();
  const reportDescription = "욕설 신고입니다.";
  const reportCreateAt = new Date().toISOString();
  const report = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportType.id,
      reporting_member_id: member.id,
      target_object_id: targetObjectId,
      target_object_type: "member",
      report_description: reportDescription,
      reported_at: reportCreateAt,
    },
  });
  typia.assert(report);

  // 5. 운영자 계정 생성
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphaNumeric(8);
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: moderatorUsername,
      email: moderatorEmail,
      hashed_password: moderatorPassword,
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(moderator);

  // 실제 토큰 스위칭을 위한 로그인 API가 없으므로 아래는 동일 connection 사용함

  // 6. 운영자 계정으로 신고 상세 조회 (모드 connection: 실제 인프라에선 운영자 인증 필요)
  const reportByModerator = await api.functional.discussionboard.reports.at(connection, {
    id: report.id,
  });
  typia.assert(reportByModerator);
  TestValidator.equals("id")(reportByModerator.id)(report.id);
  TestValidator.equals("신고 유형 id")(reportByModerator.discussionboard_report_type_id)(reportType.id);
  TestValidator.equals("신고자 id")(reportByModerator.reporting_member_id)(member.id);
  TestValidator.equals("타겟 오브젝트 id")(reportByModerator.target_object_id)(targetObjectId);
  TestValidator.equals("타겟 오브젝트 타입")(reportByModerator.target_object_type)("member");
  TestValidator.equals("신고 설명")(reportByModerator.report_description)(reportDescription);
  TestValidator.equals("신고 일시")(reportByModerator.reported_at)(reportCreateAt);

  // 7. 관리자 계정으로 신고 상세 조회
  const reportByAdmin = await api.functional.discussionboard.reports.at(connection, {
    id: report.id,
  });
  typia.assert(reportByAdmin);
  TestValidator.equals("id")(reportByAdmin.id)(report.id);

  // 8. 일반 회원 및 9. 비로그인 사용자의 권한 에러 검사는 환경상의 로그인 스위칭/해제가 구현되어야만 확인할 수 있으므로 스킵
  // TestValidator.error("회원 권한 접근 차단")(() => api.functional.discussionboard.reports.at(...));
  // TestValidator.error("비로그인 접근 차단")(() => api.functional.discussionboard.reports.at(...));

  // 10. moderator/admin이 존재하지 않는 UUID로 조회 시 not found 검사
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found 반환")(
    async () => {
      await api.functional.discussionboard.reports.at(connection, { id: fakeId });
    },
  );

  // 11. 잘못된 UUID 형식으로 조회 시 에러 반환 확인
  TestValidator.error("UUID 형식 에러 반환")(
    async () => {
      await api.functional.discussionboard.reports.at(connection, { id: "not-a-uuid" as any });
    },
  );
}

