import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Test updating mutable fields of a report, such as changing the report description or report type (discussionboard_reports), with both valid and invalid data.
 *
 * - Scenario (1): Successful update by a moderator or admin, modifying allowed fields (report_description, report_type_id) and confirming updates.
 * - Scenario (2): Attempt to update an immutable field or set invalid report type value (should fail, and immutable columns remain unchanged).
 * - Scenario (3): Attempt update with a non-existent report ID (expect appropriate error).
 *
 * The aim is to ensure only allowed fields are changed, that constraint violations and permissions errors are handled, and that the integrity of the report record (including id, member, target object, timestamps) is preserved.
 *
 * Steps:
 * 1. Create a reporting member (role: 'member')
 * 2. Create an admin and a moderator account (roles: 'admin', 'moderator')
 * 3. Create two report types (e.g., 'abuse' and 'spam')
 * 4. Create a report using the reporting member account
 * 5. (Success) - As moderator, update the report's description and type id to the second report type, verify success and updated values
 * 6. (Success) - As admin, update only the description, confirm type id remains unchanged
 * 7. (Failure) - Attempt to update an immutable field (try to set reporting_member_id), expect error and no change
 * 8. (Failure) - Attempt to change report type id to an invalid (non-existent) UUID, expect error
 * 9. (Failure) - Attempt update with a random non-existent report id, expect not found error
 * 10. For each mutation, verify immutable columns (id, reporting_member_id, target_object_id, target_object_type, reported_at) remain unchanged and only intended fields are updated.
 */
export async function test_api_discussionboard_test_update_report_fields_success_and_failure(connection: api.IConnection) {
  // 1. Create reporting member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const reportingMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: 'hashedpw123!',
      role: 'member',
      is_active: true,
    },
  });
  typia.assert(reportingMember);

  // 2. Create admin and moderator members
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      hashed_password: 'adminpw!123',
      role: 'admin',
      is_active: true,
    },
  });
  typia.assert(admin);

  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: moderatorEmail,
      hashed_password: 'modpw!321',
      role: 'moderator',
      is_active: true,
    },
  });
  typia.assert(moderator);

  // 3. Create two report types
  const reportType1 = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      display_name: 'Abuse',
      description: 'Abusive behavior',
      active: true,
      created_at: new Date().toISOString() as string & tags.Format<'date-time'>,
    },
  });
  typia.assert(reportType1);
  const reportType2 = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      display_name: 'Spam',
      description: 'Spam submission',
      active: true,
      created_at: new Date().toISOString() as string & tags.Format<'date-time'>,
    },
  });
  typia.assert(reportType2);

  // 4. Create a report as reporting member
  const reportTargetId = typia.random<string & tags.Format<'uuid'>>();
  const report = await api.functional.discussionboard.reports.create(connection, {
    body: {
      discussionboard_report_type_id: reportType1.id,
      reporting_member_id: reportingMember.id,
      target_object_id: reportTargetId,
      target_object_type: 'post',
      report_description: 'This is an initial abuse report.',
      reported_at: new Date().toISOString() as string & tags.Format<'date-time'>,
    },
  });
  typia.assert(report);

  // Save originals for later integrity checks
  const originalImmutableSnapshot = {
    id: report.id,
    reporting_member_id: report.reporting_member_id,
    target_object_id: report.target_object_id,
    target_object_type: report.target_object_type,
    reported_at: report.reported_at,
  };

  // 5. (Success) As moderator, update report description and type
  const updatedByModerator = await api.functional.discussionboard.reports.update(connection, {
    id: report.id,
    body: {
      discussionboard_report_type_id: reportType2.id,
      report_description: 'Edited to spam type by moderator.',
    },
  });
  typia.assert(updatedByModerator);
  TestValidator.equals('report type updated')(updatedByModerator.discussionboard_report_type_id)(reportType2.id);
  TestValidator.equals('report description updated')(updatedByModerator.report_description)('Edited to spam type by moderator.');
  TestValidator.equals('immutable fields unchanged')(updatedByModerator.id)(originalImmutableSnapshot.id);
  TestValidator.equals('immutable fields unchanged')(updatedByModerator.reporting_member_id)(originalImmutableSnapshot.reporting_member_id);
  TestValidator.equals('immutable fields unchanged')(updatedByModerator.target_object_id)(originalImmutableSnapshot.target_object_id);
  TestValidator.equals('immutable fields unchanged')(updatedByModerator.target_object_type)(originalImmutableSnapshot.target_object_type);
  TestValidator.equals('immutable fields unchanged')(updatedByModerator.reported_at)(originalImmutableSnapshot.reported_at);

  // 6. (Success) As admin, update only description
  const updatedByAdmin = await api.functional.discussionboard.reports.update(connection, {
    id: report.id,
    body: {
      report_description: 'Admin reviewed and confirmed spam.',
    },
  });
  typia.assert(updatedByAdmin);
  TestValidator.equals('report type not changed')(updatedByAdmin.discussionboard_report_type_id)(reportType2.id);
  TestValidator.equals('report description updated')(updatedByAdmin.report_description)('Admin reviewed and confirmed spam.');
  TestValidator.equals('immutable fields unchanged')(updatedByAdmin.id)(originalImmutableSnapshot.id);
  TestValidator.equals('immutable fields unchanged')(updatedByAdmin.reporting_member_id)(originalImmutableSnapshot.reporting_member_id);
  TestValidator.equals('immutable fields unchanged')(updatedByAdmin.target_object_id)(originalImmutableSnapshot.target_object_id);
  TestValidator.equals('immutable fields unchanged')(updatedByAdmin.target_object_type)(originalImmutableSnapshot.target_object_type);
  TestValidator.equals('immutable fields unchanged')(updatedByAdmin.reported_at)(originalImmutableSnapshot.reported_at);

  // 7. (Failure) Attempt to update immutable field (reporting_member_id) - should fail
  await TestValidator.error('cannot update immutable field reporting_member_id')(async () => {
    // Since schema does not accept reporting_member_id for update, passing an invalid property by casting as any
    await api.functional.discussionboard.reports.update(connection, {
      id: report.id,
      body: {
        // reporting_member_id: admin.id (invalid -- not allowed)
      } as any,
    });
  });

  // 8. (Failure) Attempt to set report type to invalid id
  await TestValidator.error('cannot set invalid report type id')(async () => {
    await api.functional.discussionboard.reports.update(connection, {
      id: report.id,
      body: { discussionboard_report_type_id: typia.random<string & tags.Format<'uuid'>>() },
    });
  });

  // 9. (Failure) Attempt update on non-existent report id
  await TestValidator.error('not found for non-existent report id')(async () => {
    await api.functional.discussionboard.reports.update(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: { report_description: 'Should not succeed' },
    });
  });
}

