import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Test permanent deletion (hard delete) of a moderation report, verifying correct access control, operation irreversibility, and error handling for invalid/non-existent IDs and insufficient permissions.
 *
 * This workflow covers:
 *   1. Create a regular member, and a moderator or admin member
 *   2. Create a report type
 *   3. Create a moderation report
 *   4. Moderator/admin deletes (hard) the report
 *   5. Confirm the report no longer exists (cannot GET/PUT it; deletion is irreversible; no soft delete)
 *   6. Attempt deletion with invalid/non-existent report ID and expect an error
 *   7. Attempt deletion with insufficiently privileged user (regular member) and expect an access denied error
 *   8. Attempt deletion with unauthenticated (no user) and expect an access denied error
 *
 * All steps must ensure proper business enforcement and confirm that only users with 'moderator' or 'admin' role can hard-delete reports. Deletion removes the record permanently.
 */
export async function test_api_discussionboard_test_delete_report_with_valid_and_invalid_id_and_access_control(connection: api.IConnection) {
  // 1. Create regular member
  const memberRegular = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true
    }
  });
  typia.assert(memberRegular);

  // 2. Create moderator member
  const memberModerator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "moderator",
      is_active: true
    }
  });
  typia.assert(memberModerator);

  // 3. Create report type
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      display_name: "Test Report Type",
      description: "Test Type for hard delete report",
      active: true,
      created_at: new Date().toISOString()
    }
  });
