 * 3. Fetch the comment by its id using the /discussionboard/comments/{id} endpoint.
 * 4. Assert that the returned comment matches the data of the created comment and contains all schema fields, with deleted_at being null or undefined (not soft deleted).
 */
export async function test_api_discussionboard_test_get_comment_by_id_when_not_deleted(
  connection: api.IConnection,
) {
  // 1. Create a discussion board post
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    is_deleted: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 2. Create a comment for the post
  const commentInput: IComment.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: post.discussionboard_member_id,
    body: RandomGenerator.paragraph()(),
  };
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: commentInput,
  });
  typia.assert(comment);

  // Confirm the comment is not soft deleted
  TestValidator.equals("deleted_at should be null or undefined")(comment.deleted_at == null)(true);

  // 3. Fetch the comment by its id
  const fetched = await api.functional.discussionboard.comments.at(connection, {
    id: comment.id,
  });
  typia.assert(fetched);

  // 4. Assert the fetched comment matches key fields of the created comment
