import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Test creation of a comment snapshot after editing a comment.
 *
 * This test simulates a realistic audit/moderation/history tracking scenario in the discussionboard domain:
 *
 * - A member creates a discussion post
 * - The same member comments on it
 * - The comment is updated (edited)
 * - A snapshot is created, capturing the comment's precise state at snapshot time
 * - The snapshot record is validated to match the comment's properties and metadata at snapshot creation
 *
 * This verifies that the snapshot accurately reflects the edited comment, supporting historical versioning use cases.
 *
 * Steps:
 * 1. Create a post
 * 2. Create a comment under the post
 * 3. Update the comment body
 * 4. Create a snapshot of the updated comment (version 2)
 * 5. Assert that the snapshot accurately stores all key metadata and content fields from the updated comment
 */
export async function test_api_discussionboard_test_create_comment_snapshot_on_edit(
  connection: api.IConnection,
) {
  // Step 1: Create a post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(5),
      body: RandomGenerator.content()(2)(3),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // Step 2: Create a comment for this post
  const memberId = post.discussionboard_member_id;
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberId,
      body: RandomGenerator.paragraph()(2),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // Step 3: Update the comment body
  const editedBody = RandomGenerator.paragraph()(2);
  const updated = await api.functional.discussionboard.comments.update(connection, {
    id: comment.id,
    body: {
      body: editedBody,
    } satisfies IComment.IUpdate,
  });
  typia.assert(updated);

  // Step 4: Create a snapshot of the updated comment (version 2, snapshot time = now)
  const version = 2;
  const snapshotTime = new Date().toISOString();
  const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: {
      discussionboard_comment_id: updated.id,
      discussionboard_member_id: updated.discussionboard_member_id,
      discussionboard_post_id: updated.discussionboard_post_id,
      body: updated.body,
      version,
      snapshot_created_at: snapshotTime,
    } satisfies IDiscussionboardCommentSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // Step 5: Assert that snapshot accurately reflects the comment at snapshot time
  TestValidator.equals("snapshot comment id")(snapshot.discussionboard_comment_id)(updated.id);
  TestValidator.equals("snapshot member id")(snapshot.discussionboard_member_id)(updated.discussionboard_member_id);
  TestValidator.equals("snapshot post id")(snapshot.discussionboard_post_id)(updated.discussionboard_post_id);
  TestValidator.equals("snapshot body")(snapshot.body)(updated.body);
  TestValidator.equals("snapshot version")(snapshot.version)(version);
}

