/**
 * Test the normal registration workflow for a new member in the discussion board system.
 *
 * Steps:
 * 1. Generate unique username and email.
 * 2. Attempt to register the member using all valid required fields: username, email, hashed_password, role, and is_active=true.
 * 3. Verify system creates the member:
 *    - Response includes generated id, created_at, updated_at (auto-populated by backend)
 *    - Response omits registration-time-sensitive fields (such as hashed_password)
 *    - id must be a valid UUID, email must match the requested email, role is strictly one of the allowed enums ("member", "moderator", "admin")
 *    - is_active should match the supplied value
 *    - deleted_at should be omitted or null
 * 4. Attempt to register another member using same username or email and verify unique constraints (error thrown).
 * 5. Try to register by supplying forbidden response fields (id, created_at, updated_at), ensure these are rejected or ignored.
 */
export async function test_api_discussionboard_test_create_member_with_unique_credentials_and_valid_role(connection: api.IConnection) {
  // Step 1: Generate unique credentials
  const username = RandomGenerator.alphabets(10);
  const email = typia.random<string & tags.Format<"email">>();
  const hashed_password = RandomGenerator.alphaNumeric(32);
  const role: "member" | "moderator" | "admin" = RandomGenerator.pick(["member", "moderator", "admin"]);
  const is_active = true;

  // Step 2: Register new member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username,
      email,
      hashed_password,
      role,
      is_active,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // Step 3: Validate response fields
  TestValidator.predicate("id must be UUID")(typeof member.id === "string" && member.id.length > 0);
  TestValidator.equals("username matches")(member.username)(username);
  TestValidator.equals("email matches")(member.email)(email);
  TestValidator.equals("role allowed")(member.role)(role);
  TestValidator.equals("is_active matches")(member.is_active)(is_active);
  TestValidator.predicate("created_at exists")(typeof member.created_at === "string");
  TestValidator.predicate("updated_at exists")(typeof member.updated_at === "string");
  TestValidator.predicate("hashed_password not leaked")(typeof (member as any).hashed_password === "undefined");
  TestValidator.predicate("deleted_at is undefined or null")(typeof member.deleted_at === "undefined" || member.deleted_at === null);

  // Step 4: Attempt to register duplicate user (should fail)
  await TestValidator.error("duplicate username/email")(async () => {
    await api.functional.discussionboard.members.create(connection, {
      body: {
        username,
        email,
        hashed_password: RandomGenerator.alphaNumeric(32),
        role,
        is_active,
      } satisfies IDiscussionboardMember.ICreate,
    });
  });

  // Step 5: Attempt to submit forbidden auto-generated fields (should fail)
  await TestValidator.error("auto fields forbidden")(async () => {
    await api.functional.discussionboard.members.create(connection, {
      body: Object.assign({
        username: RandomGenerator.alphabets(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        role,
        is_active,
      }, {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }) as any,
    });
  });
}

