 * /discussionboard/members 엔드포인트에 회원 가입 요청 데이터를 보낼 때,
 * 필수 필드(username, email, hashed_password, role, is_active) 중 하나라도
 * 누락하면 API가 적절히 거부하며, 실제 회원 레코드가 생성되지 않아야 함을 검증합니다.
 *
 * 각 필드를 한 번씩 누락하여 회원 생성 시도를 반복하며, 다음을 검증합니다:
 * 1. API 요청이 유효성 검증 오류로 실패하여 예외를 반환한다.
 * 2. 실제 회원 레코드는 생성되지 않는다(단, 본 테스트는 오류 발생만 검증하고, 오류 메시지나 DB 후속조회는 수행하지 않는다).
 *
 * TypeScript의 타입 검증상, 필수값 누락 객체를 SDK에 직접 전달할 수 없어, 본 테스트 루프 범위 내에서만 `as any`
 * 캐스팅을 사용하여 런타임에서 필드 누락 케이스를 검증합니다. (실제 프로덕션 코드에서는 절대 사용 불가)
 */
export async function test_api_discussionboard_test_create_member_without_required_fields(
  connection: api.IConnection,
) {
  // 완전한 등록 정보 객체 정의
  const validInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  };

  // 특정 필드만 제거하는 보조 함수
  const omit = <T extends object, K extends keyof T>(obj: T, key: K): Omit<T, K> => {
    const clone = { ...obj };
    delete clone[key];
    return clone as Omit<T, K>;
  };

  // 필수 필드 목록
  const requiredFields: (keyof IDiscussionboardMember.ICreate)[] = [
    "username",
    "email",
    "hashed_password",
    "role",
    "is_active",
  ];

  for (const field of requiredFields) {
    // 필수 필드 1개씩 누락한 입력 생성
    const invalidInput = omit(validInput, field);
    await TestValidator.error(`필수 필드 누락: ${field}`)(async () => {
      // (타입강제 해제, 오직 런타임 유효성 오류 검증용 - 절대 본래 사용 금지)
      await api.functional.discussionboard.members.create(connection, {
        body: invalidInput as any,
      });
    });
  }
}

