import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMember";

/**
 * 회원 목록(검색) API에 대해 username, email을 복합조건으로 필터링하여 검색 결과의 정확성을 검증합니다.
 *
 * - 최소 1명의 회원을 미리 회원가입 API로 생성하여, 테스트 시 해당 회원이 반드시 검색에 노출되도록 함
 * - username, email 중복 조건 모두 만족하는 멤버만 응답되는지 확인
 * - 페이징(page/limit) 및 전체 데이터 개수(pagination 메타데이터) 검증
 * - 정확히 일치 조건(=)이 각 필드에서 제대로 동작하는지 검증
 * - 존재하지 않는 username 또는 email로 검색 시 결과가 0건임을 확인
 */
export async function test_api_discussionboard_test_search_members_by_username_and_email(
  connection: api.IConnection,
) {
  // 1. 테스트 회원 사전 등록
  const username = RandomGenerator.alphaNumeric(8);
  const email = `${username}@example.com`;
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username,
      email,
      hashed_password: RandomGenerator.alphaNumeric(24),
      role: RandomGenerator.pick(["member", "moderator", "admin"]),
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. username + email 복합 조건 검색
  const pageResp = await api.functional.discussionboard.members.index(connection, {
    body: {
      username,
      email,
      pagination: {
        page: 1,
        limit: 10,
      },
    },
  });
  typia.assert(pageResp);

  // 2-1. 데이터가 1건이고, 방금 생성한 회원만 응답인지 체크
  TestValidator.equals("검색 데이터 1건")(pageResp.data.length)(1);
  TestValidator.equals("username 일치")(pageResp.data[0].username)(username);
  TestValidator.equals("email 일치")(pageResp.data[0].email)(email);

  // 2-2. pagination 메타 확인
  TestValidator.equals("current page 1")(pageResp.pagination.current)(1);
  TestValidator.equals("limit 10")(pageResp.pagination.limit)(10);
  TestValidator.equals("records 1")(pageResp.pagination.records)(1);
  TestValidator.equals("pages 1")(pageResp.pagination.pages)(1);

  // 3. 존재하지 않는 조합으로 검색 (0건)
  const failResp = await api.functional.discussionboard.members.index(connection, {
    body: {
      username: "notexistuser",
      email: "nobody999@example.com",
      pagination: {
        page: 1,
        limit: 10,
      },
    },
  });
  typia.assert(failResp);
  TestValidator.equals("0건")(failResp.data.length)(0);
  TestValidator.equals("pagination.records=0")(failResp.pagination.records)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMember";

/**
 * Verify correct role-based filtering of discussion board members.
 *
 * This E2E test ensures that searching for members by a specific role returns only those members,
 * and excludes all others. It proves correct back-end implementation of the role filter, covering:
 *
 * 1. Creation of multiple members with each of the possible roles ("member", "moderator", "admin")
 * 2. Searching with a filter for a chosen role (e.g., "moderator")
 * 3. Verification that only members with the requested role are present in the search results
 * 4. Confirmation that no other members with other roles are included
 * 5. All members of the filtered role that were created are present
 */
export async function test_api_discussionboard_test_search_members_with_role_filter(
  connection: api.IConnection,
) {
  // 1. Create members with all valid roles (each role at least twice for coverage)
  const roles: ("member" | "moderator" | "admin")[] = ["member", "moderator", "admin"];
  const createdMembers: IDiscussionboardMember[] = [];
  for (const role of roles) {
    // For each role, generate two members
    for (let i = 0; i < 2; ++i) {
      const username = RandomGenerator.alphaNumeric(8) + `_${role}_${i}`;
      const email = `${username}@example.com` as string & tags.Format<"email">;
      const member = await api.functional.discussionboard.members.create(connection, {
        body: {
          username,
          email,
          hashed_password: RandomGenerator.alphaNumeric(16),
          role,
          is_active: true,
        } satisfies IDiscussionboardMember.ICreate,
      });
      typia.assert(member);
      createdMembers.push(member);
    }
  }

  // 2. Choose a target role to search/filter on ("moderator")
  const targetRole: "member" | "moderator" | "admin" = "moderator";
  const expectedMembers = createdMembers.filter((m) => m.role === targetRole);

  // 3. Query members using role filter
  const response = await api.functional.discussionboard.members.index(connection, {
    body: {
      role: targetRole,
      pagination: {
        page: 1,
        limit: 100,
      },
    } satisfies IDiscussionboardMember.IRequest,
  });
  typia.assert(response);

  // 4. Assert all results have ONLY the requested role
  for (const member of response.data) {
    TestValidator.equals("role matches filter")(member.role)(targetRole);
  }

  // 5. Assert that all created members with the filtered role are present
  for (const created of expectedMembers) {
    TestValidator.predicate("expected member is in result")(
      response.data.some((found) => found.id === created.id),
    );
  }

  // 6. Assert that no members with other roles are present
  for (const member of response.data) {
    TestValidator.predicate("no unwanted roles")(
      member.role === targetRole,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMember";

/**
 * 회원 가입일자(created_at) 기준 범위 쿼리 테스트
 *
 * - 서로 다른 시각에 회원 2명을 등록
 * - 가입 시각을 기준으로 created_at_from/created_at_to 필터를 조합하여 호출
 * - 각 범위 조합별로 필터 대상 회원이 정확히 도출되는지 검증
 * - pagination 옵션 전달 시 반환건수/limit 일치 여부 확인
 * - 반환된 data의 모든 member의 created_at 값이 쿼리 범위 내임을 체크
 */
export async function test_api_discussionboard_test_search_members_by_date_range(
  connection: api.IConnection,
) {
  // 1. 서로 다른 가입 시각의 회원 2명 생성 (가입 시차 2초)
  const usernameA = RandomGenerator.alphabets(8);
  const emailA = typia.random<string & tags.Format<"email">>();
  const timeBefore = new Date(Date.now() - 2000).toISOString();
  const memberA = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: usernameA,
      email: emailA,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberA);

  await new Promise((resolve) => setTimeout(resolve, 1200)); // 1.2초 대기

  const usernameB = RandomGenerator.alphabets(8);
  const emailB = typia.random<string & tags.Format<"email">>();
  const timeAfter = new Date().toISOString();
  const memberB = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: usernameB,
      email: emailB,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberB);

  // 2. 전체 created_at 범위에서 모두 반환되는지
  const resultAll = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: timeBefore,
      created_at_to: timeAfter,
    },
  });
  typia.assert(resultAll);
  TestValidator.predicate("memberA/B 모두 포함됨")(
    resultAll.data.some((m) => m.id === memberA.id) &&
      resultAll.data.some((m) => m.id === memberB.id),
  );
  for (const m of resultAll.data) {
    TestValidator.predicate("created_at 쿼리 만족")(
      m.created_at >= timeBefore && m.created_at <= timeAfter,
    );
  }

  // 3. from~to: memberA 가입시각 단일 조회
  const resultA = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: memberA.created_at,
      created_at_to: memberA.created_at,
    },
  });
  typia.assert(resultA);
  TestValidator.predicate("memberA만 반환")(
    resultA.data.length === 1 && resultA.data[0].id === memberA.id,
  );

  // 4. from~to: memberB 가입시각 단일 조회
  const resultB = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: memberB.created_at,
      created_at_to: memberB.created_at,
    },
  });
  typia.assert(resultB);
  TestValidator.predicate("memberB만 반환")(
    resultB.data.length === 1 && resultB.data[0].id === memberB.id,
  );

  // 5. pagination: page=1, limit=1 설정 시 정확히 1건만 반환됨
  const paged = await api.functional.discussionboard.members.index(connection, {
    body: {
      created_at_from: timeBefore,
      created_at_to: timeAfter,
      pagination: { page: 1, limit: 1 },
    },
  });
  typia.assert(paged);
  TestValidator.equals("1건만 반환됨")(paged.data.length)(1);
  TestValidator.equals("pagination.limit=1")(paged.pagination.limit)(1);
}

