/**
 * Test channel listing with advanced filtering, pagination and role validation.
 *
 * - Goal: Validate the listing (index) API for discussion board channels.
 *   - Ensure admin can list channels with all filter combinations using only valid schema fields (code, name, active, position)
 *   - Validate partial filters, multi-criteria queries, and pagination work as intended
 *   - Confirm response format matches contract, especially pagination and data array
 *   - Confirm counts (records returned and pagination metadata) are accurate for each query
 *   - Ensure unauthorized requests (e.g. non-admin) are rejected (simulate by removing auth header if possible)
 *
 * Steps:
 * 1. Setup: Create several channels with varying codes, names, active states, and positions using the create API
 * 2. Filter by individual fields (code substring, name, active, position) and assert results contain only correct records
 * 3. Test multi-field/compound filter (e.g., code + active, name + position) and validate only correct records returned
 * 4. Check pagination: limit/page parameters restrict results, pagination metadata (current, limit, records, pages) is correct
 * 5. Try sorting if available (NOTE: no sort param present in contract, so only test pagination)
 * 6. Attempt request without authentication, expect 401/403 error or failure.
 */
export async function test_api_discussionboard_test_list_channels_with_common_filters_as_admin(
  connection: api.IConnection,
) {
  // 1. Setup: Create channels with diverse attributes
  const channels = await Promise.all([
    api.functional.discussionboard.channels.create(connection, {
      body: {
        code: "pol",
        name: "Politics",
        description: "Political topics",
        position: 1,
        active: true,
      },
    }),
    api.functional.discussionboard.channels.create(connection, {
      body: {
        code: "econ",
        name: "Economics",
        description: "Economic topics",
        position: 2,
        active: true,
      },
    }),
    api.functional.discussionboard.channels.create(connection, {
      body: {
        code: "sports",
        name: "Sports",
        description: "Sports discussions",
        position: 3,
        active: false,
      },
    }),
    api.functional.discussionboard.channels.create(connection, {
      body: {
        code: "arts",
        name: "Arts",
        description: "Art forums",
        position: 4,
        active: false,
      },
    }),
  ]);

  // 2. Filter by code substring
  {
    const codeRes = await api.functional.discussionboard.channels.index(connection, {
      body: { code: "po" },
    });
    typia.assert(codeRes);
    TestValidator.predicate("code filter only matches 'pol'")(codeRes.data.length === 1 && codeRes.data[0].code === "pol");
  }

  // 3. Filter by active=true
  {
    const activeRes = await api.functional.discussionboard.channels.index(connection, {
      body: { active: true },
    });
    typia.assert(activeRes);
    const expectedCodes = ["pol", "econ"];
    TestValidator.predicate("active filter works")(
      activeRes.data.length === 2 && activeRes.data.every((c) => expectedCodes.includes(c.code)),
    );
  }
  // 4. Filter by position
  {
    const posRes = await api.functional.discussionboard.channels.index(connection, {
      body: { position: 3 },
    });
    typia.assert(posRes);
    TestValidator.predicate("position=3 only returns sports")(
      posRes.data.length === 1 && posRes.data[0].code === "sports",
    );
  }
  // 5. Filter by name substring
  {
    const nameRes = await api.functional.discussionboard.channels.index(connection, {
      body: { name: "Art" },
    });
    typia.assert(nameRes);
    TestValidator.predicate("name filter for 'Arts'")(nameRes.data.length === 1 && nameRes.data[0].name === "Arts");
  }
  // 6. Multi-criteria: active=false + code substring "ar"
  {
    const multiRes = await api.functional.discussionboard.channels.index(connection, {
      body: { code: "ar", active: false },
    });
    typia.assert(multiRes);
    TestValidator.predicate("multi-filter for 'arts'")(
      multiRes.data.length === 1 && multiRes.data[0].code === "arts" && multiRes.data[0].active === false,
    );
  }
  // 7. Pagination: limit=2, page=1
  {
    const pageRes1 = await api.functional.discussionboard.channels.index(connection, {
      body: { limit: 2, page: 1 },
    });
    typia.assert(pageRes1);
    TestValidator.predicate("First page contains 2 results")(pageRes1.data.length === 2);
    TestValidator.equals("pagination.current page")(pageRes1.pagination.current)(1);
    TestValidator.equals("pagination.limit")(pageRes1.pagination.limit)(2);
    TestValidator.equals("pagination.records")(pageRes1.pagination.records)(4);
    TestValidator.equals("pagination.pages")(pageRes1.pagination.pages)(2);
  }
  // 8. Pagination: limit=2, page=2
  {
    const pageRes2 = await api.functional.discussionboard.channels.index(connection, {
      body: { limit: 2, page: 2 },
    });
    typia.assert(pageRes2);
    TestValidator.predicate("Second page contains 2 results")(pageRes2.data.length === 2);
    TestValidator.equals("pagination.current page")(pageRes2.pagination.current)(2);
  }
  // 9. Unauthorized access check (simulate as possible): clear auth header
  {
    const unauthConn = { ...connection, headers: { ...connection.headers } };
    // Remove typical authorization header if present
    if (unauthConn.headers?.Authorization) delete unauthConn.headers.Authorization;
    await TestValidator.error("unauthorized user is rejected")(async () => {
      await api.functional.discussionboard.channels.index(unauthConn, {
        body: {},
      });
    });
  }
}

