import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";

/**
 * Validate retrieval of discussion board channel details by a valid channel ID.
 *
 * Business context: Admin users require the ability to view detailed information about an individual channel for audit, configuration,
 * or management UI use cases. This test ensures that, after creating a channel, its detailed attributes (code, name, description, position,
 * active flag, creation and last modification timestamps) are accurately retrievable using the ID via the detail API endpoint.
 *
 * Step-by-step Process:
 * 1. Create a new discussion board channel using the admin endpoint, capturing the returned ID and all creation data.
 * 2. Retrieve the created channel's details by its unique ID using the detail API.
 * 3. Validate that all fields returned in the detail response match those provided in creation (except system-generated fields: id, created_at, updated_at).
 * 4. Assert the presence, types, and values of all returned schema-defined fields (id, code, name, description, position, active, created_at, updated_at).
 * 5. Ensure a successful, accurate 'happy path' experience for channel detail viewing in the admin dashboard.
 */
export async function test_api_discussionboard_test_retrieve_existing_channel_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a new channel for testing
  const createInput: IDiscussionboardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
  };

  const created: IDiscussionboardChannel =
    await api.functional.discussionboard.channels.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Retrieve the channel's details by ID
  const retrieved: IDiscussionboardChannel =
    await api.functional.discussionboard.channels.at(connection, {
      id: created.id,
    });
  typia.assert(retrieved);

  // 3. Validate all schema fields are present and correct
  TestValidator.equals("id matches")(retrieved.id)(created.id);
  TestValidator.equals("code matches")(retrieved.code)(createInput.code);
  TestValidator.equals("name matches")(retrieved.name)(createInput.name);
  TestValidator.equals("description matches")(retrieved.description)(createInput.description);
