  // 2. 첫 번째 섹션 생성 (특정 코드, 이름 지정)
  const sectionCode = RandomGenerator.alphaNumeric(7);
  const sectionName = RandomGenerator.paragraph()(2);
  const sectionCreate: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    code: sectionCode,
    name: sectionName,
    description: RandomGenerator.paragraph()(1),
    position: typia.random<number & tags.Type<"int32">>(),
