import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching of comment reports with a filter that produces no results.
 *
 * This test verifies that the comment report search endpoint properly returns an empty dataset without error when provided with filters that match no reports. This includes testing robustness of pagination and the correct empty response structure.
 *
 * Business Context:
 * Moderators must be able to filter comment reports by various criteria (report type, creation window, etc.) as part of their moderation workflow. This test ensures that the backend can gracefully handle searches that yield no records, maintaining API contract for pagination and not failing when no data is found.
 *
 * Step-by-step process:
 * 1. Create a comment (to ensure the system has at least one valid comment to report on).
 * 2. Create a valid report for the comment (to populate some data for contrast).
 * 3. Search for comment reports with a combination of filters that are guaranteed to return zero results:
 *    a. Use a fictitious report_type_id (random UUID not matching any report), OR
 *    b. Use a created_at date range that is strictly in the future.
 * 4. Validate that the response `data` array is empty and pagination/reporting fields are accurate (records should be 0).
 * 5. Optionally compare response fields to known standards so pagination is correctly reported on empty results.
 */
export async function test_api_discussionboard_test_comment_report_search_pagination_and_empty_results(
  connection: api.IConnection,
) {
  // 1. Create a comment (dependency)
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      body: `This is a comment posted for report search empty result test at ${new Date().toISOString()}`
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 2. Create a valid report on the comment (dependency to ensure system is populated)
  const realReportTypeId = typia.random<string & tags.Format<"uuid">>();
  const report = await api.functional.discussionboard.commentReports.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: comment.discussionboard_member_id,
      discussionboard_report_type_id: realReportTypeId,
      reason: "Report for negative search test",
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentReport.ICreate,
  });
  typia.assert(report);

  // 3a. Search for comment reports with a guaranteed-empty filter: non-existent report_type_id
  {
    const output = await api.functional.discussionboard.commentReports.index(connection, {
      body: {
        discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>()
      } satisfies IDiscussionboardCommentReport.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("empty data on non-existent report_type filter")(output.data)([]);
    TestValidator.equals("zero records")(output.pagination.records)(0);
  }

  // 3b. Search for comment reports with a strictly future created_at_from
  {
    const now = new Date();
    const future = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 365); // 1 year in the future
    const output = await api.functional.discussionboard.commentReports.index(connection, {
      body: {
        created_at_from: future.toISOString(),
      } satisfies IDiscussionboardCommentReport.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("empty data on future created_at_from")(output.data)([]);
    TestValidator.equals("zero records")(output.pagination.records)(0);
  }
}

