/**
 * Validate listing moderation actions with filters that ensure an empty result set.
 *
 * Test Context:
 * - Ensure the search endpoint correctly responds with zero results when filtering with values that do not match any records:
 *   - Use an `action_type` filter that is guaranteed not to exist.
 *   - Use an `acting_moderator_id` that does not match any moderator who has performed actions.
 *
 * Steps:
 * 1. (Dependency) Create at least one valid moderation action with normal/random values so there is real data in the system.
 * 2. Search moderation actions by an impossible `action_type`, verify empty "data" array and correct pagination meta (zero results).
 * 3. Search moderation actions by a random/non-existent `acting_moderator_id`, verify empty "data" and pagination again.
 */
export async function test_api_discussionboard_test_list_moderation_actions_with_no_results(connection: api.IConnection) {
  // 1. Create (ensure) at least one valid moderation action exists
  const action = await api.functional.discussionboard.moderationActions.create(connection, {
    body: {
      acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
      target_object_id: typia.random<string & tags.Format<"uuid">>(),
      target_object_type: "post",
      action_type: "delete",
      rationale: "Initial moderation for setup",
      actioned_at: new Date().toISOString(),
    } satisfies IDiscussionboardModerationAction.ICreate,
  });
  typia.assert(action);

  // 2. Search by impossible action_type (guaranteed not to exist)
  const impossibleActionType = "nonexistent_action_type";
  const output1 = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { action_type: impossibleActionType } satisfies IDiscussionboardModerationAction.IRequest,
  });
  typia.assert(output1);
  TestValidator.equals("empty data for impossible action_type")(output1.data.length)(0);
  TestValidator.equals("zero total records for impossible action_type")(output1.pagination.records)(0);

  // 3. Search by non-existent acting_moderator_id
  const impossibleModeratorId = typia.random<string & tags.Format<"uuid">>();
  // (ensure not matching the real moderator used above)
  if (impossibleModeratorId === action.acting_moderator_id) {
    // very unlikely, but try again
    return await test_api_discussionboard_test_list_moderation_actions_with_no_results(connection);
  }
  const output2 = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { acting_moderator_id: impossibleModeratorId } satisfies IDiscussionboardModerationAction.IRequest,
  });
  typia.assert(output2);
  TestValidator.equals("empty data for impossible moderator")(output2.data.length)(0);
  TestValidator.equals("zero total records for impossible moderator")(output2.pagination.records)(0);
}

