 *
 * [테스트 시나리오]
 * 1. 사전 데이터 준비: moderation action 레코드 생성
 * 2. 수정 요청: 일부 mutable 필드(rationale, action_type) 수정
 * 3. 결과 검증: 응답이 바뀐 필드는 반영되고, 나머지는 변하지 않음
 */
export async function test_api_discussionboard_test_update_moderation_action_success(
  connection: api.IConnection,
) {
  // 1. moderation action 레코드 생성 (사전 데이터 세팅)
  const createInput: IDiscussionboardModerationAction.ICreate = {
    acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    target_object_id: typia.random<string & tags.Format<"uuid">>(),
    target_object_type: "post",
    action_type: "warn",
    rationale: "Original Reason",
    actioned_at: new Date().toISOString(),
  };
  const moderationAction = await api.functional.discussionboard.moderationActions.create(
    connection,
    { body: createInput },
  );
  typia.assert(moderationAction);

