 * 4. update 권한 없음에 따른 에러 발생(Forbidden/Unauthorized) 확인
 *
 * [사업적 의의 및 비즈니스 규칙]
 * - moderation action update 권한은 운영자/관리자에만 주어져야 하며, 일반 회원(member)은 API를 통해 수정 불가해야 합니다.
 */
export async function test_api_discussionboard_test_update_moderation_action_requires_moderator_auth(
