        email: moderatorEmail,
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: "moderator",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    },
  );
  typia.assert(moderator);

  const moderationAction: IDiscussionboardModerationAction = await api.functional.discussionboard.moderationActions.create(
