        target_object_type: "post",
        action_type: "warn",
        rationale: "테스트 목적({member} 권한거부 케이스)",
        actioned_at: new Date().toISOString(),
      } satisfies IDiscussionboardModerationAction.ICreate,
    },
  );
  typia.assert(moderationAction);

  // 3. 일반 회원(member) 토큰으로 moderation action update 시도
  // (E2E 프레임워크가 connection context에 자동 히스토리/토큰 주입한다고 가정)
  await TestValidator.error("member 권한 update forbidden")(
