import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Permanently ban a member as a moderator, and verify correct linkage and repeatability.
 *
 * This test simulates the moderator flow:
 * 1. Create a member to be banned.
 * 2. Create an admin to assign moderator authority.
 * 3. Create a member to be moderator.
 * 4. Assign the moderator role to the moderator by the admin.
 * 5. The moderator issues a permanent ban for the member; verify all schema-required linkages and values.
 * 6. Attempt a repeat permanent ban for the same member by the same moderator to ensure schema allows it (test expects no error as per provided DTO/rules).
 */
export async function test_api_discussionboard_test_create_ban_success_permanent(
  connection: api.IConnection,
) {
  // 1. Create the member to be banned
  const bannedMemberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "member",
    is_active: true,
  };
  const bannedMember = await api.functional.discussionboard.members.create(connection, { body: bannedMemberInput });
  typia.assert(bannedMember);

  // 2. Create an admin (for moderator assignment)
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "admin",
    is_active: true,
  };
  const admin = await api.functional.discussionboard.members.create(connection, { body: adminInput });
  typia.assert(admin);

  // 3. Create a moderator member
  const moderatorInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "moderator",
    is_active: true,
  };
  const moderator = await api.functional.discussionboard.members.create(connection, { body: moderatorInput });
  typia.assert(moderator);

  // 4. Assign moderator role to the moderator, by the admin
  const now = new Date().toISOString();
  const modAssign = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: moderator.id,
      assigned_by_admin_id: admin.id,
      assigned_at: now,
      expires_at: null,
      revoked_at: null,
    },
  });
  typia.assert(modAssign);

  // 5. Moderator issues a permanent ban to the banned member
  const banReason = "Violation of forum policy (permanent ban)";
  const banInput: IDiscussionboardBan.ICreate = {
    banned_member_id: bannedMember.id,
    acting_moderator_id: moderator.id,
    reason: banReason,
    ban_type: "permanent",
    banned_at: now,
    expires_at: null,
  };
  const ban = await api.functional.discussionboard.bans.create(connection, { body: banInput });
  typia.assert(ban);

  // Check all fields and correct linkage
  TestValidator.equals("banned_member_id")(ban.banned_member_id)(bannedMember.id);
  TestValidator.equals("acting_moderator_id")(ban.acting_moderator_id)(moderator.id);
  TestValidator.equals("reason")(ban.reason)(banReason);
  TestValidator.equals("ban_type")(ban.ban_type)("permanent");
  TestValidator.equals("expires_at is null")(ban.expires_at)(null);

  // 6. Repeated permanent ban for the same member by same moderator (allowed by schema/rule)
  const ban2Input: IDiscussionboardBan.ICreate = {
    banned_member_id: bannedMember.id,
    acting_moderator_id: moderator.id,
    reason: "Subsequent violation (testing repeat)",
    ban_type: "permanent",
    banned_at: new Date().toISOString(),
    expires_at: null,
  };
  const ban2 = await api.functional.discussionboard.bans.create(connection, { body: ban2Input });
  typia.assert(ban2);
  TestValidator.equals("banned_member_id of repeat ban")(ban2.banned_member_id)(bannedMember.id);
  TestValidator.equals("ban_type for repeat")(ban2.ban_type)("permanent");
}

