 *
 * This test function ensures that when a comment snapshot exists, fetching it by its unique identifier returns all expected schema fields with correct values.
 * The scenario covers end-to-end entity creation and access, closely matching a real workflow.
 *
 * Steps:
 * 1. Create a member, which will serve as the author for subsequent actions.
 * 2. Create a post authored by the member (arbitrary thread/board IDs supplied for validity).
 * 3. Create a comment on the post by the same member.
 * 4. Create a new comment snapshot with realistic body, version, and timestamp values referencing the above entities.
 * 5. Fetch the snapshot via GET by its ID.
 * 6. Assert that all returned fields match what was inserted (ID, relationships, body, version, snapshot_created_at).
 */
export async function test_api_discussionboard_test_get_comment_snapshot_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a member for authorship
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
