      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a comment on the post
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. Create a comment snapshot referencing previous entities
  const version = 1;
  const snapshot_created_at = new Date().toISOString();
  const snapshotInput = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: member.id,
    discussionboard_post_id: post.id,
    body: comment.body,
    version,
    snapshot_created_at,
  } satisfies IDiscussionboardCommentSnapshot.ICreate;
  const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: snapshotInput,
  });
  typia.assert(snapshot);

  // 5. Retrieve the comment snapshot by its ID
  const fetched = await api.functional.discussionboard.commentSnapshots.at(connection, { id: snapshot.id });
  typia.assert(fetched);

  // 6. Validate all expected fields
  TestValidator.equals("id")(fetched.id)(snapshot.id);
  TestValidator.equals("discussionboard_comment_id")(fetched.discussionboard_comment_id)(snapshotInput.discussionboard_comment_id);
  TestValidator.equals("discussionboard_member_id")(fetched.discussionboard_member_id)(snapshotInput.discussionboard_member_id);
  TestValidator.equals("discussionboard_post_id")(fetched.discussionboard_post_id)(snapshotInput.discussionboard_post_id);
  TestValidator.equals("body")(fetched.body)(snapshotInput.body);
  TestValidator.equals("version")(fetched.version)(snapshotInput.version);
  TestValidator.equals("snapshot_created_at")(fetched.snapshot_created_at)(snapshotInput.snapshot_created_at);
