/**
 * Test updating a comment snapshot with valid data.
 *
 * This test ensures that updating a comment snapshot's modifiable fields
 * (body and/or version) works as expected through the API.
 *
 * The test proceeds with the following workflow:
 * 1. Create a member who will author comments and snapshots
 * 2. Create a post to attach the comment
 * 3. Create a comment on the post by the member
 * 4. Create a comment snapshot from that comment
 * 5. Update the snapshot's body and version using the update endpoint
 * 6. Validate that the returned object reflects the new body/content and version as expected, and still matches the original snapshot's id
 */
export async function test_api_discussionboard_test_update_comment_snapshot_with_valid_data(
  connection: api.IConnection,
) {
