import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotificationTemplate";

/**
 * Validates creation of a discussion board notification template with all schema-compliant fields.
 *
 * Ensures a system admin can successfully create a notification template with required fields: code, name, subject, body, is_active, and (optionally) description. Test uses unique, random values for code and name to guarantee uniqueness and business rule fulfillment. After creation, verifies response echoes all supplied fields and assigns timestamps, and that only schema-accepted fields are returned (rejecting non-schema properties).
 *
 * Steps:
 * 1. (Authentication assumed handled by test harness)
 * 2. Prepare valid request body with unique code, name, and all required fields (also randomly decide to include description).
 * 3. Call create notification template API.
 * 4. Assert response matches input fields (code, name, subject, body, is_active, description) and includes schema-compliant id, created_at, updated_at timestamps.
 * 5. Validate non-existence of non-schema properties in response.
 */
export async function test_api_discussionboard_notificationTemplates_test_create_notification_template_with_valid_fields(
  connection: api.IConnection,
) {
  // 2. Prepare request body with unique/valid test data (sometimes omit description)
  const body = {
    code: `e2e-code-` + typia.random<string & tags.Format<"uuid">>().slice(0, 8),
    name: `E2E Template ` + RandomGenerator.alphaNumeric(8),
    description: Math.random() < 0.5 ? RandomGenerator.paragraph()() : null,
    subject: `E2E Subject: ` + RandomGenerator.paragraph()(),
    body: `Dear {user}, \nE2E notification: ` + RandomGenerator.content()()(),
    is_active: Math.random() < 0.8, // mostly active
  } satisfies IDiscussionboardNotificationTemplate.ICreate;

  // 3. Call create endpoint
  const output = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    { body },
  );
  typia.assert(output);

  // 4. Validate required echo and assignment of system fields
  TestValidator.equals("code echo")(output.code)(body.code);
  TestValidator.equals("name echo")(output.name)(body.name);
  TestValidator.equals("subject echo")(output.subject)(body.subject);
  TestValidator.equals("body echo")(output.body)(body.body);
  TestValidator.equals("is_active echo")(output.is_active)(body.is_active);
  TestValidator.equals("description echo")(output.description ?? null)(body.description ?? null);

  // 5. Validate existence and format of system fields
  typia.assert< string & tags.Format<"uuid"> >(output.id);
  typia.assert< string & tags.Format<"date-time"> >(output.created_at);
  typia.assert< string & tags.Format<"date-time"> >(output.updated_at);

  // 6. Validate no extraneous properties exist
  const allowedKeys = [
    "id","code","name","description","subject","body","is_active","created_at","updated_at"
  ];
  for (const k of Object.keys(output)) {
    if (!allowedKeys.includes(k)) {
      throw new Error(`Unexpected property in response: ${k}`);
    }
  }
}

