import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotificationTemplate";
import type { IPageDiscussionboardNotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotificationTemplate";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching and filtering for notification templates using valid criteria (code, name, is_active, created_at/updated_at ranges).
 *
 * This test function ensures that the API supports a variety of valid search and filter parameters as defined by the schema, including code, name, is_active status, and date ranges for creation and update times. It also verifies that pagination is honored. This mimics an admin or moderator browsing/filtering notification templates for moderation or review.
 *
 * Steps:
 * 1. Create several notification templates with differing code, name, is_active, and timestamps.
 * 2. Test filtering by each valid criteria:
 *    - code
 *    - name
 *    - is_active (true/false)
 *    - created_at range
 *    - updated_at range
 * 3. Test pagination (limit, page) is respected.
 * 4. Validate that only schema-defined fields are accepted for filter/search (skipped in logic as type safety enforces this).
 * 5. Assert that only matching templates are returned, and response paging is correct.
 */
export async function test_api_discussionboard_notificationTemplates_test_search_notification_templates_with_valid_criteria(
  connection: api.IConnection,
) {
  // 1. Create several notification templates with various field values
  const timeStart: string = new Date(Date.now() - 10 * 60 * 1000).toISOString(); // 10 minutes ago
  const templates: IDiscussionboardNotificationTemplate[] = [];
  for (let i = 0; i < 4; ++i) {
    const template: IDiscussionboardNotificationTemplate = await api.functional.discussionboard.notificationTemplates.create(connection, {
      body: {
        code: `code_filter_test_${i}`,
        name: `Filter Test Name ${i}`,
        description: `Test template for filtering (${i})`,
        subject: `Filter Test Subject ${i}`,
        body: `Body Filter Test ${i}`,
        is_active: i % 2 === 0,
      } satisfies IDiscussionboardNotificationTemplate.ICreate,
    });
    typia.assert(template);
    templates.push(template);
  }
  const timeEnd: string = new Date(Date.now() + 10 * 60 * 1000).toISOString(); // 10 minutes from now

  // 2a. Filter by code
  for (const template of templates) {
    const res = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { code: template.code },
    });
    typia.assert(res);
    TestValidator.predicate("filter by code finds correct template")(res.data.some((t) => t.code === template.code));
  }

  // 2b. Filter by name
  for (const template of templates) {
    const res = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { name: template.name },
    });
    typia.assert(res);
    TestValidator.predicate("filter by name finds correct template")(res.data.some((t) => t.name === template.name));
  }

  // 2c. Filter by is_active: true
  let res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { is_active: true },
  });
  typia.assert(res);
  TestValidator.predicate("all returned templates are is_active=true")(res.data.every((t) => t.is_active));
  TestValidator.predicate("pagination fields present")(res.pagination.current >= 1 && res.pagination.limit >= 1);

  // 2d. Filter by is_active: false
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { is_active: false },
  });
  typia.assert(res);
  TestValidator.predicate("all returned templates are is_active=false")(res.data.every((t) => t.is_active === false));
  TestValidator.predicate("pagination fields present")(res.pagination.current >= 1 && res.pagination.limit >= 1);

  // 2e. Filter by created_at range
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { created_at_from: timeStart, created_at_to: timeEnd },
  });
  typia.assert(res);
  TestValidator.predicate("all results within created_at range")(res.data.every((t) => t.created_at >= timeStart && t.created_at <= timeEnd));

  // 2f. Filter by updated_at range
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { updated_at_from: timeStart, updated_at_to: timeEnd },
  });
  typia.assert(res);
  TestValidator.predicate("all results within updated_at range")(res.data.every((t) => t.updated_at >= timeStart && t.updated_at <= timeEnd));

  // 2g. Pagination (page/limit)
  res = await api.functional.discussionboard.notificationTemplates.index(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(res);
  TestValidator.equals("limit honored")(res.data.length)(2);
  TestValidator.equals("current page is 1")(res.pagination.current)(1);
  TestValidator.equals("per page equals limit")(res.pagination.limit)(2);

  // 3. All search fields are schema-defined (invalid fields cannot be tested at compile time)
  // 4. typia.assert validates all returned fields are schema-compliant
}

