 *
 * Step-by-step process:
 * 1. Create a new notification template via the creation endpoint to obtain a valid UUID.
 * 2. Retrieve this template using the GET-by-ID endpoint with the returned UUID.
 * 3. Assert that all fields are present, populated, and that relevant business fields match those from creation.
 * 4. Assert correct typing and that timestamp fields are valid ISO date strings.
 */
export async function test_api_discussionboard_notificationTemplates_test_get_notification_template_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a notification template to serve as the "existing" entity for ID-based retrieval
  const templateInput: IDiscussionboardNotificationTemplate.ICreate = {
    code: RandomGenerator.alphaNumeric(8), // unique programmatic reference
    name: RandomGenerator.paragraph()(1), // human-readable label
    description: Math.random() < 0.5 ? null : RandomGenerator.content()()(),
