 * 3. Verify that the privacy policy is created successfully: - All user-supplied fields are reflected in the response - System-generated fields (id, created_at, updated_at) are present and valid - No extra fields are accepted
 * 4. Schema validation: Ensure output is exactly the IDiscussionboardPrivacyPolicy structure.
 *
 * Only schema-allowed fields are supplied and checked. This workflow ensures happy-path creation for compliance, including legal, regulatory, and audit-critical requirements.
 */
export async function test_api_discussionboard_test_create_privacy_policy_with_complete_valid_data(
  connection: api.IConnection,
) {
  // 1. Register an admin member
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "admin",
