import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPrivacyPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPrivacyPolicy";
import type { Idiscussionboard_privacy_policies } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_privacy_policies";

/**
 * 업데이트 가능한 필드를 변경하여 기존 개인정보 처리방침(privacy policy)을 갱신하는 기능을 검증합니다.
 * 
 * 이 테스트는 실제 id 값을 가진 개인정보처리방침 레코드를 미리 생성해 두고, 여러 필드(버전, 제목, 본문, 시행일 등)를 수정 요청합니다. 수정 결과가 응답에 반영되어야 하며, 변화된 정보가 새로운 조회 시에도 일관되게 유지됨을 확인합니다.
 * 
 * 개인정보 처리방침의 갱신은 규제 변경이나 정책 개정 시 법적 효력을 갖기 때문에, 모든 수정 작업의 반영 및 적절한 필드 트래킹이 필수적입니다.
 *
 * 1. 관리자 계정 등록 (권한 획득)
 * 2. 최초 개인정보 처리방침 등록
 * 3. 개인정보 처리방침 일부 필드 수정 (버전, 제목, 본문, 시행일 중 하나 이상)
 * 4. 응답값이 수정 요청 내용과 일치하는지 확인
 * 5. 변경된 개인정보 처리방침을 재조회하여 영속성 및 일관성 확인
 */
export async function test_api_discussionboard_privacyPolicies_test_update_privacy_policy_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 관리자 회원 생성 (권한)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminUsername = RandomGenerator.alphaNumeric(10);
  const admin: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(admin);
  TestValidator.equals("admin role check")(admin.role)("admin");

  // 2. 개인정보 처리방침 신규 등록
  const initialPolicyInput: IDiscussionboardPrivacyPolicy.ICreate = {
    version: `v${new Date().getFullYear()}.${String(new Date().getMonth()+1).padStart(2,"0")}`,
    effective_date: new Date(Date.now() + 3600 * 24 * 1000).toISOString(),
    title: "초기 개인정보처리방침",
    content: RandomGenerator.paragraph()(),
  };
  const initialPolicy = await api.functional.discussionboard.privacyPolicies.create(connection, {
    body: initialPolicyInput,
  });
  typia.assert(initialPolicy);

  // 3. 개인정보 처리방침 일부 필드 수정 (버전/제목/본문/시행일)
  const updateInput: Idiscussionboard_privacy_policies.IUpdate = {
    version: `v${new Date().getFullYear()}.${String(new Date().getMonth()+2).padStart(2,"0")}`,
    title: "수정된 개인정보처리방침",
    content: RandomGenerator.paragraph()(),
    effective_date: new Date(Date.now() + 3600 * 48 * 1000).toISOString(),
  };

  const updatedPolicy = await api.functional.discussionboard.privacyPolicies.update(connection, {
    id: initialPolicy.id,
    body: updateInput,
  });
  typia.assert(updatedPolicy);
  // 4. 응답값이 수정 요청값과 일치하는지 검증
  if (updateInput.version) TestValidator.equals("policy version updated")(updatedPolicy.version)(updateInput.version);
  if (updateInput.title) TestValidator.equals("policy title updated")(updatedPolicy.title)(updateInput.title);
  if (updateInput.content) TestValidator.equals("policy content updated")(updatedPolicy.content)(updateInput.content);
  if (updateInput.effective_date) TestValidator.equals("policy effective_date updated")(updatedPolicy.effective_date)(updateInput.effective_date);

  // 5. 변경된 개인정보 처리방침 재조회 (API 미제공 시 위 결과로 대체)
  // 추가 'get' 기능이 명시적으로 존재하지 않으므로, update 결과값 일치 여부만 검증함.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPrivacyPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPrivacyPolicy";
import type { Idiscussionboard_privacy_policies } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_privacy_policies";

/**
 * Validate that privacy policy version update enforces uniqueness.
 *
 * This test ensures that when updating the 'version' field of a privacy policy (using its id),
 * the server correctly validates uniqueness constraints. The update attempt uses a version string
 * that already belongs to a different policy record, so the update should fail with an error.
 *
 * Steps:
 * 1. Register an admin member. (Required for performing policy updates)
 * 2. Create the first privacy policy with unique version 'v2025.01'.
 * 3. Create a second, different privacy policy with version 'v2025.02'.
 * 4. Attempt to update the second privacy policy, setting version to 'v2025.01' (duplicate).
 * 5. Confirm the update fails due to unique constraint violation.
 */
export async function test_api_discussionboard_privacyPolicies_test_update_privacy_policy_with_duplicate_version(
  connection: api.IConnection,
) {
  // 1. Register admin member
  const adminUsername = RandomGenerator.alphaNumeric(8);
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(admin);

  // 2. Create the first privacy policy with 'v2025.01'
  const policy1 = await api.functional.discussionboard.privacyPolicies.create(connection, {
    body: {
      version: "v2025.01",
      effective_date: new Date().toISOString(),
      title: "Privacy Policy January 2025",
      content: "Full privacy policy content for v2025.01.",
    } satisfies IDiscussionboardPrivacyPolicy.ICreate,
  });
  typia.assert(policy1);

  // 3. Create a second privacy policy with 'v2025.02'
  const policy2 = await api.functional.discussionboard.privacyPolicies.create(connection, {
    body: {
      version: "v2025.02",
      effective_date: new Date(Date.now() + 100000).toISOString(),
      title: "Privacy Policy February 2025",
      content: "Full privacy policy content for v2025.02.",
    } satisfies IDiscussionboardPrivacyPolicy.ICreate,
  });
  typia.assert(policy2);

  // 4. Attempt to update the version of policy2 to the duplicate version 'v2025.01' (should fail)
  await TestValidator.error("Unique constraint violation when updating to duplicate version")(
    () =>
      api.functional.discussionboard.privacyPolicies.update(connection, {
        id: policy2.id,
        body: { version: "v2025.01" } satisfies Idiscussionboard_privacy_policies.IUpdate,
      }),
  );
}

