    } satisfies IDiscussionboardCommentVote.IRequest,
  });
  typia.assert(byFutureRange);
  TestValidator.equals("future yields 0 results")(byFutureRange.data.length)(0);

  // 5.5 Pagination/limit test (limit 2 per page, check page meta and page flips)
  const paginated1 = await api.functional.discussionboard.commentVotes.index(connection, {
    body: {
      // No filters, default get all, but limit to 2
      // (most recent votes will be at the end due to sort, so we just test length, page meta)
    } satisfies IDiscussionboardCommentVote.IRequest,
  });
  typia.assert(paginated1);
  TestValidator.predicate("page meta structure")(
    typeof paginated1.pagination.current === "number" &&
      typeof paginated1.pagination.limit === "number" &&
      typeof paginated1.pagination.records === "number" &&
      typeof paginated1.pagination.pages === "number",
  );
  TestValidator.predicate("non-empty page")(
    paginated1.data.length > 0,
