import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Validate rejection of comment report creation with foreign key violations.
 *
 * This test ensures that the comment report creation endpoint strictly enforces referential integrity and schema constraints. 
 * The following error conditions must be validated:
 *   1. Report references a non-existent (random) comment UUID.
 *   2. Report references a non-existent member (reporter) UUID.
 *   3. Report references a non-existent report type UUID.
 *
 * Each variant should result in error, confirming that backend does NOT allow orphaned records or schema-violating submissions.
 * Valid member(s) will be created to derive legitimate UUIDs for contrast/error control. Valid fields (like 'reason', timestamp, etc.) must have syntactically correct data.
 * Only the foreign key(s) under test will be intentionally set to invalid UUIDs; all other fields should use appropriate test data.
 *
 * Steps:
 *   1. Create two members—one for control (potential reporter); another for isolation if needed
 *   2. Attempt to create a comment report with:
 *     a. An invalid (random, guaranteed non-existent) comment ID (valid reporter and report type)
 *     b. An invalid (random, guaranteed non-existent) reporter/member ID (valid comment and report type)
 *     c. An invalid (random, guaranteed non-existent) report type ID (valid comment and reporter)
 *   3. Confirm that all attempts result in errors, demonstrating enforcement of FK and schema limits
 */
export async function test_api_discussionboard_test_create_comment_report_with_nonexistent_comment_or_user(
  connection: api.IConnection,
) {
  // 1. Create two valid members for use as potential reporter and author
  const member1 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member2);

  // Use random UUIDs to ensure violation of FKs
  const nonexistent_uuid = typia.random<string & tags.Format<"uuid">>();
  const report_reason = "Testing FK constraint enforcement";
  const report_time = new Date().toISOString() as string & tags.Format<"date-time">;

  // (a) Invalid comment UUID
  await TestValidator.error("Should fail with nonexistent comment UUID")(
    async () => {
      await api.functional.discussionboard.commentReports.create(connection, {
        body: {
          discussionboard_comment_id: nonexistent_uuid,
          discussionboard_member_id: member1.id,
          discussionboard_report_type_id: nonexistent_uuid,
          reason: report_reason,
          created_at: report_time,
        },
      });
    },
  );

  // (b) Invalid member UUID
  await TestValidator.error("Should fail with nonexistent member UUID")(
    async () => {
      await api.functional.discussionboard.commentReports.create(connection, {
        body: {
          discussionboard_comment_id: nonexistent_uuid,
          discussionboard_member_id: nonexistent_uuid,
          discussionboard_report_type_id: nonexistent_uuid,
          reason: report_reason,
          created_at: report_time,
        },
      });
    },
  );

  // (c) Invalid report type UUID
  await TestValidator.error("Should fail with nonexistent report type UUID")(
    async () => {
      await api.functional.discussionboard.commentReports.create(connection, {
        body: {
          discussionboard_comment_id: nonexistent_uuid,
          discussionboard_member_id: member1.id,
          discussionboard_report_type_id: nonexistent_uuid,
          reason: report_reason,
          created_at: report_time,
        },
      });
    },
  );
}

