import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostVote";

/**
 * Validate successful updating of a post vote with valid data as an admin or moderator.
 *
 * This test covers the following workflow:
 * 1. Create a member with role 'admin' or 'moderator'.
 * 2. Create a post for a new thread and board, by this member.
 * 3. Create a post vote (upvote) for that post by this member.
 * 4. Update the post vote: change vote_type using PUT (admin/moderator privilege).
 * 5. Confirm that the update was successful and the vote_type is as expected.
 *
 * The test ensures that the API correctly processes post vote updates by privileged users and that response data matches the schema and business logic.
 */
export async function test_api_discussionboard_test_update_post_vote_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create an admin or moderator member
  const memberReq: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: RandomGenerator.pick(["admin", "moderator"]),
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberReq });
  typia.assert(member);

  // 2. Create a post (needs new thread/board UUIDs)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const postCreate: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: threadId,
    discussionboard_member_id: member.id,
    discussionboard_board_id: boardId,
    title: RandomGenerator.paragraph()(2, 6),
    body: RandomGenerator.content()()(2, 8),
    is_deleted: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postCreate });
  typia.assert(post);

  // 3. Create initial post vote (upvote) as admin/moderator
  const voteCreate: IPostVote.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: 1,
    created_at: new Date().toISOString(),
  };
  const vote = await api.functional.discussionboard.postVotes.create(connection, { body: voteCreate });
  typia.assert(vote);
  TestValidator.equals("vote_type equals 1 (upvote)")(vote.vote_type)(1);

  // 4. Update the vote_type (change upvote to downvote)
  const changedVoteType = -1;
  const updatedVote = await api.functional.discussionboard.postVotes.update(connection, {
    id: vote.id,
    body: { vote_type: changedVoteType } satisfies IPostVote.IUpdate,
  });
  typia.assert(updatedVote);

  // 5. Check the update took effect and business fields match
  TestValidator.equals("vote_type updated to -1")(updatedVote.vote_type)(changedVoteType);
  TestValidator.equals("vote id unchanged")(updatedVote.id)(vote.id);
  TestValidator.equals("post id matches")(updatedVote.discussionboard_post_id)(post.id);
  TestValidator.equals("member id matches")(updatedVote.discussionboard_member_id)(member.id);
  TestValidator.equals("created_at unchanged")(updatedVote.created_at)(vote.created_at);
}

