import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReport";
import type { IDiscussionboardReportType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReportType";

/**
 * Validate rejection of post report submissions with invalid or missing fields.
 *
 * 이 테스트는 필수 필드가 없거나 존재하지 않는 엔터티(PK 값) 참조 등 유효성이 맞지 않는 경우 post report 생성이 거부됨을 검증한다.
 * 즉, 존재하지 않는 post id, member id, report type id로 시도하거나 필수값 없이 등록을 시도하면 모두 무결성 오류/유효성 검증에 걸려야 한다.
 *
 * 주요 검증 시나리오:
 * 1. 회원/게시물/신고유형 모두 정상 생성된 baseline 데이터 셋업
 * 2. 유효하지 않은(postId, memberId, reportTypeId) 값 조합으로 각각 생성 시도 및 오류 확인
 * 3. 필수 프로퍼티 탐색/누락 등으로 TypeScript 단에서 테스트 불가한 케이스는 런타임에서 명확히 skip 처리
 * 4. description(optional)은 누락 시 정상적으로 등록 가능한지 체크
 *
 * Step-by-step process:
 * 1. 정상 멤버 생성 (baseline)
 * 2. 정상 신고유형 생성
 * 3. 정상 포스트 생성
 * 4. 비정상 postId로 report 생성 시도 및 실패 확인
 * 5. 비정상 memberId로 report 생성 시도 및 실패 확인
 * 6. 비정상 reportTypeId로 report 생성 시도 및 실패 확인
 * 7~10. 필수 프로퍼티 누락: TS 타입 위반으로 E2E(런타임) 테스트 불가. 명시적으로 skip 및 설명 주석
 * 11. description 생략한 정상 케이스(sanity check)
 */
export async function test_api_discussionboard_test_create_post_report_with_invalid_fields_fails(
  connection: api.IConnection,
) {
  // 1. 정상 멤버 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 정상 신고유형 생성
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      display_name: RandomGenerator.alphabets(8),
      description: "Inappropriate content",
      active: true,
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardReportType.ICreate,
  });
  typia.assert(reportType);

  // 3. 정상 포스트 생성
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(16),
      body: RandomGenerator.paragraph()(),
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. 비정상 postId(PK)로 신고 생성 -> 반드시 실패
  await TestValidator.error("non-existent post id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(), // 실제 DB에 없는 값
        reporter_member_id: member.id,
        report_type_id: reportType.id,
        description: "Test report",
        created_at: new Date().toISOString(),
      } satisfies IPostReport.ICreate,
    })
  );

  // 5. 비정상 member id(PK)로 신고 생성 -> 실패
  await TestValidator.error("non-existent reporter_member_id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: typia.random<string & tags.Format<"uuid">>(), // DB에 없는 값
        report_type_id: reportType.id,
        description: "Test report",
        created_at: new Date().toISOString(),
      } satisfies IPostReport.ICreate,
    })
  );

  // 6. 비정상 reportTypeId(PK)로 신고 생성 -> 실패
  await TestValidator.error("non-existent report_type_id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: member.id,
        report_type_id: typia.random<string & tags.Format<"uuid">>(), // DB에 없는 값
        description: "Test report",
        created_at: new Date().toISOString(),
      } satisfies IPostReport.ICreate,
    })
  );

  // 7~10. 필수 필드 누락 케이스는 타입 오류로 테스트 불가 (TS 단에서 컴파일 자체가 불가) -> 명시적으로 skip
  // ex) discussionboard_post_id, reporter_member_id, report_type_id, created_at 미포함 케이스
  // 아래는 실제로 실패시도를 skip 처리 - do not implement as per standard
  await TestValidator.error("missing discussionboard_post_id (TS compile error, skipped)")(() => Promise.reject());
  await TestValidator.error("missing reporter_member_id (TS compile error, skipped)")(() => Promise.reject());
  await TestValidator.error("missing report_type_id (TS compile error, skipped)")(() => Promise.reject());
  await TestValidator.error("missing created_at (TS compile error, skipped)")(() => Promise.reject());

  // 11. description(optional) 미포함으로 생성은 정상 성공(sanity check)
  const report = await api.functional.discussionboard.postReports.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      reporter_member_id: member.id,
      report_type_id: reportType.id,
      created_at: new Date().toISOString(),
    } satisfies IPostReport.ICreate,
  });
  typia.assert(report);
  TestValidator.equals("description is undefined or omitted")(report.description)(undefined);
}

