 *    - discussionboard_member_id: 회원 id가 일치
 *    - status: 'pending'(기본)
 *    - requested_at: 요청 시각과 대략 일치(10초 이내)
 *    - reviewed_at, completed_at, admin_remark: null 혹은 미지정
 */
export async function test_api_discussionboard_dataErasureRequests_create_successful_for_member(
