    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Submit the first data erasure request with status 'pending'
  const now = new Date().toISOString();
  const erasureInput = {
    discussionboard_member_id: member.id,
    status: "pending",
    requested_at: now,
  } satisfies Idiscussionboard_data_erasure_requests.ICreate;
  const firstReq = await api.functional.discussionboard.dataErasureRequests.create(connection, { body: erasureInput });
  typia.assert(firstReq);
  TestValidator.equals("first request status is pending")(firstReq.status)("pending");
  TestValidator.equals("member linked in request")(firstReq.discussionboard_member_id)(member.id);

  // 3. Try to make another pending erasure request for the same member
  await TestValidator.error("Cannot submit a duplicate pending data erasure request")(() =>
    api.functional.discussionboard.dataErasureRequests.create(connection, { body: erasureInput })
  );
}

