import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_data_erasure_requests } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_data_erasure_requests";
import type { IPageIdiscussionboard_data_erasure_requests } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_data_erasure_requests";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 데이터 삭제 요청 리스트 검색(필터+페이징) 기능의 관리자 시나리오 검증
 *
 * - 상태값(status), 회원ID, 날짜 범위(requested_at 등) 별 필터 조건을 이용해 정상적으로 페이지네이션/정렬된 결과가 반환되는지 확인합니다.
 * - 회원 2~3명, 요청 상태/날짜 조합을 다양하게 생성한 뒤 각 조합별 필터로 검색했을 때 일치하는 결과만 반환되는지 검증
 * - 페이지/limit 조작, 0건(결과 없음) 시나리오, 여러 개 결과(페이지네이션) 모두 테스트
 */
export async function test_api_discussionboard_data_erasure_requests_test_list_data_erasure_requests_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. 2~3명의 테스트 회원 생성
  const members = await Promise.all(
    ArrayUtil.repeat(3)(async () => {
      const member = await api.functional.discussionboard.members.create(connection, {
        body: {
          username: RandomGenerator.alphaNumeric(10),
          email: typia.random<string & tags.Format<'email'>>(),
          hashed_password: RandomGenerator.alphaNumeric(12),
          role: 'member',
          is_active: true,
        } satisfies IDiscussionboardMember.ICreate,
      });
      typia.assert(member);
      return member;
    })
  );

  // 2. 다양한 상태/날짜로 데이터 삭제 요청 생성 (최소 6건)
  const statuses = ['pending', 'approved', 'denied', 'completed'];
  const baseDate = new Date();
  const requests = await Promise.all(
    ArrayUtil.repeat(6)(async (i) => {
      const status = statuses[i % statuses.length];
      const member = members[i % members.length];
      // 날짜는 하루씩 다르게 분포
      const requested_at = new Date(baseDate.getTime() - i * 86400000).toISOString();
      const req = await api.functional.discussionboard.dataErasureRequests.create(connection, {
        body: {
          discussionboard_member_id: member.id,
          status,
          requested_at,
          admin_remark: `test remark ${i}`,
        } satisfies Idiscussionboard_data_erasure_requests.ICreate,
      });
      typia.assert(req);
      return req;
    })
  );

  // 3. 전체 데이터 삭제 요청(조건X) -> 6건 이상 존재하는지, pagination 구조 확인
  const listAll = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: {},
  });
  typia.assert(listAll);
  TestValidator.predicate('전체 결과 6건 이상')(listAll.pagination.records >= 6);
  TestValidator.equals('페이지네이션 배열 길이')(listAll.data.length)(Math.min(listAll.pagination.limit, listAll.pagination.records));

  // 4. 상태별 단일/복수개 필터 조회(pending 등)
  for (const status of statuses) {
    const filtered = await api.functional.discussionboard.dataErasureRequests.index(connection, {
      body: { status },
    });
    typia.assert(filtered);
    for (const item of filtered.data) {
      TestValidator.equals('status 필터링')(item.status)(status);
    }
  }

  // 5. 특정 회원-ID로 필터
  const member = RandomGenerator.pick(members);
  const filteredByMember = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { discussionboard_member_id: member.id },
  });
  typia.assert(filteredByMember);
  for (const item of filteredByMember.data) {
    TestValidator.equals('member_id 필터링')(item.discussionboard_member_id)(member.id);
  }

  // 6. 날짜 범위: 최근 하루에 해당하는 데이터만 가져오도록 확인
  const targetRequest = requests[0];
  const filteredByDate = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { requested_at: targetRequest.requested_at },
  });
  typia.assert(filteredByDate);
  for (const item of filteredByDate.data) {
    TestValidator.equals('requested_at 일치')(item.requested_at)(targetRequest.requested_at);
  }

  // 7. 빈 결과(매칭불가 조건) 검증
  const emptyResult = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { status: 'nonexistent-status-value', discussionboard_member_id: typia.random<string & tags.Format<'uuid'>>() },
  });
  typia.assert(emptyResult);
  TestValidator.equals('빈 결과')(emptyResult.data.length)(0);
}

