import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostSnapshot";
import type { IPageIPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching and paginating post snapshot records with various filter criteria.
 *
 * This test covers the following business requirements:
 * 1. The ability to search post snapshots filtered by post ID, editor_member_id, or taken_at time range.
 * 2. Pagination, ensuring that limit and page work as expected.
 * 3. Only schema-defined filter fields should be allowed (validation error for extra fields).
 * 4. Realistic end-to-end workflow: (a) Create two distinct posts, (b) Create multiple snapshots for each post with different editors and times, (c) Test and verify filters and pagination, (d) Check validation error with non-schema filter.
 *
 * Steps:
 * 1. Create two discussionboard posts, each with unique thread, member, and board IDs.
 * 2. For each post, create multiple snapshots with different editor_member_id and taken_at times.
 * 3. Execute snapshot searches:
 *     a. By post ID (should return only that post's snapshots)
 *     b. By editor_member_id (verifies multiple posts, one editor)
 *     c. By taken_at range (returns the proper snapshots)
 *     d. By pagination/limit (validates page counts, limit enforcement)
 * 4. Attempt search with a bogus filter field and confirm validation error.
 * 5. Assert all successful responses' structure, and business logic on results.
 */
export async function test_api_discussionboard_test_search_post_snapshots_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two posts with unique properties (member, thread, board)
  const threadId1 = typia.random<string & tags.Format<"uuid">>();
  const threadId2 = typia.random<string & tags.Format<"uuid">>();
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const boardId1 = typia.random<string & tags.Format<"uuid">>();
  const boardId2 = typia.random<string & tags.Format<"uuid">>();

  const now = Date.now();
  const takenTimes: string[] = [
    new Date(now - 3600 * 1000 * 2).toISOString(),
    new Date(now - 3600 * 1000).toISOString(),
    new Date(now).toISOString(),
  ];

  const post1 = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId1,
      discussionboard_member_id: memberId1,
      discussionboard_board_id: boardId1,
      title: "Post 1 Title",
      body: "Post 1 Body",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(post1);

  const post2 = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId2,
      discussionboard_member_id: memberId2,
      discussionboard_board_id: boardId2,
      title: "Post 2 Title",
      body: "Post 2 Body",
      is_deleted: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  typia.assert(post2);

  // 2. Create two snapshots per post (purposeful differences)
  const snapshot1p1 = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post1.id,
      editor_member_id: memberId1,
      title: "P1 V1",
      body: "Body1 V1",
      taken_at: takenTimes[0],
    },
  });
  typia.assert(snapshot1p1);

  const snapshot2p1 = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post1.id,
      editor_member_id: null,
      title: "P1 V2",
      body: "Body1 V2",
      taken_at: takenTimes[1],
    },
  });
  typia.assert(snapshot2p1);

  const snapshot1p2 = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post2.id,
      editor_member_id: memberId2,
      title: "P2 V1",
      body: "Body2 V1",
      taken_at: takenTimes[0],
    },
  });
  typia.assert(snapshot1p2);

  const snapshot2p2 = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post2.id,
      editor_member_id: memberId1, // memberId1 edits both posts
      title: "P2 V2",
      body: "Body2 V2",
      taken_at: takenTimes[2],
    },
  });
  typia.assert(snapshot2p2);

  // 3a. Filter by post1's ID
  let result = await api.functional.discussionboard.postSnapshots.index(connection, {
    body: { discussionboard_post_id: post1.id },
  });
  typia.assert(result);
  TestValidator.predicate("Snapshot data only for post1")(
    result.data.every((s) => s.discussionboard_post_id === post1.id),
  );

  // 3b. Filter by memberId1 as editor (should return two snapshots, even across posts)
  result = await api.functional.discussionboard.postSnapshots.index(connection, {
    body: { editor_member_id: memberId1 },
  });
  typia.assert(result);
  TestValidator.predicate("Results match editor_member_id=memberId1")(
    result.data.every((s) => s.editor_member_id === memberId1),
  );

  // 3c. Filter by taken_at range (should match only snapshots in window)
  result = await api.functional.discussionboard.postSnapshots.index(connection, {
    body: { taken_at_from: takenTimes[1], taken_at_to: takenTimes[2] },
  });
  typia.assert(result);
  TestValidator.predicate("taken_at range is respected")(
    result.data.every(
      (s) => s.taken_at >= takenTimes[1] && s.taken_at <= takenTimes[2],
    ),
  );

  // 3d. Pagination: Fetch 1 result per page, check that only 1 comes back
  result = await api.functional.discussionboard.postSnapshots.index(connection, {
    body: { limit: 1 },
  });
  typia.assert(result);
  TestValidator.equals("pagination limit=1")(result.pagination.limit)(1);
  TestValidator.equals("one data per page")(result.data.length)(1);

