import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostVote";

/**
 * E2E: Post voting creation and retraction/neutralization flow (valid scenarios)
 *
 * This test validates the proper creation and update semantics for upvotes, downvotes, and vote neutralizations
 * by a given member for a discussionboard post.
 *
 * Steps:
 * 1. Create a member (as the voting user)
 * 2. Create a post (authored by this member)
 * 3. Cast an upvote (vote_type: 1) for the post by the member
 * 4. Cast a downvote (vote_type: -1) for the same post by the same member (should update vote or be rejected as duplicate)
 * 5. Attempt a duplicate upvote (vote_type: 1 again) for the same post/member (should update vote or be rejected)
 * 6. Set vote_type to 0 for the same post/member (should record vote neutralization/retraction)
 * 7. (Optional) Re-cast upvote after neutralization (should allow fresh vote)
 *
 * Business rules:
 * - Each (member, post) pair should have at most one active vote at a time, of vote_type: 1, -1, or 0
 * - Confirm output contains correct post and member references, and vote_type matches input
 * - Confirm any business logic error on illegal duplicates or out-of-bounds values
 *
 * Test verifies that vote creation, updating, and neutralization semantics are properly enforced.
 */
export async function test_api_discussionboard_test_create_post_vote_valid(
  connection: api.IConnection,
) {
  // 1. Create member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create post (as this member, with random thread and board IDs)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: member.id,
      discussionboard_board_id: boardId,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Cast upvote (vote_type=1)
  const vote1 = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      vote_type: 1,
      created_at: new Date().toISOString(),
    } satisfies IPostVote.ICreate,
  });
  typia.assert(vote1);
  TestValidator.equals("vote_type upvote")(vote1.vote_type)(1);
  TestValidator.equals("member on vote")(vote1.discussionboard_member_id)(member.id);
  TestValidator.equals("post on vote")(vote1.discussionboard_post_id)(post.id);

  // 4. Cast downvote (vote_type=-1) for same post/member
  const vote2 = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      vote_type: -1,
      created_at: new Date().toISOString(),
    } satisfies IPostVote.ICreate,
  });
  typia.assert(vote2);
  TestValidator.equals("vote_type downvote")(vote2.vote_type)(-1);
  TestValidator.equals("same member id")(vote2.discussionboard_member_id)(member.id);
  TestValidator.equals("same post id")(vote2.discussionboard_post_id)(post.id);

  // 5. Duplicate upvote (should update or reject)
  const vote3 = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      vote_type: 1,
      created_at: new Date().toISOString(),
    } satisfies IPostVote.ICreate,
  });
  typia.assert(vote3);
  TestValidator.equals("vote_type upvote (updated)")(vote3.vote_type)(1);
  TestValidator.equals("same member id")(vote3.discussionboard_member_id)(member.id);
  TestValidator.equals("same post id")(vote3.discussionboard_post_id)(post.id);

  // 6. Set vote_type to 0 for same post/member (neutral/retract)
  const vote4 = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      vote_type: 0,
      created_at: new Date().toISOString(),
    } satisfies IPostVote.ICreate,
  });
  typia.assert(vote4);
  TestValidator.equals("vote_type neutral")(vote4.vote_type)(0);
  TestValidator.equals("same member id for neutral")(vote4.discussionboard_member_id)(member.id);
  TestValidator.equals("same post id for neutral")(vote4.discussionboard_post_id)(post.id);

  // 7. Optional: re-cast upvote after neutralization
  const vote5 = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      vote_type: 1,
      created_at: new Date().toISOString(),
    } satisfies IPostVote.ICreate,
  });
  typia.assert(vote5);
  TestValidator.equals("re-upvote after neutral")(vote5.vote_type)(1);
}

