import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardEngagementMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardEngagementMetric";
import type { IPageIDiscussionboardEngagementMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardEngagementMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate retrieving a discussion board engagement metric by a valid ID.
 *
 * This end-to-end test covers the workflow of:
 * 1. Creating an admin member
 * 2. Creating a board to collect engagement activity
 * 3. Generating engagement (post and comment) by the admin on the board
 * 4. Querying engagement metrics filtered for the specific member and board to locate a metric row
 * 5. Retrieving the engagement metric by its ID with the GET API
 * 6. Validating that the record matches schema, user, board, and engagement data
 * 7. Ensuring no non-schema fields are returned
 *
 * Business context:
 * - Verifies that engagement metric aggregation is tracked for actual activity
 * - Ensures proper linkage between member, board, and metrics
 * - Confirms only schema fields are present in the API response
 *
 * Step-by-step process:
 * 1. Create admin member
 * 2. Create a board (with dummy category/section IDs for test isolation)
 * 3. Create a post by admin on the board (using a new thread ID)
 * 4. Create a comment on the post (by admin)
 * 5. Query engagement metrics for this member/board
 * 6. Find a metric entry with at least one post and comment
 * 7. Retrieve the metric by ID
 * 8. Assert all IDs and counts match and only schema fields appear
 */
export async function test_api_discussionboard_test_retrieve_engagement_metric_valid_id(
  connection: api.IConnection,
) {
  // 1. Create an admin member
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: RandomGenerator.alphaNumeric(6) + "@test.com",
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "admin",
    is_active: true,
  };
  const admin = await api.functional.discussionboard.members.create(connection, { body: adminInput });
  typia.assert(admin);

  // 2. Create a board (using dummy UUIDs for category and section)
  const boardInput: Idiscussionboard_boards.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphaNumeric(6),
    code: RandomGenerator.alphaNumeric(10),
    description: null,
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, { body: boardInput });
  typia.assert(board);

  // 3. Generate engagement: create a post on the board by the admin
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: threadId,
    discussionboard_member_id: admin.id,
    discussionboard_board_id: board.id,
    title: "Test Engagement Metric Post",
    body: "Content for engagement metric test.",
    is_deleted: false,
    created_at: now,
    updated_at: now,
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 4. Generate engagement: create a comment on the post
  const commentInput: IComment.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: admin.id,
    body: "Comment for engagement metric test.",
  };
  const comment = await api.functional.discussionboard.comments.create(connection, { body: commentInput });
  typia.assert(comment);

  // 5. Query engagement metrics for this member and board
  const metricsPage = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: {
      discussionboard_member_id: admin.id,
      discussionboard_board_id: board.id,
      engagement_date_from: null,
      engagement_date_to: null,
    },
  });
  typia.assert(metricsPage);
  TestValidator.predicate("at least one metric record found")(metricsPage.data.length > 0);

  // 6. Find a matching metric entry (at least one post/comment)
  const metric = metricsPage.data.find(
    (m) => m.posts_created_count >= 1 && m.comments_created_count >= 1 && m.discussionboard_member_id === admin.id && m.discussionboard_board_id === board.id,
  );
  TestValidator.predicate("metric for member and board exists")(!!metric);

  // 7. Retrieve the metric by ID
  const metricById = await api.functional.discussionboard.engagementMetrics.at(connection, { id: metric!.id });
  typia.assert(metricById);

  // 8. Assert all schema fields are correct and present, and only schema fields are returned
  TestValidator.equals("metric ID matches")(metricById.id)(metric!.id);
  TestValidator.equals("discussionboard_member_id matches")(metricById.discussionboard_member_id)(admin.id);
  TestValidator.equals("discussionboard_board_id matches")(metricById.discussionboard_board_id)(board.id);
  TestValidator.predicate("at least one post created")(metricById.posts_created_count >= 1);
  TestValidator.predicate("at least one comment created")(metricById.comments_created_count >= 1);
  TestValidator.predicate("votes_cast_count >= 0")(metricById.votes_cast_count >= 0);

  const allowedFields = [
    "id",
    "discussionboard_member_id",
    "discussionboard_board_id",
    "engagement_date",
    "posts_created_count",
    "comments_created_count",
    "votes_cast_count",
  ];
  for (const key of Object.keys(metricById)) {
    TestValidator.predicate(`field '${key}' must be defined in schema`)(allowedFields.includes(key));
  }
}

