import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardActivityLog";
import type { IPageIDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate fetching a single activity log by valid id.
 *
 * This test ensures that after triggering a user event (member creation), the activity log is correctly written and retrievable by its unique id.
 *
 * Steps:
 * 1. Create a new discussion board member (which should generate an activity log).
 * 2. Query the activity logs, filtering by the newly created member's id.
 * 3. Select an event log related to the member creation (usually the latest or one matching the member id).
 * 4. Retrieve the log by its id from the single-get API.
 * 5. Validate that all key fields match between the list and detail retrieval.
 */
export async function test_api_discussionboard_test_get_activity_log_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board member to trigger an activity log
  const memberInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Query activity logs filtered by new member's id
  const logsPage = await api.functional.discussionboard.activityLogs.index(connection, {
    body: { discussionboard_member_id: member.id } satisfies IDiscussionboardActivityLog.IRequest,
  });
  typia.assert(logsPage);
  if (!logsPage.data.length) throw new Error("No activity logs found for new member");

  // 3. Pick the latest or most relevant log (usually the member registration)
  const relatedLog = logsPage.data.find(
    (log) => log.discussionboard_member_id === member.id
  ) ?? logsPage.data[0];

  // 4. Fetch the log by its id
  const logById = await api.functional.discussionboard.activityLogs.at(connection, {
    id: relatedLog.id,
  });
  typia.assert(logById);

  // 5. Validate all details match between list and single-get
  TestValidator.equals("activity log id")(logById.id)(relatedLog.id);
  TestValidator.equals("member id")(logById.discussionboard_member_id)(relatedLog.discussionboard_member_id);
  TestValidator.equals("event type")(logById.event_type)(relatedLog.event_type);
  TestValidator.equals("event timestamp")(logById.event_timestamp)(relatedLog.event_timestamp);
  TestValidator.equals("event metadata")(logById.event_metadata)(relatedLog.event_metadata);
  TestValidator.equals("board id")(logById.discussionboard_board_id)(relatedLog.discussionboard_board_id);
  TestValidator.equals("thread id")(logById.discussionboard_thread_id)(relatedLog.discussionboard_thread_id);
  TestValidator.equals("post id")(logById.discussionboard_post_id)(relatedLog.discussionboard_post_id);
  TestValidator.equals("comment id")(logById.discussionboard_comment_id)(relatedLog.discussionboard_comment_id);
}

