import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardTrendingTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTrendingTopic";
import type { IPageIDiscussionboardTrendingTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardTrendingTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing trending topics with various filters and pagination as an admin.
 *
 * This test ensures that trending topics can be listed with proper filter options,
 * including filtering by board id, date ranges, and paginating the results. It
 * simulates realistic trending topic creation by creating new boards (since at
 * least one is required for valid threads), several threads per board (which
 * would later be used to appear as trending), and then retrieves trending topics
 * using the trendingTopics endpoint with different filter and pagination inputs.
 *
 * The test must:
 * 1. Create 2 boards
 * 2. For each board, create 2 threads (simulate distinct topics)
 * 3. Attempt to retrieve trending topics for a specific board with date filter,
 *    and with/without pagination options, using the trendingTopics endpoint
 * 4. Validate that only records matching the filtered board and within date
 *    range are present, that schema matches, and that pagination fields are correct
 */
export async function test_api_discussionboard_test_list_trending_topics_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two unique boards
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();

  const board1 = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: categoryId,
      discussionboard_section_id: sectionId,
      name: `Board 1 - ${RandomGenerator.alphaNumeric(6)}`,
      code: `code1-${RandomGenerator.alphaNumeric(8)}`,
      description: "Trending Test Board 1",
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board1);

  const board2 = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: categoryId,
      discussionboard_section_id: sectionId,
      name: `Board 2 - ${RandomGenerator.alphaNumeric(6)}`,
      code: `code2-${RandomGenerator.alphaNumeric(8)}`,
      description: "Trending Test Board 2",
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board2);

  // 2. For each board, create two threads (topics)
  const authorId = typia.random<string & tags.Format<"uuid">>();
  const threads: string[] = [];
  for (const board of [board1, board2]) {
    for (let i = 0; i < 2; i++) {
      const thread = await api.functional.discussionboard.threads.create(connection, {
        body: {
          board_id: board.id,
          author_member_id: authorId,
          title: `Topic ${i} for board ${board.name}`,
          body: `Thread content for topic ${i}`,
        },
      });
      typia.assert(thread);
      threads.push(thread.id);
    }
  }

  // 3. Prepare ranking date range for trending topic queries
  // Use a broad range including now, to ensure all results
  const now = new Date();
  const rankingDateFrom = new Date(now.getTime() - 5 * 24 * 60 * 60 * 1000).toISOString();
  const rankingDateTo = new Date(now.getTime() + 1 * 24 * 60 * 60 * 1000).toISOString();

  // 4. Retrieve trending topics filtered by board1 id, and ranking period date
  const trendingResult = await api.functional.discussionboard.trendingTopics.index(connection, {
    body: {
      discussionboard_board_id: board1.id,
      ranking_period_date_from: rankingDateFrom,
      ranking_period_date_to: rankingDateTo,
    },
