import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardNotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotificationTemplate";
import type { IDiscussionboardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotificationPreference";
import type { IPageDiscussionboardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching/filtering notification preferences with various filter options.
 *
 * This test ensures that searching notification preferences works correctly across supported schema fields:
 * - Filtering by member id
 * - Filtering by template code
 * - Filtering by channel enablement (email_enabled, inapp_enabled, browser_enabled)
 *
 * Steps:
 * 1. Create several distinct members (at least 2) with unique email and username.
 * 2. Create several notification templates (at least 2), each with unique code and name.
 * 3. For each member-template-channel permutation, create notification preferences with various combinations of email_enabled, inapp_enabled, and browser_enabled.
 * 4. For each type of filter—member id, code, and channel enablement—perform a search and confirm that results only include matching preferences (by examining returned data fields).
 * 5. Repeat with combined filters (e.g., member id + code, code + inapp_enabled, etc.) and verify that only the expected set of preferences are returned.
 * 6. Confirm that counts in paginated results line up with total matching objects for the scenario.
 */
export async function test_api_discussionboard_test_search_notification_preferences_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create test members
  const members = await ArrayUtil.asyncRepeat(2)(async () => {
    const member = await api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphabets(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: RandomGenerator.pick(["member", "moderator", "admin"]),
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    });
    typia.assert(member);
    return member;
  });

  // 2. Create notification templates
  const templates = await ArrayUtil.asyncRepeat(2)(async () => {
    const code = RandomGenerator.alphaNumeric(10);
    const template = await api.functional.discussionboard.notificationTemplates.create(connection, {
      body: {
        code,
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.paragraph()(1),
        subject: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(1),
        is_active: true,
      } satisfies IDiscussionboardNotificationTemplate.ICreate,
    });
    typia.assert(template);
    return template;
  });

  // 3. Create notification preferences for all member-template-channel permutations
  const booleanCombos = [
    { email_enabled: true, inapp_enabled: false, browser_enabled: false },
    { email_enabled: false, inapp_enabled: true, browser_enabled: false },
    { email_enabled: false, inapp_enabled: false, browser_enabled: true },
    { email_enabled: true, inapp_enabled: true, browser_enabled: false },
  ];
  const preferences: IDiscussionboardNotificationPreference[] = [];
  for (const member of members) {
    for (const template of templates) {
      for (const combo of booleanCombos) {
        const pref = await api.functional.discussionboard.notificationPreferences.create(connection, {
          body: {
            discussionboard_member_id: member.id,
            code: template.code,
            email_enabled: combo.email_enabled,
            inapp_enabled: combo.inapp_enabled,
            browser_enabled: combo.browser_enabled,
          } satisfies IDiscussionboardNotificationPreference.ICreate,
        });
        typia.assert(pref);
        preferences.push(pref);
      }
    }
  }

  // 4. Filter by member id
  for (const member of members) {
    const resp = await api.functional.discussionboard.notificationPreferences.index(connection, {
      body: { discussionboard_member_id: member.id },
    });
    typia.assert(resp);
    TestValidator.predicate("filtered by member id")(
      resp.data.every(p => p.discussionboard_member_id === member.id),
    );
  }
  // 5. Filter by code
  for (const template of templates) {
    const resp = await api.functional.discussionboard.notificationPreferences.index(connection, {
      body: { code: template.code },
    });
    typia.assert(resp);
    TestValidator.predicate("filtered by code")(
      resp.data.every(p => p.code === template.code),
    );
  }
  // 6. Filter by channel enablements
  for (const c of [
    { field: "email_enabled" as const, value: true },
    { field: "email_enabled" as const, value: false },
    { field: "inapp_enabled" as const, value: true },
    { field: "inapp_enabled" as const, value: false },
    { field: "browser_enabled" as const, value: true },
    { field: "browser_enabled" as const, value: false },
  ]) {
    const filter: Record<string, boolean> = { [c.field]: c.value };
    const resp = await api.functional.discussionboard.notificationPreferences.index(connection, {
      body: filter,
    });
    typia.assert(resp);
    TestValidator.predicate(`filter by ${c.field} ${c.value}`)(
      resp.data.every(p => p[c.field] === c.value),
    );
  }
  // 7. Combined filter (member id + code + channel flag)
  const example = preferences[0];
  const resp = await api.functional.discussionboard.notificationPreferences.index(connection, {
    body: {
      discussionboard_member_id: example.discussionboard_member_id,
      code: example.code,
      email_enabled: example.email_enabled,
      inapp_enabled: example.inapp_enabled,
      browser_enabled: example.browser_enabled,
    },
  });
  typia.assert(resp);
  TestValidator.predicate("combined filter matches only correct preference")(
    resp.data.every(
      p => p.discussionboard_member_id === example.discussionboard_member_id &&
           p.code === example.code &&
           p.email_enabled === example.email_enabled &&
           p.inapp_enabled === example.inapp_enabled &&
           p.browser_enabled === example.browser_enabled
    ) && resp.data.length > 0,
  );
  // 8. Pagination count (limit=2)
  const paged = await api.functional.discussionboard.notificationPreferences.index(connection, {
    body: { limit: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("page limit respected")(paged.data.length <= 2)(true);
}

