import type { IDiscussionboardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotificationPreference";

/**
 * Validates updating (PUT) a notification preference with valid enablement-flags.
 *
 * This test covers the following scenario:
 * 1. Register a new discussion board member.
 * 2. Create a notification template (required by preferences system).
 * 3. Create a notification preference record for that member and template.
 * 4. Update the notification preference (by id) to toggle one or more of the boolean flags (email_enabled, inapp_enabled, browser_enabled). Also update updated_at timestamp and set code/discussionboard_member_id to original values.
 * 5. Verify that the response reflects the new value(s), all schema fields are present and only allowed fields are changed (not extra fields).
 */
export async function test_api_discussionboard_test_update_notification_preference_with_valid_data(connection: api.IConnection) {
  // 1. Create a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = RandomGenerator.alphaNumeric(10);
  const memberPassword = RandomGenerator.alphaNumeric(16);
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: memberPassword,
      role: "member",
      is_active: true,
    }
  });
  typia.assert(member);

  // 2. Create a notification template
  const templateCode = RandomGenerator.alphaNumeric(8);
  const template = await api.functional.discussionboard.notificationTemplates.create(connection, {
    body: {
      code: templateCode,
      name: "Mention alert",
      description: "Template for mention alert notifications.",
      subject: "You were mentioned!",
      body: "Hi {{username}}, you have a new mention.",
      is_active: true,
    }
  });
  typia.assert(template);

  // 3. Create initial notification preference
  const origPreference = await api.functional.discussionboard.notificationPreferences.create(connection, {
    body: {
      discussionboard_member_id: member.id,
      code: template.code,
      email_enabled: true,
      inapp_enabled: false,
      browser_enabled: true,
    }
  });
  typia.assert(origPreference);

  // 4. Update preference (toggle inapp_enabled, flip email_enabled)
  const updatedPreferenceBody = {
    discussionboard_member_id: member.id,
    code: template.code,
    email_enabled: false, // flip old
    inapp_enabled: true, // toggle
    browser_enabled: origPreference.browser_enabled,
    created_at: origPreference.created_at,
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  } satisfies IDiscussionboardNotificationPreference.IUpdate;
  const updatedPreference = await api.functional.discussionboard.notificationPreferences.update(connection, {
    id: origPreference.id,
    body: updatedPreferenceBody,
  });
  typia.assert(updatedPreference);

  // 5. Verify: All fields match new values, id unchanged, and non-toggled fields retained
  TestValidator.equals("id matches")(updatedPreference.id)(origPreference.id);
  TestValidator.equals("discussionboard_member_id matches")(updatedPreference.discussionboard_member_id)(member.id);
  TestValidator.equals("code matches")(updatedPreference.code)(template.code);
  TestValidator.equals("email_enabled updated")(updatedPreference.email_enabled)(false);
  TestValidator.equals("inapp_enabled updated")(updatedPreference.inapp_enabled)(true);
  TestValidator.equals("browser_enabled unchanged")(updatedPreference.browser_enabled)(origPreference.browser_enabled);
  TestValidator.equals("created_at kept")(updatedPreference.created_at)(origPreference.created_at);
  TestValidator.notEquals("updated_at changed")(updatedPreference.updated_at)(origPreference.updated_at);
}

