import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { Idiscussionboard_boards } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_boards";
import type { IDiscussionboardBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardModerator";
import type { IDiscussionboardBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardModerators";
import type { IPageIDiscussionboardBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBoardModerators";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates listing and searching board-moderator assignments with schema-compliant filters and pagination.
 *
 * This test creates two boards and two moderators, assigns each moderator to both boards with varying is_primary and joined_at,
 * then thoroughly validates the PATCH /discussionboard/boardModerators endpoint's filtering, pagination, error handling, and access control.
 *
 * Steps:
 * 1. Create two boards (boardA, boardB) with unique attributes for linking
 * 2. Create two moderators (mod1, mod2) with valid assignment metadata
 * 3. Assign both moderators to both boards, varying is_primary and joined_at
 * 4. List all assignments (validate 4 exist, pagination correct)
 * 5. Search/filter: by moderator id, board id, is_primary true/false, joined_at (single exact)
 * 6. Paginate with limit=2, page=2; validate returned records and pagination metadata
 * 7. Send invalid filters: (a) non-existent field (b) invalid datatype; verify errors are thrown
 * 8. Member access negative test is skipped (login not implemented)
 */
export async function test_api_discussionboard_test_list_board_moderator_assignments_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two boards
  const boardA = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(10),
      is_active: true,
      is_visible: true,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(boardA);
  const boardB = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(10),
      is_active: false,
      is_visible: false,
    } satisfies Idiscussionboard_boards.ICreate,
  });
  typia.assert(boardB);

  // 2. Create two moderators
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const mod1 = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      assigned_by_admin_id: adminId,
      assigned_at: new Date().toISOString(),
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(mod1);
  const mod2 = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      assigned_by_admin_id: adminId,
      assigned_at: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString(),
      expires_at: null,
    } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(mod2);

  // 3. Assign both moderators to both boards with varying attributes
  const assignmentA1 = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: boardA.id,
      discussionboard_moderator_id: mod1.id,
      is_primary: true,
      joined_at: new Date().toISOString(),
    } satisfies IDiscussionboardBoardModerator.ICreate,
  });
  typia.assert(assignmentA1);
  const assignmentA2 = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: boardA.id,
      discussionboard_moderator_id: mod2.id,
      is_primary: false,
      joined_at: new Date(Date.now() - 1000 * 60 * 60).toISOString(),
    } satisfies IDiscussionboardBoardModerator.ICreate,
  });
  typia.assert(assignmentA2);
  const assignmentB1 = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: boardB.id,
      discussionboard_moderator_id: mod1.id,
      is_primary: false,
      joined_at: new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString(),
    } satisfies IDiscussionboardBoardModerator.ICreate,
  });
  typia.assert(assignmentB1);
  const assignmentB2 = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: boardB.id,
      discussionboard_moderator_id: mod2.id,
      is_primary: true,
      joined_at: new Date(Date.now() - 1000 * 60 * 60 * 3).toISOString(),
    } satisfies IDiscussionboardBoardModerator.ICreate,
  });
  typia.assert(assignmentB2);

  // 4. List all board-moderator assignments (no filter)
  const allAssignments = await api.functional.discussionboard.boardModerators.index(connection, { body: {} });
  typia.assert(allAssignments);
  TestValidator.equals("assignment count")(allAssignments.data.length)(4);

  // 5. Search/filter by moderator id, board id, is_primary, joined_at
  const byMod1 = await api.functional.discussionboard.boardModerators.index(connection, { body: { discussionboard_moderator_id: mod1.id } });
  typia.assert(byMod1);
  TestValidator.predicate("all assignments are for mod1")(byMod1.data.every(x => x.discussionboard_moderator_id === mod1.id));
  const byBoardA = await api.functional.discussionboard.boardModerators.index(connection, { body: { discussionboard_board_id: boardA.id } });
  typia.assert(byBoardA);
  TestValidator.predicate("all assignments are for boardA")(byBoardA.data.every(x => x.discussionboard_board_id === boardA.id));
  const byPrimary = await api.functional.discussionboard.boardModerators.index(connection, { body: { is_primary: true } });
  typia.assert(byPrimary);
  TestValidator.predicate("all assignments are primary")(byPrimary.data.every(x => x.is_primary === true));

  // Filter by exact joined_at (using assignmentA1)
  const byJoinedAt = await api.functional.discussionboard.boardModerators.index(connection, { body: { joined_at: assignmentA1.joined_at } });
  typia.assert(byJoinedAt);
  TestValidator.predicate("contains assignmentA1")(byJoinedAt.data.some(x => x.id === assignmentA1.id));

  // 6. Paginate with limit=2, page=2
  const paginated = await api.functional.discussionboard.boardModerators.index(connection, { body: { limit: 2, page: 2 } });
  typia.assert(paginated);
  TestValidator.equals("page metadata")(paginated.pagination.current)(2);
  TestValidator.equals("limit metadata")(paginated.pagination.limit)(2);
  TestValidator.equals("data length")(paginated.data.length)(2);

  // 7. Invalid filters: non-existent field, wrong datatype for page
  await TestValidator.error("invalid filter field")(async () => {
    await api.functional.discussionboard.boardModerators.index(connection, { body: { foo: "bar" } as any });
  });
  await TestValidator.error("invalid filter datatype")(async () => {
    await api.functional.discussionboard.boardModerators.index(connection, { body: { page: "not-a-number" as any } });
  });

  // 8. Simulate member access – skipped as member login/api context is not available
}

