/**
 * Validates updating a post reference entity by ID.
 *
 * Verifies that:
 * - A post reference can be successfully updated to point to a different target post
 * - The reference_type field can be changed via update
 * - Only allowed schema fields are modified/returned
 * - Setting nullable fields (like target_thread_id) to null works as expected
 * - All expected field values are accurately reflected in the updated result
 *
 * Workflow:
 * 1. Create an initial post reference (refA)
 * 2. Create a second post reference (refB)
 * 3. Update refB's target post and reference_type
 * 4. Verify the changes are reflected in the updated object
 * 5. Set a nullable field (target_thread_id) to null via update and verify
 */
export async function test_api_discussionboard_postReferences_test_update_post_reference_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create the first valid post reference (refA)
  const sourcePostA = typia.random<string & tags.Format<"uuid">>();
  const targetPostA = typia.random<string & tags.Format<"uuid">>();
  const refA = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: sourcePostA,
      target_post_id: targetPostA,
      reference_type: "post",
    } satisfies IPostReference.ICreate,
  });
  typia.assert(refA);

  // 2. Create the second post reference (refB), referencing a different target post
  const sourcePostB = typia.random<string & tags.Format<"uuid">>();
  const targetPostB = typia.random<string & tags.Format<"uuid">>();
  const refB = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: sourcePostB,
      target_post_id: targetPostB,
      reference_type: "post",
    } satisfies IPostReference.ICreate,
  });
  typia.assert(refB);

  // 3. Update the second post reference: change target post and reference_type
  const updatedReferenceType = "comment";
  const updated = await api.functional.discussionboard.postReferences.update(connection, {
    id: refB.id,
    body: {
      target_post_id: refA.target_post_id,
      reference_type: updatedReferenceType,
    } satisfies IPostReference.IUpdate,
  });
  typia.assert(updated);

  // 4. Validate updated values and unchanged stable fields
  TestValidator.equals("updated target_post_id")(updated.target_post_id)(refA.target_post_id);
  TestValidator.equals("updated reference_type")(updated.reference_type)(updatedReferenceType);
  TestValidator.equals("id remains unchanged")(updated.id)(refB.id);
  TestValidator.equals("source_post_id remains unchanged")(updated.source_post_id)(refB.source_post_id);

  // 5. Set target_thread_id to null explicitly and verify
  const updatedNullThread = await api.functional.discussionboard.postReferences.update(connection, {
    id: refB.id,
    body: {
      target_thread_id: null,
    } satisfies IPostReference.IUpdate,
  });
  typia.assert(updatedNullThread);
  TestValidator.equals("target_thread_id is null")(updatedNullThread.target_thread_id)(null);
}

