      source_post_id: typia.random<string & tags.Format<"uuid">>(),
      target_post_id: typia.random<string & tags.Format<"uuid">>(),
      reference_type: "post"
    } satisfies IPostReference.ICreate
  });
  typia.assert(refCreate);

  // 2. Attempt update with both target_post_id and target_thread_id (business logic may reject this combination)
  await TestValidator.error("update with both target_post_id and target_thread_id should fail")(
    async () => {
      await api.functional.discussionboard.postReferences.update(connection, {
        id: refCreate.id,
        body: {
          target_post_id: typia.random<string & tags.Format<"uuid">>(),
          target_thread_id: typia.random<string & tags.Format<"uuid">>(),
          reference_type: "post-thread-mixed"
        } satisfies IPostReference.IUpdate
      });
    }
  );

  // 3. Attempt update with an invalid (empty) reference_type value
  await TestValidator.error("update with invalid reference_type should fail")(
    async () => {
      await api.functional.discussionboard.postReferences.update(connection, {
        id: refCreate.id,
        body: {
          reference_type: ""
        } satisfies IPostReference.IUpdate
      });
    }
  );

  // 4. Attempt update with a non-existent target_post_id
  await TestValidator.error("update with non-existent target_post_id should fail")(
    async () => {
      await api.functional.discussionboard.postReferences.update(connection, {
        id: refCreate.id,
        body: {
          target_post_id: typia.random<string & tags.Format<"uuid">>()
        } satisfies IPostReference.IUpdate
      });
    }
  );
}

