import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * E2E test for creating a comment directly on a discussion board post.
 *
 * This test validates that a comment can be created under an existing post, verifying all schema-defined fields are present and correct linkages are established.
 *
 * Steps:
 * 1. Create a new discussion thread, simulating a real user and board linkage.
 * 2. Create a new post within the thread (providing thread, member, and board UUIDs, and content fields).
 * 3. Create a new comment under the post, linking by post/member IDs.
 * 4. Assert that the created comment correctly references the post and member, and has all required schema fields populated.
 */
export async function test_api_discussionboard_test_create_comment_on_post(
  connection: api.IConnection,
) {
  // 1. Create a new discussion thread
  const boardId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const memberId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const threadTitle: string = RandomGenerator.paragraph()(8); // Reasonably unique
  const threadBody: string = RandomGenerator.content()()();

  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: boardId,
      author_member_id: memberId,
      title: threadTitle,
      body: threadBody,
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);
  TestValidator.equals("thread.title")(thread.title)(threadTitle);
  TestValidator.equals("thread.board_id")(thread.board_id)(boardId);
  TestValidator.equals("thread.author_member_id")(thread.author_member_id)(memberId);

  // 2. Create a post within this thread
  const postTitle: string = RandomGenerator.paragraph()(3);
  const postBody: string = RandomGenerator.content()()();
  const now: string & tags.Format<"date-time"> = new Date().toISOString() as string & tags.Format<"date-time">;

  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: postTitle,
      body: postBody,
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals("post.title")(post.title)(postTitle);
  TestValidator.equals("post.body")(post.body)(postBody);
  TestValidator.equals("post.discussionboard_thread_id")(post.discussionboard_thread_id)(thread.id);
  TestValidator.equals("post.discussionboard_member_id")(post.discussionboard_member_id)(memberId);
  TestValidator.equals("post.discussionboard_board_id")(post.discussionboard_board_id)(boardId);
  TestValidator.equals("post.is_deleted")(post.is_deleted)(false);

  // 3. Create a top-level comment on the post
  const commentBody: string = RandomGenerator.paragraph()(6);
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberId,
      body: commentBody,
      // parent_id intentionally omitted (top-level)
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("comment.discussionboard_post_id")(comment.discussionboard_post_id)(post.id);
  TestValidator.equals("comment.discussionboard_member_id")(comment.discussionboard_member_id)(memberId);
  TestValidator.equals("comment.body")(comment.body)(commentBody);
  TestValidator.equals("top-level comment parent_id")(comment.parent_id)(null);
  TestValidator.predicate("comment.created_at is valid")(
    typeof comment.created_at === "string" && !isNaN(Date.parse(comment.created_at))
  );
  TestValidator.equals("comment deleted_at")(comment.deleted_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Test creating a nested comment (reply to an existing comment).
 *
 * This test ensures the system supports threaded/nested comments (replies).
 *
 * Steps:
 * 1. Create a thread (to get board/thread context)
 * 2. Create a post under the thread (to serve as anchor for comments)
 * 3. Create a top-level (parent) comment under the post
 * 4. Create a nested/reply comment referencing the parent comment's id as parent_id
 * 5. Validate:
 *    a. Reply comment's parent_id matches the parent comment's id
 *    b. Reply comment references the correct post and member
 */
export async function test_api_discussionboard_test_create_comment_reply_to_existing_comment(
  connection: api.IConnection,
) {
  // 1. Prepare mock board/thread/post/member IDs for context
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const author_member_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id,
      author_member_id,
      title: `Thread for nested comment test - ${RandomGenerator.alphabets(8)}`,
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. Create post linked to thread
  const now = new Date().toISOString();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: author_member_id,
      discussionboard_board_id: board_id,
      title: `Test post for reply threading`,
      body: RandomGenerator.content()()(),
      is_deleted: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create parent comment (top-level, no parent_id)
  const parentComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: author_member_id,
      body: RandomGenerator.content()()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(parentComment);

  // 5. Create reply comment (nested under parent), set parent_id
  const replyComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: author_member_id,
      parent_id: parentComment.id,
      body: RandomGenerator.content()()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(replyComment);

  // Validate reply's parent_id, post, and member
  TestValidator.equals("reply parent_id")(replyComment.parent_id)(parentComment.id);
  TestValidator.equals("reply post id")(replyComment.discussionboard_post_id)(post.id);
  TestValidator.equals("reply member id")(replyComment.discussionboard_member_id)(author_member_id);
}

