  const invalidPostId = typia.random<string & tags.Format<"uuid">>();
  // 2. Prepare a random member id (also non-existent, since only post id matters here)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  // 3. Attempt to create the comment and assert that an error is thrown
  await TestValidator.error("Creating comment with invalid post id should fail")(
    async () => {
      await api.functional.discussionboard.comments.create(connection, {
